CREATE OR REPLACE FUNCTION "private"."area_pets_in_use"("p_room_id" "uuid", "p_range" "tstzrange", "p_exclude_booking" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(sum(
           (select count(*) from public.booking_pets bp
             where bp.booking_id = s.booking_id)
         ), 0)::integer
    from public.boarding_stays s
   where s.room_id = p_room_id
     and s.space_type = 'area'
     -- A cancelled stay frees its space, exactly as it does for a room.
     and s.released_at is null
     -- Half-open, so the day a guest leaves is not a day they occupy.
     and s.occupies && p_range
     and (p_exclude_booking is null or s.booking_id <> p_exclude_booking);
$$;


ALTER FUNCTION "private"."area_pets_in_use"("p_room_id" "uuid", "p_range" "tstzrange", "p_exclude_booking" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."area_pets_in_use"("p_room_id" "uuid", "p_range" "tstzrange", "p_exclude_booking" "uuid") IS 'Pets already in an area unit over a range — MoeGo area occupancy. Counts pets, not stays; ignores released stays; and because occupies is half-open, a pet checking out on a date is not counted on that date.';



CREATE OR REPLACE FUNCTION "private"."arrival_needs_a_live_booking"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_status public.booking_status;
begin
  if new.checked_in_at is null then
    return new;
  end if;
  if tg_op = 'UPDATE' and old.checked_in_at is not null then
    return new;
  end if;
  if (select auth.jwt()->>'sub') is null then
    return new;
  end if;

  select status into v_status from public.bookings where id = new.booking_id;
  if v_status in (
       'request_submitted', 'waitlisted', 'estimate_sent',
       'declined', 'cancelled', 'no_show', 'completed'
     )
  then
    raise exception 'This booking cannot be checked in while it is %.',
      replace(v_status::text, '_', ' ')
      using errcode = '22023', hint = 'booking_not_arrivable';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."arrival_needs_a_live_booking"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."assert_rule_templates"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_channel text;
  v_facility uuid;
begin
  if new.email_template_id is not null then
    select channel, facility_id into v_channel, v_facility
      from public.message_templates where id = new.email_template_id;
    if v_channel is distinct from 'email' then
      raise exception 'email_template_id names a % template', coalesce(v_channel, 'missing');
    end if;
    if v_facility is distinct from new.facility_id then
      raise exception 'email_template_id belongs to a different facility';
    end if;
  end if;

  if new.sms_template_id is not null then
    select channel, facility_id into v_channel, v_facility
      from public.message_templates where id = new.sms_template_id;
    if v_channel is distinct from 'sms' then
      raise exception 'sms_template_id names a % template', coalesce(v_channel, 'missing');
    end if;
    if v_facility is distinct from new.facility_id then
      raise exception 'sms_template_id belongs to a different facility';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."assert_rule_templates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."assert_step_templates"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_channel text;
  v_template_facility uuid;
  v_workflow_facility uuid;
begin
  select facility_id into v_workflow_facility
    from public.workflows where id = new.workflow_id;

  if new.email_template_id is not null then
    select channel, facility_id into v_channel, v_template_facility
      from public.message_templates where id = new.email_template_id;
    if v_channel is distinct from 'email' then
      raise exception 'email_template_id names a % template', coalesce(v_channel, 'missing');
    end if;
    if v_template_facility is distinct from v_workflow_facility then
      raise exception 'email_template_id belongs to a different facility';
    end if;
  end if;

  if new.sms_template_id is not null then
    select channel, facility_id into v_channel, v_template_facility
      from public.message_templates where id = new.sms_template_id;
    if v_channel is distinct from 'sms' then
      raise exception 'sms_template_id names a % template', coalesce(v_channel, 'missing');
    end if;
    if v_template_facility is distinct from v_workflow_facility then
      raise exception 'sms_template_id belongs to a different facility';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."assert_step_templates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."assert_workflow_has_steps"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.status = 'active' and coalesce(old.status, '') <> 'active' then
    if not exists (select 1 from public.workflow_steps s where s.workflow_id = new.id) then
      raise exception 'a workflow with no steps cannot be activated';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."assert_workflow_has_steps"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."attribute_tip_automatically"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking   public.bookings%rowtype;
  v_collected numeric(10,2);
  v_allocated numeric(10,2);
  v_mode      text;
  v_staff     uuid;
  v_count     integer;
begin
  -- Nothing to attribute, and nothing to take back.
  if new.booking_id is null or coalesce(new.tip, 0) = 0 then
    return null;
  end if;

  select * into v_booking from public.bookings where id = new.booking_id;
  if not found then
    return null;
  end if;

  -- A person has already answered this. Leave it alone — including when a
  -- refund has just made it wrong, which the report surfaces instead.
  if exists (
    select 1 from public.booking_tip_allocations a
     where a.booking_id = v_booking.id and a.source = 'manual'
  ) then
    return null;
  end if;

  select coalesce(sum(p.tip), 0) into v_collected
    from public.payments p
   where p.booking_id = v_booking.id;

  -- Every tip on this booking has been given back. Nobody is owed anything.
  if v_collected <= 0 then
    delete from public.booking_tip_allocations
     where booking_id = v_booking.id and source = 'auto';
    return null;
  end if;

  v_mode := coalesce(
    private.tip_attribution_mode(v_booking.facility_id, v_booking.service),
    'assigned'
  );

  -- `pool` is owed to the facility's people collectively and distributed by a
  -- human; `none` is not owed to anyone. Neither names a person, so neither
  -- writes a row — and the reports count them separately, because telling an
  -- owner a pooled tip is settled would be false.
  if v_mode in ('pool', 'none') then
    delete from public.booking_tip_allocations
     where booking_id = v_booking.id and source = 'auto';
    return null;
  end if;

  -- ── A REFUND: scale what is there, do not re-attribute ──────────────────
  --
  -- Re-running attribution on a refund would resolve the staff member again and
  -- could move the money to somebody else if the booking was reassigned in
  -- between. Reducing what exists keeps the tip with whoever earned it.
  select coalesce(sum(a.amount), 0), count(*)
    into v_allocated, v_count
    from public.booking_tip_allocations a
   where a.booking_id = v_booking.id and a.source = 'auto';

  if v_count > 0 and v_allocated > v_collected then
    update public.booking_tip_allocations a
       set amount = round(a.amount * (v_collected / v_allocated), 2)
     where a.booking_id = v_booking.id and a.source = 'auto';

    delete from public.booking_tip_allocations a
     where a.booking_id = v_booking.id and a.source = 'auto' and a.amount <= 0;

    return null;
  end if;

  -- ── Otherwise: the whole collected tip, to whoever earned it ────────────
  --
  -- `assigned_staff_id` IS a staff id — the same thing an allocation points at.
  -- Worth stating because the column was declared against
  -- `facility_memberships` in 20260801120000 and repointed later, so the
  -- original definition reads like there is a seam to cross here. There is not,
  -- and a join through `staff.membership_id` would resolve NOBODY: every tip
  -- would come out Unassigned, which looks like a data problem rather than a
  -- code one. Read the live constraint, not the first migration that named it.
  --
  -- The facility check is not redundant: it is what stops a booking that was
  -- moved between facilities attributing its tip to the wrong payroll.
  select s.id into v_staff
    from public.staff s
   where s.id = v_booking.assigned_staff_id
     and s.facility_id = v_booking.facility_id
   limit 1;

  -- Nobody to pay: a booking assigned by NAME only, or an anonymous daycare
  -- drop-off. No row, rather than a row pointing at a guess — the reports count
  -- this as Unassigned, which is a number somebody can act on.
  if v_staff is null then
    delete from public.booking_tip_allocations
     where booking_id = v_booking.id and source = 'auto';
    return null;
  end if;

  insert into public.booking_tip_allocations
    (booking_id, facility_id, staff_id, amount, method, source, author_name)
  values
    (v_booking.id, v_booking.facility_id, v_staff, v_collected,
     case when v_mode = 'split_even' then 'auto_split' else 'auto_assigned' end,
     'auto', 'Yipyy')
  on conflict (booking_id, staff_id) do update
     set amount     = excluded.amount,
         method     = excluded.method,
         updated_at = now()
   -- Never promote a manual row to auto by writing over it. The guard above
   -- should make this unreachable; a conflict clause that could do it anyway is
   -- a trap waiting for the day the guard changes.
   where public.booking_tip_allocations.source = 'auto';

  -- Any OTHER auto row on this booking is from an earlier attribution that
  -- named somebody else — a reassigned groomer. One booking, one auto
  -- allocation: leaving the old one would pay two people for one tip.
  delete from public.booking_tip_allocations
   where booking_id = v_booking.id
     and source = 'auto'
     and staff_id <> v_staff;

  return null;
end $$;


ALTER FUNCTION "private"."attribute_tip_automatically"() OWNER TO "postgres";


COMMENT ON FUNCTION "private"."attribute_tip_automatically"() IS 'Attributes a booking tips to its staff on every payment, per the facility tip_attribution rules. Never touches a manual split.';



CREATE OR REPLACE FUNCTION "private"."audit_booking_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_name   text;
  v_data   jsonb := '[]'::jsonb;
  v_money  jsonb := '[]'::jsonb;
  v_action text;
begin
  -- As audit_booking_location records it: the row id, and the ref as its name.
  v_name := new.ref::text;

  if tg_op = 'INSERT' then
    perform private.record_audit(
      'Booking created', 'Data', 'Low', 'booking', new.id::text, v_name,
      new.facility_id, null, null,
      jsonb_build_array(jsonb_build_object(
        'field', 'status', 'from', null, 'to', new.status::text)));
    return null;
  end if;

  if new.status is distinct from old.status then
    v_data := v_data || jsonb_build_object(
      'field', 'status', 'from', old.status::text, 'to', new.status::text);
  end if;
  if new.start_at is distinct from old.start_at then
    v_data := v_data || jsonb_build_object(
      'field', 'start', 'from', old.start_at, 'to', new.start_at);
  end if;
  if new.end_at is distinct from old.end_at then
    v_data := v_data || jsonb_build_object(
      'field', 'end', 'from', old.end_at, 'to', new.end_at);
  end if;
  if new.assigned_staff_id is distinct from old.assigned_staff_id then
    v_data := v_data || jsonb_build_object(
      'field', 'staff',
      'from', old.assigned_staff_name, 'to', new.assigned_staff_name);
  end if;
  if new.service_type is distinct from old.service_type then
    v_data := v_data || jsonb_build_object(
      'field', 'serviceType', 'from', old.service_type, 'to', new.service_type);
  end if;
  if new.special_requests is distinct from old.special_requests then
    v_data := v_data || jsonb_build_object(
      'field', 'notes', 'from', old.special_requests, 'to', new.special_requests);
  end if;

  if new.base_price is distinct from old.base_price then
    v_money := v_money || jsonb_build_object(
      'field', 'basePrice', 'from', old.base_price, 'to', new.base_price);
  end if;
  if new.discount is distinct from old.discount then
    v_money := v_money || jsonb_build_object(
      'field', 'discount', 'from', old.discount, 'to', new.discount);
  end if;
  if new.total_cost is distinct from old.total_cost then
    v_money := v_money || jsonb_build_object(
      'field', 'total', 'from', old.total_cost, 'to', new.total_cost);
  end if;
  if new.tip_amount is distinct from old.tip_amount then
    v_money := v_money || jsonb_build_object(
      'field', 'tip', 'from', old.tip_amount, 'to', new.tip_amount);
  end if;

  if jsonb_array_length(v_data) > 0 then
    v_action := case
      when new.status is distinct from old.status then 'Booking status changed'
      when new.start_at is distinct from old.start_at
        or new.end_at is distinct from old.end_at then 'Booking rescheduled'
      else 'Booking updated'
    end;
    perform private.record_audit(
      v_action, 'Data', 'Low', 'booking', new.id::text, v_name,
      new.facility_id, null, null, v_data);
  end if;

  if jsonb_array_length(v_money) > 0 then
    perform private.record_audit(
      'Booking price changed', 'Financial', 'Medium', 'booking',
      new.id::text, v_name, new.facility_id, null, null, v_money);
  end if;

  return null;
exception when others then
  -- The history is not worth a refused booking.
  raise warning 'booking % history not recorded: %', new.ref, sqlerrm;
  return null;
end;
$$;


ALTER FUNCTION "private"."audit_booking_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."audit_booking_location"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_facility_name text;
  v_from_name text;
  v_to_name text;
begin
  if new.location_id is not distinct from old.location_id then
    return null;
  end if;

  select name into v_facility_name from public.facilities where id = new.facility_id;
  select name into v_from_name from public.locations where id = old.location_id;
  select name into v_to_name from public.locations where id = new.location_id;

  -- 'Data' is the closest fit of the six categories audit_log's own CHECK
  -- constraint allows ('Financial','User Access','Configuration','Security',
  -- 'Data','System') -- a booking is business data, not a permission or a
  -- money event on its own.
  perform private.record_audit(
    'Booking transferred',
    'Data',
    'Medium',
    'booking',
    new.id::text,
    new.ref::text,
    new.facility_id,
    v_facility_name,
    format('Booking %s moved: %s -> %s',
      new.ref, coalesce(v_from_name, 'no branch'), coalesce(v_to_name, 'no branch')),
    jsonb_build_array(jsonb_build_object(
      'field', 'location_id', 'from', old.location_id, 'to', new.location_id)));

  return null;
end;
$$;


ALTER FUNCTION "private"."audit_booking_location"() OWNER TO "postgres";


