CREATE OR REPLACE FUNCTION "private"."audit_facility_membership"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_name  text;
  v_email text;
  v_fid   uuid;
  v_pid   text;
begin
  v_fid := case when tg_op = 'DELETE' then old.facility_id else new.facility_id end;
  v_pid := case when tg_op = 'DELETE' then old.profile_id  else new.profile_id  end;
  select f.name into v_name from public.facilities f where f.id = v_fid;
  select p.email into v_email from public.profiles p where p.id = v_pid;

  if tg_op = 'INSERT' then
    perform private.record_audit(
      'Facility access granted', 'User Access', 'High',
      'membership', v_pid, v_email, v_fid, v_name,
      format('%s joined %s as %s', coalesce(v_email, v_pid), coalesce(v_name,'a facility'), new.role));
  elsif tg_op = 'DELETE' then
    perform private.record_audit(
      'Facility access removed', 'User Access', 'High',
      'membership', v_pid, v_email, v_fid, v_name,
      format('%s was removed from %s', coalesce(v_email, v_pid), coalesce(v_name,'a facility')));
  elsif new.is_active is distinct from old.is_active or new.role is distinct from old.role then
    perform private.record_audit(
      case when new.is_active then 'Facility access changed' else 'Facility access suspended' end,
      'User Access', 'High',
      'membership', v_pid, v_email, v_fid, v_name,
      format('%s at %s', coalesce(v_email, v_pid), coalesce(v_name,'a facility')),
      jsonb_build_array(
        jsonb_build_object('field','role','from',old.role,'to',new.role),
        jsonb_build_object('field','is_active','from',old.is_active,'to',new.is_active)));
  else
    return null;
  end if;
  return null;
end $$;


ALTER FUNCTION "private"."audit_facility_membership"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."audit_facility_module"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row      record;
  v_facility text;
  v_module   text;
  v_action   text;
  v_severity text;
  v_field    text;
  v_from     text;
  v_to       text;
begin
  if tg_op = 'DELETE' then v_row := old; else v_row := new; end if;

  select f.name into v_facility from public.facilities f where f.id = v_row.facility_id;
  select m.name into v_module   from public.modules m    where m.id = v_row.module_id;

  if tg_op = 'DELETE' then
    v_action   := 'Module exception removed';
    v_severity := 'Medium';
    v_field    := 'enabled';
    v_from     := case when old.enabled then 'enabled' else 'disabled' end;
    v_to       := 'plan default';

  elsif tg_op = 'INSERT' or new.enabled is distinct from old.enabled then
    v_action   := case when new.enabled then 'Module enabled' else 'Module disabled' end;
    v_severity := case when new.enabled then 'Medium' else 'High' end;
    v_field    := 'enabled';
    v_from     := case
                    when tg_op = 'INSERT' then 'plan default'
                    when old.enabled then 'enabled'
                    else 'disabled'
                  end;
    v_to       := case when new.enabled then 'enabled' else 'disabled' end;

  elsif new.price_override_cents is distinct from old.price_override_cents then
    v_action   := 'Module price changed';
    v_severity := 'Medium';
    v_field    := 'price_override_cents';
    v_from     := coalesce(old.price_override_cents::text, 'catalogue price');
    v_to       := coalesce(new.price_override_cents::text, 'catalogue price');

  elsif new.expires_at is distinct from old.expires_at then
    v_action   := 'Module expiry changed';
    v_severity := 'Low';
    v_field    := 'expires_at';
    v_from     := coalesce(old.expires_at::text, 'no expiry');
    v_to       := coalesce(new.expires_at::text, 'no expiry');

  else
    return null;
  end if;

  perform private.record_audit(
    v_action,
    'Financial',
    v_severity,
    'module', v_row.module_id, coalesce(v_module, v_row.module_id),
    v_row.facility_id, v_facility,
    format('%s: %s %s -> %s',
           coalesce(v_facility, 'facility'), coalesce(v_module, v_row.module_id), v_from, v_to),
    jsonb_build_array(jsonb_build_object('field', v_field, 'from', v_from, 'to', v_to)));

  return null;
end;
$$;


