CREATE OR REPLACE FUNCTION "private"."boarding_stay_apply_cutoff"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_cut      time;
  v_tz       text;
  v_upper    timestamptz;
  v_end      timestamptz;
  v_checkout timestamptz;
  v_local    timestamp;
  v_extended timestamptz;
begin
  v_cut := private.checkout_cut_off(new.facility_id);
  if v_cut is null then
    return new;
  end if;

  v_upper := upper(new.occupies);
  if v_upper is null then
    return new;
  end if;

  -- The last stay is the one that ends where the booking ends. A stay that
  -- hands the pet to another kennel ends at the transfer, and a transfer is
  -- not a check-out: it keeps its exact upper bound.
  select b.end_at into v_end from public.bookings b where b.id = new.booking_id;
  if v_end is not null and v_upper < v_end then
    return new;
  end if;

  -- The real departure when it is known — stamped on the booking's FIRST
  -- stay, which is this row unless the booking was split — the booked one
  -- until then.
  select coalesce(
           case when new.segment_order = 1 then new.checked_out_at end,
           (select s.checked_out_at from public.boarding_stays s
             where s.booking_id = new.booking_id and s.segment_order = 1
               and s.id <> new.id),
           v_upper)
    into v_checkout;

  select coalesce(f.timezone, 'America/Toronto') into v_tz
    from public.facilities f where f.id = new.facility_id;
  v_tz := coalesce(v_tz, 'America/Toronto');

  v_local := v_checkout at time zone v_tz;

  -- AT or AFTER: a cut-off of 14:00 with a 14:00 check-out holds the night.
  if v_local::time >= v_cut then
    v_extended := ((date_trunc('day', v_local) + interval '1 day') at time zone v_tz);
    -- Extend only.
    if v_extended > v_upper then
      new.occupies := tstzrange(lower(new.occupies), v_extended, '[)');
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."boarding_stay_apply_cutoff"() OWNER TO "postgres";


COMMENT ON FUNCTION "private"."boarding_stay_apply_cutoff"() IS 'Holds the kennel to the next local midnight when the check-out is at or after the facility cut-off. Extends only, never shrinks, so it is idempotent and cannot free a kennel somebody paid for.';



CREATE OR REPLACE FUNCTION "private"."boarding_stay_space_type"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_space public.lodging_space_type;
begin
  select rc.space_type into v_space
    from public.facility_rooms fr
    join public.room_categories rc on rc.id = fr.category_id
   where fr.id = new.room_id;

  if v_space is null then
    -- The room FK catches a missing room. A room whose CATEGORY went missing
    -- would otherwise fall through to the column default and silently become a
    -- 'room' — and a default that decides a money rule is not a default worth
    -- having.
    raise exception 'That room has no lodging type.' using errcode = '23503';
  end if;

  new.space_type := v_space;
  return new;
end;
$$;


ALTER FUNCTION "private"."boarding_stay_space_type"() OWNER TO "postgres";


COMMENT ON FUNCTION "private"."boarding_stay_space_type"() IS 'Derives boarding_stays.space_type from the room category. Never trusts a supplied value, as the facility_id triggers do not either.';



CREATE OR REPLACE FUNCTION "private"."boarding_stays_tile_their_booking"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking uuid := case when tg_op = 'DELETE' then old.booking_id else new.booking_id end;
  v_prev    tstzrange;
  v_order   integer := 0;
  r         record;
begin
  for r in
    select s.segment_order, s.occupies
      from public.boarding_stays s
     where s.booking_id = v_booking
     order by s.segment_order
  loop
    v_order := v_order + 1;
    if r.segment_order <> v_order then
      raise exception 'A booking''s stays are numbered 1, 2, 3… with no gap.'
        using errcode = '23514', hint = 'segment_order';
    end if;
    if v_prev is not null and upper(v_prev) <> lower(r.occupies) then
      raise exception 'A booking''s stays must follow each other with no gap and no overlap.'
        using errcode = '23514', hint = 'segment_tiling';
    end if;
    v_prev := r.occupies;
  end loop;
  return null;
end;
$$;


ALTER FUNCTION "private"."boarding_stays_tile_their_booking"() OWNER TO "postgres";


