CREATE OR REPLACE FUNCTION "private"."booking_moves_the_client"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_old uuid := case when tg_op <> 'INSERT' then old.client_id end;
  v_new uuid := case when tg_op <> 'DELETE' then new.client_id end;
begin
  if v_new is not null then
    update public.clients
       set outstanding_balance = private.client_outstanding_balance(v_new)
     where id = v_new;
  end if;

  if v_old is not null and v_old is distinct from v_new then
    update public.clients
       set outstanding_balance = private.client_outstanding_balance(v_old)
     where id = v_old;
  end if;

  return null;
end;
$$;


ALTER FUNCTION "private"."booking_moves_the_client"() OWNER TO "postgres";


COMMENT ON FUNCTION "private"."booking_moves_the_client"() IS 'Recomputes the client(s) a booking touches. Handles both ids on an UPDATE so a reassigned booking does not leave its debt behind.';



