SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."bookings" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "ref" bigint NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "location_id" "uuid",
    "client_id" "uuid" NOT NULL,
    "service" "text" NOT NULL,
    "service_type" "text",
    "status" "public"."booking_status" DEFAULT 'pending'::"public"."booking_status" NOT NULL,
    "payment_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "start_at" timestamp with time zone NOT NULL,
    "end_at" timestamp with time zone NOT NULL,
    "assigned_staff_id" "uuid",
    "assigned_staff_name" "text",
    "base_price" numeric(12,2) DEFAULT 0 NOT NULL,
    "discount" numeric(12,2) DEFAULT 0 NOT NULL,
    "total_cost" numeric(12,2) DEFAULT 0 NOT NULL,
    "tip_amount" numeric(12,2),
    "special_requests" "text",
    "details" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "amount_paid" numeric(10,2) DEFAULT 0 NOT NULL,
    "extras_total" numeric(10,2) DEFAULT 0 NOT NULL,
    "amount_due" numeric(10,2) GENERATED ALWAYS AS (GREATEST((0)::numeric, (("total_cost" + "extras_total") - COALESCE("discount", (0)::numeric)))) STORED,
    "training_series_session_id" "uuid",
    "taxable" boolean DEFAULT true NOT NULL,
    "taxable_extras_total" numeric(10,2) DEFAULT 0 NOT NULL,
    CONSTRAINT "bookings_discount_within_price" CHECK (("discount" <= "base_price")),
    CONSTRAINT "bookings_ends_after_start" CHECK (("end_at" >= "start_at")),
    CONSTRAINT "bookings_money_non_negative" CHECK ((("base_price" >= (0)::numeric) AND ("discount" >= (0)::numeric) AND ("total_cost" >= (0)::numeric) AND (("tip_amount" IS NULL) OR ("tip_amount" >= (0)::numeric)))),
    CONSTRAINT "bookings_payment_status_check" CHECK (("payment_status" = ANY (ARRAY['pending'::"text", 'paid'::"text", 'refunded'::"text"])))
);


ALTER TABLE "public"."bookings" OWNER TO "postgres";


COMMENT ON COLUMN "public"."bookings"."discount" IS 'Money off the whole bill, subtracted ONCE by amount_due. Never already inside total_cost. Capped at base_price by bookings_discount_within_price.';



COMMENT ON COLUMN "public"."bookings"."total_cost" IS 'The SERVICE''s price, GROSS of the discount and before tax. What a customer owes is amount_due = total_cost + extras_total - discount, so a caller that nets the discount out of this column has it taken twice. Set by 20260924100000.';



COMMENT ON COLUMN "public"."bookings"."amount_paid" IS 'DERIVED from public.payments - sum(grand_total - tip). Never write it: private.derive_booking_payment() overwrites any value on every insert and update.';



COMMENT ON COLUMN "public"."bookings"."extras_total" IS 'DERIVED from public.booking_line_items. Never write it.';



COMMENT ON COLUMN "public"."bookings"."amount_due" IS 'What the booking COSTS, net of discount and before tax: total_cost + extras_total - discount. Not the outstanding balance -- subtract amount_paid for that. Tax is never here; it is per-facility and lives on the payment. See 20260819210000.';



COMMENT ON COLUMN "public"."bookings"."taxable" IS 'Whether this booking''s OWN service price is taxed. Extras (booking_line_items) are taxed regardless — a tax-free service does not make a bag of food tax-free. Written by the server when it prices the booking; pinned to true for anything a customer inserts. See 20260921171524.';



COMMENT ON COLUMN "public"."bookings"."taxable_extras_total" IS 'DERIVED from public.booking_line_items, like extras_total. The part of extras_total that tax applies to. Never write it: private.derive_booking_extras() overwrites any value on every insert and update.';



CREATE OR REPLACE FUNCTION "private"."cancellation_terms"("b" "public"."bookings") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_withdrawal boolean := b.status in
    ('request_submitted', 'estimate_sent', 'waitlisted');
  v_started    boolean := b.start_at <= now();
  -- Fractional on purpose. The old rule used `make_interval(hours => x::int)`,
  -- which TRUNCATES — a 1.5-hour window behaved as 1. Nothing inherits that.
  v_notice     numeric := greatest(
                 0, extract(epoch from (b.start_at - now())) / 3600.0);

  v_policies jsonb;
  v_service  jsonb;
  v_tier     jsonb;
  v_each     jsonb;
  v_best     numeric;
  v_min      numeric;

  v_charge   jsonb;
  v_kind     text;
  v_value    numeric;
  v_amount   numeric := 0;
  v_refund   text;
  v_may      text;

  v_total    numeric := coalesce(b.total_cost, 0);
  v_paid     numeric := coalesce(b.amount_paid, 0);

  v_rules    jsonb;
  v_hours    numeric;
  v_fee      numeric;
  v_late     boolean := false;
begin
  select s.value into v_policies
    from public.facility_settings s
   where s.facility_id = b.facility_id
     and s.domain = 'cancellation_policies';

  v_service := v_policies -> 'services' -> b.service;
  v_may := coalesce(v_service->>'customerMayCancel', 'instant');

  if v_service is not null
     and coalesce((v_service->>'enabled')::boolean, false)
     and jsonb_typeof(v_service->'tiers') = 'array'
     and jsonb_array_length(v_service->'tiers') > 0
  then
    for v_each in select value from jsonb_array_elements(v_service->'tiers')
    loop
      if coalesce(v_each->>'minNoticeHours', '0') ~ '^\d+(\.\d+)?$' then
        v_min := (v_each->>'minNoticeHours')::numeric;
      else
        v_min := 0;
      end if;
      if v_min <= v_notice and (v_best is null or v_min > v_best) then
        v_best := v_min;
        v_tier := v_each;
      end if;
    end loop;

    if v_tier is null then
      -- Inside every window, with no catch-all. Charging the nearest tier
      -- would invent a rule the facility did not write.
      return jsonb_build_object(
        'withdrawal', v_withdrawal,
        'started', v_started,
        'late', false,
        'noticeHours', null,
        'noticeGivenHours', round(v_notice, 2),
        'feePercentage', null,
        'source', 'policy',
        'tierId', null,
        'tierLabel', null,
        'charge', 'none',
        'amount', 0,
        'refund', 'original',
        'forfeitsPass', false,
        'customerMayCancel', v_may);
    end if;

    v_charge := coalesce(v_tier->'charge', jsonb_build_object('kind', 'none'));
    v_kind   := coalesce(v_charge->>'kind', 'none');
    v_refund := coalesce(v_tier->>'refund', 'original');
    if coalesce(v_charge->>'value', '') ~ '^\d+(\.\d+)?$' then
      v_value := (v_charge->>'value')::numeric;
    else
      v_value := 0;
    end if;

    if v_kind = 'percentage' then
      v_amount := round(v_total * greatest(0, v_value) / 100.0, 2);
    elsif v_kind = 'flat' then
      v_amount := round(greatest(0, v_value), 2);
    elsif v_kind = 'keep_deposit' then
      -- Never more than the rule asked for, never more than they paid.
      v_amount := round(least(private.deposit_for_booking(b), v_paid), 2);
    else
      -- 'none', and 'forfeit_pass' — a pass is not money.
      v_amount := 0;
    end if;

    -- A cancellation fee is never larger than the booking it is for.
    v_amount := greatest(0, least(v_amount, v_total));

    return jsonb_build_object(
      'withdrawal', v_withdrawal,
      'started', v_started,
      -- `late` means "something is owed", which is what every reader of this
      -- key already does with it.
      'late', v_amount > 0 or v_kind = 'forfeit_pass',
      -- `noticeHours` is the RULE'S THRESHOLD, which is what it has always
      -- meant — the old function returned the configured window here, not the
      -- notice given. Under a policy the threshold is the winning tier's.
      -- How much notice the customer actually managed is its own key, because
      -- one field carrying two meanings is the bug this codebase keeps finding.
      'noticeHours', v_best,
      'noticeGivenHours', round(v_notice, 2),
      -- Kept for the screens that still read a percentage; null unless the
      -- facility actually expressed one.
      'feePercentage', case when v_kind = 'percentage' then v_value end,
      'source', 'policy',
      'tierId', v_tier->>'id',
      'tierLabel', v_tier->>'label',
      'charge', v_kind,
      'amount', v_amount,
      'refund', v_refund,
      'forfeitsPass', v_kind = 'forfeit_pass',
      'customerMayCancel', v_may);
  end if;

  -- ── NO POLICY: THE FLAT RULE, EXACTLY AS IT BEHAVED BEFORE ──────────────
  --
  -- Lifted from `private.cancel_terms` unchanged, including the truncating
  -- `make_interval`. A facility that has not written a policy must see no
  -- change at all on the deploy that makes policies possible.
  select s.value into v_rules
    from public.facility_settings s
   where s.facility_id = b.facility_id
     and s.domain = 'booking_rules';

  if v_rules is not null then
    if coalesce(v_rules->>'cancelPolicyHours', '') ~ '^\d+(\.\d+)?$' then
      v_hours := (v_rules->>'cancelPolicyHours')::numeric;
    end if;
    if coalesce(v_rules->>'cancelFeePercentage', '') ~ '^\d+(\.\d+)?$' then
      v_fee := (v_rules->>'cancelFeePercentage')::numeric;
    end if;
  end if;

  v_late := not v_withdrawal
            and coalesce(v_hours, 0) > 0
            and b.start_at - now() < make_interval(hours => v_hours::int);

  return jsonb_build_object(
    'withdrawal', v_withdrawal,
    'started', v_started,
    'late', v_late,
    'noticeHours', v_hours,
    'noticeGivenHours', round(v_notice, 2),
    'feePercentage', case when v_late and coalesce(v_fee, 0) > 0 then v_fee end,
    'source', case when v_rules is null then 'none' else 'booking_rules' end,
    'tierId', null,
    'tierLabel', null,
    'charge', case when v_late and coalesce(v_fee, 0) > 0
                   then 'percentage' else 'none' end,
    -- The old rule never produced a figure. It does now, from the same
    -- percentage it has always shown the customer.
    'amount', case when v_late and coalesce(v_fee, 0) > 0
                   then greatest(0, least(round(v_total * v_fee / 100.0, 2), v_total))
                   else 0 end,
    'refund', 'original',
    'forfeitsPass', false,
    'customerMayCancel', 'instant');
end;
$_$;


ALTER FUNCTION "private"."cancellation_terms"("b" "public"."bookings") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."cancellation_terms"("b" "public"."bookings") IS 'The ONE evaluator: a cancellation policy plus a booking, as a dollar figure. Falls back to booking_rules when the facility has written no policy.';



CREATE OR REPLACE FUNCTION "private"."care_log_inherit_facility"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_facility uuid;
  v_client   uuid;
begin
  select b.facility_id, b.client_id into v_facility, v_client
    from public.bookings b where b.id = new.booking_id;

  if v_facility is null then
    raise exception 'No such booking: %', new.booking_id
      using errcode = '23503';
  end if;

  new.facility_id := v_facility;

  if new.pet_id is not null then
    if not exists (
      select 1 from public.pets p
       where p.id = new.pet_id and p.client_id = v_client
    ) then
      raise exception 'That pet is not on this booking''s client record.'
        using errcode = '23514';
    end if;
  end if;

  new.updated_at := now();
  return new;
end;
$$;


