CREATE OR REPLACE FUNCTION "private"."claim_grants_for"("p_profile_id" "text", "p_email" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_grant      record;
  v_membership uuid;
  v_claimed    integer := 0;
begin
  if p_profile_id is null or p_profile_id !~ '^user_' or p_email is null then
    return 0;
  end if;

  for v_grant in
    select * from public.facility_membership_grants
     where claimed_at is null
       and email = lower(p_email)
       and (expires_at is null or expires_at > now())
  loop
    insert into public.facility_memberships
      (facility_id, profile_id, role, access_level, is_active)
    values (v_grant.facility_id, p_profile_id, v_grant.role,
            v_grant.access_level, true)
    on conflict (profile_id, facility_id) do update
      set role         = excluded.role,
          access_level = excluded.access_level,
          is_active    = true
    returning id into v_membership;

    update public.facility_membership_grants
       set claimed_at         = now(),
           claimed_profile_id = p_profile_id
     where id = v_grant.id;

    update public.staff
       set membership_id = v_membership
     where id = v_grant.staff_id;

    v_claimed := v_claimed + 1;
  end loop;

  return v_claimed;
end;
$$;


ALTER FUNCTION "private"."claim_grants_for"("p_profile_id" "text", "p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."claim_membership_grants"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform private.claim_grants_for(new.id, new.email);
  perform private.claim_platform_invitations_for(new.id, new.email);
  return new;
end;
$$;


