COMMENT ON FUNCTION "private"."claim_membership_grants"() IS 'Turns pending grants into memberships when a profile appears carrying the granted address. A trigger and not an RPC so it has no PostgREST route.';



CREATE OR REPLACE FUNCTION "private"."claim_platform_invitations_for"("p_profile_id" "text", "p_email" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_inv     record;
  v_claimed integer := 0;
begin
  if p_profile_id is null or p_email is null then
    return 0;
  end if;

  for v_inv in
    select * from public.platform_invitations
     where accepted_at is null
       and lower(email) = lower(p_email)
       and expires_at > now()
  loop
    insert into public.platform_memberships (profile_id, role, granted_by)
    values (p_profile_id, v_inv.role, v_inv.invited_by)
    on conflict (profile_id) do nothing;

    update public.platform_invitations
       set accepted_at         = now(),
           accepted_profile_id = p_profile_id
     where id = v_inv.id;

    v_claimed := v_claimed + 1;
  end loop;

  return v_claimed;
end;
$$;


