CREATE OR REPLACE FUNCTION "private"."enforce_hire_access_level"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_sub  text := (select auth.jwt()->>'sub');
  v_role public.facility_staff_role;
begin
  if tg_table_name = 'staff' then
    v_role := new.primary_role;
  else
    v_role := new.role;
  end if;

  if v_role in ('owner','admin','manager','supervisor') then
    new.access_level := 'admin'::public.facility_access_level;
  end if;

  if new.access_level <> 'admin'::public.facility_access_level then
    return new;
  end if;

  if tg_op = 'UPDATE'
     and old.access_level = 'admin'::public.facility_access_level then
    return new;
  end if;

  if v_sub is null
     or private.is_platform_admin()
     or private.is_facility_admin(new.facility_id) then
    return new;
  end if;

  raise exception
    'Only a facility admin may hire an admin. manage_staff is not enough.'
    using errcode = '42501';
end;
$$;


ALTER FUNCTION "private"."enforce_hire_access_level"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."enforce_membership_access_level"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_sub      text := (select auth.jwt()->>'sub');
  v_becoming boolean;
begin
  if new.role in ('owner','admin','manager','supervisor') then
    if tg_op = 'UPDATE'
       and old.access_level = 'admin'::public.facility_access_level
       and new.access_level <> 'admin'::public.facility_access_level then
      raise exception
        'A % keeps admin access. Change their job title first, then their access.',
        new.role
        using errcode = '42501';
    end if;
    new.access_level := 'admin'::public.facility_access_level;
  end if;

  v_becoming := new.access_level = 'admin'::public.facility_access_level
                and (tg_op = 'INSERT'
                     or old.access_level is distinct from
                        'admin'::public.facility_access_level);

  if not v_becoming then
    return new;
  end if;

  if v_sub is null then
    return new;
  end if;

  if private.is_platform_admin() then
    return new;
  end if;

  if private.is_facility_admin(new.facility_id) then
    return new;
  end if;

  if exists (
    select 1
      from public.facility_membership_grants g
      join public.profiles p on lower(p.email) = g.email
     where g.facility_id  = new.facility_id
       and p.id           = new.profile_id
       and g.access_level = 'admin'::public.facility_access_level
  ) then
    return new;
  end if;

  raise exception
    'Only a facility admin may grant admin access. manage_staff is not enough.'
    using errcode = '42501';
end;
$$;


ALTER FUNCTION "private"."enforce_membership_access_level"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."enforce_onboarding_instance_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_can_manage boolean;
begin
  if (select auth.jwt()->>'sub') is null then
    return new;
  end if;
  v_can_manage := private.has_permission(old.facility_id, 'manage_staff');
  if v_can_manage or private.is_platform_admin() then
    return new;
  end if;
  if new.staff_id is distinct from old.staff_id
     or new.facility_id is distinct from old.facility_id then
    raise exception 'An onboarding invitation belongs to one person at one facility.'
      using errcode = '42501';
  end if;
  if new.token_hash is distinct from old.token_hash
     or new.token_expires_at is distinct from old.token_expires_at then
    raise exception 'Only a manager can reissue an onboarding link.'
      using errcode = '42501';
  end if;
  new.submitted_at := old.submitted_at;
  new.reviewed_at  := old.reviewed_at;
  return new;
end;
$$;


ALTER FUNCTION "private"."enforce_onboarding_instance_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."enforce_pet_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_facility_id uuid;
  v_can_edit    boolean;
begin
  if (select auth.jwt()->>'sub') is null then
    return new;
  end if;

  select c.facility_id into v_facility_id
    from public.clients c
   where c.id = new.client_id;

  v_can_edit := private.has_permission(v_facility_id, 'edit_pet_records');

  if v_can_edit or private.is_platform_admin() then
    return new;
  end if;

  if tg_op = 'INSERT' then
    new.details := new.details - 'evaluations';
    new.status  := 'active';
    return new;
  end if;

  if new.client_id is distinct from old.client_id then
    raise exception 'Re-homing a pet is done by the facility.'
      using errcode = '42501';
  end if;

  new.status  := old.status;
  new.details := (new.details - 'evaluations')
    || jsonb_strip_nulls(jsonb_build_object(
         'evaluations', old.details -> 'evaluations'));

  return new;
end;
$$;


