CREATE OR REPLACE FUNCTION "private"."enforce_staff_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_can_manage  boolean;
  v_can_payroll boolean;
  v_can_roles   boolean;
  v_is_self     boolean;
  v_details     jsonb;
  v_key         text;
  c_managed_keys constant text[] := array[
    'employment', 'clockIn', 'calendarAccess', 'assignedLocations',
    'upcomingAppointments', 'openTasks', 'invitationSentAt'
  ];
begin
  if (select auth.jwt()->>'sub') is null then
    return new;
  end if;

  v_can_manage  := private.has_permission(new.facility_id, 'manage_staff');
  v_can_payroll := private.has_permission(new.facility_id, 'edit_payroll');
  v_can_roles   := private.has_permission(new.facility_id, 'manage_roles');

  if tg_op = 'INSERT' then
    if not v_can_payroll then
      new.details := (coalesce(new.details, '{}'::jsonb)) - 'payroll';
    end if;
    if not v_can_roles then
      new.details := (coalesce(new.details, '{}'::jsonb)) - 'permissionOverrides';
    end if;
    return new;
  end if;

  v_is_self := old.id in (select private.own_staff_ids());

  if new.facility_id is distinct from old.facility_id then
    raise exception 'A staff record cannot be moved between facilities.'
      using errcode = '42501';
  end if;

  if new.membership_id is distinct from old.membership_id and not v_can_manage then
    raise exception 'You may not change which account a staff record belongs to.'
      using errcode = '42501';
  end if;

  if not v_can_manage
     and (new.primary_role     is distinct from old.primary_role
       or new.additional_roles is distinct from old.additional_roles
       or new.legacy_id        is distinct from old.legacy_id)
  then
    raise exception 'You may not change your own role.'
      using errcode = '42501';
  end if;

  if not v_can_manage
     and (new.status        is distinct from old.status
       or new.status_reason is distinct from old.status_reason
       or new.status_note   is distinct from old.status_note)
  then
    raise exception 'Employment status is set by a manager.'
      using errcode = '42501';
  end if;

  if not v_can_manage then
    new.first_name          := old.first_name;
    new.last_name           := old.last_name;
    new.email               := old.email;
    new.job_title           := old.job_title;
    new.service_assignments := old.service_assignments;
    new.show_on_calendar    := old.show_on_calendar;
    new.last_active         := old.last_active;
    new.status_changed_at   := old.status_changed_at;
  end if;

  v_details := coalesce(old.details, '{}'::jsonb);

  if v_can_manage then
    v_details := coalesce(new.details, '{}'::jsonb)
                 - 'payroll' - 'permissionOverrides';
    v_details := v_details
      || case when coalesce(old.details, '{}'::jsonb) ? 'payroll'
              then jsonb_build_object('payroll', old.details -> 'payroll')
              else '{}'::jsonb end
      || case when coalesce(old.details, '{}'::jsonb) ? 'permissionOverrides'
              then jsonb_build_object('permissionOverrides',
                                      old.details -> 'permissionOverrides')
              else '{}'::jsonb end;
  elsif v_is_self then
    if coalesce(new.details, '{}'::jsonb) ? 'notifications' then
      v_details := v_details || jsonb_build_object(
        'notifications', new.details -> 'notifications');
    end if;
  end if;

  if not v_can_manage then
    foreach v_key in array c_managed_keys loop
      if coalesce(old.details, '{}'::jsonb) ? v_key then
        v_details := v_details || jsonb_build_object(
          v_key, old.details -> v_key);
      else
        v_details := v_details - v_key;
      end if;
    end loop;
  end if;

  if v_can_payroll and coalesce(new.details, '{}'::jsonb) ? 'payroll' then
    v_details := v_details || jsonb_build_object('payroll', new.details -> 'payroll');
  elsif v_can_payroll and not (coalesce(new.details, '{}'::jsonb) ? 'payroll') then
    v_details := v_details - 'payroll';
  end if;

  if v_can_roles and coalesce(new.details, '{}'::jsonb) ? 'permissionOverrides' then
    v_details := v_details || jsonb_build_object(
      'permissionOverrides', new.details -> 'permissionOverrides');
  elsif v_can_roles and not (coalesce(new.details, '{}'::jsonb) ? 'permissionOverrides') then
    v_details := v_details - 'permissionOverrides';
  end if;

  new.details := v_details;
  return new;
end;
$$;


ALTER FUNCTION "private"."enforce_staff_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."enforce_template_role_uniqueness"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_clash text;
begin
  if (select auth.jwt()->>'sub') is null then
    return new;
  end if;
  if new.status <> 'active' or array_length(new.applies_to_roles, 1) is null then
    return new;
  end if;
  select string_agg(distinct r, ', ')
    into v_clash
    from public.onboarding_templates t,
         lateral unnest(t.applies_to_roles) r
   where t.facility_id = new.facility_id
     and t.id <> new.id
     and t.status = 'active'
     and r = any (new.applies_to_roles);
  if v_clash is not null then
    raise exception
      'Another active template already covers: %. A role can have only one active onboarding template.',
      v_clash using errcode = '23505';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."enforce_template_role_uniqueness"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."estimate_before_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_settings jsonb;
  v_prefix text;
  v_digits int;
  v_floor int;
begin
  -- A client's estimate belongs to the client's facility, whatever was sent.
  if new.client_id is not null then
    select facility_id into new.facility_id
      from public.clients where id = new.client_id;
    if new.facility_id is null then
      raise exception 'no such client' using errcode = '23503';
    end if;
  end if;

  if cardinality(new.pet_ids) > 0 then
    if new.client_id is null then
      raise exception 'A guest estimate names no pets on file.' using errcode = '23514';
    end if;
    if exists (
      select 1 from unnest(new.pet_ids) as p(id)
       where not exists (
         select 1 from public.pets x where x.id = p.id and x.client_id = new.client_id
       )
    ) then
      raise exception 'Every pet on an estimate must be the client''s.' using errcode = '23514';
    end if;
  end if;

  -- One number at a time per facility.
  perform pg_advisory_xact_lock(hashtext('estimates:' || new.facility_id::text));

  select value into v_settings
    from public.facility_settings
   where facility_id = new.facility_id and domain = 'estimate_settings';
  v_prefix := coalesce(nullif(v_settings->>'estimateNumberPrefix', ''), 'E');
  v_digits := greatest(1, least(12, coalesce((v_settings->>'minDigits')::int, 5)));
  -- The default prefix has always started at E10001; a facility's own prefix
  -- starts its own sequence at 1.
  v_floor := case when v_prefix = 'E' then 10000 else 0 end;

  select greatest(coalesce(max(seq), 0), v_floor) + 1 into new.seq
    from public.estimates where facility_id = new.facility_id;
  -- Padded to AT LEAST the width. lpad alone truncates a longer number.
  new.estimate_number := v_prefix ||
    case when length(new.seq::text) >= v_digits then new.seq::text
         else lpad(new.seq::text, v_digits, '0') end;

  new.created_at := now();
  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "private"."estimate_before_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."estimate_before_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  new.facility_id := old.facility_id;
  new.seq := old.seq;
  new.estimate_number := old.estimate_number;
  new.token := old.token;
  new.created_by := old.created_by;
  new.created_by_name := old.created_by_name;
  new.created_at := old.created_at;
  -- A client's estimate cannot be moved to another client's name.
  if old.client_id is not null and new.client_id is distinct from old.client_id then
    raise exception 'An estimate cannot be moved to another client.' using errcode = '23514';
  end if;
  new.updated_at := now();
  return new;
end;
$$;


