CREATE OR REPLACE FUNCTION "private"."guard_location_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_bookings bigint;
begin
  if not exists (select 1 from public.facilities f where f.id = old.facility_id) then
    return old;
  end if;

  select count(*) into v_bookings
    from public.bookings b
   where b.location_id = old.id;

  if v_bookings > 0 then
    raise exception using
      errcode = 'restrict_violation',
      message = format(
        'This location has %s booking(s) recorded against it and cannot be deleted.',
        v_bookings
      ),
      hint = 'Set its status to inactive. The branch stops taking work and its history stays readable.';
  end if;

  if old.is_primary
     and exists (
       select 1 from public.locations l
        where l.facility_id = old.facility_id
          and l.id <> old.id
     )
  then
    raise exception using
      errcode = 'restrict_violation',
      message = 'The primary location cannot be deleted while other locations exist.',
      hint = 'Make another location primary first.';
  end if;

  return old;
end;
$$;


ALTER FUNCTION "private"."guard_location_delete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."guard_request_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_may_decide boolean;
  v_permission text := case tg_argv[0]
                         when 'time_off'     then 'scheduling_approve_time_off'
                         when 'availability' then 'scheduling_manage_availability'
                         else 'scheduling_approve_swaps'
                       end;
begin
  if new.status = old.status then
    return new;
  end if;

  if old.status <> 'pending' then
    raise exception 'That request has already been %.', old.status
      using errcode = '22023';
  end if;

  v_may_decide := private.has_permission(new.facility_id, v_permission);

  if not v_may_decide and new.status <> 'cancelled' then
    raise exception 'You do not have permission to decide this request.'
      using errcode = '42501';
  end if;

  if new.status in ('approved', 'denied') then
    new.reviewed_by := coalesce(new.reviewed_by, (select auth.jwt() ->> 'sub'));
    new.reviewed_at := coalesce(new.reviewed_at, now());
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."guard_request_transition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."guard_swap_shape"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_requesting record;
  v_target     record;
begin
  select staff_id, facility_id into v_requesting
    from public.staff_shifts where id = new.requesting_shift_id;

  if v_requesting.facility_id is null then
    raise exception 'No such shift.' using errcode = 'P0002';
  end if;

  if v_requesting.facility_id <> new.facility_id then
    raise exception 'That shift belongs to another facility.'
      using errcode = '23514';
  end if;

  if v_requesting.staff_id is distinct from new.requesting_staff_id then
    raise exception 'You can only offer a shift you are assigned to.'
      using errcode = '23514';
  end if;

  if new.target_shift_id is not null then
    select staff_id, facility_id into v_target
      from public.staff_shifts where id = new.target_shift_id;

    if v_target.facility_id <> new.facility_id then
      raise exception 'That shift belongs to another facility.'
        using errcode = '23514';
    end if;

    if v_target.staff_id is distinct from new.target_staff_id then
      raise exception 'The shift you asked for is not assigned to that person.'
        using errcode = '23514';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."guard_swap_shape"() OWNER TO "postgres";


