CREATE OR REPLACE FUNCTION "private"."locations_single_primary"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.is_primary then
    perform set_config('yipyy.locations_demoting', '1', true);
    update public.locations
       set is_primary = false, updated_at = now()
     where facility_id = new.facility_id
       and id <> new.id
       and is_primary;
    perform set_config('yipyy.locations_demoting', '', true);
    return new;
  end if;

  if tg_op = 'UPDATE'
     and old.is_primary
     and coalesce(current_setting('yipyy.locations_demoting', true), '') <> '1'
     and not exists (
       select 1 from public.locations l
        where l.facility_id = new.facility_id
          and l.id <> new.id
          and l.is_primary
     )
  then
    raise exception using
      errcode = 'restrict_violation',
      message = 'A facility must have a primary location.',
      hint = 'Make another location primary; the current one is demoted automatically.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."locations_single_primary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."loyalty_apply_transaction"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_balance integer;
begin
  select a.points_balance into v_balance
    from public.loyalty_accounts a
   where a.id = new.account_id
     for update;

  if v_balance is null then
    raise exception 'That loyalty account does not exist.'
      using errcode = '23503';
  end if;

  if v_balance + new.points < 0 then
    raise exception
      'That account has % points and this would take %.',
      v_balance, -new.points
      using errcode = '23514';
  end if;

  perform set_config('app.loyalty_ledger_write', 'on', true);

  update public.loyalty_accounts a
     set points_balance           = a.points_balance + new.points,
         lifetime_points_earned   = a.lifetime_points_earned
                                      + greatest(new.points, 0),
         lifetime_points_redeemed = a.lifetime_points_redeemed
                                      + greatest(-new.points, 0),
         updated_at               = now()
   where a.id = new.account_id;

  perform set_config('app.loyalty_ledger_write', 'off', true);

  return new;
end;
$$;


ALTER FUNCTION "private"."loyalty_apply_transaction"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."loyalty_balances_come_from_the_ledger"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if coalesce(current_setting('app.loyalty_ledger_write', true), 'off') = 'on' then
    return new;
  end if;

  if new.points_balance is distinct from old.points_balance
     or new.lifetime_points_earned is distinct from old.lifetime_points_earned
     or new.lifetime_points_redeemed is distinct from old.lifetime_points_redeemed
  then
    raise exception
      'A points balance follows the ledger. Post a loyalty_transactions row instead.'
      using errcode = '0A000';
  end if;

  if new.credit_balance is distinct from old.credit_balance then
    raise exception
      'Account credit is granted by redeem_loyalty_points, not set directly.'
      using errcode = '0A000';
  end if;

  return new;
end;
$$;


