CREATE OR REPLACE FUNCTION "private"."merchant_application_status_is_not_yours"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.status is distinct from old.status
     and not private.is_platform_admin()
     and current_setting('role', true) is distinct from 'service_role'
  then
    if not (old.status in ('draft', 'more_info_needed')
            and new.status = 'withdrawn') then
      raise exception
        'The status of a merchant application is set by the review process, not by the applicant.'
        using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;


