CREATE OR REPLACE FUNCTION "private"."mirror_presence_to_booking"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking uuid := case when tg_op = 'DELETE' then old.booking_id else new.booking_id end;
  v_was_in  boolean := tg_op <> 'INSERT' and old.checked_in_at is not null;
  v_was_out boolean := tg_op <> 'INSERT' and old.checked_out_at is not null;
  v_is_in   boolean := tg_op <> 'DELETE' and new.checked_in_at is not null;
  v_is_out  boolean := tg_op <> 'DELETE' and new.checked_out_at is not null;
  v_status  public.booking_status;
  v_target  public.booking_status;
begin
  if v_was_in = v_is_in and v_was_out = v_is_out then
    return null;
  end if;

  select status into v_status from public.bookings where id = v_booking for update;
  if not found then
    return null;
  end if;

  if v_is_out and not v_was_out then
    if v_status in ('pending', 'confirmed', 'checked_in', 'in_progress', 'ready') then
      v_target := 'completed';
    end if;
  elsif v_was_out and not v_is_out and v_is_in then
    if v_status = 'completed' then
      v_target := 'checked_in';
    end if;
  elsif v_is_in and not v_was_in then
    if v_status in ('pending', 'confirmed') then
      v_target := 'checked_in';
    end if;
  elsif v_was_in and not v_is_in then
    if v_status in ('checked_in', 'in_progress', 'ready', 'completed') then
      v_target := 'confirmed';
    end if;
  end if;

  if v_target is null or v_target = v_status then
    return null;
  end if;

  perform set_config('yipyy.presence_sync', 'on', true);
  update public.bookings set status = v_target where id = v_booking;
  perform set_config('yipyy.presence_sync', '', true);
  return null;
end;
$$;


ALTER FUNCTION "private"."mirror_presence_to_booking"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."missing_required_forms"("p_facility_id" "uuid", "p_client_id" "uuid", "p_pet_ids" "uuid"[], "p_service" "text", "p_stage" "text") RETURNS TABLE("form_id" "uuid", "form_name" "text", "form_slug" "text", "pet_id" "uuid", "enforcement" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with req as (
    select f.id as form_id, f.name as form_name, f.slug as form_slug,
           f.repeat_per_pet,
           g->>'enforcement' as enforcement,
           case
             when jsonb_typeof(r->'petTypes') = 'array'
              and jsonb_array_length(r->'petTypes') > 0
             then array(select lower(x) from jsonb_array_elements_text(r->'petTypes') x)
           end as pet_types
      from public.facility_settings s
      cross join lateral jsonb_array_elements(
        case when jsonb_typeof(s.value->'services') = 'array'
             then s.value->'services' else '[]'::jsonb end) svc
      cross join lateral jsonb_array_elements(
        case when jsonb_typeof(svc->'requirements') = 'array'
             then svc->'requirements' else '[]'::jsonb end) r
      cross join lateral jsonb_array_elements(
        case when jsonb_typeof(r->'gates') = 'array'
             then r->'gates' else '[]'::jsonb end) g
      join public.forms f
        on f.id::text = r->>'formId' and f.facility_id = s.facility_id
     where s.facility_id = p_facility_id
       and s.domain = 'form_requirements'
       and svc->>'serviceType' = p_service
       and coalesce(r->>'enabled', 'true') <> 'false'
       and g->>'stage' = p_stage
       and g->>'enforcement' in ('block', 'warn')
       and f.status = 'published'
       and exists (select 1 from public.form_versions v
                    where v.form_id = f.id and v.published_at is not null)
  ),
  booked as (
    select p.id as pet_id, lower(p.species) as species
      from public.pets p
     where p.id = any(coalesce(p_pet_ids, '{}'::uuid[]))
       and p.client_id = p_client_id
  ),
  needed as (
    select rq.form_id, rq.form_name, rq.form_slug, null::uuid as pet_id, rq.enforcement
      from req rq
     where (not rq.repeat_per_pet or not exists (select 1 from booked))
       and (rq.pet_types is null
            or exists (select 1 from booked b where b.species = any(rq.pet_types)))
    union all
    select rq.form_id, rq.form_name, rq.form_slug, b.pet_id, rq.enforcement
      from req rq
      join booked b on rq.pet_types is null or b.species = any(rq.pet_types)
     where rq.repeat_per_pet
  )
  select distinct on (n.form_id, n.pet_id)
         n.form_id, n.form_name, n.form_slug, n.pet_id, n.enforcement
    from needed n
   where not exists (
     select 1 from public.form_submissions fs
      where fs.form_id = n.form_id
        and fs.client_id = p_client_id
        and fs.status in ('submitted', 'reviewed', 'flagged')
        and (n.pet_id is null or fs.pet_id = n.pet_id)
   )
   order by n.form_id, n.pet_id, (n.enforcement = 'block') desc;
$$;


ALTER FUNCTION "private"."missing_required_forms"("p_facility_id" "uuid", "p_client_id" "uuid", "p_pet_ids" "uuid"[], "p_service" "text", "p_stage" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."note_facility"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_facility uuid;
begin
  v_facility := case new.category
    when 'pet'            then (select facility_id from public.pets      where id = new.entity_id)
    when 'customer'       then (select facility_id from public.clients   where id = new.entity_id)
    when 'booking'        then (select facility_id from public.bookings  where id = new.entity_id)
    when 'incident'       then (select facility_id from public.incidents where id = new.entity_id)
    when 'internal_staff' then (select facility_id from public.staff     where id = new.entity_id)
  end;
  if v_facility is null then
    raise exception 'That % does not exist.', new.category using errcode = '23503';
  end if;
  new.facility_id := v_facility;
  if tg_op = 'UPDATE' then
    new.updated_at := now();
  end if;
  return new;
end;
$$;


