CREATE OR REPLACE FUNCTION "private"."protect_last_facility_admin"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if old.access_level <> 'admin'::public.facility_access_level
     or not old.is_active then
    return coalesce(new, old);
  end if;

  if tg_op = 'UPDATE'
     and new.access_level = 'admin'::public.facility_access_level
     and new.is_active then
    return new;
  end if;

  if tg_op = 'DELETE'
     and not exists (select 1 from public.facilities where id = old.facility_id) then
    return old;
  end if;

  if not exists (
    select 1 from public.facility_memberships m
     where m.facility_id   = old.facility_id
       and m.id           <> old.id
       and m.is_active
       and m.access_level  = 'admin'::public.facility_access_level
  ) then
    raise exception
      'That is the last admin of this facility. Promote somebody else first.'
      using errcode = '42501';
  end if;

  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "private"."protect_last_facility_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."published_form_version_is_frozen"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  if old.published_at is null then
    return new;
  end if;

  if new.schema         is distinct from old.schema
     or new.form_id     is distinct from old.form_id
     or new.facility_id is distinct from old.facility_id
     or new.version_number is distinct from old.version_number
     or new.published_at   is distinct from old.published_at
     or new.created_at     is distinct from old.created_at
  then
    raise exception
      'That form version is published and cannot be changed. Somebody may already have answered it - publish a new version instead.'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


