CREATE OR REPLACE FUNCTION "private"."purge_boarding_evidence"("p_application_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_status text;
  v_gone   integer := 0;
begin
  select status into v_status
    from public.merchant_applications where id = p_application_id;

  if v_status is null then
    raise exception 'No such application.' using errcode = '42704';
  end if;

  if v_status not in ('approved', 'rejected', 'withdrawn') then
    raise exception 'An application still in progress cannot be purged.'
      using errcode = '42501';
  end if;

  delete from vault.secrets
   where name like format('boarding:%s:%%', p_application_id);
  get diagnostics v_gone = row_count;

  update public.merchant_applications
     set bank_secret_id = null, purged_at = now()
   where id = p_application_id;

  update public.merchant_application_principals
     set national_id_secret_id = null
   where application_id = p_application_id;

  update public.merchant_application_documents
     set purged_at = now()
   where application_id = p_application_id and purged_at is null;

  return v_gone;
end;
$$;


ALTER FUNCTION "private"."purge_boarding_evidence"("p_application_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."record_audit"("p_action" "text", "p_category" "text", "p_severity" "text" DEFAULT 'Low'::"text", "p_entity_type" "text" DEFAULT NULL::"text", "p_entity_id" "text" DEFAULT NULL::"text", "p_entity_name" "text" DEFAULT NULL::"text", "p_facility_id" "uuid" DEFAULT NULL::"uuid", "p_facility_name" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_changes" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user text := (select auth.jwt()->>'sub');
  v_name text;
  v_role text;
  v_id   uuid;
begin
  select p.full_name,
         case when p.is_platform_admin then 'Platform' else 'User' end
    into v_name, v_role
    from public.profiles p
   where p.id = v_user;

  insert into public.audit_log (
    user_id, user_name, user_role,
    action, category, severity,
    entity_type, entity_id, entity_name,
    facility_id, facility_name, description, changes)
  values (
    v_user, coalesce(v_name, v_user), coalesce(v_role, 'System'),
    p_action, p_category, p_severity,
    p_entity_type, p_entity_id, p_entity_name,
    p_facility_id, p_facility_name, p_description, coalesce(p_changes, '[]'::jsonb))
  returning id into v_id;

  return v_id;
end;
$$;


