CREATE OR REPLACE FUNCTION "private"."record_grant_for_staff"("p_staff" "public"."staff", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id         uuid;
  v_profile_id text;
  v_claimed    integer := 0;
begin
  if (select auth.jwt()->>'sub') is null then
    raise exception 'You must be signed in to invite staff.'
      using errcode = '42501';
  end if;

  if p_staff.id is null then
    raise exception 'No staff record to grant a membership to.'
      using errcode = '22023';
  end if;

  if not private.has_permission(p_staff.facility_id, 'manage_staff')
     and not private.is_platform_admin() then
    raise exception 'You may not invite staff at this facility.'
      using errcode = '42501';
  end if;

  if coalesce(trim(p_staff.email), '') = '' then
    raise exception 'That staff member has no email address to invite.'
      using errcode = '22023';
  end if;

  insert into public.facility_membership_grants
    (facility_id, staff_id, email, role, access_level, granted_by, expires_at)
  values (p_staff.facility_id, p_staff.id, lower(trim(p_staff.email)),
          p_staff.primary_role, p_staff.access_level,
          (select auth.jwt()->>'sub'), p_expires_at)
  on conflict (staff_id) do update
    set email        = excluded.email,
        role         = excluded.role,
        access_level = excluded.access_level,
        granted_by   = excluded.granted_by,
        expires_at   = excluded.expires_at,
        created_at   = now(),
        claimed_at         = null,
        claimed_profile_id = null
  returning id into v_id;

  update public.staff
     set status = case
                    when p_staff.primary_role = 'owner'::public.facility_staff_role
                      then 'active'
                    else 'invited'
                  end,
         status_changed_at = now()
   where id = p_staff.id;

  select p.id into v_profile_id
    from public.profiles p
   where lower(p.email) = lower(trim(p_staff.email))
   limit 1;

  if v_profile_id is not null then
    v_claimed := private.claim_grants_for(v_profile_id, p_staff.email);
  end if;

  return jsonb_build_object(
    'grantId',     v_id,
    'staffId',     p_staff.legacy_id,
    'facilityId',  p_staff.facility_id,
    'email',       lower(trim(p_staff.email)),
    'role',        p_staff.primary_role,
    'accessLevel', p_staff.access_level,
    'claimed',     v_claimed > 0);
end;
$$;


ALTER FUNCTION "private"."record_grant_for_staff"("p_staff" "public"."staff", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."ref_sequence_follows_explicit_values"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_seq  text;
  v_max  bigint;
  v_last bigint;
begin
  select max(ref) into v_max from inserted;
  if v_max is null then
    return null;
  end if;

  v_seq := pg_catalog.pg_get_serial_sequence(
    tg_table_schema || '.' || tg_table_name, 'ref');
  if v_seq is null then
    return null;
  end if;

  execute format('select last_value from %s', v_seq) into v_last;

  if v_max > v_last then
    perform setval(v_seq, greatest(v_max, v_last), true);
  end if;

  return null;
end;
$$;


ALTER FUNCTION "private"."ref_sequence_follows_explicit_values"() OWNER TO "postgres";


COMMENT ON FUNCTION "private"."ref_sequence_follows_explicit_values"() IS 'Advance a table''s `ref` identity sequence past any explicitly supplied value. Statement-level; the trigger must declare `referencing new table as inserted`.';



CREATE OR REPLACE FUNCTION "private"."resolve_permission"("p_membership_id" "uuid", "p_permission" "text") RETURNS "public"."access_scope"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with m as (
    select fm.id, fm.facility_id, fm.role
      from public.facility_memberships fm
     where fm.id = p_membership_id
  ),
  s as (
    select st.id, st.primary_role, st.additional_roles
      from public.staff st
      join m on m.id = st.membership_id
  ),
  held_roles as (
    select m.role as role from m
     union
    select s.primary_role from s
     union
    select unnest(s.additional_roles) from s
  ),
  preset_scopes as (
    select coalesce(
             (select frp.scope
                from public.facility_role_permissions frp
               where frp.facility_id    = (select facility_id from m)
                 and frp.role           = hr.role
                 and frp.permission_key = p_permission),
             (select rpp.scope
                from public.role_preset_permissions rpp
               where rpp.role           = hr.role
                 and rpp.permission_key = p_permission)
           ) as scope
      from held_roles hr
  ),
  custom_scopes as (
    select cp.scope
      from public.staff_custom_roles scr
      join s on s.id = scr.staff_id
      join public.facility_custom_role_permissions cp
        on cp.custom_role_id = scr.custom_role_id
     where cp.permission_key = p_permission
  ),
  role_scopes as (
    select scope from preset_scopes
     union all
    select scope from custom_scopes
  )
  select coalesce(
    (select mp.scope
       from public.membership_permissions mp
      where mp.membership_id  = p_membership_id
        and mp.permission_key = p_permission),
    (select sp.scope
       from public.staff_permissions sp
       join s on s.id = sp.staff_id
      where sp.permission_key = p_permission),
    (select rs.scope
       from role_scopes rs
      where rs.scope is not null
        and rs.scope <> 'none'::public.access_scope
      order by case rs.scope
                 when 'anytime'         then 3
                 when 'operating_hours' then 2
                 when 'assigned_shifts' then 1
                 else 0
               end desc
      limit 1)
  );
$$;


ALTER FUNCTION "private"."resolve_permission"("p_membership_id" "uuid", "p_permission" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."resolve_permission"("p_membership_id" "uuid", "p_permission" "text") IS 'Effective scope for one membership and one permission. Account override, then person override (both absolute, including a stored ''none''), then the widest scope across every role held — preset roles and custom roles alike. NULL means not granted. The SQL twin of resolvePermission() in src/types/facility-staff.ts.';



CREATE OR REPLACE FUNCTION "private"."retail_product_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  new.updated_at := now();
  if tg_op = 'UPDATE' then
    new.facility_id := old.facility_id;
    new.created_by := old.created_by;
    new.created_at := old.created_at;
    if coalesce(current_setting('yipyy.stock_write', true), '') <> 'on' then
      new.stock := old.stock;
      -- A variant that already existed keeps its count; a new one starts at
      -- what it was given.
      new.variants := coalesce((
        select jsonb_agg(
                 case when o.v is not null
                      then jsonb_set(n.v, '{stock}', coalesce(o.v->'stock', '0'::jsonb))
                      else n.v end
                 order by n.ord)
          from jsonb_array_elements(new.variants) with ordinality as n(v, ord)
          left join lateral (
            select x.v from jsonb_array_elements(old.variants) as x(v)
             where x.v->>'id' = n.v->>'id' limit 1
          ) o on true
      ), '[]'::jsonb);
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."retail_product_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."retail_product_opening"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v jsonb;
begin
  if jsonb_array_length(new.variants) = 0 then
    if new.stock <> 0 then
      insert into public.retail_stock_movements
        (facility_id, product_id, delta, reason, note, author_name)
      values (new.facility_id, new.id, new.stock, 'opening', 'Opening count', 'Staff');
    end if;
  else
    for v in select * from jsonb_array_elements(new.variants) loop
      if coalesce((v->>'stock')::integer, 0) <> 0 then
        insert into public.retail_stock_movements
          (facility_id, product_id, variant_id, delta, reason, note, author_name)
        values (new.facility_id, new.id, v->>'id', (v->>'stock')::integer,
                'opening', 'Opening count', 'Staff');
      end if;
    end loop;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."retail_product_opening"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."retail_sale_discount_is_permitted"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_promo numeric;
begin
  if new.discount_total <= 0 then
    return null;
  end if;
  if current_setting('role', true) = 'service_role' then
    return null;
  end if;

  select coalesce(sum(amount), 0) into v_promo
    from public.promo_code_redemptions
   where retail_sale_id = new.id;

  if new.discount_total - v_promo > 0.005
     and not private.has_permission(new.facility_id, 'retail_apply_discount') then
    raise exception 'Not allowed to discount a sale at this facility.'
      using errcode = '42501', hint = 'discount_not_permitted';
  end if;

  return null;
end;
$$;


ALTER FUNCTION "private"."retail_sale_discount_is_permitted"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."retail_sale_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'UPDATE' then
    if (new.facility_id, new.number, new.client_id, new.items, new.subtotal,
        new.discount_total, new.tax_total, new.tip, new.total, new.tender,
        new.payment_ids, new.created_at, new.created_by)
       is distinct from
       (old.facility_id, old.number, old.client_id, old.items, old.subtotal,
        old.discount_total, old.tax_total, old.tip, old.total, old.tender,
        old.payment_ids, old.created_at, old.created_by) then
      raise exception 'A sale is changed by a return, not an edit.'
        using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."retail_sale_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."retail_stock_apply"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_facility uuid;
begin
  select facility_id into v_facility from public.retail_products where id = new.product_id;
  if v_facility is null or v_facility <> new.facility_id then
    raise exception 'That product is not this facility''s.' using errcode = '42501';
  end if;
  if new.reason = 'opening' then
    return new;  -- the count was set by the product row itself
  end if;
  perform set_config('yipyy.stock_write', 'on', true);
  if new.variant_id is null or new.variant_id = '' then
    update public.retail_products set stock = stock + new.delta
     where id = new.product_id;
  else
    update public.retail_products set variants = (
      select coalesce(jsonb_agg(
               case when v->>'id' = new.variant_id
                    then jsonb_set(v, '{stock}',
                           to_jsonb(coalesce((v->>'stock')::integer, 0) + new.delta))
                    else v end
               order by ord), '[]'::jsonb)
        from jsonb_array_elements(variants) with ordinality as x(v, ord)
    )
    where id = new.product_id;
  end if;
  perform set_config('yipyy.stock_write', 'off', true);
  return new;
end;
$$;


