CREATE OR REPLACE FUNCTION "private"."staff_commission_rate"("p_staff_id" "uuid", "p_service" "text") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  select coalesce(
    -- A per-module override wins, matched case-insensitively because
    -- `bookings.service` is free text ('Boarding') and the payroll form
    -- stores a module key ('boarding').
    (select (o ->> 'commission')::numeric
       from public.staff s,
            lateral jsonb_array_elements(
              case
                when jsonb_typeof(s.details -> 'payroll' -> 'overrides') = 'array'
                  then s.details -> 'payroll' -> 'overrides'
                else '[]'::jsonb
              end
            ) as o
      where s.id = p_staff_id
        and lower(o ->> 'serviceModule') = lower(coalesce(p_service, ''))
        and (o ->> 'commission') ~ '^[0-9]+(\.[0-9]+)?$'
      limit 1),
    (select (s.details -> 'payroll' ->> 'generalServiceCommission')::numeric
       from public.staff s
      where s.id = p_staff_id
        and (s.details -> 'payroll' ->> 'generalServiceCommission')
              ~ '^[0-9]+(\.[0-9]+)?$'),
    0
  );
$_$;


ALTER FUNCTION "private"."staff_commission_rate"("p_staff_id" "uuid", "p_service" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."staff_commission_rate"("p_staff_id" "uuid", "p_service" "text") IS 'The percentage this member of staff earns on this service: a per-module override, else generalServiceCommission, else 0. A malformed value reads as absent rather than as an error — payroll must not stop a booking being saved.';



