CREATE OR REPLACE FUNCTION "private"."submitted_answers_are_final"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  -- A draft the customer has not sent yet is still theirs to change.
  if old.status = 'draft' then
    return new;
  end if;

  if new.answers is distinct from old.answers then
    raise exception
      'Those answers have been submitted and cannot be edited. They are the record of what the person said.'
      using errcode = '42501';
  end if;

  if new.form_version_id is distinct from old.form_version_id
     or new.submitted_at is distinct from old.submitted_at
     or new.submitted_by is distinct from old.submitted_by
  then
    raise exception
      'A submission cannot be re-dated or re-versioned. Only its review state changes.'
      using errcode = '42501';
  end if;

  if new.client_id is distinct from old.client_id then
    -- The one permitted transition: nobody -> somebody.
    if old.client_id is not null then
      raise exception
        'These answers are already filed under a customer. They cannot be moved to another one.'
        using errcode = '42501';
    end if;

    if new.client_id is null then
      raise exception
        'A submission cannot be un-filed once it has been attached to a customer.'
        using errcode = '42501';
    end if;

    if not private.has_permission(new.facility_id, 'edit_clients') then
      raise exception
        'Filing answers under a customer changes their record, which needs permission to edit clients.'
        using errcode = '42501';
    end if;

    if not exists (
      select 1 from public.clients c
       where c.id = new.client_id
         and c.facility_id = new.facility_id
    ) then
      raise exception
        'That customer belongs to a different facility.'
        using errcode = '42501';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."submitted_answers_are_final"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."sync_boarding_stay"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_last integer;
begin
  if new.status in ('cancelled', 'no_show') then
    update public.boarding_stays
       set released_at = coalesce(released_at, now()), updated_at = now()
     where booking_id = new.id;
  elsif old.status in ('cancelled', 'no_show') then
    update public.boarding_stays
       set released_at = null, updated_at = now()
     where booking_id = new.id;
  end if;

  if new.start_at is distinct from old.start_at
     or new.end_at is distinct from old.end_at
  then
    select max(segment_order) into v_last
      from public.boarding_stays where booking_id = new.id;

    if v_last is null then
      return new;
    elsif v_last = 1 then
      update public.boarding_stays
         set occupies = tstzrange(new.start_at, new.end_at, '[)'), updated_at = now()
       where booking_id = new.id;
    else
      -- The first stay starts at the arrival and the last ends at the
      -- departure; the transfers between them are the staff's decisions and
      -- stay where they were put. A new range that would leave a stay with
      -- no night is refused: which kennel loses the night is not for a
      -- trigger to guess.
      if new.start_at >= (select upper(occupies) from public.boarding_stays
                           where booking_id = new.id and segment_order = 1)
         or new.end_at <= (select lower(occupies) from public.boarding_stays
                           where booking_id = new.id and segment_order = v_last)
      then
        raise exception
          'This stay moves kennels part-way. Change the move first, then the dates.'
          using errcode = '22023', hint = 'split_stay_dates';
      end if;
      update public.boarding_stays
         set occupies = tstzrange(new.start_at, upper(occupies), '[)'), updated_at = now()
       where booking_id = new.id and segment_order = 1;
      update public.boarding_stays
         set occupies = tstzrange(lower(occupies), new.end_at, '[)'), updated_at = now()
       where booking_id = new.id and segment_order = v_last;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."sync_boarding_stay"() OWNER TO "postgres";


COMMENT ON FUNCTION "private"."sync_boarding_stay"() IS 'Mirrors a booking''s cancellation and dates onto its boarding stay, so the exclusion constraint always judges the current range and cancelled stays free their room.';



CREATE OR REPLACE FUNCTION "private"."sync_grooming_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_apt      public.grooming_appointments;
  v_add_mins integer;
begin
  select * into v_apt from public.grooming_appointments where booking_id = new.id;
  if v_apt.booking_id is null then
    return null;
  end if;

  if new.status is not distinct from old.status then
    return null;
  end if;

  if new.status in ('in_progress', 'ready')
     and v_apt.check_in_at is null
     and new.status is distinct from old.status
     and old.status not in ('in_progress', 'ready')
  then
    raise exception 'This pet has not been checked in yet.' using errcode = '42501';
  end if;

  if new.status = 'checked_in' and v_apt.check_in_at is null then
    select coalesce(sum(duration_min), 0) into v_add_mins
      from public.grooming_appointment_add_ons where booking_id = new.id;

    update public.grooming_appointments
       set check_in_at = now(),
           estimated_ready_at =
             now() + make_interval(mins => v_apt.service_duration_min + v_add_mins)
     where booking_id = new.id;

  elsif new.status = 'completed' and v_apt.check_out_at is null then
    update public.grooming_appointments set check_out_at = now() where booking_id = new.id;

  elsif new.status in ('confirmed', 'pending')
        and (v_apt.check_in_at is not null or v_apt.check_out_at is not null) then
    -- Back to before arrival: the pet is not here, so it has no arrival, no
    -- ready time and no collection. It only ever cleared the collection.
    update public.grooming_appointments
       set check_in_at = null, estimated_ready_at = null, check_out_at = null
     where booking_id = new.id;

  elsif new.status in ('checked_in', 'in_progress')
        and v_apt.check_out_at is not null then
    update public.grooming_appointments set check_out_at = null where booking_id = new.id;
  end if;

  return null;
end;
$$;


ALTER FUNCTION "private"."sync_grooming_lifecycle"() OWNER TO "postgres";


COMMENT ON FUNCTION "private"."sync_grooming_lifecycle"() IS 'Stamps grooming check-in/check-out from the booking status and derives the ready ETA. No-ops for non-grooming bookings.';



CREATE OR REPLACE FUNCTION "private"."sync_offboarding_completion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_instance uuid := coalesce(new.instance_id, old.instance_id);
  v_total    integer;
  v_done     integer;
begin
  select count(*), count(*) filter (where completed_at is not null)
    into v_total, v_done
    from public.offboarding_task_states
   where instance_id = v_instance;

  update public.offboarding_instances i
     set completed_at = case
           when v_total > 0 and v_done = v_total
             then coalesce(i.completed_at, now())
           else null
         end
   where i.id = v_instance
     and i.completed_at is distinct from (case
           when v_total > 0 and v_done = v_total
             then coalesce(i.completed_at, now())
           else null
         end);

  return null;
end;
$$;


ALTER FUNCTION "private"."sync_offboarding_completion"() OWNER TO "postgres";


COMMENT ON FUNCTION "private"."sync_offboarding_completion"() IS 'Derives offboarding_instances.completed_at from its task rows. Sets it when every task is done, clears it when one is reopened.';



