CREATE OR REPLACE FUNCTION "private"."task_owner_moves_status_only"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  -- A CASCADE IS NOT A REASSIGNMENT. `staff.on delete set null` arrives here as
  -- an UPDATE, and a guard that refuses it makes the staff row undeletable —
  -- exactly how `audit_log.facility_id` made facilities undeletable.
  if new.assigned_to is null
     and old.assigned_to is not null
     and not exists (select 1 from public.staff s where s.id = old.assigned_to)
  then
    return new;
  end if;

  if private.has_permission(new.facility_id, 'ops_manage_tasks') then
    return new;
  end if;

  if new.title            is distinct from old.title
     or new.description   is distinct from old.description
     or new.category      is distinct from old.category
     or new.priority      is distinct from old.priority
     or new.assigned_to   is distinct from old.assigned_to
     or new.due_at        is distinct from old.due_at
     or new.estimated_minutes is distinct from old.estimated_minutes
     or new.requires_photo    is distinct from old.requires_photo
     or new.requires_signoff  is distinct from old.requires_signoff
     or new.source        is distinct from old.source
     or new.source_ref    is distinct from old.source_ref
     or new.template_id   is distinct from old.template_id
     or new.facility_id   is distinct from old.facility_id
  then
    raise exception
      'You can update the progress of a task assigned to you, but not what it asks for or who it belongs to.'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."task_owner_moves_status_only"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."tip_attribution_mode"("p_facility_id" "uuid", "p_service" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- The service's own rule, then the facility default, then 'assigned' — which
  -- matches DEFAULT_TIP_ATTRIBUTION in src/lib/settings/domains.ts. A facility
  -- that has never opened the screen has no row here at all, and must behave
  -- exactly like one that opened it and changed nothing.
  select coalesce(
    nullif(s.value #>> array['byService', p_service, 'mode'], ''),
    nullif(s.value ->> 'defaultMode', ''),
    'assigned'
  )
    from public.facility_settings s
   where s.facility_id = p_facility_id
     and s.domain = 'tip_attribution'
  limit 1;
$$;


ALTER FUNCTION "private"."tip_attribution_mode"("p_facility_id" "uuid", "p_service" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."tip_attribution_mode"("p_facility_id" "uuid", "p_service" "text") IS 'Which attribution rule applies to a service: the service own rule, else the facility default, else assigned.';



CREATE OR REPLACE FUNCTION "private"."tips_allocated_within_tips_taken"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking   uuid := coalesce(new.booking_id, old.booking_id);
  v_collected numeric(10,2);
  v_allocated numeric(10,2);
begin
  select coalesce(sum(p.tip), 0) into v_collected
    from public.payments p
   where p.booking_id = v_booking;

  select coalesce(sum(a.amount), 0) into v_allocated
    from public.booking_tip_allocations a
   where a.booking_id = v_booking;

  if v_allocated > v_collected + 0.005 then
    raise exception
      'Tips allocated (%) exceed the tips collected on this booking (%).',
      to_char(v_allocated, 'FM999999990.00'),
      to_char(v_collected, 'FM999999990.00')
      using errcode = '23514';
  end if;

  return null;
end $$;


