CREATE OR REPLACE FUNCTION "private"."training_note_from_pet"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_facility uuid;
  v_client   uuid;
begin
  select p.facility_id, p.client_id into v_facility, v_client
    from public.pets p where p.id = new.pet_id;
  if v_facility is null then
    raise exception 'training_notes: no such pet' using errcode = '23503';
  end if;
  new.facility_id := v_facility;
  if tg_op = 'INSERT' then
    new.client_id := v_client;
  else
    -- Neither moves after insert.
    new.client_id := old.client_id;
    new.pet_id := old.pet_id;
    new.facility_id := old.facility_id;
  end if;
  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "private"."training_note_from_pet"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."training_session_conditions_are_valid"("p_conditions" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select p_conditions is null or (
    jsonb_typeof(p_conditions) = 'object'
    and not exists (
      select 1 from jsonb_object_keys(p_conditions) k(key)
       where k.key not in ('weather', 'distractionLevel')
    )
    and (
      not (p_conditions ? 'weather')
      or (
        jsonb_typeof(p_conditions -> 'weather') = 'array'
        and jsonb_array_length(p_conditions -> 'weather') <= 6
        and not exists (
          select 1 from jsonb_array_elements(p_conditions -> 'weather') w(value)
           where jsonb_typeof(w.value) <> 'string'
              or (w.value #>> '{}') not in ('sunny', 'cloudy', 'rain', 'hot', 'cold', 'windy')
        )
      )
    )
    and (
      not (p_conditions ? 'distractionLevel')
      or (
        jsonb_typeof(p_conditions -> 'distractionLevel') = 'string'
        and (p_conditions ->> 'distractionLevel') in ('low', 'medium', 'high')
      )
    )
  );
$$;


ALTER FUNCTION "private"."training_session_conditions_are_valid"("p_conditions" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."unfinished_booking_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_facility uuid;
  v_staff boolean;
  v_service boolean := current_setting('role', true) = 'service_role';
begin
  if tg_op = 'INSERT' then
    select facility_id into v_facility from public.clients where id = new.client_id;
    if v_facility is null then
      raise exception 'No such client.' using errcode = '23503';
    end if;
    new.facility_id := v_facility;
    new.status := 'abandoned';
    new.notes := '[]'::jsonb;
    new.last_contacted_at := null;
    new.recovered_at := null;
    new.abandoned_at := now();
    new.created_at := now();
    new.updated_at := now();
    new.recovery_not_before := now();
    new.recovery_resolved_at := null;
    new.recovery_outcome := null;
    new.recovery_detail := null;
    return new;
  end if;

  new.id := old.id;
  new.facility_id := old.facility_id;
  new.client_id := old.client_id;
  new.created_at := old.created_at;

  if not v_service then
    -- The follow-up record is the tick's alone.
    new.recovery_resolved_at := old.recovery_resolved_at;
    new.recovery_outcome := old.recovery_outcome;
    new.recovery_detail := old.recovery_detail;
    new.recovery_not_before := old.recovery_not_before;
    new.abandoned_at := old.abandoned_at;
  end if;

  v_staff := private.is_platform_admin()
    or private.has_permission(old.facility_id, 'edit_bookings');
  if not v_staff and not v_service then
    -- A customer may re-save their draft or say they came back; the outreach
    -- record is the facility's.
    if new.status is distinct from old.status and new.status <> 'recovered' then
      raise exception 'Only the facility marks a booking as contacted.'
        using errcode = '42501';
    end if;
    new.notes := old.notes;
    new.last_contacted_at := old.last_contacted_at;

    -- Leaving the form again restarts the clock, until the one message is owed.
    if (new.draft is distinct from old.draft or new.step is distinct from old.step)
       and old.recovery_resolved_at is null then
      new.abandoned_at := now();
      new.recovery_not_before := now();
    end if;
  end if;

  if new.status = 'recovered' and old.status <> 'recovered' then
    new.recovered_at := now();
  elsif new.status <> 'recovered' then
    new.recovered_at := null;
  end if;
  if new.status = 'contacted' and old.status <> 'contacted' then
    new.last_contacted_at := now();
  end if;
  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "private"."unfinished_booking_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."waiver_signature_is_append_only"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  if old.revoked_at is not null then
    raise exception
      'That signature is already revoked. A signature is superseded by a new one, not edited.'
      using errcode = '42501';
  end if;

  if new.revoked_at is null then
    raise exception
      'waiver_signatures is append-only. The only change a signature accepts is being revoked.'
      using errcode = '42501';
  end if;

  if new.id                     is distinct from old.id
     or new.facility_id         is distinct from old.facility_id
     or new.waiver_id           is distinct from old.waiver_id
     or new.client_id           is distinct from old.client_id
     or new.pet_id              is distinct from old.pet_id
     or new.waiver_name         is distinct from old.waiver_name
     or new.waiver_version      is distinct from old.waiver_version
     or new.waiver_text         is distinct from old.waiver_text
     or new.waiver_hash         is distinct from old.waiver_hash
     or new.signature_name      is distinct from old.signature_name
     or new.signature_data      is distinct from old.signature_data
     or new.witness_name        is distinct from old.witness_name
     or new.witness_signature_data is distinct from old.witness_signature_data
     or new.ip_address          is distinct from old.ip_address
     or new.user_agent          is distinct from old.user_agent
     or new.signed_at           is distinct from old.signed_at
     or new.signed_by           is distinct from old.signed_by
     or new.expires_at          is distinct from old.expires_at
     or new.created_at          is distinct from old.created_at
  then
    raise exception
      'A signature records what a person agreed to and cannot be edited. Only revoking it is allowed.'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."waiver_signature_is_append_only"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."yipyy_go_deadline"("p_booking_id" "uuid") RETURNS timestamp with time zone
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select b.start_at - make_interval(
           hours => greatest(0, floor(coalesce((s.value -> 'timing' ->> 'deadline')::numeric, 0)))::int
         )
    from public.bookings b
    left join public.facility_settings s
      on s.facility_id = b.facility_id and s.domain = 'yipyy_go_config'
   where b.id = p_booking_id;
$$;


