CREATE OR REPLACE FUNCTION "private"."yipyy_go_stay_days"("p_booking" "public"."bookings") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when p_booking.service = 'boarding'
           then greatest(1, (timezone(z.tz, p_booking.end_at))::date - (timezone(z.tz, p_booking.start_at))::date)
           else greatest(1, (timezone(z.tz, p_booking.end_at))::date - (timezone(z.tz, p_booking.start_at))::date + 1)
         end
    from (
      select coalesce(
        (select nullif(f.timezone, '') from public.facilities f where f.id = p_booking.facility_id),
        'America/Toronto'
      ) as tz
    ) z;
$$;


ALTER FUNCTION "private"."yipyy_go_stay_days"("p_booking" "public"."bookings") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."yipyy_go_submission_derive"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_facility uuid;
  v_client   uuid;
begin
  if tg_op = 'UPDATE' then
    new.id          := old.id;
    new.facility_id := old.facility_id;
    new.client_id   := old.client_id;
    new.booking_id  := old.booking_id;
    new.pet_id      := old.pet_id;
    new.created_at  := old.created_at;
    new.updated_at  := now();
    return new;
  end if;

  select b.facility_id, b.client_id into v_facility, v_client
    from public.bookings b where b.id = new.booking_id;
  if not found then
    raise exception 'That booking does not exist.' using errcode = '23503';
  end if;
  if not exists (
    select 1 from public.booking_pets bp
     where bp.booking_id = new.booking_id and bp.pet_id = new.pet_id
  ) then
    raise exception 'That pet is not on this booking.' using errcode = '23514';
  end if;

  new.facility_id := v_facility;
  new.client_id   := v_client;
  new.created_at  := now();
  new.updated_at  := now();
  return new;
end;
$$;


ALTER FUNCTION "private"."yipyy_go_submission_derive"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."yipyy_go_write_charges"("p_booking_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking  public.bookings;
  v_settings jsonb;
  v_mode     text;
  v_fee      jsonb;
  v_days     integer;
  v_desired  jsonb := '{}'::jsonb;
  v_sub      public.yipyy_go_submissions;
  v_req      jsonb;
  v_offer    jsonb;
  v_price    record;
  v_key      text;
  v_qty      integer;
  v_charge   public.yipyy_go_charges;
  v_want     jsonb;
  v_line     uuid;
begin
  select * into v_booking from public.bookings where id = p_booking_id for update;
  if not found or v_booking.status::text in ('completed', 'cancelled', 'declined', 'no_show') then
    return;
  end if;

  select s.value into v_settings from public.facility_settings s
   where s.facility_id = v_booking.facility_id and s.domain = 'yipyy_go_config';
  v_mode := coalesce(v_settings ->> 'addOnsApproval', 'auto');
  v_fee := v_settings -> 'medicationFee';
  v_days := private.yipyy_go_stay_days(v_booking);

  for v_sub in
    select * from public.yipyy_go_submissions y
     where y.booking_id = p_booking_id
       and (y.status = 'approved' or (v_mode = 'auto' and y.status = 'submitted'))
     order by y.created_at
  loop
    for v_req in select e.value from jsonb_array_elements(v_sub.add_on_requests) e(value) loop
      continue when jsonb_typeof(v_req) <> 'object';
      v_offer := private.yipyy_go_offered_add_on(v_booking, v_req ->> 'addOnId');
      continue when v_offer is null;
      select * into v_price
        from private.yipyy_go_price_add_on(
               v_booking, v_offer,
               case when jsonb_typeof(v_req -> 'quantity') = 'number'
                    then floor((v_req ->> 'quantity')::numeric)::int else 1 end);
      continue when v_price.unit_price is null or v_price.unit_price <= 0;
      v_key := case when v_offer ->> 'petScope' = 'per_pet'
                    then 'addon:' || v_sub.id::text || ':' || (v_offer ->> 'id')
                    else 'addon:' || p_booking_id::text || ':' || (v_offer ->> 'id')
               end;
      -- An add-on charged per booking, asked for on two dogs, is one line.
      continue when v_desired ? v_key
                and (v_desired -> v_key ->> 'quantity')::int >= v_price.quantity;
      v_desired := v_desired || jsonb_build_object(v_key, jsonb_build_object(
        'kind', 'add_on',
        'addOnId', v_offer ->> 'id',
        'submissionId', v_sub.id,
        'name', left(v_offer ->> 'name', 200),
        'unitPrice', v_price.unit_price,
        'quantity', v_price.quantity));
    end loop;

    if coalesce((v_fee ->> 'enabled')::boolean, false)
       and jsonb_typeof(v_fee -> 'amount') = 'number'
       and (v_fee ->> 'amount')::numeric > 0
       and not coalesce((v_sub.answers ->> 'noMedications')::boolean, false)
       and jsonb_typeof(v_sub.answers -> 'medications') = 'array'
       and jsonb_array_length(v_sub.answers -> 'medications') > 0
    then
      v_qty := case v_fee ->> 'billing'
                 when 'per_stay' then 1
                 when 'per_day' then v_days
                 else private.yipyy_go_medication_doses(v_sub.answers, v_days)
               end;
      if v_qty > 0 then
        v_desired := v_desired || jsonb_build_object('medfee:' || v_sub.id::text, jsonb_build_object(
          'kind', 'medication_fee',
          'addOnId', null,
          'submissionId', v_sub.id,
          'name', left(coalesce(nullif(btrim(v_fee ->> 'label'), ''), 'Medication fee'), 200),
          'unitPrice', round((v_fee ->> 'amount')::numeric, 2),
          'quantity', v_qty));
      end if;
    end if;
  end loop;

  for v_charge in
    select * from public.yipyy_go_charges c where c.booking_id = p_booking_id for update
  loop
    v_want := v_desired -> v_charge.charge_key;
    if v_want is null then
      if v_charge.line_item_id is not null then
        delete from public.booking_line_items where id = v_charge.line_item_id;
      end if;
      delete from public.yipyy_go_charges where id = v_charge.id;
    elsif v_charge.line_item_id is not null
      and (v_charge.unit_price <> (v_want ->> 'unitPrice')::numeric
           or v_charge.quantity <> (v_want ->> 'quantity')::int)
    then
      update public.booking_line_items
         set unit_price = (v_want ->> 'unitPrice')::numeric,
             quantity = (v_want ->> 'quantity')::int
       where id = v_charge.line_item_id;
      update public.yipyy_go_charges
         set unit_price = (v_want ->> 'unitPrice')::numeric,
             quantity = (v_want ->> 'quantity')::int,
             submission_id = (v_want ->> 'submissionId')::uuid,
             updated_at = now()
       where id = v_charge.id;
    end if;
    -- A charge whose line staff removed (line_item_id is null) is left as it
    -- is: the form does not put it back.
    v_desired := v_desired - v_charge.charge_key;
  end loop;

  for v_key, v_want in select d.key, d.value from jsonb_each(v_desired) d loop
    insert into public.booking_line_items
      (booking_id, facility_id, kind, name, unit_price, quantity, source_id)
    values
      (p_booking_id, v_booking.facility_id,
       case when v_want ->> 'kind' = 'medication_fee' then 'fee' else 'item' end,
       v_want ->> 'name', (v_want ->> 'unitPrice')::numeric, (v_want ->> 'quantity')::int,
       'yipyy-go:' || v_key)
    returning id into v_line;

    insert into public.yipyy_go_charges
      (facility_id, booking_id, submission_id, kind, add_on_id, charge_key, name, unit_price, quantity, line_item_id)
    values
      (v_booking.facility_id, p_booking_id, (v_want ->> 'submissionId')::uuid, v_want ->> 'kind',
       v_want ->> 'addOnId', v_key, v_want ->> 'name', (v_want ->> 'unitPrice')::numeric,
       (v_want ->> 'quantity')::int, v_line);
  end loop;
end;
$$;


ALTER FUNCTION "private"."yipyy_go_write_charges"("p_booking_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_platform_invitation"("p_token_hash" "bytea", "p_profile_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_inv   public.platform_invitations;
  v_email text;
begin
  select * into v_inv from public.platform_invitations
   where token_hash = p_token_hash;

  if v_inv.id is null then
    raise exception 'That invitation link is not valid.' using errcode = 'no_data_found';
  end if;
  if v_inv.accepted_at is not null then
    raise exception 'That invitation has already been used.' using errcode = '42501';
  end if;
  if v_inv.expires_at <= now() then
    raise exception 'That invitation has expired.' using errcode = '42501';
  end if;

  select lower(email) into v_email from public.profiles where id = p_profile_id;
  if v_email is null then
    raise exception 'No such profile.' using errcode = 'no_data_found';
  end if;
  if v_email <> lower(v_inv.email) then
    raise exception 'That invitation was sent to a different address.'
      using errcode = '42501';
  end if;

  insert into public.platform_memberships (profile_id, role, granted_by)
  values (p_profile_id, v_inv.role, v_inv.invited_by)
  on conflict (profile_id) do nothing;

  update public.platform_invitations
     set accepted_at = now(), accepted_profile_id = p_profile_id
   where id = v_inv.id;

  return jsonb_build_object(
    'invitationId', v_inv.id,
    'profileId',    p_profile_id,
    'role',         v_inv.role);
end;
$$;


ALTER FUNCTION "public"."accept_platform_invitation"("p_token_hash" "bytea", "p_profile_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."active_platform_announcements"("p_facility_id" "uuid") RETURNS TABLE("id" "uuid", "title" "text", "body" "text", "priority" "text", "published_at" timestamp with time zone, "starts_at" timestamp with time zone, "read_at" timestamp with time zone, "dismissed_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select a.id, a.title, a.body, a.priority, a.published_at, a.starts_at,
         r.read_at, r.dismissed_at
    from public.platform_announcements a
    left join public.platform_announcement_receipts r
      on r.announcement_id = a.id
     and r.profile_id = (select auth.jwt()->>'sub')
   where (p_facility_id in (select private.member_facility_ids())
          or (select private.is_platform_admin()))
     and private.platform_announcement_is_live(a.status, a.starts_at, a.published_at, a.auto_archive_days)
     and (
           a.target = 'all'
        or (a.target = 'facilities' and p_facility_id = any (a.facility_ids))
        or (a.target = 'business_type' and exists (
              select 1 from public.facilities f
               where f.id = p_facility_id and f.business_types && a.business_types))
        or (a.target = 'plan_tier' and exists (
              select 1 from public.facility_subscriptions s
               where s.facility_id = p_facility_id and s.tier_id = any (a.plan_tier_ids)))
     )
   order by coalesce(a.starts_at, a.published_at) desc;
$$;


ALTER FUNCTION "public"."active_platform_announcements"("p_facility_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_owner_booking_note"("p_ref" bigint, "p_kind" "text", "p_content" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings;
  v_name    text;
  v_text    text := btrim(coalesce(p_content, ''));
  v_sub     text := (select auth.jwt()->>'sub');
  v_id      uuid;
begin
  select b.* into v_booking
    from public.bookings b
   where b.ref = p_ref
     and b.client_id in (select private.own_client_ids());
  if not found then
    raise exception 'No such booking.' using errcode = 'P0002';
  end if;

  -- `cancel_request` joined on 2026-09-22. A facility whose cancellation
  -- policy says `customerMayCancel: "request"` for this service cancels it
  -- itself, so the customer asks here instead of cancelling. The note IS the
  -- request: there is no approve/deny surface in the product yet, and half of
  -- one would be worse than a request the desk can read and act on.
  if p_kind is null
     or p_kind not in ('note', 'change_dates', 'cancel_request') then
    raise exception 'A note, a request to change dates, or a request to cancel.'
      using errcode = '22023';
  end if;
  if length(v_text) = 0 or length(v_text) > 1000 then
    raise exception 'Write between 1 and 1000 characters.' using errcode = '22023';
  end if;
  if v_booking.status not in ('pending', 'request_submitted', 'estimate_sent',
                              'waitlisted', 'confirmed', 'checked_in',
                              'in_progress', 'ready') then
    raise exception 'This booking is closed. Contact the facility.'
      using errcode = '55000';
  end if;
  if (select count(*) from public.notes n
       where n.entity_id = v_booking.id
         and n.category = 'booking'
         and n.customer_request is not null
         and n.created_by = v_sub
         and n.created_at > now() - interval '1 day') >= 10 then
    raise exception 'That is ten today. Call the facility instead.'
      using errcode = '54000';
  end if;

  select c.name into v_name from public.clients c where c.id = v_booking.client_id;

  perform set_config('yipyy.owner_note', 'on', true);
  insert into public.notes
    (facility_id, category, entity_id, content, visibility,
     created_by, created_by_name, customer_request)
  values
    (v_booking.facility_id, 'booking', v_booking.id, v_text,
     'shared_with_customer', v_sub, v_name, p_kind)
  returning id into v_id;
  perform set_config('yipyy.owner_note', '', true);

  return v_id;
end;
$$;


ALTER FUNCTION "public"."add_owner_booking_note"("p_ref" bigint, "p_kind" "text", "p_content" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."gift_cards" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "code" "text" NOT NULL,
    "kind" "text" DEFAULT 'online'::"text" NOT NULL,
    "initial_amount" numeric(10,2) NOT NULL,
    "balance" numeric(10,2) DEFAULT 0 NOT NULL,
    "currency" "text" DEFAULT 'CAD'::"text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "purchased_by_client_id" "uuid",
    "recipient_name" "text",
    "recipient_email" "text",
    "message" "text",
    "expires_at" timestamp with time zone,
    "issued_by" "text",
    "issued_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_used_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "gift_cards_balance_not_negative" CHECK (("balance" >= (0)::numeric)),
    CONSTRAINT "gift_cards_initial_amount_positive" CHECK (("initial_amount" > (0)::numeric)),
    CONSTRAINT "gift_cards_kind_known" CHECK (("kind" = ANY (ARRAY['online'::"text", 'physical'::"text"]))),
    CONSTRAINT "gift_cards_status_known" CHECK (("status" = ANY (ARRAY['active'::"text", 'redeemed'::"text", 'expired'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."gift_cards" OWNER TO "postgres";


COMMENT ON TABLE "public"."gift_cards" IS 'Stored value a facility owes a customer. `balance` is maintained by trigger from gift_card_transactions and must never be written directly - the ledger is the truth.';



COMMENT ON COLUMN "public"."gift_cards"."balance" IS 'DERIVED. Maintained by private.gift_card_apply_transaction from the ledger. A direct write is refused by private.gift_card_balance_comes_from_the_ledger.';



CREATE OR REPLACE FUNCTION "public"."adjust_gift_card"("p_gift_card_id" "uuid", "p_amount" numeric, "p_reason" "text") RETURNS "public"."gift_cards"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_card   public.gift_cards%rowtype;
  v_reason text := nullif(btrim(p_reason), '');
  v_sub    text := (select auth.jwt() ->> 'sub');
begin
  if p_amount is null or p_amount = 0 then
    raise exception 'An adjustment has to move the balance.'
      using errcode = '22023';
  end if;

  if v_reason is null then
    raise exception 'An adjustment needs a reason. It is the only record of why the balance changed.'
      using errcode = '22023';
  end if;

  select * into v_card
    from public.gift_cards
   where id = p_gift_card_id
     and private.has_permission(facility_id, 'financial_manage_gift_cards')
   for update;

  if not found then
    raise exception 'No gift card you can adjust.' using errcode = '42501';
  end if;

  if v_card.status = 'cancelled' then
    raise exception 'That gift card was cancelled. Reinstate it before adjusting the balance.'
      using errcode = '42501';
  end if;

  insert into public.gift_card_transactions (
    gift_card_id, facility_id, kind, amount, balance_after, note, created_by
  )
  values (
    v_card.id, v_card.facility_id, 'adjusted', p_amount, 0, v_reason, v_sub
  );

  select * into v_card from public.gift_cards where id = v_card.id;
  return v_card;
end;
$$;


ALTER FUNCTION "public"."adjust_gift_card"("p_gift_card_id" "uuid", "p_amount" numeric, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."adjust_gift_card"("p_gift_card_id" "uuid", "p_amount" numeric, "p_reason" "text") IS 'Correct a gift card balance by appending a signed `adjusted` ledger entry. Requires financial_manage_gift_cards, checked in the same query that finds the card. A reason is mandatory - it is the only record of why. The overdraft is refused by the applying trigger, not here.';



CREATE TABLE IF NOT EXISTS "public"."call_record" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "provider_call_sid" "text" NOT NULL,
    "direction" "text" DEFAULT 'inbound'::"text" NOT NULL,
    "from_number" "text",
    "to_number" "text",
    "status" "text" DEFAULT 'ringing'::"text" NOT NULL,
    "started_at" timestamp with time zone,
    "answered_at" timestamp with time zone,
    "ended_at" timestamp with time zone,
    "duration_s" integer,
    "client_id" "uuid",
    "client_match" "text" DEFAULT 'none'::"text" NOT NULL,
    "handled_by" "uuid",
    "location_id" "uuid",
    "notes" "text",
    "tags" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "follow_up_status" "text",
    "qa_score" integer,
    "booking_id" "uuid",
    "attribution_source" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "assigned_to" "uuid",
    CONSTRAINT "call_record_attribution_check" CHECK ((("attribution_source" IS NULL) OR ("attribution_source" = ANY (ARRAY['in_call'::"text", 'post_call_window'::"text", 'manual'::"text"])))),
    CONSTRAINT "call_record_attribution_needs_booking" CHECK ((("booking_id" IS NULL) = ("attribution_source" IS NULL))),
    CONSTRAINT "call_record_direction_check" CHECK (("direction" = ANY (ARRAY['inbound'::"text", 'outbound'::"text"]))),
    CONSTRAINT "call_record_duration_check" CHECK ((("duration_s" IS NULL) OR ("duration_s" >= 0))),
    CONSTRAINT "call_record_follow_up_check" CHECK ((("follow_up_status" IS NULL) OR ("follow_up_status" = ANY (ARRAY['pending'::"text", 'in_progress'::"text", 'completed'::"text", 'no_action'::"text"])))),
    CONSTRAINT "call_record_match_check" CHECK (("client_match" = ANY (ARRAY['exact'::"text", 'ambiguous'::"text", 'none'::"text"]))),
    CONSTRAINT "call_record_qa_check" CHECK ((("qa_score" IS NULL) OR (("qa_score" >= 1) AND ("qa_score" <= 5)))),
    CONSTRAINT "call_record_status_check" CHECK (("status" = ANY (ARRAY['ringing'::"text", 'in_progress'::"text", 'completed'::"text", 'missed'::"text", 'failed'::"text", 'voicemail'::"text"])))
);


ALTER TABLE "public"."call_record" OWNER TO "postgres";


COMMENT ON TABLE "public"."call_record" IS 'One row per call, projected from call_event by trigger. No UPDATE policy: staff must not be able to edit the numbers reported about them. Annotations go through public.annotate_call().';



COMMENT ON COLUMN "public"."call_record"."client_match" IS 'exact | ambiguous | none - how the caller was identified. Recorded so an attribution rate can state its denominator.';



COMMENT ON COLUMN "public"."call_record"."assigned_to" IS 'Who owes the follow-up. Distinct from handled_by, which is who took the call.';



CREATE OR REPLACE FUNCTION "public"."annotate_call"("p_call_id" "uuid", "p_notes" "text" DEFAULT NULL::"text", "p_tags" "text"[] DEFAULT NULL::"text"[], "p_follow_up_status" "text" DEFAULT NULL::"text", "p_handled_by" "uuid" DEFAULT NULL::"uuid", "p_assigned_to" "uuid" DEFAULT NULL::"uuid", "p_qa_score" integer DEFAULT NULL::integer, "p_booking_id" "uuid" DEFAULT NULL::"uuid", "p_attribution_source" "text" DEFAULT NULL::"text") RETURNS "public"."call_record"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_facility uuid;
  v_row      public.call_record;
begin
  select facility_id into v_facility
  from public.call_record where id = p_call_id;

  if v_facility is null then
    raise exception 'No such call' using errcode = '42704';
  end if;

  if not private.has_permission(v_facility, 'calling_view') then
    raise exception 'Not permitted to annotate calls at this facility'
      using errcode = '42501';
  end if;

  if p_qa_score is not null
     and not private.has_permission(v_facility, 'calling_manage_routing') then
    raise exception 'Not permitted to score calls at this facility'
      using errcode = '42501';
  end if;

  update public.call_record set
    notes              = coalesce(p_notes, notes),
    tags               = coalesce(p_tags, tags),
    follow_up_status   = coalesce(p_follow_up_status, follow_up_status),
    handled_by         = coalesce(p_handled_by, handled_by),
    assigned_to        = coalesce(p_assigned_to, assigned_to),
    qa_score           = coalesce(p_qa_score, qa_score),
    booking_id         = coalesce(p_booking_id, booking_id),
    attribution_source = coalesce(p_attribution_source, attribution_source),
    updated_at         = now()
  where id = p_call_id
  returning * into v_row;

  -- `status`, `duration_s`, `started_at`, `answered_at`, `ended_at` and
  -- `client_match` remain absent from that SET list and from this signature.
  -- They are what the reports measure, and no human edit reaches them.
  return v_row;
end
$$;


ALTER FUNCTION "public"."annotate_call"("p_call_id" "uuid", "p_notes" "text", "p_tags" "text"[], "p_follow_up_status" "text", "p_handled_by" "uuid", "p_assigned_to" "uuid", "p_qa_score" integer, "p_booking_id" "uuid", "p_attribution_source" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."staff_shifts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "staff_id" "uuid",
    "department_id" "uuid" NOT NULL,
    "position_id" "uuid" NOT NULL,
    "starts_at" timestamp with time zone NOT NULL,
    "ends_at" timestamp with time zone NOT NULL,
    "break_minutes" integer DEFAULT 0 NOT NULL,
    "notes" "text",
    "status" "public"."shift_status" DEFAULT 'draft'::"public"."shift_status" NOT NULL,
    "recurrence_id" "uuid",
    "required_skills" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "urgent" boolean DEFAULT false NOT NULL,
    "slots" integer DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "staff_shifts_break_fits" CHECK (((("break_minutes")::double precision * '00:01:00'::interval) < ("ends_at" - "starts_at"))),
    CONSTRAINT "staff_shifts_break_minutes_check" CHECK (("break_minutes" >= 0)),
    CONSTRAINT "staff_shifts_ends_after_it_starts" CHECK (("ends_at" > "starts_at")),
    CONSTRAINT "staff_shifts_slots_check" CHECK (("slots" >= 1))
);


ALTER TABLE "public"."staff_shifts" OWNER TO "postgres";


COMMENT ON TABLE "public"."staff_shifts" IS 'One rostered shift. staff_id NULL is an OPEN shift. Times are instants, like bookings; the API converts to the facility-local date and HH:MM the roster draws.';



CREATE OR REPLACE FUNCTION "public"."apply_schedule_template"("p_template_id" "uuid", "p_week_start" "date") RETURNS SETOF "public"."staff_shifts"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_template    public.schedule_templates;
  v_application uuid;
  v_tz          text;
  v_line        public.schedule_template_shifts;
  v_day         date;
  v_starts      timestamptz;
  v_ends        timestamptz;
begin
  select * into v_template
    from public.schedule_templates where id = p_template_id;
  if not found then
    raise exception 'No such schedule template.' using errcode = '42501';
  end if;

  if not v_template.is_active then
    raise exception 'That template is retired.' using errcode = '22023';
  end if;

  select l.timezone into v_tz
    from public.locations l
   where l.facility_id = v_template.facility_id
   order by l.is_primary desc
   limit 1;
  v_tz := coalesce(v_tz, 'UTC');

  begin
    insert into public.schedule_template_applications
      (template_id, facility_id, week_start, applied_by)
    values
      (p_template_id, v_template.facility_id, p_week_start,
       (select auth.jwt() ->> 'sub'))
    returning id into v_application;
  exception when unique_violation then
    return;
  end;

  for v_line in
    select * from public.schedule_template_shifts
     where template_id = p_template_id
     order by day_of_week, start_time, sort_order
  loop
    v_day := p_week_start + v_line.day_of_week;

    v_starts := (v_day + v_line.start_time) at time zone v_tz;
    v_ends := (
      case when v_line.end_time > v_line.start_time
           then v_day + v_line.end_time
           else v_day + 1 + v_line.end_time
      end
    ) at time zone v_tz;

    return query
      insert into public.staff_shifts (
        facility_id, staff_id, department_id, position_id,
        starts_at, ends_at, break_minutes,
        status, recurrence_id, required_skills, slots
      ) values (
        v_template.facility_id, v_line.staff_id, v_line.department_id,
        v_line.position_id, v_starts, v_ends, v_line.break_minutes,
        'draft', v_application, v_line.required_skills, v_line.slots
      )
      returning *;
  end loop;

  return;
end;
$$;


ALTER FUNCTION "public"."apply_schedule_template"("p_template_id" "uuid", "p_week_start" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_schedule_template"("p_template_id" "uuid", "p_week_start" "date") IS 'Creates a week of DRAFT shifts from a template, in the facility''s timezone. Idempotent per (template, week). SECURITY INVOKER.';



CREATE OR REPLACE FUNCTION "public"."approve_availability_request"("p_request_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS TABLE("day_of_week" smallint, "is_available" boolean, "available_from" time without time zone, "available_to" time without time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  v_request record;
  v_day     jsonb;
begin
  select * into v_request
    from public.staff_availability_requests
   where id = p_request_id;

  if v_request.id is null then
    raise exception 'No such availability request.' using errcode = 'P0002';
  end if;

  if not private.has_permission(v_request.facility_id, 'scheduling_manage_availability') then
    raise exception 'You do not have permission to decide availability.'
      using errcode = '42501';
  end if;

  if v_request.status <> 'pending' then
    raise exception 'That request has already been %.', v_request.status
      using errcode = '22023';
  end if;

  for v_day in select * from jsonb_array_elements(v_request.proposed)
  loop
    insert into public.staff_availability as sa (
      staff_id, facility_id, day_of_week, is_available,
      available_from, available_to, notes
    )
    values (
      v_request.staff_id,
      v_request.facility_id,
      (v_day ->> 'dayOfWeek')::smallint,
      coalesce((v_day ->> 'isAvailable')::boolean, false),
      case when coalesce((v_day ->> 'isAvailable')::boolean, false)
           then nullif(v_day ->> 'startTime', '')::time end,
      case when coalesce((v_day ->> 'isAvailable')::boolean, false)
           then nullif(v_day ->> 'endTime', '')::time end,
      nullif(v_day ->> 'notes', '')
    )
    on conflict (staff_id, day_of_week) do update
      set is_available   = excluded.is_available,
          available_from = excluded.available_from,
          available_to   = excluded.available_to,
          notes          = excluded.notes,
          updated_at     = now();
  end loop;

  update public.staff_availability_requests
     set status       = 'approved',
         reviewed_by  = (select auth.jwt() ->> 'sub'),
         reviewed_at  = now(),
         review_notes = p_notes
   where id = p_request_id;

  return query
    select a.day_of_week, a.is_available, a.available_from, a.available_to
      from public.staff_availability a
     where a.staff_id = v_request.staff_id
     order by a.day_of_week;
end;
$$;


ALTER FUNCTION "public"."approve_availability_request"("p_request_id" "uuid", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."approve_availability_request"("p_request_id" "uuid", "p_notes" "text") IS 'Approve a proposed weekly availability AND apply it, in one transaction. The proposal replaces the week rather than merging into it.';



CREATE OR REPLACE FUNCTION "public"."approve_shift_swap"("p_request_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS TABLE("moved_shift_id" "uuid", "now_assigned" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_request record;
begin
  select * into v_request
    from public.shift_swap_requests
   where id = p_request_id;

  if v_request.id is null then
    raise exception 'No such swap request.' using errcode = 'P0002';
  end if;

  if not private.has_permission(v_request.facility_id, 'scheduling_approve_swaps') then
    raise exception 'You do not have permission to approve shift swaps.'
      using errcode = '42501';
  end if;

  if v_request.status <> 'pending' then
    raise exception 'That request has already been %.', v_request.status
      using errcode = '22023';
  end if;

  update public.staff_shifts
     set staff_id = null
   where id in (v_request.requesting_shift_id, v_request.target_shift_id);

  update public.staff_shifts
     set staff_id = v_request.target_staff_id
   where id = v_request.requesting_shift_id;

  if v_request.target_shift_id is not null then
    update public.staff_shifts
       set staff_id = v_request.requesting_staff_id
     where id = v_request.target_shift_id;
  end if;

  update public.shift_swap_requests
     set status       = 'approved',
         reviewed_by  = (select auth.jwt() ->> 'sub'),
         reviewed_at  = now(),
         review_notes = p_notes
   where id = p_request_id;

  return query
    select s.id, s.staff_id
      from public.staff_shifts s
     where s.id = v_request.requesting_shift_id
        or s.id = v_request.target_shift_id
     order by s.starts_at;
end;
$$;


ALTER FUNCTION "public"."approve_shift_swap"("p_request_id" "uuid", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."approve_shift_swap"("p_request_id" "uuid", "p_notes" "text") IS 'Approve a swap AND move the shifts, in one transaction. If the trade would double-book somebody the exclusion constraint raises 23P01, everything rolls back, and the request stays pending — approved-but-not-applied is unreachable.';



CREATE OR REPLACE FUNCTION "public"."assign_boarding_room"("p_booking_ref" bigint, "p_room_id" "text" DEFAULT NULL::"text", "p_override_reason" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_booking_id  uuid;
  v_facility_id uuid;
  v_start       timestamptz;
  v_end         timestamptz;
  v_room_id     uuid;
  v_override    text;
  v_touched     integer;
  v_existing    boolean;
begin
  select b.id, b.facility_id, b.start_at, b.end_at
    into v_booking_id, v_facility_id, v_start, v_end
    from public.bookings b
   where b.ref = p_booking_ref;

  if v_booking_id is null then
    raise exception 'That booking does not exist, or is not yours.'
      using errcode = '42501';
  end if;

  if p_room_id is null then
    select exists (
      select 1 from public.boarding_stays s where s.booking_id = v_booking_id
    ) into v_existing;

    if not v_existing then
      return null;
    end if;

    delete from public.boarding_stays where booking_id = v_booking_id;
    get diagnostics v_touched = row_count;

    if v_touched = 0 then
      raise exception 'Not allowed to change this booking''s room.'
        using errcode = '42501';
    end if;
    return null;
  end if;

  select r.id into v_room_id
    from public.facility_rooms r
   where r.facility_id = v_facility_id
     and r.legacy_id = p_room_id
     and r.active;

  if v_room_id is null then
    raise exception 'This facility has no room %.', p_room_id
      using errcode = '23503';
  end if;

  v_override := nullif(trim(coalesce(p_override_reason, '')), '');

  if v_override is not null
     and not private.has_permission(v_facility_id, 'override_booking_capacity')
  then
    raise exception 'Not allowed to override capacity limits.'
      using errcode = '42501';
  end if;

  select exists (
    select 1 from public.boarding_stays s where s.booking_id = v_booking_id
  ) into v_existing;

  if v_existing then
    -- The whole booking in one kennel: a split is undone, and segment 1 —
    -- which carries the arrival — takes the booking's range.
    delete from public.boarding_stays
     where booking_id = v_booking_id and segment_order > 1;

    update public.boarding_stays
       set room_id         = v_room_id,
           occupies        = tstzrange(v_start, v_end, '[)'),
           override_reason = v_override,
           released_at     = null,
           updated_at      = now()
     where booking_id = v_booking_id and segment_order = 1;

    get diagnostics v_touched = row_count;
    if v_touched = 0 then
      raise exception 'Not allowed to change this booking''s room.'
        using errcode = '42501';
    end if;
  else
    insert into public.boarding_stays
      (booking_id, facility_id, room_id, occupies, override_reason)
    values
      (v_booking_id, v_facility_id, v_room_id,
       tstzrange(v_start, v_end, '[)'), v_override);
  end if;

  return p_room_id;
end;
$$;


ALTER FUNCTION "public"."assign_boarding_room"("p_booking_ref" bigint, "p_room_id" "text", "p_override_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assign_boarding_room"("p_booking_ref" bigint, "p_room_id" "text", "p_override_reason" "text") IS 'Assigns, moves or clears a booking''s kennel. SECURITY INVOKER, so RLS judges every write as the caller; the exclusion constraint on boarding_stays refuses a room already taken for those dates.';



CREATE OR REPLACE FUNCTION "public"."attach_unattached_payment"("p_id" "uuid", "p_booking_ref" bigint DEFAULT NULL::bigint, "p_client_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_row       public.unattached_payments;
  v_booking   public.bookings;
  v_client    uuid;
  v_payment   uuid;
  v_subtotal  numeric(10,2);
  v_tax       numeric(10,2);
  v_tip       numeric(10,2);
  v_changed   integer;
begin
  select * into v_row from public.unattached_payments where id = p_id;

  if v_row.id is null then
    raise exception 'No such payment.' using errcode = '42704';
  end if;

  if v_row.status <> 'unattached' then
    raise exception 'That payment has already been dealt with.' using errcode = '42501';
  end if;

  if p_booking_ref is null and p_client_id is null then
    raise exception 'Say which booking or which client this belongs to.' using errcode = '22023';
  end if;

  if p_booking_ref is not null then
    select * into v_booking from public.bookings
     where ref = p_booking_ref and facility_id = v_row.facility_id;
    if v_booking.id is null then
      raise exception 'No booking % at this facility.', p_booking_ref using errcode = '42704';
    end if;
    v_client := coalesce(p_client_id, v_booking.client_id);
  else
    v_client := p_client_id;
  end if;

  v_subtotal := (v_row.amount_cents - v_row.tip_cents - v_row.tax_cents) / 100.0;
  v_tax      := v_row.tax_cents / 100.0;
  v_tip      := v_row.tip_cents / 100.0;

  insert into public.payments (
    facility_id, booking_id, client_id, method,
    subtotal, tax, tip, amount_charged, grand_total,
    processor, processor_payment_id,
    processor_order_id, processor_merchant_id, processor_device_serial,
    card_brand, card_last4, entry_method, author_name)
  values (
    v_row.facility_id, v_booking.id, v_client,
    case when v_row.entry_method = 'ecom' then 'new-card' else 'terminal' end,
    v_subtotal, v_tax, v_tip,
    v_row.amount_cents / 100.0, v_row.amount_cents / 100.0,
    v_row.processor, v_row.processor_payment_id,
    v_row.processor_order_id, v_row.processor_merchant_id,
    v_row.processor_device_serial,
    v_row.card_brand, v_row.card_last4, v_row.entry_method,
    'Attached from Clover')
  returning id into v_payment;

  update public.unattached_payments
     set status = 'attached',
         attached_payment_id = v_payment,
         resolved_by = (select auth.jwt() ->> 'sub'),
         resolved_at = now(),
         note = p_note,
         updated_at = now()
   where id = p_id and status = 'unattached';

  get diagnostics v_changed = row_count;
  if v_changed = 0 then
    raise exception
      'That payment could not be claimed - either somebody else dealt with it first, or you cannot take payments at this facility.'
      using errcode = '42501';
  end if;

  return v_payment;
end;
$$;


ALTER FUNCTION "public"."attach_unattached_payment"("p_id" "uuid", "p_booking_ref" bigint, "p_client_id" "uuid", "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."attach_unattached_payment"("p_id" "uuid", "p_booking_ref" bigint, "p_client_id" "uuid", "p_note" "text") IS 'Places a Clover payment against a booking. Claims the queue row BEFORE writing the append-only ledger row and refuses on a zero-row claim, so a payment can never be recorded twice. security invoker: payments_insert and the resolve policy both judge the caller.';



CREATE OR REPLACE FUNCTION "public"."audience_filter"("p_facility_id" "uuid", "p_field" "text", "p_operator" "text", "p_value" "jsonb") RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_zone text;
  v_today date;
  v_num int;
  v_text text;
  v_arr text[];
begin
  select coalesce(f.timezone, 'America/Toronto') into v_zone
    from public.facilities f where f.id = p_facility_id;
  v_today := (now() at time zone coalesce(v_zone, 'America/Toronto'))::date;

  case p_field

  when 'last_visit_days' then
    v_num := (p_value #>> '{}')::int;
    if p_operator = 'more_than' then
      return query select c.id from public.clients c
        where c.facility_id = p_facility_id
          and (c.last_visit_date is null or c.last_visit_date < v_today - v_num);
    elsif p_operator = 'less_than' then
      return query select c.id from public.clients c
        where c.facility_id = p_facility_id
          and c.last_visit_date is not null
          and c.last_visit_date >= v_today - v_num;
    else
      raise exception 'operator "%" is not valid for %', p_operator, p_field;
    end if;

  when 'last_service_type' then
    select array_agg(x) into v_arr from jsonb_array_elements_text(p_value) x;
    if p_operator not in ('in', 'not_in') then
      raise exception 'operator "%" is not valid for %', p_operator, p_field;
    end if;
    return query
      with latest as (
        select distinct on (b.client_id) b.client_id, b.service_type
          from public.bookings b
         where b.facility_id = p_facility_id
         order by b.client_id, b.start_at desc
      )
      select c.id from public.clients c
        left join latest l on l.client_id = c.id
       where c.facility_id = p_facility_id
         and case when p_operator = 'in'
                  then l.service_type = any(v_arr)
                  else l.service_type is null or not (l.service_type = any(v_arr))
             end;

  when 'vaccination_status' then
    if p_operator = 'expired' then
      return query select distinct p.client_id from public.pets p
        join public.pet_vaccinations v on v.pet_id = p.id
       where p.facility_id = p_facility_id
         and v.status = 'approved'
         and v.expires_on is not null
         and v.expires_on < v_today;
    elsif p_operator = 'expiring_within' then
      v_num := (p_value #>> '{}')::int;
      return query select distinct p.client_id from public.pets p
        join public.pet_vaccinations v on v.pet_id = p.id
       where p.facility_id = p_facility_id
         and v.status = 'approved'
         and v.expires_on is not null
         and v.expires_on >= v_today
         and v.expires_on <= v_today + v_num;
    elsif p_operator = 'missing' then
      return query select distinct p.client_id from public.pets p
       where p.facility_id = p_facility_id
         and not exists (
           select 1 from public.pet_vaccinations v
            where v.pet_id = p.id and v.status = 'approved'
         );
    else
      raise exception 'operator "%" is not valid for %', p_operator, p_field;
    end if;

  when 'customer_tag' then
    v_text := p_value #>> '{}';
    if p_operator = 'has' then
      return query select distinct a.entity_id from public.facility_tag_assignments a
       where a.facility_id = p_facility_id
         and a.entity_type = 'customer'
         and a.tag_id = v_text::uuid
         and (a.expires_at is null or a.expires_at > now());
    elsif p_operator = 'not_has' then
      return query select c.id from public.clients c
       where c.facility_id = p_facility_id
         and not exists (
           select 1 from public.facility_tag_assignments a
            where a.entity_type = 'customer' and a.entity_id = c.id
              and a.tag_id = v_text::uuid
              and (a.expires_at is null or a.expires_at > now())
         );
    else
      raise exception 'operator "%" is not valid for %', p_operator, p_field;
    end if;

  when 'has_active_booking' then
    if p_operator <> 'is' then
      raise exception 'operator "%" is not valid for %', p_operator, p_field;
    end if;
    if (p_value #>> '{}')::boolean then
      return query select distinct b.client_id from public.bookings b
       where b.facility_id = p_facility_id
         and b.start_at >= now()
         and b.status not in ('cancelled', 'declined', 'no_show');
    else
      return query select c.id from public.clients c
       where c.facility_id = p_facility_id
         and not exists (
           select 1 from public.bookings b
            where b.client_id = c.id and b.start_at >= now()
              and b.status not in ('cancelled', 'declined', 'no_show')
         );
    end if;

  when 'total_visits' then
    v_num := (p_value #>> '{}')::int;
    if p_operator not in ('more_than', 'less_than') then
      raise exception 'operator "%" is not valid for %', p_operator, p_field;
    end if;
    return query
      with visits as (
        select c.id as client_id,
               (select count(*) from public.bookings b
                 where b.client_id = c.id and b.status = 'completed') as n
          from public.clients c
         where c.facility_id = p_facility_id
      )
      select v.client_id from visits v
       where case when p_operator = 'more_than' then v.n > v_num else v.n < v_num end;

  when 'last_booking_date' then
    if p_operator not in ('before', 'after') then
      raise exception 'operator "%" is not valid for %', p_operator, p_field;
    end if;
    return query
      with latest as (
        select b.client_id, max(b.start_at) as last_at
          from public.bookings b
         where b.facility_id = p_facility_id
         group by b.client_id
      )
      select l.client_id from latest l
       where case when p_operator = 'before'
                  then l.last_at < ((p_value #>> '{}')::date)
                  else l.last_at >= ((p_value #>> '{}')::date)
             end;

  when 'membership_status' then
    if p_operator <> 'is' then
      raise exception 'operator "%" is not valid for %', p_operator, p_field;
    end if;
    v_text := p_value #>> '{}';
    if v_text = 'none' then
      return query select c.id from public.clients c
       where c.facility_id = p_facility_id
         and not exists (
           select 1 from public.customer_memberships m
            where m.client_id = c.id and m.status = 'active'
         );
    else
      return query select distinct m.client_id from public.customer_memberships m
       where m.facility_id = p_facility_id and m.status = v_text;
    end if;

  else
    raise exception 'unknown audience field "%"', p_field;
  end case;
end;
$$;


ALTER FUNCTION "public"."audience_filter"("p_facility_id" "uuid", "p_field" "text", "p_operator" "text", "p_value" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."audience_filter"("p_facility_id" "uuid", "p_field" "text", "p_operator" "text", "p_value" "jsonb") IS 'One filter -> the client ids it names. SECURITY INVOKER. In public rather than private only because service_role cannot reach the private schema.';



