ALTER TABLE "public"."loyalty_badge_awards" OWNER TO "postgres";


COMMENT ON TABLE "public"."loyalty_badge_awards" IS 'One row per (loyalty account, badge), created the first time the account meets the badge''s condition. Append-only against applications: no UPDATE or DELETE policy exists. Award through award_loyalty_badge(), which issues the reward in the same transaction.';



CREATE OR REPLACE FUNCTION "public"."award_loyalty_badge"("p_account_id" "uuid", "p_badge_id" "text", "p_description" "text" DEFAULT NULL::"text", "p_reward_type" "text" DEFAULT NULL::"text", "p_reward_value" numeric DEFAULT NULL::numeric, "p_applies_to" "text"[] DEFAULT NULL::"text"[], "p_points" integer DEFAULT 0) RETURNS "public"."loyalty_badge_awards"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_facility uuid;
  v_voucher  public.loyalty_vouchers;
  v_award    public.loyalty_badge_awards;
begin
  select a.facility_id into v_facility
    from public.loyalty_accounts a
   where a.id = p_account_id;

  if v_facility is null then
    raise exception 'That loyalty account does not exist.' using errcode = 'P0002';
  end if;

  if not private.has_permission(v_facility, 'marketing_manage_loyalty') then
    raise exception 'You do not have permission to award a loyalty badge.'
      using errcode = '42501';
  end if;

  if p_points < 0 then
    raise exception 'A badge cannot award negative points.' using errcode = '22023';
  end if;

  if p_points > 0 then
    insert into public.loyalty_transactions
      (facility_id, account_id, kind, points, description, source)
    values
      (v_facility, p_account_id, 'earned', p_points,
       coalesce(p_description, 'Badge earned'), 'manual');
  elsif p_reward_type is not null then
    v_voucher := public.redeem_loyalty_points(
      p_account_id,
      p_reward_type,
      p_reward_value,
      0,
      null,
      p_applies_to,
      coalesce(p_description, 'Badge earned')
    );
  end if;

  insert into public.loyalty_badge_awards
    (facility_id, account_id, badge_id, voucher_id, points_awarded)
  values
    (v_facility, p_account_id, p_badge_id, v_voucher.id, greatest(p_points, 0))
  returning * into v_award;

  return v_award;
end;
$$;


ALTER FUNCTION "public"."award_loyalty_badge"("p_account_id" "uuid", "p_badge_id" "text", "p_description" "text", "p_reward_type" "text", "p_reward_value" numeric, "p_applies_to" "text"[], "p_points" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."award_loyalty_badge"("p_account_id" "uuid", "p_badge_id" "text", "p_description" "text", "p_reward_type" "text", "p_reward_value" numeric, "p_applies_to" "text"[], "p_points" integer) IS 'Record a badge as earned and issue its reward in one transaction. Raises 23505 when the account already holds it, which rolls the reward back — so a retried checkout cannot award twice. Requires marketing_manage_loyalty on the account''s own facility; anon holds no EXECUTE grant — see rpc-session-required.sql for why that must be revoked explicitly rather than via `from public`.';



CREATE OR REPLACE FUNCTION "public"."booking_cancel_terms"("p_ref" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings;
begin
  select * into v_booking from public.bookings b where b.ref = p_ref;
  if not found then
    return null;
  end if;

  -- Not theirs to see and not real are the same answer, deliberately: a
  -- refusal that distinguishes them tells a stranger the booking exists.
  if not private.has_permission(v_booking.facility_id, 'edit_bookings') then
    return null;
  end if;

  return private.cancellation_terms(v_booking)
    || jsonb_build_object(
         'status', v_booking.status,
         'totalCost', coalesce(v_booking.total_cost, 0),
         'amountPaid', coalesce(v_booking.amount_paid, 0),
         'cancellable', v_booking.status in (
           'pending', 'request_submitted', 'estimate_sent',
           'waitlisted', 'confirmed', 'checked_in'));
end;
$$;


ALTER FUNCTION "public"."booking_cancel_terms"("p_ref" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."booking_cancel_terms"("p_ref" bigint) IS 'What a cancellation costs, for staff. The same evaluator the customer preview reads.';



CREATE OR REPLACE FUNCTION "public"."booking_client_summary"("p_facility_id" "uuid") RETURNS TABLE("client_ref" bigint, "booking_count" integer, "first_day" "date", "last_day" "date", "services" "text"[], "has_active" boolean, "rebooked_within_60_days" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with history as (
    select c.ref as client_ref,
           lower(b.service::text) as service,
           b.status::text as status,
           b.start_at,
           (b.start_at at time zone coalesce(f.timezone, 'America/Toronto'))::date as day,
           lag(b.start_at) over (partition by b.client_id order by b.start_at) as previous_start
      from public.bookings b
      join public.clients c on c.id = b.client_id
      join public.facilities f on f.id = b.facility_id
     where b.facility_id = p_facility_id
  )
  select client_ref,
         count(*)::integer,
         min(day),
         max(day),
         coalesce(array_agg(distinct service) filter (where service is not null), '{}'),
         bool_or(status in ('confirmed', 'pending')),
         bool_or(previous_start is not null and start_at - previous_start <= interval '60 days')
    from history
   group by client_ref;
$$;


ALTER FUNCTION "public"."booking_client_summary"("p_facility_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."booking_facility_totals"("p_facility_id" "uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_staff_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("total" integer, "today" integer, "upcoming" integer, "pending" integer, "paid_revenue" numeric, "pending_revenue" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with zone as (
    select coalesce(timezone, 'America/Toronto') as tz
      from public.facilities where id = p_facility_id
  ),
  scoped as (
    select b.status::text as status,
           b.payment_status::text as payment_status,
           b.total_cost,
           (b.start_at at time zone (select tz from zone))::date as day
      from public.bookings b
     where b.facility_id = p_facility_id
       and (p_location_id is null or b.location_id = p_location_id)
       and (p_staff_id is null or b.assigned_staff_id = p_staff_id)
  ),
  local_today as (
    select (now() at time zone (select tz from zone))::date as d
  )
  select count(*)::integer,
         (count(*) filter (where day = (select d from local_today)))::integer,
         (count(*) filter (where day > (select d from local_today) and status <> 'cancelled'))::integer,
         (count(*) filter (where status = 'pending'))::integer,
         coalesce(sum(total_cost) filter (where payment_status = 'paid'), 0),
         coalesce(sum(total_cost) filter (where payment_status = 'pending'), 0)
    from scoped;
$$;


ALTER FUNCTION "public"."booking_facility_totals"("p_facility_id" "uuid", "p_location_id" "uuid", "p_staff_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."booking_missing_forms"("p_booking_id" "uuid", "p_stage" "text") RETURNS TABLE("form_id" "uuid", "form_name" "text", "form_slug" "text", "pet_id" "uuid", "pet_name" "text", "enforcement" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select m.form_id, m.form_name, m.form_slug, m.pet_id, p.name, m.enforcement
    from public.bookings b
    cross join lateral private.missing_required_forms(
      b.facility_id,
      b.client_id,
      array(select bp.pet_id from public.booking_pets bp where bp.booking_id = b.id),
      b.service,
      p_stage
    ) m
    left join public.pets p on p.id = m.pet_id
   where b.id = p_booking_id
     and p_stage in ('before_booking', 'before_approval', 'before_checkin');
$$;


