CREATE OR REPLACE FUNCTION "public"."close_payment_intent"("p_intent_id" "uuid", "p_status" "text", "p_failure_code" "text" DEFAULT NULL::"text", "p_failure_message" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  update public.payment_intents
     set status          = p_status,
         failure_code    = p_failure_code,
         failure_message = left(p_failure_message, 500),
         completed_at    = case when p_status in ('created', 'sent')
                                then completed_at else now() end
   where id = p_intent_id
     and payment_id is null;
$$;


