CREATE OR REPLACE FUNCTION "public"."close_payment_webhook"("p_event_id" "uuid", "p_status" "text", "p_outcome" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_status not in ('processed', 'ignored', 'failed') then
    raise exception 'A webhook closes as processed, ignored or failed — not %', p_status
      using errcode = '22023';
  end if;

  update public.payment_webhook_events
     set status       = p_status,
         outcome      = p_outcome,
         processed_at = now()
   where id = p_event_id;
end;
$$;


