CREATE OR REPLACE FUNCTION "public"."compile_audience"("p_facility_id" "uuid", "p_filters" "jsonb") RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_group jsonb;
  v_filter jsonb;
  v_group_ids uuid[];
  v_filter_ids uuid[];
  v_result uuid[] := null;
  v_op text := coalesce(p_filters ->> 'groupLogicOperator', 'AND');
  v_first boolean := true;
begin
  if p_filters is null or jsonb_array_length(coalesce(p_filters -> 'filterGroups', '[]'::jsonb)) = 0 then
    return;
  end if;

  for v_group in select * from jsonb_array_elements(p_filters -> 'filterGroups') loop
    v_group_ids := null;

    for v_filter in select * from jsonb_array_elements(coalesce(v_group -> 'filters', '[]'::jsonb)) loop
      select coalesce(array_agg(id), '{}') into v_filter_ids
        from public.audience_filter(
          p_facility_id,
          v_filter ->> 'field',
          v_filter ->> 'operator',
          coalesce(v_filter -> 'value', 'null'::jsonb)
        ) as id;

      if v_group_ids is null then
        v_group_ids := v_filter_ids;
      else
        select coalesce(array_agg(x), '{}') into v_group_ids
          from unnest(v_group_ids) x where x = any(v_filter_ids);
      end if;
    end loop;

    if v_group_ids is null then
      continue;
    end if;

    if v_first then
      v_result := v_group_ids;
      v_first := false;
    elsif v_op = 'OR' then
      select coalesce(array_agg(distinct x), '{}') into v_result
        from unnest(v_result || v_group_ids) x;
    else
      select coalesce(array_agg(x), '{}') into v_result
        from unnest(v_result) x where x = any(v_group_ids);
    end if;
  end loop;

  if v_result is null then
    return;
  end if;

  return query select distinct x from unnest(v_result) x;
end;
$$;


ALTER FUNCTION "public"."compile_audience"("p_facility_id" "uuid", "p_filters" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."compile_audience"("p_facility_id" "uuid", "p_filters" "jsonb") IS 'Filter json -> the client ids it names. SECURITY INVOKER so RLS still decides what the caller can see. An empty filter names nobody.';



CREATE TABLE IF NOT EXISTS "public"."yipyy_go_submissions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "client_id" "uuid" NOT NULL,
    "booking_id" "uuid" NOT NULL,
    "pet_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "answers" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "add_on_requests" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "tip_choice" "jsonb",
    "submitted_at" timestamp with time zone,
    "submitted_by_name" "text",
    "reviewed_at" timestamp with time zone,
    "reviewed_by_name" "text",
    "changes_message" "text",
    "completed_reason" "text",
    "completed_at" timestamp with time zone,
    "completed_by_name" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "yipyy_go_submissions_add_on_requests_check" CHECK ((("jsonb_typeof"("add_on_requests") = 'array'::"text") AND ("jsonb_array_length"("add_on_requests") <= 50))),
    CONSTRAINT "yipyy_go_submissions_answers_check" CHECK ((("jsonb_typeof"("answers") = 'object'::"text") AND ("octet_length"(("answers")::"text") <= 65536))),
    CONSTRAINT "yipyy_go_submissions_changes_message_check" CHECK ((("changes_message" IS NULL) OR (("length"("btrim"("changes_message")) >= 1) AND ("length"("btrim"("changes_message")) <= 1000)))),
    CONSTRAINT "yipyy_go_submissions_changes_say_what" CHECK ((("status" <> 'changes_requested'::"text") OR ("changes_message" IS NOT NULL))),
    CONSTRAINT "yipyy_go_submissions_completed_by_name_check" CHECK ((("completed_by_name" IS NULL) OR (("length"("completed_by_name") >= 1) AND ("length"("completed_by_name") <= 200)))),
    CONSTRAINT "yipyy_go_submissions_completed_reason_check" CHECK ((("completed_reason" IS NULL) OR (("length"("btrim"("completed_reason")) >= 1) AND ("length"("btrim"("completed_reason")) <= 1000)))),
    CONSTRAINT "yipyy_go_submissions_reviewed_by_name_check" CHECK ((("reviewed_by_name" IS NULL) OR (("length"("reviewed_by_name") >= 1) AND ("length"("reviewed_by_name") <= 200)))),
    CONSTRAINT "yipyy_go_submissions_staff_completion_says_why" CHECK ((("status" <> 'completed_by_staff'::"text") OR ("completed_reason" IS NOT NULL))),
    CONSTRAINT "yipyy_go_submissions_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'submitted'::"text", 'changes_requested'::"text", 'approved'::"text", 'completed_by_staff'::"text"]))),
    CONSTRAINT "yipyy_go_submissions_submitted_by_name_check" CHECK ((("submitted_by_name" IS NULL) OR (("length"("submitted_by_name") >= 1) AND ("length"("submitted_by_name") <= 200)))),
    CONSTRAINT "yipyy_go_submissions_tip_choice_check" CHECK ((("tip_choice" IS NULL) OR ("jsonb_typeof"("tip_choice") = 'object'::"text")))
);


ALTER TABLE "public"."yipyy_go_submissions" OWNER TO "postgres";


COMMENT ON TABLE "public"."yipyy_go_submissions" IS 'A pre-arrival (Yipyy Go) form, one per booking and pet: what the owner said about belongings, feeding, medications and behaviour, and where it stands with the facility. Written only through the Yipyy Go functions. Replaces the fixture src/data/yipyygo-forms.ts (2026-09-13).';



CREATE OR REPLACE FUNCTION "public"."complete_yipyy_go_by_staff"("p_booking_id" "uuid", "p_pet_id" "uuid", "p_reason" "text", "p_by_name" "text" DEFAULT NULL::"text") RETURNS "public"."yipyy_go_submissions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings;
  v_status  text;
  v_row     public.yipyy_go_submissions;
begin
  select * into v_booking from public.bookings where id = p_booking_id;
  if not found
     or not (
       private.yipyy_go_may_check_in(v_booking.facility_id, v_booking.service)
       or private.has_permission(v_booking.facility_id, 'edit_bookings')
     )
     or not exists (
       select 1 from public.booking_pets bp where bp.booking_id = p_booking_id and bp.pet_id = p_pet_id
     )
  then
    raise exception 'That booking is not yours to complete.' using errcode = '42501';
  end if;

  if private.yipyy_go_requirement(v_booking.facility_id, v_booking.service) is null then
    raise exception 'This booking does not ask for a pre-arrival form.' using errcode = '22023';
  end if;
  if p_reason is null or length(btrim(p_reason)) not between 1 and 1000 then
    raise exception 'Say why the form is being completed for them.' using errcode = '22023';
  end if;

  select status into v_status from public.yipyy_go_submissions
   where booking_id = p_booking_id and pet_id = p_pet_id;
  if v_status in ('submitted', 'approved', 'completed_by_staff') then
    raise exception 'This form is already complete.' using errcode = '22023';
  end if;

  insert into public.yipyy_go_submissions as y
    (booking_id, pet_id, status, completed_reason, completed_at, completed_by_name)
  values
    (p_booking_id, p_pet_id, 'completed_by_staff', btrim(p_reason), now(),
     nullif(left(btrim(coalesce(p_by_name, '')), 200), ''))
  on conflict (booking_id, pet_id) do update
     set status = 'completed_by_staff',
         completed_reason = excluded.completed_reason,
         completed_at = excluded.completed_at,
         completed_by_name = excluded.completed_by_name
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."complete_yipyy_go_by_staff"("p_booking_id" "uuid", "p_pet_id" "uuid", "p_reason" "text", "p_by_name" "text") OWNER TO "postgres";


