    CONSTRAINT "loyalty_vouchers_reward_type_check" CHECK (("reward_type" = ANY (ARRAY['discount_pct'::"text", 'discount_fixed'::"text", 'free_service'::"text", 'credit_balance'::"text"]))),
    CONSTRAINT "loyalty_vouchers_reward_value_check" CHECK (("reward_value" > (0)::numeric)),
