COMMENT ON TABLE "public"."loyalty_vouchers" IS 'A reward a customer holds. Spend it with consume_loyalty_voucher(), which is the only thing that can move it to used - and can only do so once.';



CREATE OR REPLACE FUNCTION "public"."consume_loyalty_voucher"("p_voucher_id" "uuid", "p_booking_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."loyalty_vouchers"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_facility uuid;
  v_voucher  public.loyalty_vouchers;
begin
  select v.facility_id into v_facility
    from public.loyalty_vouchers v
   where v.id = p_voucher_id;

  if v_facility is null then
    raise exception 'That reward does not exist.' using errcode = 'P0002';
  end if;

  if not (private.has_permission(v_facility, 'take_payment')
          or private.has_permission(v_facility, 'marketing_manage_loyalty')) then
    raise exception 'You do not have permission to apply a reward.'
      using errcode = '42501';
  end if;

  update public.loyalty_vouchers v
     set status             = 'used',
         used_at            = now(),
         used_on_booking_id = coalesce(p_booking_id, v.used_on_booking_id)
   where v.id = p_voucher_id
     and v.status = 'active'
     and (v.expires_at is null or v.expires_at > now())
  returning * into v_voucher;

  if v_voucher.id is null then
    raise exception 'That reward has already been used, or has expired.'
      using errcode = '22023';
  end if;

  return v_voucher;
end;
$$;


ALTER FUNCTION "public"."consume_loyalty_voucher"("p_voucher_id" "uuid", "p_booking_id" "uuid") OWNER TO "postgres";


