$$;


ALTER FUNCTION "public"."count_audience"("p_facility_id" "uuid", "p_filters" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."count_audience"("p_facility_id" "uuid", "p_filters" "jsonb") IS 'How many clients an audience names. COUNT(*), never fetch-and-length - a 20k-client facility would feel the difference.';



CREATE OR REPLACE FUNCTION "public"."create_booking"("p_booking" "jsonb", "p_pet_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_grooming" "jsonb" DEFAULT NULL::"jsonb", "p_boarding" "jsonb" DEFAULT NULL::"jsonb") RETURNS TABLE("booking_id" "uuid", "booking_ref" bigint)
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_known        text[] := array[
    'facility_id', 'location_id', 'client_id', 'service', 'service_type',
    'status', 'start_at', 'end_at',
    'assigned_staff_id', 'assigned_staff_name',
    'base_price', 'discount', 'total_cost', 'tip_amount',
    'special_requests', 'details', 'training_series_session_id',
    'form_override_reason'
  ];
  v_unknown      text[];
  v_booking_id   uuid;
  v_ref          bigint;
  v_facility_id  uuid;
  v_start        timestamptz;
  v_end          timestamptz;
  v_is_staff     boolean;
  v_service_id   uuid;
  v_service_name text;
  v_price        numeric;
  v_duration     integer;
  v_size         text;
  v_size_price   numeric;
  v_size_dur     integer;
  v_weight       numeric;
  v_station_id   uuid;
  v_written      integer;
  v_requested    integer;
  v_room_id      uuid;
  v_override     text;
  v_missing      text;
  v_form_reason  text;
  v_eval_service text;
begin
  select array_agg(k) into v_unknown
    from jsonb_object_keys(p_booking) k where k <> all (v_known);

  if v_unknown is not null then
    raise exception 'create_booking does not handle booking column(s): %',
      array_to_string(v_unknown, ', ') using errcode = '22023';
  end if;

  if p_booking->>'service' = 'grooming' and p_grooming is null then
    raise exception 'A grooming booking needs its appointment details.'
      using errcode = '22023';
  end if;

  select string_agg(distinct m.form_name, ', ') into v_missing
    from private.missing_required_forms(
           (p_booking->>'facility_id')::uuid,
           (p_booking->>'client_id')::uuid,
           p_pet_ids,
           p_booking->>'service',
           'before_booking') m
   where m.enforcement = 'block';

  v_form_reason := nullif(btrim(coalesce(p_booking->>'form_override_reason', '')), '');

  if v_missing is not null then
    if not private.has_permission((p_booking->>'facility_id')::uuid, 'create_bookings') then
      raise exception 'Complete % before booking.', v_missing
        using errcode = '22023', hint = 'form_required';
    elsif v_form_reason is null then
      raise exception 'Say why this booking goes ahead without %.', v_missing
        using errcode = '22023', hint = 'form_override_reason_required';
    end if;
  end if;

  -- ── THE EVALUATION A DAYCARE SERVICE REQUIRES BEFORE ONLINE BOOKING ─────
  --
  -- Only for a caller who cannot create bookings, i.e. the customer. The
  -- field is 'requires_evaluation_online' and the online channel is what it
  -- governs; staff at the desk are the other question, and this is not it.
  --
  -- The service is named in the message because a refusal a customer cannot
  -- act on is not a refusal, it is a dead end.
  if p_booking->>'service' = 'daycare'
     and p_booking->'details'->>'daycareServiceId' is not null
     and not private.has_permission((p_booking->>'facility_id')::uuid, 'create_bookings')
  then
    select s.name into v_eval_service
      from public.daycare_services s
     where s.facility_id = (p_booking->>'facility_id')::uuid
       and (s.id::text = p_booking->'details'->>'daycareServiceId'
            or s.legacy_id = p_booking->'details'->>'daycareServiceId')
       and s.requires_evaluation_online
       -- Refuse when ANY pet on the booking lacks a pass. A booking is one
       -- record for every animal on it, so it cannot go ahead half-approved.
       and exists (
         select 1 from unnest(p_pet_ids) pid
          where not private.pet_passed_daycare_evaluation(pid))
     limit 1;

    if v_eval_service is not null then
      raise exception 'Book an evaluation before booking %.', v_eval_service
        using errcode = '22023', hint = 'daycare_evaluation_required';
    end if;
  end if;

  insert into public.bookings (
    facility_id, location_id, client_id, service, service_type,
    status, start_at, end_at,
    assigned_staff_id, assigned_staff_name,
    base_price, discount, total_cost, tip_amount,
    special_requests, details, training_series_session_id
  )
  select
    b.facility_id, b.location_id, b.client_id, b.service, b.service_type,
    coalesce(b.status, 'pending'::public.booking_status),
    b.start_at, b.end_at,
    b.assigned_staff_id, b.assigned_staff_name,
    coalesce(b.base_price, 0), coalesce(b.discount, 0),
    coalesce(b.total_cost, 0), b.tip_amount,
    b.special_requests, coalesce(b.details, '{}'::jsonb), b.training_series_session_id
    from jsonb_populate_record(null::public.bookings, p_booking) b
  returning id, ref, facility_id, start_at, end_at
       into v_booking_id, v_ref, v_facility_id, v_start, v_end;

  if array_length(p_pet_ids, 1) > 0 then
    insert into public.booking_pets (booking_id, pet_id)
    select v_booking_id, unnest(p_pet_ids);
  end if;

  if v_missing is not null then
    perform private.record_form_overrides(v_booking_id, 'before_booking', v_form_reason);
  end if;

  if p_boarding is not null and p_boarding->>'roomId' is not null then
    select r.id into v_room_id
      from public.facility_rooms r
     where r.facility_id = v_facility_id
       and (r.legacy_id = p_boarding->>'roomId' or r.id::text = p_boarding->>'roomId')
       and r.active;

    if v_room_id is null then
      raise exception 'This facility has no room %.',
        p_boarding->>'roomId' using errcode = '23503';
    end if;

    v_override := nullif(trim(coalesce(p_boarding->>'overrideReason', '')), '');

    if v_override is not null
       and not private.has_permission(v_facility_id, 'override_booking_capacity')
    then
      raise exception 'Not allowed to override capacity limits.'
        using errcode = '42501';
    end if;

    insert into public.boarding_stays
      (booking_id, facility_id, room_id, occupies, override_reason)
    values
      (v_booking_id, v_facility_id, v_room_id,
       tstzrange(v_start, v_end, '[)'), v_override);
  end if;

  if p_grooming is null then
    booking_id := v_booking_id; booking_ref := v_ref; return next; return;
  end if;

  v_is_staff := private.has_permission(v_facility_id, 'create_bookings');

  select s.id, s.name, s.base_price, s.duration_min
    into v_service_id, v_service_name, v_price, v_duration
    from public.grooming_services s
   where s.facility_id = v_facility_id
     and (s.legacy_id = p_grooming->>'serviceId' or s.id::text = p_grooming->>'serviceId');

  if v_service_id is null then
    raise exception 'This facility has no grooming service %.',
      coalesce(p_grooming->>'serviceId', '(none given)') using errcode = '23503';
  end if;

  select p.weight into v_weight from public.pets p where p.id = p_pet_ids[1];

  if v_weight is not null then
    select t->>'id' into v_size
      from public.grooming_config c,
           lateral jsonb_array_elements(c.pet_size_tiers) t
     where c.facility_id = v_facility_id
       and (t->>'maxWeightLbs' is null
            or v_weight <= (t->>'maxWeightLbs')::numeric)
     order by coalesce((t->>'maxWeightLbs')::numeric, 999999)
     limit 1;
  end if;

  if v_size is not null then
    select sp.price, sp.duration_min into v_size_price, v_size_dur
      from public.grooming_service_size_prices sp
     where sp.service_id = v_service_id and sp.size_label = v_size;
    if v_size_price is not null then v_price := v_size_price; end if;
    if v_size_dur   is not null then v_duration := v_size_dur; end if;
  end if;

  if (p_grooming->>'durationOverrideMin') is not null then
    v_duration := (p_grooming->>'durationOverrideMin')::integer;
  end if;

  if p_grooming->>'stationId' is not null then
    select st.id into v_station_id
      from public.grooming_stations st
     where st.facility_id = v_facility_id
       and (st.legacy_id = p_grooming->>'stationId' or st.id::text = p_grooming->>'stationId');
  end if;

  insert into public.grooming_appointments (
    booking_id, facility_id, service_id, service_name,
    size_label, service_price, service_duration_min, station_id
  )
  values (
    v_booking_id, v_facility_id, v_service_id, v_service_name, v_size,
    case when v_is_staff then v_price else 0 end,
    greatest(coalesce(v_duration, 60), 1), v_station_id
  );

  if jsonb_typeof(p_grooming->'addOnIds') = 'array' then
    insert into public.grooming_appointment_add_ons (
      booking_id, facility_id, add_on_id, name, price, duration_min
    )
    select v_booking_id, v_facility_id, a.id, a.name,
           case when v_is_staff then a.price else 0 end, a.duration_min
      from jsonb_array_elements_text(p_grooming->'addOnIds') requested
      join public.grooming_add_ons a
        on a.facility_id = v_facility_id
       and (a.legacy_id = requested or a.id::text = requested);

    get diagnostics v_written = row_count;
    v_requested := jsonb_array_length(p_grooming->'addOnIds');

    if v_written <> v_requested then
      raise exception 'This facility has % of the % grooming add-ons requested.',
        v_written, v_requested using errcode = '23503';
    end if;
  end if;

  booking_id := v_booking_id; booking_ref := v_ref; return next;
end;
$$;


ALTER FUNCTION "public"."create_booking"("p_booking" "jsonb", "p_pet_ids" "uuid"[], "p_grooming" "jsonb", "p_boarding" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_booking"("p_booking" "jsonb", "p_pet_ids" "uuid"[], "p_grooming" "jsonb", "p_boarding" "jsonb") IS 'Creates a booking, its pets and -- per module -- its grooming appointment or its boarding stay, in one transaction. SECURITY INVOKER: every insert is judged by RLS as the caller, and any refusal rolls back the whole booking.';



CREATE OR REPLACE FUNCTION "public"."create_bookings"("p_items" "jsonb") RETURNS TABLE("item_index" integer, "booking_id" "uuid", "booking_ref" bigint)
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_item    jsonb;
  v_index   integer := 0;
  v_pets    uuid[];
  v_created record;
begin
  if p_items is null or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) = 0 then
    raise exception 'create_bookings needs at least one booking.'
      using errcode = '22023';
  end if;

  if jsonb_array_length(p_items) > 100 then
    raise exception 'create_bookings takes at most 100 bookings at once.'
      using errcode = '22023';
  end if;

  for v_item in select value from jsonb_array_elements(p_items) loop
    select coalesce(array_agg(x::uuid), '{}'::uuid[]) into v_pets
      from jsonb_array_elements_text(coalesce(v_item->'petIds', '[]'::jsonb)) x;

    select * into v_created from public.create_booking(
      v_item->'booking',
      v_pets,
      nullif(v_item->'grooming', 'null'::jsonb),
      nullif(v_item->'boarding', 'null'::jsonb)
    );

    item_index  := v_index;
    booking_id  := v_created.booking_id;
    booking_ref := v_created.booking_ref;
    return next;
    v_index := v_index + 1;
  end loop;
end;
$$;


ALTER FUNCTION "public"."create_bookings"("p_items" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."training_series" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "location_id" "uuid",
    "staff_id" "uuid",
    "name" "text" NOT NULL,
    "course_type_name" "text" DEFAULT ''::"text" NOT NULL,
    "day_of_week" smallint NOT NULL,
    "start_time" time without time zone NOT NULL,
    "duration_minutes" integer NOT NULL,
    "start_date" "date" NOT NULL,
    "number_of_sessions" integer NOT NULL,
    "capacity" integer DEFAULT 0 NOT NULL,
    "total_price" numeric(10,2) DEFAULT 0 NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "taxable" boolean DEFAULT true NOT NULL,
    CONSTRAINT "training_series_capacity_check" CHECK (("capacity" >= 0)),
    CONSTRAINT "training_series_day_of_week_check" CHECK ((("day_of_week" >= 0) AND ("day_of_week" <= 6))),
    CONSTRAINT "training_series_duration_minutes_check" CHECK (("duration_minutes" > 0)),
    CONSTRAINT "training_series_number_of_sessions_check" CHECK (("number_of_sessions" > 0)),
    CONSTRAINT "training_series_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'active'::"text", 'completed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "training_series_total_price_check" CHECK (("total_price" >= (0)::numeric))
);


ALTER TABLE "public"."training_series" OWNER TO "postgres";


COMMENT ON TABLE "public"."training_series" IS 'A real training class offering -- schedule, instructor, branch, capacity, price. Sessions are generated once at create time (see create_training_series). The rich course-type/discipline catalog stays on the mock side; course_type_name here is a label only.';



COMMENT ON COLUMN "public"."training_series"."taxable" IS 'Whether enrolment in this series is charged the facility''s tax. The SERIES rather than the program, because training_series.total_price is what actually prices a training booking and a series carries no reference to the program it was modelled on. Default true — see 20260921171524.';



CREATE OR REPLACE FUNCTION "public"."create_training_series"("p_facility_id" "uuid", "p_name" "text", "p_day_of_week" smallint, "p_start_time" time without time zone, "p_duration_minutes" integer, "p_start_date" "date", "p_number_of_sessions" integer, "p_capacity" integer DEFAULT 0, "p_total_price" numeric DEFAULT 0, "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_staff_id" "uuid" DEFAULT NULL::"uuid", "p_course_type_name" "text" DEFAULT ''::"text") RETURNS "public"."training_series"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_series       public.training_series;
  v_tz           text;
  v_session_date date;
  v_start_at     timestamptz;
  v_end_at       timestamptz;
  v_i            integer;
begin
  if p_location_id is not null and not exists (
       select 1 from public.locations l
        where l.id = p_location_id and l.facility_id = p_facility_id)
  then
    raise exception 'That location does not belong to this facility.'
      using errcode = '23514';
  end if;

  if p_staff_id is not null and not exists (
       select 1 from public.staff s
        where s.id = p_staff_id and s.facility_id = p_facility_id)
  then
    raise exception 'That staff member does not belong to this facility.'
      using errcode = '23514';
  end if;

  if p_location_id is not null then
    select l.timezone into v_tz from public.locations l where l.id = p_location_id;
  end if;
  if v_tz is null then
    select l.timezone into v_tz
      from public.locations l
     where l.facility_id = p_facility_id
     order by l.is_primary desc
     limit 1;
  end if;
  v_tz := coalesce(v_tz, 'UTC');

  insert into public.training_series (
    facility_id, location_id, staff_id, name, course_type_name,
    day_of_week, start_time, duration_minutes, start_date,
    number_of_sessions, capacity, total_price
  ) values (
    p_facility_id, p_location_id, p_staff_id, p_name, coalesce(p_course_type_name, ''),
    p_day_of_week, p_start_time, p_duration_minutes, p_start_date,
    p_number_of_sessions, coalesce(p_capacity, 0), coalesce(p_total_price, 0)
  )
  returning * into v_series;

  for v_i in 0 .. v_series.number_of_sessions - 1 loop
    v_session_date := v_series.start_date + (v_i * 7);
    v_start_at := (v_session_date + v_series.start_time) at time zone v_tz;
    v_end_at := v_start_at + make_interval(mins => v_series.duration_minutes);

    insert into public.training_series_sessions (
      series_id, facility_id, session_number, start_at, end_at
    ) values (
      v_series.id, v_series.facility_id, v_i + 1, v_start_at, v_end_at
    );
  end loop;

  return v_series;
end;
$$;


ALTER FUNCTION "public"."create_training_series"("p_facility_id" "uuid", "p_name" "text", "p_day_of_week" smallint, "p_start_time" time without time zone, "p_duration_minutes" integer, "p_start_date" "date", "p_number_of_sessions" integer, "p_capacity" integer, "p_total_price" numeric, "p_location_id" "uuid", "p_staff_id" "uuid", "p_course_type_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_training_series"("p_facility_id" "uuid", "p_name" "text", "p_day_of_week" smallint, "p_start_time" time without time zone, "p_duration_minutes" integer, "p_start_date" "date", "p_number_of_sessions" integer, "p_capacity" integer, "p_total_price" numeric, "p_location_id" "uuid", "p_staff_id" "uuid", "p_course_type_name" "text") IS 'Creates a training series and materializes all of its sessions, once, in the facility''s (or the series'' own branch''s) timezone. SECURITY INVOKER -- judged by training_series_write.';



