CREATE TABLE IF NOT EXISTS "public"."training_makeups" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "missed_booking_id" "uuid" NOT NULL,
    "missed_session_id" "uuid",
    "pet_id" "uuid" NOT NULL,
    "client_id" "uuid" NOT NULL,
    "status" "text" NOT NULL,
    "host_session_id" "uuid",
    "host_booking_id" "uuid",
    "owner_note" "text",
    "ineligible_reason" "text",
    "requested_at" timestamp with time zone,
    "offered_at" timestamp with time zone,
    "offered_by_name" "text",
    "answered_at" timestamp with time zone,
    "decided_at" timestamp with time zone,
    "decided_by_name" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "training_makeups_ineligible_reason_check" CHECK ((("ineligible_reason" IS NULL) OR (("length"("ineligible_reason") >= 1) AND ("length"("ineligible_reason") <= 1000)))),
    CONSTRAINT "training_makeups_ineligible_says_why" CHECK ((("status" <> 'ineligible'::"text") OR ("ineligible_reason" IS NOT NULL))),
    CONSTRAINT "training_makeups_owner_note_check" CHECK ((("owner_note" IS NULL) OR (("length"("owner_note") >= 1) AND ("length"("owner_note") <= 1000)))),
    CONSTRAINT "training_makeups_status_check" CHECK (("status" = ANY (ARRAY['requested'::"text", 'offered'::"text", 'declined'::"text", 'skipped'::"text", 'ineligible'::"text"])))
);


ALTER TABLE "public"."training_makeups" OWNER TO "postgres";


COMMENT ON TABLE "public"."training_makeups" IS 'What happens after a dog misses a training session: requested, offered (a $0 seat booked in another series), declined, skipped or ineligible. Written only through the five make-up functions. Replaces the make-up fixtures (2026-09-12).';



CREATE OR REPLACE FUNCTION "public"."decline_training_makeup"("p_makeup_id" "uuid") RETURNS "public"."training_makeups"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.training_makeups;
begin
  select * into v_row from public.training_makeups where id = p_makeup_id for update;
  if not found or private.training_makeup_actor(v_row.facility_id, v_row.client_id) is null then
    raise exception 'That make-up is not yours to decline.' using errcode = '42501';
  end if;
  if v_row.status = 'declined' then
    return v_row;
  end if;
  if v_row.status <> 'offered' then
    raise exception 'Only a booked make-up seat can be declined.' using errcode = '22023';
  end if;

  if v_row.host_booking_id is not null then
    if exists (
      select 1 from public.training_attendance a
       where a.booking_id = v_row.host_booking_id and a.checked_in_at is not null
    ) or exists (
      select 1 from public.bookings b
       where b.id = v_row.host_booking_id
         and b.status::text not in ('pending', 'request_submitted', 'confirmed', 'cancelled')
    ) then
      raise exception 'That make-up session has already started.' using errcode = '22023';
    end if;
    update public.bookings
       set status = 'cancelled'
     where id = v_row.host_booking_id
       and status::text <> 'cancelled';
  end if;

  update public.training_makeups
     set status = 'declined', answered_at = now(), updated_at = now()
   where id = v_row.id
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."decline_training_makeup"("p_makeup_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."disconnect_payment_connection"("p_facility_id" "uuid", "p_reason" "text", "p_processor" "text" DEFAULT 'clover'::"text") RETURNS TABLE("connection_revoked" boolean, "credentials_removed" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_changed  integer;
  v_access   uuid;
  v_refresh  uuid;
begin
  update public.payment_connections
     set status     = 'revoked',
         revoked_at = coalesce(revoked_at, now()),
         last_error = p_reason,
         updated_at = now()
   where facility_id = p_facility_id
     and processor   = p_processor
     and status is distinct from 'revoked';

  get diagnostics v_changed = row_count;
  connection_revoked := v_changed > 0;

  delete from private.payment_credentials
   where facility_id = p_facility_id
     and processor   = p_processor
  returning access_token_secret_id, refresh_token_secret_id
       into v_access, v_refresh;

  get diagnostics v_changed = row_count;
  credentials_removed := v_changed > 0;

  if v_access is not null then
    delete from vault.secrets where id = v_access;
  end if;

  if v_refresh is not null then
    delete from vault.secrets where id = v_refresh;
  end if;

  return next;
end;
$$;


ALTER FUNCTION "public"."disconnect_payment_connection"("p_facility_id" "uuid", "p_reason" "text", "p_processor" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."disconnect_payment_connection"("p_facility_id" "uuid", "p_reason" "text", "p_processor" "text") IS 'Revoke a facility''s payment connection AND destroy the stored OAuth credentials. Clover has no revoke API, so this gives up our own copy; the merchant must uninstall the app to kill the tokens at their end.';



CREATE OR REPLACE FUNCTION "public"."dismiss_unattached_payment"("p_id" "uuid", "p_note" "text") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_changed integer;
begin
  if coalesce(trim(p_note), '') = '' then
    raise exception 'Say why this payment is being set aside.'
      using errcode = '22023';
  end if;

  update public.unattached_payments
     set status = 'dismissed',
         resolved_by = (select auth.jwt() ->> 'sub'),
         resolved_at = now(),
         note = p_note,
         updated_at = now()
   where id = p_id
     and status = 'unattached'
     -- INVOKER cannot help here: there is no UPDATE policy on this table, so
     -- the permission is asked for directly. `financial_take_payment` is the
     -- same key attaching requires — setting a payment aside is the same
     -- decision with the opposite answer.
     and private.has_permission(facility_id, 'financial_take_payment');

  get diagnostics v_changed = row_count;
  return v_changed > 0;
end;
$$;


ALTER FUNCTION "public"."dismiss_unattached_payment"("p_id" "uuid", "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."dismiss_unattached_payment"("p_id" "uuid", "p_note" "text") IS 'Sets an unclaimed payment aside with a stated reason. Returns false when nothing moved — the caller must not report success on a zero-row update.';



CREATE OR REPLACE FUNCTION "public"."emit_automation_event"("p_facility_id" "uuid", "p_kind" "text", "p_dedupe_key" "text", "p_client_id" "uuid" DEFAULT NULL::"uuid", "p_pet_id" "uuid" DEFAULT NULL::"uuid", "p_booking_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_sub text := (select auth.jwt() ->> 'sub');
  v_id bigint;
begin
  if v_sub is not null
     and not private.is_platform_admin()
     and p_facility_id not in (select private.member_facility_ids()) then
    raise exception 'not a member of that facility';
  end if;

  insert into public.automation_events (
    facility_id, kind, dedupe_key, client_id, pet_id, booking_id, location_id, payload
  ) values (
    p_facility_id, p_kind, p_dedupe_key, p_client_id, p_pet_id, p_booking_id, p_location_id,
    coalesce(p_payload, '{}'::jsonb)
  )
  on conflict (dedupe_key) do nothing
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."emit_automation_event"("p_facility_id" "uuid", "p_kind" "text", "p_dedupe_key" "text", "p_client_id" "uuid", "p_pet_id" "uuid", "p_booking_id" "uuid", "p_location_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."emit_automation_event"("p_facility_id" "uuid", "p_kind" "text", "p_dedupe_key" "text", "p_client_id" "uuid", "p_pet_id" "uuid", "p_booking_id" "uuid", "p_location_id" "uuid", "p_payload" "jsonb") IS 'Record a domain event for automations. Idempotent on dedupe_key. Returns NULL when the event already existed.';



CREATE OR REPLACE FUNCTION "public"."enroll_in_training_series"("p_series_id" "uuid", "p_pet_id" "uuid", "p_client_id" "uuid", "p_join_waitlist" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_series     public.training_series;
  v_enrolled   integer;
  v_status     text;
  v_enrollment public.training_series_enrollments;
  v_session    public.training_series_sessions;
  v_created    record;
  v_price      numeric;
  v_bookings   jsonb := '[]'::jsonb;
begin
  perform pg_advisory_xact_lock(hashtext(p_series_id::text));

  select * into v_series from public.training_series where id = p_series_id;
  if not found then
    raise exception 'No such training series.' using errcode = '23503';
  end if;

  if v_series.status <> 'active' then
    raise exception 'This series is not open for enrollment.' using errcode = '22023';
  end if;

  select count(*) into v_enrolled
    from public.training_series_enrollments
   where series_id = p_series_id and status = 'enrolled';

  if v_enrolled >= v_series.capacity then
    if not p_join_waitlist then
      raise exception 'This series is full.' using errcode = '22023';
    end if;
    v_status := 'waitlisted';
  else
    v_status := 'enrolled';
  end if;

  insert into public.training_series_enrollments (
    series_id, facility_id, pet_id, client_id, status
  ) values (
    p_series_id, v_series.facility_id, p_pet_id, p_client_id, v_status
  )
  returning * into v_enrollment;

  if v_status = 'waitlisted' then
    return jsonb_build_object('enrollment', to_jsonb(v_enrollment), 'bookings', v_bookings);
  end if;

  v_price := case when v_series.number_of_sessions > 0
                  then round(v_series.total_price / v_series.number_of_sessions, 2)
                  else 0 end;

  for v_session in
    select * from public.training_series_sessions
     where series_id = p_series_id
       and status = 'scheduled'
       and start_at >= now()
     order by session_number
  loop
    select * into v_created from public.create_booking(
      jsonb_build_object(
        'facility_id', v_series.facility_id,
        'location_id', v_series.location_id,
        'client_id', p_client_id,
        'service', 'training',
        'service_type', v_series.course_type_name,
        'status', 'confirmed',
        'start_at', v_session.start_at,
        'end_at', v_session.end_at,
        'assigned_staff_id', v_series.staff_id,
        'base_price', v_price,
        'total_cost', v_price,
        'training_series_session_id', v_session.id
      ),
      array[p_pet_id]
    );

    v_bookings := v_bookings || jsonb_build_object(
      'bookingId', v_created.booking_id,
      'bookingRef', v_created.booking_ref,
      'sessionId', v_session.id,
      'sessionNumber', v_session.session_number
    );
  end loop;

  return jsonb_build_object('enrollment', to_jsonb(v_enrollment), 'bookings', v_bookings);
end;
$$;


ALTER FUNCTION "public"."enroll_in_training_series"("p_series_id" "uuid", "p_pet_id" "uuid", "p_client_id" "uuid", "p_join_waitlist" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enroll_in_training_series"("p_series_id" "uuid", "p_pet_id" "uuid", "p_client_id" "uuid", "p_join_waitlist" boolean) IS 'Enrolls a pet in a series and books every remaining session through create_booking() itself -- pricing/status-by-caller is not reimplemented here, the bookings-level trigger already does it. Full + not joining the waitlist raises; full + joining creates the enrollment as waitlisted with no bookings. SECURITY INVOKER -- judged by training_series_enrollments_insert and create_booking''s own policies.';



CREATE OR REPLACE FUNCTION "public"."ensure_automation_rules"("p_facility_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_email uuid;
  v_sms uuid;
begin
  -- The templates have to exist first; both seeders are idempotent so calling
  -- this twice, or in either order, is safe.
  perform public.ensure_message_templates(p_facility_id);

  -- Booking confirmation. The one trigger that actually delivers today.
  select id into v_email from public.message_templates
   where facility_id = p_facility_id and key = 'booking_confirmation';
  insert into public.automation_rules
    (facility_id, seed_key, name, trigger, email_template_id, is_transactional, created_by)
  values (p_facility_id, 'booking_confirmation', 'Booking Confirmation',
          'booking_created', v_email, true, 'yipyy')
  on conflict (facility_id, seed_key) where seed_key is not null do nothing;

  -- Check-out notice, email and text on one rule.
  select id into v_email from public.message_templates
   where facility_id = p_facility_id and key = 'check_out_notice';
  select id into v_sms from public.message_templates
   where facility_id = p_facility_id and key = 'check_out_notice_sms';
  insert into public.automation_rules
    (facility_id, seed_key, name, trigger, email_template_id, sms_template_id, is_transactional, created_by)
  values (p_facility_id, 'check_out_notice', 'Check-Out Notice',
          'check_out', v_email, v_sms, true, 'yipyy')
  on conflict (facility_id, seed_key) where seed_key is not null do nothing;

  select id into v_email from public.message_templates
   where facility_id = p_facility_id and key = 'check_in_notice';
  insert into public.automation_rules
    (facility_id, seed_key, name, trigger, email_template_id, is_transactional, created_by)
  values (p_facility_id, 'check_in_notice', 'Check-In Notice',
          'check_in', v_email, true, 'yipyy')
  on conflict (facility_id, seed_key) where seed_key is not null do nothing;

  select id into v_sms from public.message_templates
   where facility_id = p_facility_id and key = 'reminder_24h';
  insert into public.automation_rules
    (facility_id, seed_key, name, trigger, sms_template_id, offset_minutes, is_transactional, created_by)
  values (p_facility_id, 'reminder_24h', '24-Hour Reminder',
          '24h_before', v_sms, -1440, true, 'yipyy')
  on conflict (facility_id, seed_key) where seed_key is not null do nothing;

  -- ── Payment ──────────────────────────────────────────────────────────────
  select id into v_email from public.message_templates
   where facility_id = p_facility_id and key = 'payment_receipt';
  insert into public.automation_rules
    (facility_id, seed_key, name, trigger, email_template_id, is_transactional, created_by)
  values (p_facility_id, 'payment_receipt', 'Payment Receipt',
          'payment_received', v_email, true, 'yipyy')
  on conflict (facility_id, seed_key) where seed_key is not null do nothing;

  -- The one the spec calls out by name: the template existed in the picker and
  -- there was no rule anywhere, so staff had no way to discover it at all.
  select id into v_email from public.message_templates
   where facility_id = p_facility_id and key = 'overdue_invoice';
  insert into public.automation_rules
    (facility_id, seed_key, name, trigger, email_template_id, is_transactional, created_by)
  values (p_facility_id, 'overdue_invoice', 'Overdue Invoice Reminder',
          'payment_overdue', v_email, true, 'yipyy')
  on conflict (facility_id, seed_key) where seed_key is not null do nothing;

  -- Revenue protection for facilities that hold a booking against a deposit.
  select id into v_email from public.message_templates
   where facility_id = p_facility_id and key = 'deposit_request';
  insert into public.automation_rules
    (facility_id, seed_key, name, trigger, email_template_id, is_transactional, created_by)
  values (p_facility_id, 'deposit_request', 'Deposit Request',
          'booking_created', v_email, true, 'yipyy')
  on conflict (facility_id, seed_key) where seed_key is not null do nothing;

  -- ── Booking requests ─────────────────────────────────────────────────────
  select id into v_email from public.message_templates
   where facility_id = p_facility_id and key = 'booking_request_received';
  insert into public.automation_rules
    (facility_id, seed_key, name, trigger, email_template_id, is_transactional, created_by)
  values (p_facility_id, 'booking_request_received', 'Booking Request Received',
          'booking_request_submitted', v_email, true, 'yipyy')
  on conflict (facility_id, seed_key) where seed_key is not null do nothing;

  select id into v_email from public.message_templates
   where facility_id = p_facility_id and key = 'booking_request_approved';
  insert into public.automation_rules
    (facility_id, seed_key, name, trigger, email_template_id, is_transactional, created_by)
  values (p_facility_id, 'booking_request_approved', 'Booking Request Approved',
          'booking_request_approved', v_email, true, 'yipyy')
  on conflict (facility_id, seed_key) where seed_key is not null do nothing;

  select id into v_email from public.message_templates
   where facility_id = p_facility_id and key = 'booking_request_declined';
  insert into public.automation_rules
    (facility_id, seed_key, name, trigger, email_template_id, is_transactional, created_by)
  values (p_facility_id, 'booking_request_declined', 'Booking Request Declined',
          'booking_request_declined', v_email, true, 'yipyy')
  on conflict (facility_id, seed_key) where seed_key is not null do nothing;

  -- ── Reminders ────────────────────────────────────────────────────────────
  --
  -- NOT transactional. A vaccination reminder is a relationship message about a
  -- service requirement, but it is not confirming something the customer just
  -- asked for, so a marketing opt-out should stop it.
  select id into v_email from public.message_templates
   where facility_id = p_facility_id and key = 'vaccination_expiry';
  insert into public.automation_rules
    (facility_id, seed_key, name, trigger, email_template_id, offset_minutes, is_transactional, created_by)
  values (p_facility_id, 'vaccination_expiry', 'Vaccination Expiry Warning',
          'vaccination_expiry', v_email, -43200, false, 'yipyy')
  on conflict (facility_id, seed_key) where seed_key is not null do nothing;
end;
$$;


