CREATE OR REPLACE FUNCTION "public"."facility_branding_by_slug"("p_slug" "text") RETURNS TABLE("facility_id" "uuid", "name" "text", "slug" "text", "logo_url" "text", "wordmark_url" "text", "primary_color" "text", "accent_color" "text", "tagline" "text", "allow_customer_signup" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select f.id, f.name, f.slug,
         b.logo_url, b.wordmark_url, b.primary_color, b.accent_color, b.tagline,
         f.allow_customer_signup
    from public.facilities f
    left join public.facility_branding b on b.facility_id = f.id
   where f.slug = lower(trim(p_slug))
   limit 1;
$$;


ALTER FUNCTION "public"."facility_branding_by_slug"("p_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."facility_branding_by_slug"("p_slug" "text") IS 'The public branding for one facility, by exact slug. DELIBERATELY anon-callable and allowlisted in V7 of rpc-session-required.sql: a branded sign-in page renders for a visitor who is by definition not signed in, so src/lib/api/facility-branding.ts calls this with the publishable key and no session. An exact-slug lookup rather than a directory, and it omits support_email/support_phone on purpose. Revoking anon here blanks every facility''s front door.';



CREATE OR REPLACE FUNCTION "public"."facility_has_module"("p_facility_id" "uuid", "p_module_id" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    (select fm.enabled
       from public.facility_modules fm
      where fm.facility_id = p_facility_id
        and fm.module_id = p_module_id
        and (fm.expires_at is null or fm.expires_at > now())),
    exists (
      select 1
        from public.tier_modules tm
        join public.facility_subscriptions s on s.tier_id = tm.tier_id
       where s.facility_id = p_facility_id
         and tm.module_id = p_module_id),
    false);
$$;


ALTER FUNCTION "public"."facility_has_module"("p_facility_id" "uuid", "p_module_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."facility_module_entitlements"("p_facility_id" "uuid") RETURNS TABLE("module_id" "text", "slug" "text", "name" "text", "description" "text", "category" "text", "icon" "text", "enabled" boolean, "source" "text", "price_cents" integer, "list_price_cents" integer, "price_override_cents" integer, "included_in_plan" boolean, "available_on_plan" boolean, "is_standalone" boolean, "min_tier_rank" smallint, "expires_at" timestamp with time zone, "note" "text", "missing_dependencies" "text"[])
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with plan as (
    select t.id as tier_id, t.rank
      from public.facility_subscriptions s
      join public.subscription_tiers t on t.id = s.tier_id
     where s.facility_id = p_facility_id
  ),
  override as (
    select fm.module_id, fm.enabled, fm.price_override_cents, fm.expires_at, fm.note
      from public.facility_modules fm
     where fm.facility_id = p_facility_id
       and (fm.expires_at is null or fm.expires_at > now())
  ),
  resolved as (
    select m.id, m.slug, m.name, m.description, m.category, m.icon,
           m.price_monthly_cents, m.min_tier_rank, m.is_standalone, m.sort_order,
           exists (
             select 1 from public.tier_modules tm
              where tm.module_id = m.id
                and tm.tier_id = (select p.tier_id from plan p)
           ) as included,
           o.enabled              as ov_enabled,
           o.price_override_cents as ov_price,
           o.expires_at           as ov_expires,
           o.note                 as ov_note
      from public.modules m
      left join override o on o.module_id = m.id
     where m.is_active
  )
  select
    r.id,
    r.slug,
    r.name,
    r.description,
    r.category,
    r.icon,
    coalesce(r.ov_enabled, r.included) as enabled,
    case
      when not coalesce(r.ov_enabled, r.included)
        then case when r.included then 'withdrawn' else 'not included' end
      when r.included then 'plan'
      else 'add-on'
    end as source,
    coalesce(
      r.ov_price,
      case when r.included then 0 else r.price_monthly_cents end
    )::integer as price_cents,
    r.price_monthly_cents,
    r.ov_price,
    r.included,
    (r.min_tier_rank <= coalesce((select p.rank from plan p), 0)) as available_on_plan,
    r.is_standalone,
    r.min_tier_rank,
    r.ov_expires,
    coalesce(r.ov_note, ''),
    (
      select coalesce(array_agg(d.requires_module_id order by d.requires_module_id), '{}')
        from public.module_dependencies d
       where d.module_id = r.id
         and not coalesce(
               (select coalesce(x.ov_enabled, x.included) from resolved x where x.id = d.requires_module_id),
               false)
    ) as missing_dependencies
  from resolved r
  order by r.sort_order;
$$;


ALTER FUNCTION "public"."facility_module_entitlements"("p_facility_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."facility_module_entitlements"("p_facility_id" "uuid") IS 'The effective module list for one facility: the plan, with this facility''s overrides applied. Reads under the caller''s own permissions.';



CREATE OR REPLACE FUNCTION "public"."facility_report"("p_facility_id" "uuid", "p_months" integer DEFAULT 6) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with bounds as (
    select date_trunc('month', now())
             - make_interval(months => greatest(coalesce(p_months, 6), 1) - 1) as lo,
           date_trunc('month', now()) + interval '1 month'                     as hi
  ),
  months as (
    select generate_series(
             (select lo from bounds),
             (select hi from bounds) - interval '1 month',
             interval '1 month')::date as month
  ),
  booking as (
    select b.id,
           b.client_id,
           coalesce(nullif(trim(b.service), ''), 'unspecified') as service,
           b.status::text                                       as status,
           date_trunc('month', b.start_at)::date                as month,
           coalesce(b.amount_due, 0)                            as amount_due,
           coalesce(b.amount_paid, 0)                           as amount_paid
      from public.bookings b, bounds
     where b.facility_id = p_facility_id
       and b.start_at >= bounds.lo
       and b.start_at <  bounds.hi
  ),
  money as (
    select bk.month,
           bk.service,
           sum(p.grand_total - p.tip) as revenue,
           sum(p.tip)                 as tips
      from public.payments p
      join booking bk on bk.id = p.booking_id
     where p.facility_id = p_facility_id
     group by bk.month, bk.service
  ),
  booking_month as (
    select month,
           count(*)                                      as bookings,
           count(*) filter (where status = 'cancelled')   as cancelled,
           count(*) filter (where status = 'completed')   as completed
      from booking
     group by month
  ),
  money_month as (
    select month, sum(revenue) as revenue, sum(tips) as tips
      from money
     group by month
  ),
  service_bookings as (
    select service,
           count(*)                                    as bookings,
           count(*) filter (where status = 'cancelled') as cancelled
      from booking
     group by service
  ),
  service_money as (
    select service, sum(revenue) as revenue, sum(tips) as tips
      from money
     group by service
  )
  select jsonb_build_object(
    'from', (select lo from bounds),
    'to',   (select hi from bounds),
    'months', coalesce((
      select jsonb_agg(jsonb_build_object(
               'month',        to_char(m.month, 'YYYY-MM'),
               'bookings',     coalesce(bm.bookings, 0),
               'cancelled',    coalesce(bm.cancelled, 0),
               'completed',    coalesce(bm.completed, 0),
               'revenueCents', round(coalesce(mm.revenue, 0) * 100)::bigint,
               'tipsCents',    round(coalesce(mm.tips, 0) * 100)::bigint
             ) order by m.month)
        from months m
        left join booking_month bm on bm.month = m.month
        left join money_month  mm on mm.month = m.month), '[]'::jsonb),
    'services', coalesce((
      select jsonb_agg(jsonb_build_object(
               'service',      sb.service,
               'bookings',     sb.bookings,
               'cancelled',    sb.cancelled,
               'revenueCents', round(coalesce(sm.revenue, 0) * 100)::bigint
             ) order by coalesce(sm.revenue, 0) desc, sb.service)
        from service_bookings sb
        left join service_money sm on sm.service = sb.service), '[]'::jsonb),
    'totals', jsonb_build_object(
      'bookings',        (select count(*) from booking),
      'cancelled',       (select count(*) from booking where status = 'cancelled'),
      'completed',       (select count(*) from booking where status = 'completed'),
      'revenueCents',    (select round(coalesce(sum(revenue), 0) * 100)::bigint from money),
      'tipsCents',       (select round(coalesce(sum(tips), 0) * 100)::bigint from money),
      'outstandingCents',(select round(coalesce(sum(greatest(amount_due - amount_paid, 0)), 0) * 100)::bigint
                            from booking where status <> 'cancelled'),
      'activeClients',   (select count(distinct client_id) from booking where client_id is not null),
      'newClients',      (select count(*) from public.clients c, bounds
                           where c.facility_id = p_facility_id
                             and c.created_at >= bounds.lo
                             and c.created_at <  bounds.hi)
    )
  );
$$;


ALTER FUNCTION "public"."facility_report"("p_facility_id" "uuid", "p_months" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."facility_report"("p_facility_id" "uuid", "p_months" integer) IS 'One facility''s bookings and takings by service month. Revenue excludes tips; money is dated by the booking it paid for, not by when the payment row was written — see the header of 20260807620000.';



CREATE OR REPLACE FUNCTION "public"."facility_report_dataset"("p_facility_id" "uuid", "p_report" "text", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_prev_from" timestamp with time zone, "p_prev_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_result jsonb;
begin
  -- ── Revenue by service ────────────────────────────────────────────────
  if p_report = 'revenue-by-service' then
    select jsonb_build_object(
      'current',  coalesce((select jsonb_agg(r order by r->>'service')
                     from (select jsonb_build_object(
                             'service', b.service,
                             'revenue', coalesce(sum(p.grand_total), 0),
                             'bookings', count(distinct b.id) filter (where b.status <> 'cancelled')) as r
                             from public.bookings b
                             left join public.payments p on p.booking_id = b.id
                            where b.facility_id = p_facility_id
                              and (b.status <> 'cancelled' or p.id is not null)
                              and b.start_at >= p_from and b.start_at < p_to
                            group by b.service) x), '[]'::jsonb),
      'previous', coalesce((select jsonb_agg(r order by r->>'service')
                     from (select jsonb_build_object(
                             'service', b.service,
                             'revenue', coalesce(sum(p.grand_total), 0),
                             'bookings', count(distinct b.id) filter (where b.status <> 'cancelled')) as r
                             from public.bookings b
                             left join public.payments p on p.booking_id = b.id
                            where b.facility_id = p_facility_id
                              and (b.status <> 'cancelled' or p.id is not null)
                              and b.start_at >= p_prev_from and b.start_at < p_prev_to
                            group by b.service) x), '[]'::jsonb),
      'hours',    coalesce((select jsonb_agg(r order by r->>'service')
                     from (select jsonb_build_object(
                             'service', b.service,
                             'hours', round(sum(extract(epoch from
                               (coalesce(b.end_at, b.start_at + interval '1 hour')
                                - b.start_at)) / 3600.0)::numeric, 1)) as r
                             from public.bookings b
                            where b.facility_id = p_facility_id
                              and b.status <> 'cancelled'
                              and b.start_at >= p_from and b.start_at < p_to
                            group by b.service) x), '[]'::jsonb)
    ) into v_result;

  -- ── Revenue by location ───────────────────────────────────────────────
  elsif p_report = 'revenue-by-location' then
    select jsonb_build_object(
      'current',  coalesce((select jsonb_agg(r order by r->>'location')
                     from (select coalesce(l.id::text, 'none') as loc_key,
                                  jsonb_build_object(
                                    'locationId', l.id,
                                    'location', coalesce(l.name, 'No branch'),
                                    'revenue', coalesce(sum(p.grand_total), 0),
                                    'bookings', count(distinct b.id) filter (where b.status <> 'cancelled')) as r
                             from public.bookings b
                             left join public.payments p on p.booking_id = b.id
                             left join public.locations l on l.id = b.location_id
                            where b.facility_id = p_facility_id
                              and (b.status <> 'cancelled' or p.id is not null)
                              and b.start_at >= p_from and b.start_at < p_to
                            group by l.id, l.name) x), '[]'::jsonb),
      'previous', coalesce((select jsonb_agg(r order by r->>'location')
                     from (select coalesce(l.id::text, 'none') as loc_key,
                                  jsonb_build_object(
                                    'locationId', l.id,
                                    'location', coalesce(l.name, 'No branch'),
                                    'revenue', coalesce(sum(p.grand_total), 0),
                                    'bookings', count(distinct b.id) filter (where b.status <> 'cancelled')) as r
                             from public.bookings b
                             left join public.payments p on p.booking_id = b.id
                             left join public.locations l on l.id = b.location_id
                            where b.facility_id = p_facility_id
                              and (b.status <> 'cancelled' or p.id is not null)
                              and b.start_at >= p_prev_from and b.start_at < p_prev_to
                            group by l.id, l.name) x), '[]'::jsonb)
    ) into v_result;

  -- ── Service mix by location ────────────────────────────────────────────
  --
  -- Same join as revenue-by-location, grouped by (service, location) instead
  -- of just location. Powers the Service Mix chart and the per-location
  -- service breakdown on the Command Center KPI tiles.
  elsif p_report = 'service-mix-by-location' then
    select jsonb_build_object(
      'current',  coalesce((select jsonb_agg(r order by r->>'service', r->>'location')
                     from (select jsonb_build_object(
                                    'service', b.service,
                                    'locationId', l.id,
                                    'location', coalesce(l.name, 'No branch'),
                                    'revenue', coalesce(sum(p.grand_total), 0),
                                    'bookings', count(distinct b.id) filter (where b.status <> 'cancelled')) as r
                             from public.bookings b
                             left join public.payments p on p.booking_id = b.id
                             left join public.locations l on l.id = b.location_id
                            where b.facility_id = p_facility_id
                              and (b.status <> 'cancelled' or p.id is not null)
                              and b.start_at >= p_from and b.start_at < p_to
                            group by b.service, l.id, l.name) x), '[]'::jsonb),
      'previous', coalesce((select jsonb_agg(r order by r->>'service', r->>'location')
                     from (select jsonb_build_object(
                                    'service', b.service,
                                    'locationId', l.id,
                                    'location', coalesce(l.name, 'No branch'),
                                    'revenue', coalesce(sum(p.grand_total), 0),
                                    'bookings', count(distinct b.id) filter (where b.status <> 'cancelled')) as r
                             from public.bookings b
                             left join public.payments p on p.booking_id = b.id
                             left join public.locations l on l.id = b.location_id
                            where b.facility_id = p_facility_id
                              and (b.status <> 'cancelled' or p.id is not null)
                              and b.start_at >= p_prev_from and b.start_at < p_prev_to
                            group by b.service, l.id, l.name) x), '[]'::jsonb)
    ) into v_result;

  -- ── Training attendance by location ─────────────────────────────────────
  --
  -- Bookings + check-in facts only -- no class/series/enrollment table exists,
  -- so this cannot answer "active classes" or "students enrolled". `bookings`
  -- counts exclude cancellations, same as every other report here.
  elsif p_report = 'training-attendance-by-location' then
    select jsonb_build_object(
      'current',  coalesce((select jsonb_agg(r order by r->>'location')
                     from (select jsonb_build_object(
                                    'locationId', l.id,
                                    'location', coalesce(l.name, 'No branch'),
                                    'bookings', count(distinct b.id) filter (where b.status <> 'cancelled'),
                                    'checkedIn', count(distinct b.id) filter (
                                      where b.status <> 'cancelled' and ta.checked_in_at is not null),
                                    'checkedOut', count(distinct b.id) filter (
                                      where b.status <> 'cancelled' and ta.checked_out_at is not null)) as r
                             from public.bookings b
                             left join public.training_attendance ta on ta.booking_id = b.id
                             left join public.locations l on l.id = b.location_id
                            where b.facility_id = p_facility_id
                              and b.service = 'training'
                              and b.start_at >= p_from and b.start_at < p_to
                            group by l.id, l.name) x), '[]'::jsonb),
      'previous', coalesce((select jsonb_agg(r order by r->>'location')
                     from (select jsonb_build_object(
                                    'locationId', l.id,
                                    'location', coalesce(l.name, 'No branch'),
                                    'bookings', count(distinct b.id) filter (where b.status <> 'cancelled'),
                                    'checkedIn', count(distinct b.id) filter (
                                      where b.status <> 'cancelled' and ta.checked_in_at is not null),
                                    'checkedOut', count(distinct b.id) filter (
                                      where b.status <> 'cancelled' and ta.checked_out_at is not null)) as r
                             from public.bookings b
                             left join public.training_attendance ta on ta.booking_id = b.id
                             left join public.locations l on l.id = b.location_id
                            where b.facility_id = p_facility_id
                              and b.service = 'training'
                              and b.start_at >= p_prev_from and b.start_at < p_prev_to
                            group by l.id, l.name) x), '[]'::jsonb)
    ) into v_result;

  -- ── Occupancy, per day ────────────────────────────────────────────────
  elsif p_report = 'occupancy-report' then
    with capacity as (
      select coalesce(sum(capacity), 0) as total
        from public.facility_rooms
       where facility_id = p_facility_id and active
    ),
    days as (
      select g::date as the_day, 'current' as win
        from generate_series(p_from::date, (p_to - interval '1 day')::date,
                             interval '1 day') g
      union all
      select g::date, 'previous'
        from generate_series(p_prev_from::date, (p_prev_to - interval '1 day')::date,
                             interval '1 day') g
    ),
    stays as (
      select b.start_at, b.end_at, b.total_cost,
             greatest(1, extract(epoch from
               (coalesce(b.end_at, b.start_at + interval '1 day') - b.start_at))
               / 86400.0) as nights
        from public.bookings b
       where b.facility_id = p_facility_id
         and b.service = 'boarding'
         and b.status <> 'cancelled'
    ),
    rows as (
      select d.win, d.the_day, o.occupied, c.total,
             case when c.total > 0
                  then round((o.occupied::numeric / c.total) * 100, 2)
                  else 0 end as rate,
             round(o.revenue, 2) as revenue
        from days d
        cross join capacity c
        cross join lateral (
          select count(*) as occupied,
                 coalesce(sum(s.total_cost / s.nights), 0) as revenue
            from stays s
           where s.start_at::date <= d.the_day
             and coalesce(s.end_at, s.start_at + interval '1 day')::date >= d.the_day
        ) o
    )
    select jsonb_build_object(
      'current',  coalesce((select jsonb_agg(jsonb_build_object(
                     'date', the_day, 'occupied', occupied, 'capacity', total,
                     'occupancyRate', rate, 'revenue', revenue) order by the_day)
                     from rows where win = 'current'), '[]'::jsonb),
      'previous', coalesce((select jsonb_agg(jsonb_build_object(
                     'date', the_day, 'occupied', occupied, 'capacity', total,
                     'occupancyRate', rate, 'revenue', revenue) order by the_day)
                     from rows where win = 'previous'), '[]'::jsonb)
    ) into v_result;

  -- ── Cancelled bookings ────────────────────────────────────────────────
  elsif p_report = 'cancelled-bookings' then
    select jsonb_build_object(
      'current', coalesce((select jsonb_agg(r order by r->>'date' desc) from (
          select jsonb_build_object(
            'date', b.start_at,
            'service', b.service,
            'clientName', coalesce(c.name, 'Unknown'),
            'petName', coalesce((select string_agg(pt.name, ', ')
                                   from public.booking_pets bp
                                   join public.pets pt on pt.id = bp.pet_id
                                  where bp.booking_id = b.id), 'Unknown'),
            'reason', b.special_requests,
            'refundAmount', coalesce((select -sum(p.grand_total)
                                        from public.payments p
                                       where p.booking_id = b.id
                                         and p.grand_total < 0), 0)
          ) as r
            from public.bookings b
            left join public.clients c on c.id = b.client_id
           where b.facility_id = p_facility_id
             and b.status = 'cancelled'
             and b.start_at >= p_from and b.start_at < p_to) x), '[]'::jsonb),
      'previousRefunds', coalesce((
          select -sum(p.grand_total)
            from public.payments p
            join public.bookings b on b.id = p.booking_id
           where b.facility_id = p_facility_id
             and b.status = 'cancelled'
             and b.start_at >= p_prev_from and b.start_at < p_prev_to
             and p.grand_total < 0), 0),
      'previousCount', (select count(*) from public.bookings b
                         where b.facility_id = p_facility_id
                           and b.status = 'cancelled'
                           and b.start_at >= p_prev_from and b.start_at < p_prev_to)
    ) into v_result;

  -- ── Customer value ────────────────────────────────────────────────────
  elsif p_report = 'customer-value' then
    select jsonb_build_object(
      'customers', coalesce((select jsonb_agg(r order by (r->>'totalSpent')::numeric desc) from (
          select jsonb_build_object(
            'id', c.id,
            'name', c.name,
            'totalSpent', coalesce(sum(p.grand_total), 0),
            'totalBookings', count(distinct b.id),
            'lastVisit', max(b.start_at)
          ) as r
            from public.clients c
            join public.bookings b on b.client_id = c.id
                 and b.status <> 'cancelled'
                 and b.start_at >= p_from and b.start_at < p_to
            left join public.payments p on p.booking_id = b.id
           where c.facility_id = p_facility_id
           group by c.id, c.name) x), '[]'::jsonb),
      'activeClients', (select count(distinct b.client_id) from public.bookings b
                         where b.facility_id = p_facility_id
                           and b.status <> 'cancelled'
                           and b.start_at >= p_from and b.start_at < p_to),
      'prevActiveClients', (select count(distinct b.client_id) from public.bookings b
                             where b.facility_id = p_facility_id
                               and b.status <> 'cancelled'
                               and b.start_at >= p_prev_from and b.start_at < p_prev_to),
      'returningClients', (select count(*) from (
          select b.client_id from public.bookings b
           where b.facility_id = p_facility_id and b.status <> 'cancelled'
             and b.start_at >= p_prev_from and b.start_at < p_prev_to
             and b.client_id is not null
          intersect
          select b.client_id from public.bookings b
           where b.facility_id = p_facility_id and b.status <> 'cancelled'
             and b.start_at >= p_from and b.start_at < p_to
             and b.client_id is not null) z)
    ) into v_result;

  -- ── Total revenue ─────────────────────────────────────────────────────
  elsif p_report = 'total-revenue' then
    select jsonb_build_object(
      'daily', coalesce((select jsonb_agg(jsonb_build_object(
                   'date', day, 'gross', gross, 'refunded', refunded,
                   'net', net, 'transactions', txns) order by day)
                 from (select p.created_at::date as day,
                              coalesce(sum(p.grand_total) filter (where p.grand_total > 0), 0) as gross,
                              coalesce(-sum(p.grand_total) filter (where p.grand_total < 0), 0) as refunded,
                              sum(p.grand_total) as net,
                              count(*) filter (where p.grand_total > 0) as txns
                         from public.payments p
                        where p.facility_id = p_facility_id
                          and p.created_at >= p_from and p.created_at < p_to
                        group by 1) d), '[]'::jsonb),
      'transactions', (select count(*) from public.payments
                        where facility_id = p_facility_id
                          and created_at >= p_from and created_at < p_to
                          and grand_total > 0),
      'gross', coalesce((select sum(grand_total) from public.payments
                          where facility_id = p_facility_id
                            and created_at >= p_from and created_at < p_to
                            and grand_total > 0), 0),
      'refunded', coalesce((select -sum(grand_total) from public.payments
                             where facility_id = p_facility_id
                               and created_at >= p_from and created_at < p_to
                               and grand_total < 0), 0),
      'prevGross', coalesce((select sum(grand_total) from public.payments
                              where facility_id = p_facility_id
                                and created_at >= p_prev_from and created_at < p_prev_to
                                and grand_total > 0), 0)
    ) into v_result;

  -- ── Service charges ───────────────────────────────────────────────────
  --
  -- What a facility's own pricing rules earned, under the name it gave each
  -- one. `fee_id is not null` is what tells a service charge from a retail
  -- item or a line somebody typed: the rule that charged it is on the row
  -- (20260923090000).
  --
  -- GROUPED BY `fee_id`, NOT BY NAME. The name is what the invoice said and a
  -- facility may fix a typo in it at any time; the id is the durable identity,
  -- which is the whole reason it is on the row. Grouping by name would split
  -- one fee's history in two the day somebody corrected its spelling. The name
  -- shown is the one on the most recent line.
  --
  -- The window is the BOOKING's start, as `revenue-by-service` beside it uses,
  -- so the two can be read against each other — a charge added at the till
  -- still belongs to the stay it was added to.
  --
  -- A DISCOUNT authored as a custom fee is a negative line, and it is counted
  -- rather than filtered out: the question is what the facility's charges did
  -- to its revenue, and dropping the negatives answers a different one.
  elsif p_report = 'service-charges' then
    select jsonb_build_object(
      'current', coalesce((select jsonb_agg(r order by (r->>'revenue')::numeric desc, r->>'name')
          from (select jsonb_build_object(
                  'feeId', li.fee_id,
                  'name', (array_agg(li.name order by li.created_at desc))[1],
                  'revenue', coalesce(sum(li.price), 0),
                  'timesCharged', count(*),
                  'bookings', count(distinct li.booking_id)) as r
                  from public.booking_line_items li
                  join public.bookings b on b.id = li.booking_id
                 where li.facility_id = p_facility_id
                   and li.fee_id is not null
                   and b.status <> 'cancelled'
                   and b.start_at >= p_from and b.start_at < p_to
                 group by li.fee_id) x), '[]'::jsonb),
      'total', coalesce((select sum(li.price)
                           from public.booking_line_items li
                           join public.bookings b on b.id = li.booking_id
                          where li.facility_id = p_facility_id
                            and li.fee_id is not null
                            and b.status <> 'cancelled'
                            and b.start_at >= p_from and b.start_at < p_to), 0),
      'previousTotal', coalesce((select sum(li.price)
                           from public.booking_line_items li
                           join public.bookings b on b.id = li.booking_id
                          where li.facility_id = p_facility_id
                            and li.fee_id is not null
                            and b.status <> 'cancelled'
                            and b.start_at >= p_prev_from and b.start_at < p_prev_to), 0)
    ) into v_result;
  -- ── WHAT EACH PERSON EARNED ─────────────────────────────────────────────
  --
  -- Straight off `booking_commission_allocations`, which is already the
  -- answer: service only, net of discounts, before tax, in proportion to what
  -- was paid, with service charges excluded by construction
  -- (20260923220000). Recomputing any of that here would be a second opinion
  -- about somebody's pay.
  --
  -- `unpaid` is the figure a payout run needs — what is earned but not yet
  -- handed over — and it is a SUM over rows with no `paid_at`, never a count.
  --
  -- Windowed on the BOOKING's start, like every other report here, so a
  -- month's commission lines up with the month's revenue rather than with
  -- whenever the card happened to settle.
  elsif p_report = 'commission' then
    select jsonb_build_object(
      'current', coalesce((select jsonb_agg(r order by (r->>'earned')::numeric desc, r->>'name')
          from (select jsonb_build_object(
                  'staffId', a.staff_id,
                  'name', (array_agg(btrim(s.first_name || ' ' || s.last_name)))[1],
                  'earned', coalesce(sum(a.amount), 0),
                  'basis', coalesce(sum(a.basis), 0),
                  'bookings', count(distinct a.booking_id),
                  'unpaid', coalesce(sum(a.amount) filter (where a.paid_at is null), 0)) as r
                  from public.booking_commission_allocations a
                  join public.staff s on s.id = a.staff_id
                  join public.bookings b on b.id = a.booking_id
                 where a.facility_id = p_facility_id
                   and b.status <> 'cancelled'
                   and b.start_at >= p_from and b.start_at < p_to
                 group by a.staff_id) x), '[]'::jsonb),
      'total', coalesce((select sum(a.amount)
                           from public.booking_commission_allocations a
                           join public.bookings b on b.id = a.booking_id
                          where a.facility_id = p_facility_id
                            and b.status <> 'cancelled'
                            and b.start_at >= p_from and b.start_at < p_to), 0),
      'previousTotal', coalesce((select sum(a.amount)
                           from public.booking_commission_allocations a
                           join public.bookings b on b.id = a.booking_id
                          where a.facility_id = p_facility_id
                            and b.status <> 'cancelled'
                            and b.start_at >= p_prev_from and b.start_at < p_prev_to), 0)
    ) into v_result;

  else
    raise exception 'No such report: %', p_report using errcode = '22023';
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."facility_report_dataset"("p_facility_id" "uuid", "p_report" "text", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_prev_from" timestamp with time zone, "p_prev_to" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."facility_report_dataset"("p_facility_id" "uuid", "p_report" "text", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_prev_from" timestamp with time zone, "p_prev_to" timestamp with time zone) IS 'The dataset behind one facility report, from bookings, payments, clients, locations, facility_rooms and training_attendance. Cancelled bookings are excluded everywhere except the cancellation report. security invoker: RLS decides what is visible. Raises on an unknown report id rather than returning empty.';



CREATE OR REPLACE FUNCTION "public"."facility_report_kpis"("p_facility_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_prev_from" timestamp with time zone, "p_prev_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare v_capacity numeric; v_result jsonb;
begin
  select coalesce(sum(capacity), 0) into v_capacity
    from public.facility_rooms where facility_id = p_facility_id and active;

  with counted as (
    select b.client_id, b.start_at, b.end_at, b.service,
           (b.start_at >= p_from and b.start_at < p_to) as in_now,
           (b.start_at >= p_prev_from and b.start_at < p_prev_to) as in_prev
      from public.bookings b
     where b.facility_id = p_facility_id
       and b.status <> 'cancelled'
       and b.start_at >= least(p_from, p_prev_from)
       and b.start_at <  greatest(p_to, p_prev_to)
  ),
  bookings_now  as (select count(*) n, count(distinct client_id) clients from counted where in_now),
  bookings_prev as (select count(*) n, count(distinct client_id) clients from counted where in_prev),
  returning_clients as (
    select count(*) as n from (
      select client_id from counted where in_prev and client_id is not null
      intersect
      select client_id from counted where in_now and client_id is not null) bw
  ),
  money_now as (select coalesce(sum(grand_total),0) net from public.payments
                 where facility_id = p_facility_id and created_at >= p_from and created_at < p_to),
  money_prev as (select coalesce(sum(grand_total),0) net from public.payments
                 where facility_id = p_facility_id and created_at >= p_prev_from and created_at < p_prev_to),
  nights as (
    select
      sum(greatest(0, extract(epoch from (least(coalesce(end_at, start_at + interval '1 day'), p_to)
          - greatest(start_at, p_from)))/86400.0)) filter (where in_now and service = 'boarding') as now_nights,
      sum(greatest(0, extract(epoch from (least(coalesce(end_at, start_at + interval '1 day'), p_prev_to)
          - greatest(start_at, p_prev_from)))/86400.0)) filter (where in_prev and service = 'boarding') as prev_nights
    from counted
  ),
  window_days as (
    select greatest(1, extract(epoch from (p_to - p_from))/86400.0) now_days,
           greatest(1, extract(epoch from (p_prev_to - p_prev_from))/86400.0) prev_days
  )
  select jsonb_build_object(
    'bookings', bn.n, 'prevBookings', bp.n,
    'revenue', mn.net, 'prevRevenue', mp.net,
    'activeClients', bn.clients, 'prevActiveClients', bp.clients,
    'capacity', v_capacity,
    'boardingNights', coalesce(ng.now_nights, 0),
    'occupancyRate', case when v_capacity > 0 then least(1, coalesce(ng.now_nights,0)/(v_capacity*wd.now_days)) else 0 end,
    'prevOccupancyRate', case when v_capacity > 0 then least(1, coalesce(ng.prev_nights,0)/(v_capacity*wd.prev_days)) else 0 end,
    'retentionRate', case when bp.clients > 0 then rc.n::numeric/bp.clients else 0 end,
    'aov', case when bn.n > 0 then mn.net/bn.n else 0 end,
    'prevAov', case when bp.n > 0 then mp.net/bp.n else 0 end
  ) into v_result
  from bookings_now bn, bookings_prev bp, returning_clients rc,
       money_now mn, money_prev mp, nights ng, window_days wd;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."facility_report_kpis"("p_facility_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_prev_from" timestamp with time zone, "p_prev_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."facility_revenue_trend_by_location"("p_facility_id" "uuid", "p_months" integer DEFAULT 12) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'month', to_char(month_start, 'YYYY-MM'),
           'locationId', location_id,
           'location', location_name,
           'revenue', revenue
         ) order by month_start, location_name), '[]'::jsonb)
    from (
      select date_trunc('month', b.start_at) as month_start,
             l.id as location_id,
             coalesce(l.name, 'No branch') as location_name,
             coalesce(sum(p.grand_total), 0) as revenue
        from public.bookings b
        left join public.payments p on p.booking_id = b.id
        left join public.locations l on l.id = b.location_id
       where b.facility_id = p_facility_id
         and b.status <> 'cancelled'
         and b.start_at >= date_trunc('month', now()) - (make_interval(months => p_months - 1))
         and b.start_at < date_trunc('month', now()) + interval '1 month'
       group by 1, 2, 3
    ) t;
$$;


ALTER FUNCTION "public"."facility_revenue_trend_by_location"("p_facility_id" "uuid", "p_months" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."facility_revenue_trend_by_location"("p_facility_id" "uuid", "p_months" integer) IS 'Trailing N months of revenue per branch, from bookings/payments/locations. security invoker: RLS decides what is visible.';



CREATE OR REPLACE FUNCTION "public"."facility_staff_recipients"("p_facility_id" "uuid") RETURNS TABLE("email" "text", "full_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select distinct p.email::text, p.full_name::text
    from public.facility_memberships m
    join public.profiles p on p.id::text = m.profile_id::text
   where m.facility_id = p_facility_id
     and m.is_active
     and m.role::text in ('owner', 'admin')
     and p.email is not null
     and btrim(p.email::text) <> '';
$$;


ALTER FUNCTION "public"."facility_staff_recipients"("p_facility_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."facility_takings"("p_facility_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_time_zone" "text" DEFAULT 'UTC'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_zone   text := coalesce(nullif(trim(p_time_zone), ''), 'UTC');
  v_result jsonb;
begin
  begin
    perform now() at time zone v_zone;
  exception
    when others then v_zone := 'UTC';
  end;

  with scoped as (
    select p.grand_total, p.tip, p.tax, p.method, p.processor, p.booking_id,
           (p.created_at at time zone v_zone)::date as local_day
      from public.payments p
     where p.facility_id = p_facility_id
       and p.created_at >= p_from
       and p.created_at <  p_to
  ),
  totals as (
    select
      coalesce(sum(grand_total) filter (where grand_total > 0), 0)  as gross,
      coalesce(-sum(grand_total) filter (where grand_total < 0), 0) as refunded,
      coalesce(sum(grand_total), 0)                                 as net,
      coalesce(sum(tip), 0)                                         as tips,
      coalesce(sum(tax), 0)                                         as tax,
      count(*) filter (where grand_total > 0)                       as sales,
      count(*) filter (where grand_total < 0)                       as refunds,
      count(*) filter (where processor = 'clover' and grand_total > 0) as clover_sales,
      coalesce(sum(grand_total) filter (where processor = 'clover' and grand_total > 0), 0) as clover_gross
    from scoped
  ),
  failures as (
    select count(*) as failed
      from public.payment_intents pi
     where pi.facility_id = p_facility_id
       and pi.created_at >= p_from
       and pi.created_at <  p_to
       and pi.status in ('failed', 'declined')
  ),
  by_service as (
    select coalesce(b.service, 'other') as service,
           sum(s.grand_total) as net,
           count(*) filter (where s.grand_total > 0) as sales
      from scoped s left join public.bookings b on b.id = s.booking_id
     group by 1
  ),
  by_day as (
    select local_day,
           coalesce(sum(grand_total) filter (where grand_total > 0), 0)  as gross,
           coalesce(-sum(grand_total) filter (where grand_total < 0), 0) as refunded,
           sum(grand_total) as net,
           count(*) filter (where grand_total > 0) as sales
      from scoped group by 1
  ),
  by_method as (
    select method, sum(grand_total) as net,
           count(*) filter (where grand_total > 0) as sales
      from scoped group by 1
  ),
  by_channel as (
    select case when method = 'terminal' then 'in_person'
                when method in ('new-card', 'card-on-file') then 'online'
                else 'other' end as channel,
           sum(grand_total) as net,
           count(*) filter (where grand_total > 0) as sales
      from scoped group by 1
  )
  select jsonb_build_object(
    'gross', t.gross, 'refunded', t.refunded, 'net', t.net,
    'tips', t.tips, 'tax', t.tax, 'sales', t.sales, 'refunds', t.refunds,
    'failed', f.failed, 'cloverSales', t.clover_sales,
    'cloverGross', t.clover_gross, 'timeZone', v_zone,
    'byService', coalesce((select jsonb_agg(jsonb_build_object('service', service, 'net', net, 'sales', sales) order by net desc) from by_service), '[]'::jsonb),
    'byDay', coalesce((select jsonb_agg(jsonb_build_object('day', local_day, 'gross', gross, 'refunded', refunded, 'net', net, 'sales', sales) order by local_day) from by_day), '[]'::jsonb),
    'byMethod', coalesce((select jsonb_agg(jsonb_build_object('method', method, 'net', net, 'sales', sales) order by net desc) from by_method), '[]'::jsonb),
    'byChannel', coalesce((select jsonb_agg(jsonb_build_object('channel', channel, 'net', net, 'sales', sales) order by net desc) from by_channel), '[]'::jsonb)
  ) into v_result
  from totals t cross join failures f;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."facility_takings"("p_facility_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_time_zone" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."facility_tasks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "category" "text" DEFAULT 'general'::"text" NOT NULL,
    "priority" "text" DEFAULT 'medium'::"text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "assigned_to" "uuid",
    "due_at" timestamp with time zone,
    "estimated_minutes" integer,
    "requires_photo" boolean DEFAULT false NOT NULL,
    "requires_signoff" boolean DEFAULT false NOT NULL,
    "notes" "text",
    "completed_at" timestamp with time zone,
    "completed_by" "uuid",
    "source" "text" DEFAULT 'manual'::"text" NOT NULL,
    "source_ref" "text",
    "template_id" "uuid",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "facility_tasks_completed_together" CHECK ((("status" = 'completed'::"text") = ("completed_at" IS NOT NULL))),
    CONSTRAINT "facility_tasks_estimated_minutes_check" CHECK ((("estimated_minutes" IS NULL) OR ("estimated_minutes" > 0))),
    CONSTRAINT "facility_tasks_priority_check" CHECK (("priority" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text", 'urgent'::"text"]))),
    CONSTRAINT "facility_tasks_source_check" CHECK (("source" = ANY (ARRAY['manual'::"text", 'call_follow_up'::"text", 'reputation_escalation'::"text", 'template'::"text"]))),
    CONSTRAINT "facility_tasks_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'in_progress'::"text", 'completed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "facility_tasks_title_check" CHECK (("btrim"("title") <> ''::"text"))
);


ALTER TABLE "public"."facility_tasks" OWNER TO "postgres";


COMMENT ON TABLE "public"."facility_tasks" IS 'Work assigned to staff. Cancelled, never deleted - an abandoned task is a fact about how the week ran.';



COMMENT ON COLUMN "public"."facility_tasks"."source_ref" IS 'The producing feature''s own id. Unique per (facility, source) so two people working one queue cannot each create the same follow-up.';



CREATE OR REPLACE FUNCTION "public"."generate_tasks_from_group"("p_group_id" "uuid", "p_for_date" "date" DEFAULT NULL::"date", "p_assign_to" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "public"."facility_tasks"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_group   public.facility_task_groups;
  v_date    date;
  v_due     timestamptz;
  v_def     public.facility_task_definitions;
  v_ref     text;
begin
  select * into v_group from public.facility_task_groups where id = p_group_id;
  if not found then
    raise exception 'No such task group.' using errcode = '42501';
  end if;

  if not v_group.is_active then
    raise exception 'That task group is retired.' using errcode = '22023';
  end if;

  v_date := coalesce(p_for_date, current_date);

  if not v_group.is_recurring and v_group.specific_date is distinct from v_date then
    raise exception 'That group only runs on %.', v_group.specific_date
      using errcode = '22023';
  end if;

  if v_group.is_recurring
     and array_length(v_group.days_of_week, 1) is not null
     and not (extract(dow from v_date)::smallint = any (v_group.days_of_week))
  then
    raise exception 'That group does not run on that day of the week.'
      using errcode = '22023';
  end if;

  v_due := case v_group.shift_key
             when 'morning'   then v_date + time '12:00'
             when 'afternoon' then v_date + time '17:00'
             when 'night'     then v_date + time '23:59'
             else v_date + time '23:59'
           end;

  for v_def in
    select d.*
      from public.facility_task_group_items i
      join public.facility_task_definitions d on d.id = i.definition_id
     where i.group_id = p_group_id
       and d.is_active
     order by i.sort_order, d.title
  loop
    v_ref := p_group_id::text || ':' || v_date::text || ':' || v_def.id::text;

    begin
      return query
        insert into public.facility_tasks (
          facility_id, title, description, category, priority,
          assigned_to, due_at, estimated_minutes,
          requires_photo, requires_signoff,
          source, source_ref
        ) values (
          v_group.facility_id, v_def.title, v_def.description,
          v_def.category, v_def.priority,
          p_assign_to, v_due, v_def.estimated_minutes,
          v_def.requires_photo, v_def.requires_signoff,
          'template', v_ref
        )
        returning *;
    exception when unique_violation then
      null;
    end;
  end loop;

  return;
end;
$$;


ALTER FUNCTION "public"."generate_tasks_from_group"("p_group_id" "uuid", "p_for_date" "date", "p_assign_to" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."generate_tasks_from_group"("p_group_id" "uuid", "p_for_date" "date", "p_assign_to" "uuid") IS 'Creates today''s tasks for a group. Idempotent via facility_tasks_source_unique. SECURITY INVOKER so RLS still decides.';



CREATE OR REPLACE FUNCTION "public"."gift_card_totals"("p_facility_id" "uuid", "p_sales_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_sales_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_redeem_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_redeem_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with cards as (
    select g.id, g.status, g.kind, g.balance, g.initial_amount, g.issued_at
    from public.gift_cards g
    where g.facility_id = p_facility_id
  ),
  sold as (
    select c.*
    from cards c
    where (p_sales_from is null or c.issued_at >= p_sales_from)
      and (p_sales_to  is null or c.issued_at <  p_sales_to)
  ),
  -- What the screen counts as a redemption, matched exactly: every `redeemed`
  -- entry, plus an `adjusted` one that took money OFF. to-legacy-card.ts makes
  -- the same call, and a total that disagreed with the rows under it would be
  -- the whole defect again in a new place.
  redeemed as (
    select abs(t.amount) as amount, b.service
    from public.gift_card_transactions t
    left join public.bookings b on b.id = t.booking_id
    where t.facility_id = p_facility_id
      and (t.kind = 'redeemed' or (t.kind = 'adjusted' and t.amount < 0))
      and (p_redeem_from is null or t.created_at >= p_redeem_from)
      and (p_redeem_to   is null or t.created_at <  p_redeem_to)
  )
  select jsonb_build_object(
    -- Point in time, never date-ranged: money owed is owed today.
    'liability', (
      select jsonb_build_object(
        'count', count(*),
        'total', coalesce(sum(c.balance), 0)
      )
      from cards c
      where c.status = 'active' and c.balance > 0
    ),
    'cardCount', (select count(*) from cards),
    -- All-time face value: what the facility has ever sold, at issue price.
    'faceValue', (select coalesce(sum(c.initial_amount), 0) from cards c),
    'byStatus', (
      select coalesce(
        jsonb_object_agg(s.status,
          jsonb_build_object('count', s.n, 'balance', s.balance)),
        '{}'::jsonb)
      from (
        select c.status, count(*) as n, coalesce(sum(c.balance), 0) as balance
        from cards c
        group by c.status
      ) s
    ),
    'sales', (
      select jsonb_build_object(
        'count', count(*),
        'value', coalesce(sum(s.initial_amount), 0),
        -- `kind` is 'physical' or 'online'; anything not physical is digital,
        -- so a third kind added later counts as digital rather than vanishing.
        'physical', count(*) filter (where s.kind = 'physical'),
        'digital',  count(*) filter (where s.kind is distinct from 'physical'),
        -- Period-scoped, and deliberately NOT the same as `liability` above:
        -- what is still held on the cards sold in this window.
        'active', count(*) filter (where s.status = 'active'),
        'outstanding', coalesce(
          sum(s.balance) filter (where s.status = 'active'), 0)
      )
      from sold s
    ),
    'salesByMonth', (
      select coalesce(
        jsonb_agg(jsonb_build_object('month', m.month, 'value', m.value)
                  order by m.month),
        '[]'::jsonb)
      from (
        select to_char(date_trunc('month', s.issued_at), 'YYYY-MM') as month,
               sum(s.initial_amount) as value
        from sold s
        group by 1
      ) m
    ),
    'redemptions', (
      select jsonb_build_object(
        'count', count(*),
        'total', coalesce(sum(r.amount), 0)
      )
      from redeemed r
    ),
    'redemptionsByService', (
      select coalesce(
        jsonb_agg(jsonb_build_object('service', x.service, 'value', x.value)
                  order by x.value desc),
        '[]'::jsonb)
      from (
        select coalesce(r.service, 'unattributed') as service,
               sum(r.amount) as value
        from redeemed r
        group by 1
      ) x
    )
  );
$$;


ALTER FUNCTION "public"."gift_card_totals"("p_facility_id" "uuid", "p_sales_from" timestamp with time zone, "p_sales_to" timestamp with time zone, "p_redeem_from" timestamp with time zone, "p_redeem_to" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."gift_card_totals"("p_facility_id" "uuid", "p_sales_from" timestamp with time zone, "p_sales_to" timestamp with time zone, "p_redeem_from" timestamp with time zone, "p_redeem_to" timestamp with time zone) IS 'Gift-card liability, sales and redemptions for one facility, aggregated in SQL rather than by downloading every card. Security invoker: gift_cards RLS decides what it can see.';



CREATE OR REPLACE FUNCTION "public"."grant_platform_role"("p_profile_id" "text", "p_role" "public"."platform_role") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_caller text := (select auth.jwt()->>'sub');
begin
  if not private.has_platform_role('superadmin') then
    raise exception 'Only a superadmin may change platform roles.' using errcode = '42501';
  end if;
  if p_profile_id is null or p_profile_id !~ '^user_' then
    raise exception 'Not a Clerk identity: %.', coalesce(p_profile_id,'null') using errcode = '22023';
  end if;
  if not exists (select 1 from public.profiles where id = p_profile_id) then
    raise exception 'No such profile.' using errcode = 'no_data_found';
  end if;

  insert into public.platform_memberships (profile_id, role, granted_by)
  values (p_profile_id, p_role, v_caller)
  on conflict (profile_id) do update
    set role = excluded.role, granted_by = excluded.granted_by;

  return jsonb_build_object('profileId', p_profile_id, 'role', p_role);
end;
$$;


ALTER FUNCTION "public"."grant_platform_role"("p_profile_id" "text", "p_role" "public"."platform_role") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."hq_client_network_value"("p_facility_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(row_to_json(x) order by x."totalSpend" desc), '[]'::jsonb)
    from (
      select
        c.ref as "clientId",
        c.name as "clientName",
        coalesce((
          select jsonb_agg(pt.name order by pt.name)
            from public.pets pt
           where pt.client_id = c.id
        ), '[]'::jsonb) as "petNames",
        coalesce(sum(p.grand_total) filter (where p.grand_total > 0), 0) as "totalSpend",
        count(distinct b.id) as "totalVisits",
        min(b.start_at) as "firstVisitedAt",
        max(b.start_at) as "lastVisitedAt",
        la.current_tier_id as "loyaltyTierId",
        coalesce((
          select jsonb_agg(jsonb_build_object(
                   'locationId', v.location_id,
                   'visits', v.visits,
                   'spend', v.spend
                 ) order by v.visits desc)
            from (
              select b2.location_id,
                     count(*) as visits,
                     coalesce(sum(p2.grand_total) filter (where p2.grand_total > 0), 0) as spend
                from public.bookings b2
                left join public.payments p2 on p2.booking_id = b2.id
               where b2.client_id = c.id
                 and b2.status <> 'cancelled'
                 and b2.location_id is not null
               group by b2.location_id
            ) v
        ), '[]'::jsonb) as "locationsVisited"
        from public.clients c
        join public.bookings b on b.client_id = c.id and b.status <> 'cancelled'
        left join public.payments p on p.booking_id = b.id
        left join public.loyalty_accounts la on la.client_id = c.id
       where c.facility_id = p_facility_id
       group by c.id, c.ref, c.name, la.current_tier_id
    ) x
$$;


ALTER FUNCTION "public"."hq_client_network_value"("p_facility_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."hq_client_network_value"("p_facility_id" "uuid") IS 'Lifetime spend/visits per client, broken down per location they have booked at. security invoker: RLS decides what is visible. No time window -- every HQ Clients figure is lifetime.';



CREATE OR REPLACE FUNCTION "public"."invite_facility_owner"("p_facility_id" "uuid", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_staff    public.staff;
  v_facility public.facilities;
  v_grant    jsonb;
begin
  if not private.is_platform_admin() then
    raise exception 'Only a platform administrator may invite a facility owner.'
      using errcode = '42501';
  end if;

  select * into v_facility from public.facilities where id = p_facility_id;
  if v_facility.id is null then
    raise exception 'No such facility.' using errcode = 'no_data_found';
  end if;

  select * into v_staff
    from public.staff
   where facility_id = p_facility_id
     and primary_role = 'owner'
   order by created_at
   limit 1;

  if v_staff.id is null then
    raise exception 'That facility has no owner to invite.'
      using errcode = 'no_data_found';
  end if;

  v_grant := private.record_grant_for_staff(v_staff, p_expires_at);

  return v_grant || jsonb_build_object(
    'facilityName', v_facility.name,
    'facilitySlug', v_facility.slug,
    'ownerName',    trim(v_staff.first_name || ' ' || coalesce(v_staff.last_name, '')),
    'expiresAt',    p_expires_at);
end;
$$;


ALTER FUNCTION "public"."invite_facility_owner"("p_facility_id" "uuid", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invite_platform_admin"("p_email" "text", "p_full_name" "text", "p_role" "public"."platform_role", "p_token_hash" "bytea", "p_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_caller text := (select auth.jwt()->>'sub');
  v_email  text := lower(trim(coalesce(p_email, '')));
  v_id     uuid;
begin
  if not private.has_platform_role('superadmin') then
    raise exception 'Only a superadmin may invite a platform administrator.'
      using errcode = '42501';
  end if;

  if v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'That is not a valid email address.' using errcode = '22023';
  end if;

  if p_token_hash is null or octet_length(p_token_hash) <> 32 then
    raise exception 'A platform invitation needs a 32-byte token hash.'
      using errcode = '22023';
  end if;

  if p_expires_at is null or p_expires_at <= now() then
    raise exception 'A platform invitation must expire in the future.'
      using errcode = '22023';
  end if;

  if exists (
    select 1 from public.platform_memberships m
      join public.profiles p on p.id = m.profile_id
     where lower(p.email) = v_email
  ) then
    raise exception 'That address is already on the platform team.'
      using errcode = '23505';
  end if;

  insert into public.platform_invitations
    (email, full_name, role, token_hash, invited_by, expires_at)
  values (v_email, nullif(trim(coalesce(p_full_name,'')),''), p_role,
          p_token_hash, v_caller, p_expires_at)
  on conflict (lower(email)) where accepted_at is null do update
    set full_name  = excluded.full_name,
        role       = excluded.role,
        token_hash = excluded.token_hash,
        invited_by = excluded.invited_by,
        expires_at = excluded.expires_at,
        created_at = now()
  returning id into v_id;

  return jsonb_build_object(
    'invitationId', v_id,
    'email',        v_email,
    'role',         p_role,
    'expiresAt',    p_expires_at);
end;
$_$;


ALTER FUNCTION "public"."invite_platform_admin"("p_email" "text", "p_full_name" "text", "p_role" "public"."platform_role", "p_token_hash" "bytea", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."issue_gift_card"("p_facility_id" "uuid", "p_amount" numeric, "p_kind" "text" DEFAULT 'online'::"text", "p_code" "text" DEFAULT NULL::"text", "p_recipient_name" "text" DEFAULT NULL::"text", "p_recipient_email" "text" DEFAULT NULL::"text", "p_message" "text" DEFAULT NULL::"text", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_purchased_by_client_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."gift_cards"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_card public.gift_cards%rowtype;
  v_code text;
  v_sub  text := (select auth.jwt() ->> 'sub');
begin
  -- FIRST. Nothing is read, created or reported before this: the caller names
  -- the facility, so there is no row to leak by checking afterwards.
  if not private.has_permission(p_facility_id, 'financial_manage_gift_cards') then
    raise exception 'You do not have permission to issue a gift card here.'
      using errcode = '42501';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'A gift card has to be worth something.'
      using errcode = '22023';
  end if;

  -- A code the business supplied (a printed batch) is kept; otherwise one is
  -- generated here rather than in the application, so two tabs cannot mint the
  -- same code and the uniqueness constraint is the arbiter either way.
  v_code := coalesce(
    nullif(btrim(p_code), ''),
    upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 16))
  );

  insert into public.gift_cards (
    facility_id, code, kind, initial_amount, status,
    purchased_by_client_id, recipient_name, recipient_email, message,
    expires_at, issued_by
  )
  values (
    p_facility_id, v_code, p_kind, p_amount, 'active',
    p_purchased_by_client_id, p_recipient_name, p_recipient_email, p_message,
    p_expires_at, v_sub
  )
  returning * into v_card;

  -- The opening balance IS a ledger entry. There is no other way to put money
  -- on a card, so `balance` and the sum of the ledger cannot drift apart.
  insert into public.gift_card_transactions (
    gift_card_id, facility_id, kind, amount, balance_after, note, created_by
  )
  values (v_card.id, p_facility_id, 'issued', p_amount, p_amount, p_message, v_sub);

  select * into v_card from public.gift_cards where id = v_card.id;
  return v_card;
end;
$$;


ALTER FUNCTION "public"."issue_gift_card"("p_facility_id" "uuid", "p_amount" numeric, "p_kind" "text", "p_code" "text", "p_recipient_name" "text", "p_recipient_email" "text", "p_message" "text", "p_expires_at" timestamp with time zone, "p_purchased_by_client_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."issue_gift_card"("p_facility_id" "uuid", "p_amount" numeric, "p_kind" "text", "p_code" "text", "p_recipient_name" "text", "p_recipient_email" "text", "p_message" "text", "p_expires_at" timestamp with time zone, "p_purchased_by_client_id" "uuid") IS 'Create a gift card and its opening ledger entry in one transaction. Requires financial_manage_gift_cards on the named facility, checked BEFORE anything is read or written. Generates an unguessable code when none is supplied. anon holds no EXECUTE grant.';



CREATE OR REPLACE FUNCTION "public"."issue_yipyy_go_check_in_pass"("p_booking_id" "uuid", "p_token_hash" "bytea") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings;
  v_expires timestamptz;
begin
  select * into v_booking from public.bookings where id = p_booking_id;
  if not found or not private.yipyy_go_is_owner(v_booking.client_id) then
    raise exception 'That booking is not yours.' using errcode = '42501';
  end if;
  if p_token_hash is null or octet_length(p_token_hash) <> 32 then
    raise exception 'That is not a check-in code.' using errcode = '22023';
  end if;
  if v_booking.status::text not in ('pending', 'request_submitted', 'estimate_sent', 'waitlisted', 'confirmed')
     or v_booking.end_at < now()
     or exists (
       select 1 from public.booking_presence p
        where p.booking_id = p_booking_id and p.arrived_at is not null
     )
  then
    raise exception 'This booking is not arriving.' using errcode = '22023';
  end if;
  if private.yipyy_go_requirement(v_booking.facility_id, v_booking.service) is null then
    raise exception 'This booking does not use a check-in code.' using errcode = '22023';
  end if;

  v_expires := greatest(v_booking.end_at, v_booking.start_at + interval '12 hours');

  insert into public.yipyy_go_check_in_passes as cp (booking_id, facility_id, token_hash, token_expires_at)
  values (p_booking_id, v_booking.facility_id, p_token_hash, v_expires)
  on conflict (booking_id) do update
     set token_hash = excluded.token_hash,
         token_expires_at = excluded.token_expires_at,
         issued_at = now(),
         issued_by = excluded.issued_by,
         rotations = cp.rotations + 1;

  return v_expires;
end;
$$;


