CREATE OR REPLACE FUNCTION "public"."link_client_record"("p_facility_slug" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_facility uuid;
begin
  select f.id into v_facility
    from public.facilities f
   where f.slug = lower(trim(p_facility_slug));
  if v_facility is null then
    return null;
  end if;
  return private.link_client_at(v_facility);
end;
$$;


ALTER FUNCTION "public"."link_client_record"("p_facility_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_my_client_record"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id  text := (select auth.jwt()->>'sub');
  v_email    text;
  v_existing uuid;
  v_facility uuid;
  v_matches  integer;
begin
  if v_user_id is null then
    return null;
  end if;

  select p.email into v_email
    from public.profiles p
   where p.id = v_user_id;
  if v_email is null then
    return null;
  end if;

  select c.id into v_existing
    from public.clients c
   where c.profile_id = v_user_id
   order by c.ref
   limit 1;
  if v_existing is not null then
    return v_existing;
  end if;

  select count(*) into v_matches
    from public.clients c
   where lower(c.email) = lower(v_email)
     and c.profile_id is null;

  if v_matches <> 1 then
    return null;
  end if;

  -- The one match. NOT `min(c.facility_id)` in the count query above: there is
  -- no min() for uuid, and the function raised "function min(uuid) does not
  -- exist" at runtime while a test that only read its SOURCE passed.
  select c.facility_id into v_facility
    from public.clients c
   where lower(c.email) = lower(v_email)
     and c.profile_id is null
   limit 1;

  return private.link_client_at(v_facility);
end;
$$;


ALTER FUNCTION "public"."link_my_client_record"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."link_my_client_record"() IS 'Claim the calling customer''s own client record when no facility is named (the apex). Claims AT MOST ONE, and only when exactly one unclaimed row carries their address — an ambiguous match claims nothing.';



CREATE OR REPLACE FUNCTION "public"."link_staff_invite"("p_staff_legacy_id" "text", "p_profile_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_staff      public.staff;
  v_email      text;
  v_membership uuid;
begin
  if (select auth.jwt()->>'sub') is null then
    raise exception 'You must be signed in to invite staff.'
      using errcode = '42501';
  end if;

  if p_profile_id !~ '^user_' then
    raise exception 'Not a Clerk identity: %. A membership granted to it could never be used.', p_profile_id
      using errcode = '22023';
  end if;

  select * into v_staff from public.staff where legacy_id = p_staff_legacy_id;
  if v_staff.id is null then
    raise exception 'No staff record for %.', p_staff_legacy_id
      using errcode = 'no_data_found';
  end if;

  if not private.has_permission(v_staff.facility_id, 'manage_staff')
     and not private.is_platform_admin() then
    raise exception 'You may not invite staff at this facility.'
      using errcode = '42501';
  end if;

  select email into v_email from public.profiles where id = p_profile_id;
  if v_email is null then
    raise exception 'No profile for %. They must sign in once before they can be linked.', p_profile_id
      using errcode = 'no_data_found';
  end if;

  insert into public.facility_memberships
    (facility_id, profile_id, role, is_active)
  values (v_staff.facility_id, p_profile_id, v_staff.primary_role, true)
  on conflict (profile_id, facility_id) do update
    set role      = excluded.role,
        is_active = true
  returning id into v_membership;

  update public.staff
     set membership_id     = v_membership,
         status            = 'invited',
         status_changed_at = now()
   where id = v_staff.id;

  update public.facility_membership_grants
     set claimed_at         = now(),
         claimed_profile_id = p_profile_id
   where staff_id = v_staff.id and claimed_at is null;

  return jsonb_build_object(
    'staffId',      v_staff.legacy_id,
    'facilityId',   v_staff.facility_id,
    'membershipId', v_membership,
    'profileId',    p_profile_id);
end;
$$;


ALTER FUNCTION "public"."link_staff_invite"("p_staff_legacy_id" "text", "p_profile_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."location_booking_counts"("p_facility_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(
    jsonb_object_agg(x.location_id, x.n),
    '{}'::jsonb)
  from (
    select b.location_id::text as location_id, count(*) as n
    from public.bookings b
    where b.facility_id = p_facility_id
      and b.location_id is not null
    group by b.location_id
  ) x;
$$;


ALTER FUNCTION "public"."location_booking_counts"("p_facility_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."location_booking_counts"("p_facility_id" "uuid") IS 'location_id -> booking count for one facility, as one grouped query rather than a PostgREST count embed evaluated per location. Security invoker: bookings RLS decides what is counted.';



CREATE OR REPLACE FUNCTION "public"."lodging_occupancy"("p_room_id" "uuid", "p_on" "date") RETURNS TABLE("space_type" "text", "used" integer, "capacity" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with unit as (
    select fr.id,
           rc.space_type,
           rc.max_pets_per_area,
           coalesce(fr.capacity, rc.default_capacity) as unit_capacity,
           fr.facility_id
      from public.facility_rooms fr
      join public.room_categories rc on rc.id = fr.category_id
     where fr.id = p_room_id
       and (
         private.is_platform_admin()
         or private.has_permission(fr.facility_id, 'view_services')
         or fr.facility_id in (select private.client_facility_ids())
       )
  ),
  day as (
    select tstzrange(p_on::timestamptz, (p_on + 1)::timestamptz, '[)') as r
  )
  select u.space_type::text,
         case
           when u.space_type = 'area'
             then private.area_pets_in_use(u.id, d.r, null)
           else (
             select count(*)::integer from public.boarding_stays s
              where s.room_id = u.id
                and s.released_at is null
                and s.occupies && d.r
           )
         end as used,
         case when u.space_type = 'area'
              then u.max_pets_per_area
              else 1
         end as capacity
    from unit u cross join day d;
$$;


ALTER FUNCTION "public"."lodging_occupancy"("p_room_id" "uuid", "p_on" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."lodging_occupancy"("p_room_id" "uuid", "p_on" "date") IS 'X of Y for one lodging unit on one date, MoeGo style: a room is 0 or 1 of 1, an area is pets of max_pets_per_area. A pet checking out that date is not counted, because occupies is half-open.';



CREATE TABLE IF NOT EXISTS "public"."training_homework_practice" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "homework_id" "uuid" NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "client_id" "uuid" NOT NULL,
    "practice_date" "date" NOT NULL,
    "logged_by" "text" NOT NULL,
    "marked_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "trainer_response" "text",
    "trainer_responded_at" timestamp with time zone,
    "trainer_responded_by" "text",
    CONSTRAINT "training_homework_practice_logged_by_check" CHECK (("logged_by" = ANY (ARRAY['owner'::"text", 'staff'::"text"]))),
    CONSTRAINT "training_homework_practice_response_is_dated" CHECK ((("trainer_response" IS NULL) = ("trainer_responded_at" IS NULL))),
    CONSTRAINT "training_homework_practice_trainer_response_check" CHECK ((("trainer_response" IS NULL) OR (("length"("btrim"("trainer_response")) >= 1) AND ("length"("btrim"("trainer_response")) <= 2000))))
);


ALTER TABLE "public"."training_homework_practice" OWNER TO "postgres";


COMMENT ON TABLE "public"."training_homework_practice" IS 'One day a piece of homework was practised, logged by its owner or by staff through log_homework_practice(), with the trainer''s response to that day.';



CREATE OR REPLACE FUNCTION "public"."log_homework_practice"("p_homework_id" "uuid", "p_practice_date" "date") RETURNS "public"."training_homework_practice"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_homework public.training_homework;
  v_by       text;
  v_row      public.training_homework_practice;
begin
  select * into v_homework
    from public.training_homework
   where id = p_homework_id;

  -- One refusal for "no such homework" and "not yours", so the answer does
  -- not tell a stranger which homework exists.
  if v_homework.id is null then
    raise exception 'That homework is not yours to log.' using errcode = '42501';
  end if;
  if private.has_permission(v_homework.facility_id, 'training_log_progress') then
    v_by := 'staff';
  elsif v_homework.client_id in (select private.own_client_ids()) then
    v_by := 'owner';
  else
    raise exception 'That homework is not yours to log.' using errcode = '42501';
  end if;

  if v_homework.completed_at is not null then
    raise exception 'That homework is already complete.' using errcode = '22023';
  end if;
  -- A facility's "today" is never later than UTC's tomorrow, so anything past
  -- that is a day that has not happened.
  if p_practice_date is null
     or p_practice_date > (now() at time zone 'utc')::date + 1 then
    raise exception 'Practice is logged for today or a day already past.' using errcode = '22023';
  end if;

  insert into public.training_homework_practice
    (homework_id, facility_id, client_id, practice_date, logged_by)
  values
    (v_homework.id, v_homework.facility_id, v_homework.client_id, p_practice_date, v_by)
  on conflict (homework_id, practice_date) do nothing
  returning * into v_row;

  if v_row.id is null then
    -- Already logged for that day: the same row back, and the due date stays.
    select * into v_row
      from public.training_homework_practice
     where homework_id = v_homework.id
       and practice_date = p_practice_date;
  else
    update public.training_homework
       set next_due_date = private.homework_next_due(v_homework.frequency, p_practice_date)
     where id = v_homework.id;
  end if;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."log_homework_practice"("p_homework_id" "uuid", "p_practice_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."log_homework_practice"("p_homework_id" "uuid", "p_practice_date" "date") IS 'Log one day of practice on a piece of homework — by staff with training_log_progress or by its owner — and move its next due date. Idempotent per day.';



CREATE OR REPLACE FUNCTION "public"."mark_all_my_notifications_read"("p_facility_id" "uuid") RETURNS integer
