    CONSTRAINT "report_cards_sent_has_timestamp" CHECK ((("delivery_status" = 'sent'::"text") = ("sent_at" IS NOT NULL))),
    CONSTRAINT "report_cards_service_type_check" CHECK (("service_type" = ANY (ARRAY['daycare'::"text", 'boarding'::"text", 'grooming'::"text", 'training'::"text"])))
);


ALTER TABLE "public"."report_cards" OWNER TO "postgres";


COMMENT ON TABLE "public"."report_cards" IS 'One report card per pet per visit. `input` is the staff''s answers, `generated` the prose built from them. The owner''s columns (viewed_at, favourite, reply_message, rating_*) are written only by the SECURITY DEFINER functions in 20260822300000 — no customer UPDATE policy exists. A card can be deleted only while it is unsent; once sent it is something the owner received, and it carries their reply and rating.';



CREATE OR REPLACE FUNCTION "public"."mark_report_card_viewed"("p_card_id" "uuid") RETURNS "public"."report_cards"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_card public.report_cards;
begin
  -- `viewed_at` is first-view, not last-view: it answers "has the owner seen
  -- this", which a facility chases up. Overwriting it on every open would
  -- erase the only thing it is asked.
  update public.report_cards
     set viewed_at  = coalesce(viewed_at, now()),
         updated_at = now()
   where id = p_card_id
     and client_id in (select private.own_client_ids())
     and delivery_status = 'sent'
  returning * into v_card;

  if v_card.id is null then
    raise exception 'That report card is not yours to read.' using errcode = '42501';
  end if;

  return v_card;
end;
$$;


ALTER FUNCTION "public"."mark_report_card_viewed"("p_card_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_report_card_viewed"("p_card_id" "uuid") IS 'Record the first time the owner opened a sent card. Raises 42501 for a card belonging to someone else, and for one that does not exist — the two are deliberately indistinguishable. anon holds no EXECUTE grant.';



CREATE OR REPLACE FUNCTION "public"."mark_tips_paid"("p_facility_id" "uuid", "p_staff_id" "uuid", "p_from" "date", "p_to" "date", "p_note" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_count integer;
begin
  -- `edit_payroll`, NOT `take_payment`. Splitting a tip is a till act and
  -- 20260806940000 argues at length for letting reception do it. Recording that
  -- money has LEFT the business is a payroll act, and the same argument runs the
  -- other way.
  if not private.has_permission(p_facility_id, 'edit_payroll') then
    raise exception 'Not allowed to record tip payouts at this facility.'
      using errcode = '42501';
  end if;

  update public.booking_tip_allocations a
     set paid_at     = now(),
         paid_by     = auth.uid(),
         payout_note = p_note
   where a.facility_id = p_facility_id
     and a.staff_id    = p_staff_id
     and a.created_at >= p_from
     and a.created_at <  (p_to + 1)
     -- Already paid stays paid at its original date. Re-running a payout must
     -- not restamp somebody's settled tips with today.
     and a.paid_at is null;

  get diagnostics v_count = row_count;
  return v_count;
end $$;


ALTER FUNCTION "public"."mark_tips_paid"("p_facility_id" "uuid", "p_staff_id" "uuid", "p_from" "date", "p_to" "date", "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_tips_paid"("p_facility_id" "uuid", "p_staff_id" "uuid", "p_from" "date", "p_to" "date", "p_note" "text") IS 'Marks one staff member unpaid tip allocations in a date range as paid. edit_payroll only. Returns the number of rows actually changed - zero means nothing was outstanding, which the caller must not report as a payout.';



CREATE OR REPLACE FUNCTION "public"."mark_training_makeup_ineligible"("p_missed_booking_id" "uuid", "p_reason" "text", "p_by_name" "text" DEFAULT NULL::"text") RETURNS "public"."training_makeups"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_missed record;
  v_row    public.training_makeups;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  select * into v_missed from private.training_missed_booking(p_missed_booking_id);
  if not found or not private.has_permission(v_missed.facility_id, 'create_bookings') then
    raise exception 'Not allowed to decide a make-up for that session.' using errcode = '42501';
  end if;
  if v_reason is null or length(v_reason) > 1000 then
    raise exception 'Say why there is no make-up.' using errcode = '22023';
  end if;

  select * into v_row from public.training_makeups
   where missed_booking_id = p_missed_booking_id
   for update;
  if found and v_row.status = 'offered' and v_row.host_booking_id is not null then
    if exists (
      select 1 from public.training_attendance a
       where a.booking_id = v_row.host_booking_id and a.checked_in_at is not null
    ) then
      raise exception 'That make-up session has already started.' using errcode = '22023';
    end if;
    update public.bookings
       set status = 'cancelled'
     where id = v_row.host_booking_id
       and status::text not in ('cancelled', 'completed');
  end if;

  insert into public.training_makeups
    (facility_id, missed_booking_id, missed_session_id, pet_id, client_id, status,
     ineligible_reason, decided_at, decided_by_name)
  values
    (v_missed.facility_id, p_missed_booking_id, v_missed.session_id, v_missed.pet_id,
     v_missed.client_id, 'ineligible', v_reason, now(),
     nullif(btrim(coalesce(p_by_name, '')), ''))
  on conflict (missed_booking_id) do update
     set status = 'ineligible',
         ineligible_reason = excluded.ineligible_reason,
         decided_at = excluded.decided_at,
         decided_by_name = excluded.decided_by_name,
         updated_at = now()
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."mark_training_makeup_ineligible"("p_missed_booking_id" "uuid", "p_reason" "text", "p_by_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."migrate_profile_subject"("p_old_id" "text", "p_new_id" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_email text;
begin
  if p_old_id is null or p_new_id is null then
    raise exception 'migrate_profile_subject: both ids are required';
  end if;

  if p_old_id = p_new_id then
    return;
  end if;

  select email into v_email from public.profiles where id = p_old_id;
  if v_email is null then
    raise exception 'migrate_profile_subject: no profile %', p_old_id;
  end if;

  if exists (select 1 from public.profiles where id = p_new_id) then
    raise exception
      'migrate_profile_subject: % already has a profile; resolve the duplicate by hand',
      p_new_id;
  end if;

  insert into public.profiles (id, email, full_name, avatar_url)
  select p_new_id, p_new_id || '@migration.invalid', full_name, avatar_url
  from public.profiles
  where id = p_old_id;

  update public.facility_memberships      set profile_id   = p_new_id where profile_id   = p_old_id;
  update public.platform_memberships      set profile_id   = p_new_id where profile_id   = p_old_id;
  update public.platform_memberships      set granted_by   = p_new_id where granted_by   = p_old_id;
  update public.clients                   set profile_id   = p_new_id where profile_id   = p_old_id;
  update public.payment_intents           set created_by   = p_new_id where created_by   = p_old_id;
  update public.payment_connections       set connected_by = p_new_id where connected_by = p_old_id;
  update public.facility_settings         set updated_by   = p_new_id where updated_by   = p_old_id;
  update public.facility_modules          set granted_by   = p_new_id where granted_by   = p_old_id;
  update public.communication_connections set connected_by = p_new_id where connected_by = p_old_id;

  delete from public.profiles where id = p_old_id;

  update public.profiles set email = v_email where id = p_new_id;

  update public.profiles set is_platform_admin = false where id = p_new_id;
end;
$$;


ALTER FUNCTION "public"."migrate_profile_subject"("p_old_id" "text", "p_new_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."migrate_profile_subject"("p_old_id" "text", "p_new_id" "text") IS 'Move a profile and all its grants/attribution to a new identity subject. Service-role only. Written for the Clerk->WorkOS cutover (ADR 0004).';



CREATE OR REPLACE FUNCTION "public"."my_booking_cancel_terms"("p_ref" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings;
begin
  select * into v_booking
    from public.bookings b
   where b.ref = p_ref
     and b.client_id in (select private.own_client_ids());
  if not found then
    return null;
  end if;
  return private.cancellation_terms(v_booking)
    || jsonb_build_object(
         'status', v_booking.status,
         'cancellable',
           v_booking.status in ('pending', 'request_submitted', 'estimate_sent',
                                'waitlisted', 'confirmed')
           and (v_booking.status in ('request_submitted', 'estimate_sent', 'waitlisted')
                or v_booking.start_at > now()));
end;
$$;


ALTER FUNCTION "public"."my_booking_cancel_terms"("p_ref" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."my_client_at"("p_facility_slug" "text") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select c.id
    from public.clients c
    join public.facilities f on f.id = c.facility_id
   where f.slug = lower(trim(p_facility_slug))
     and c.profile_id = (select auth.jwt()->>'sub')
   limit 1;
$$;


ALTER FUNCTION "public"."my_client_at"("p_facility_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."my_notification_preferences"("p_facility_id" "uuid") RETURNS TABLE("membership_id" "uuid", "role" "text", "in_app" "jsonb", "email" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select m.id, m.role::text,
         coalesce(p.in_app, '{}'::jsonb),
         coalesce(p.email, '{}'::jsonb)
    from public.facility_memberships m
    left join public.staff_notification_preferences p on p.membership_id = m.id
   where m.facility_id = p_facility_id
     and m.is_active
     and m.profile_id = (select auth.jwt()->>'sub')
   limit 1;
$$;


ALTER FUNCTION "public"."my_notification_preferences"("p_facility_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."my_permissions"() RETURNS TABLE("permission_key" "text", "scope" "public"."access_scope")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select p.key, 'anytime'::public.access_scope
    from public.permissions p
   where private.is_platform_admin()
  union all
  select p.key,
         coalesce(
           private.resolve_permission(m.id, p.key),
           'none'::public.access_scope
         )
    from public.permissions p
    cross join (
      select fm.id
        from public.facility_memberships fm
       where fm.profile_id = (select auth.jwt()->>'sub')
         and fm.is_active
       order by fm.created_at
       limit 1
    ) m
   where not private.is_platform_admin();
$$;


ALTER FUNCTION "public"."my_permissions"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."my_pet_vaccinations"() RETURNS TABLE("id" "uuid", "pet_ref" integer, "vaccine_name" "text", "administered_on" "date", "expires_on" "date", "veterinarian_name" "text", "veterinary_clinic" "text", "document_url" "text", "status" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select v.id,
         p.ref,
         v.vaccine_name,
         v.administered_on,
         v.expires_on,
         v.veterinarian_name,
         v.veterinary_clinic,
         v.document_url,
         v.status
    from public.pet_vaccinations v
    join public.pets p on p.id = v.pet_id
   where (select auth.jwt()->>'sub') is not null
     and v.pet_id in (select private.own_pet_ids())
   order by v.expires_on desc nulls last;
$$;


ALTER FUNCTION "public"."my_pet_vaccinations"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."my_pet_vaccinations"() IS 'The calling customer''s own pets'' vaccination records, without the staff-internal review columns. The pet_vaccinations table policy stays staff-only; this is the owner''s window onto it.';



CREATE OR REPLACE FUNCTION "public"."my_store_credit"() RETURNS TABLE("facility_id" "uuid", "facility_name" "text", "balance" numeric, "total_in" numeric, "total_out" numeric, "entry_count" bigint, "last_activity_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select e.facility_id,
         f.name,
         sum(e.amount)::numeric,
         coalesce(sum(e.amount) filter (where e.amount > 0), 0)::numeric,
         coalesce(abs(sum(e.amount) filter (where e.amount < 0)), 0)::numeric,
         count(*)::bigint,
         max(e.created_at)
    from public.store_credit_entries e
    join public.facilities f on f.id = e.facility_id
   where e.client_id in (select private.own_client_ids())
   group by e.facility_id, f.name
   order by max(e.created_at) desc;
$$;


ALTER FUNCTION "public"."my_store_credit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."my_store_credit_entries"("p_facility_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "facility_id" "uuid", "amount" numeric, "reason" "text", "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select e.id, e.facility_id, e.amount, e.reason, e.created_at
    from public.store_credit_entries e
   where e.client_id in (select private.own_client_ids())
     and (p_facility_id is null or e.facility_id = p_facility_id)
   order by e.created_at desc
   limit least(greatest(coalesce(p_limit, 100), 1), 500);
$$;


ALTER FUNCTION "public"."my_store_credit_entries"("p_facility_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."name_intent_order"("p_intent_id" "uuid", "p_order_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  update public.payment_intents
     set processor_order_id = p_order_id,
         updated_at = now()
   where id = p_intent_id
     -- Only while it is still open. An intent that has already produced a
     -- payment must not gain an order id the payment row cannot be given.
     and payment_id is null;
end;
$$;


ALTER FUNCTION "public"."name_intent_order"("p_intent_id" "uuid", "p_order_id" "text") OWNER TO "postgres";


