CREATE OR REPLACE FUNCTION "public"."notify_staff"("p_facility_id" "uuid", "p_kind" "text", "p_category" "text", "p_permission" "text", "p_mandatory" boolean, "p_urgent" boolean, "p_params" "jsonb", "p_link" "text", "p_source_id" "uuid", "p_dedupe_key" "text", "p_role_defaults" "jsonb", "p_actor_profile_id" "text" DEFAULT NULL::"text", "p_only_memberships" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("membership_id" "uuid", "email" "text", "full_name" "text", "created" boolean, "send_email" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
begin
  return query
  with candidates as (
    select m.id as mid,
           m.profile_id,
           m.role::text as member_role,
           p.email as member_email,
           p.full_name as member_name,
           pref.in_app as pref_in_app,
           pref.email as pref_email
      from public.facility_memberships m
      join public.profiles p on p.id = m.profile_id
      left join public.staff_notification_preferences pref on pref.membership_id = m.id
      left join public.facility_subscriptions s on s.facility_id = m.facility_id
     where m.facility_id = p_facility_id
       and m.is_active
       and coalesce(s.status, 'active') not in ('suspended', 'cancelled')
       -- Nobody is told about what they just did themselves.
       and (p_actor_profile_id is null or m.profile_id <> p_actor_profile_id)
       and (p_only_memberships is null or m.id = any (p_only_memberships))
       and (
         p_permission is null
         or coalesce(private.resolve_permission(m.id, p_permission), 'none'::public.access_scope)
            <> 'none'::public.access_scope
       )
  ),
  decided as (
    select c.*,
           (
             p_mandatory
             or coalesce(
                  (c.pref_in_app ->> p_category)::boolean,
                  -- A notice addressed to one person is on unless they said no.
                  p_only_memberships is not null
                  or coalesce(p_role_defaults -> c.member_role, '[]'::jsonb) ? p_category
                )
           ) as in_app_on,
           coalesce((c.pref_email ->> p_category)::boolean, false) as email_on
      from candidates c
  ),
  inserted as (
    insert into public.staff_notifications as n
      (facility_id, membership_id, recipient_profile_id, kind, category, urgent,
       params, link, source_id, dedupe_key)
    select p_facility_id, d.mid, d.profile_id, p_kind, p_category, p_urgent,
           coalesce(p_params, '{}'::jsonb), p_link, p_source_id, p_dedupe_key
      from decided d
     where d.in_app_on
    on conflict on constraint staff_notifications_membership_id_dedupe_key_key do nothing
    returning n.membership_id
  )
  select d.mid,
         d.member_email::text,
         d.member_name::text,
         (i.membership_id is not null),
         -- Email only for a notice created now, so a retried event never mails twice.
         (i.membership_id is not null and d.email_on
           and d.member_email is not null and btrim(d.member_email::text) <> '')
    from decided d
    left join inserted i on i.membership_id = d.mid
   where d.in_app_on;
end;
$$;


ALTER FUNCTION "public"."notify_staff"("p_facility_id" "uuid", "p_kind" "text", "p_category" "text", "p_permission" "text", "p_mandatory" boolean, "p_urgent" boolean, "p_params" "jsonb", "p_link" "text", "p_source_id" "uuid", "p_dedupe_key" "text", "p_role_defaults" "jsonb", "p_actor_profile_id" "text", "p_only_memberships" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."offboard_staff"("p_staff_legacy_id" "text", "p_reason" "text", "p_template_id" "uuid" DEFAULT NULL::"uuid", "p_last_day" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_staff     public.staff;
  v_template  public.offboarding_templates;
  v_instance  uuid;
  v_tasks     integer := 0;
begin
  -- A SESSION IS REQUIRED, and this is checked FIRST — before the staff lookup,
  -- so that "No staff record for X" cannot be used by an unauthenticated caller
  -- as an oracle for which legacy_ids exist. See 20260804200000 for why the
  -- trigger-style `auth.uid() is null` carve-out must never appear in an RPC.
  if (select auth.jwt()->>'sub') is null then
    raise exception 'You must be signed in to offboard staff.'
      using errcode = '42501';
  end if;

  select * into v_staff from public.staff where legacy_id = p_staff_legacy_id;
  if v_staff.id is null then
    raise exception 'No staff record for %.', p_staff_legacy_id
      using errcode = 'no_data_found';
  end if;

  if not private.has_permission(v_staff.facility_id, 'manage_staff')
     and not private.is_platform_admin() then
    raise exception 'You may not offboard staff at this facility.'
      using errcode = '42501';
  end if;

  -- Reason-specific template first, then a universal one. The plural resolver
  -- (getOffboardingTemplatesForReason) exists because several may match and the
  -- UI offers a choice; when the caller has already chosen, p_template_id wins.
  if p_template_id is not null then
    select * into v_template from public.offboarding_templates
     where id = p_template_id and facility_id = v_staff.facility_id;
  else
    select * into v_template from public.offboarding_templates
     where facility_id = v_staff.facility_id
       and p_reason = any (applies_to_reasons)
     order by created_at limit 1;
    if v_template.id is null then
      select * into v_template from public.offboarding_templates
       where facility_id = v_staff.facility_id
         and cardinality(applies_to_reasons) = 0
       order by created_at limit 1;
    end if;
  end if;

  -- 1. The record.
  insert into public.offboarding_instances
    (staff_id, facility_id, template_id, reason, last_day)
  values (v_staff.id, v_staff.facility_id, v_template.id, p_reason, p_last_day)
  on conflict (staff_id) do update
    set reason      = excluded.reason,
        last_day    = excluded.last_day,
        template_id = coalesce(excluded.template_id,
                               public.offboarding_instances.template_id)
  returning id into v_instance;

  -- 2. The checklist, materialised from the template with concrete due dates.
  --    `on conflict do nothing` so re-running does not wipe completed tasks.
  insert into public.offboarding_task_states
    (instance_id, facility_id, task_id, task_key, name, description, required,
     assigned_to, position, due_date)
  select v_instance, v_staff.facility_id, t.id, coalesce(t.legacy_id, t.id::text),
         t.name, t.description, t.required, t.assigned_to, t.position,
         case t.due
           when 'within_days'     then coalesce(p_last_day, current_date) + t.days
           when 'before_last_day' then p_last_day
           else current_date
         end
    from public.offboarding_tasks t
   where t.template_id = v_template.id
  on conflict (instance_id, task_key) do nothing;

  get diagnostics v_tasks = row_count;

  -- 3. Terminated…
  update public.staff
     set status            = 'terminated',
         status_reason     = p_reason,
         status_changed_at = now()
   where id = v_staff.id;

  -- 4. …and revoked, in the SAME statement sequence and the same transaction.
  --    This is the line the brief is about. is_active = false closes every
  --    policy in the schema at once, because all three access helpers filter on
  --    it and the JWT hook stops emitting the facility.
  update public.facility_memberships
     set is_active = false
   where id = v_staff.membership_id;

  return jsonb_build_object(
    'staffId',    v_staff.legacy_id,
    'instanceId', v_instance,
    'templateId', v_template.id,
    'tasks',      v_tasks,
    'revoked',    v_staff.membership_id is not null);
end;
$$;


ALTER FUNCTION "public"."offboard_staff"("p_staff_legacy_id" "text", "p_reason" "text", "p_template_id" "uuid", "p_last_day" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."offboard_staff"("p_staff_legacy_id" "text", "p_reason" "text", "p_template_id" "uuid", "p_last_day" "date") IS 'Terminate + revoke + materialise the checklist in ONE transaction. is_active=false is the revocation; every access helper already filters on it.';



CREATE OR REPLACE FUNCTION "public"."offer_training_makeup"("p_missed_booking_id" "uuid", "p_host_session_id" "uuid", "p_by_name" "text" DEFAULT NULL::"text") RETURNS "public"."training_makeups"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_missed  record;
  v_host    record;
  v_taken   integer;
  v_created record;
  v_row     public.training_makeups;
begin
  select * into v_missed from private.training_missed_booking(p_missed_booking_id);
  if not found or not private.has_permission(v_missed.facility_id, 'create_bookings') then
    raise exception 'Not allowed to offer a make-up for that session.' using errcode = '42501';
  end if;

  select * into v_row from public.training_makeups
   where missed_booking_id = p_missed_booking_id
   for update;
  if found and v_row.status = 'offered' then
    raise exception 'A seat is already booked for this make-up.' using errcode = '22023';
  elsif found and v_row.status = 'skipped' then
    raise exception 'The owner skipped this session.' using errcode = '22023';
  elsif found and v_row.status = 'ineligible' then
    raise exception 'This absence was marked ineligible.' using errcode = '22023';
  end if;

  -- Two offers into one session cannot both take its last seat.
  perform pg_advisory_xact_lock(hashtext(p_host_session_id::text));

  select s.start_at, s.end_at, s.status as session_status,
         ts.id as series_id, ts.facility_id, ts.location_id, ts.staff_id, ts.capacity,
         ts.status as series_status, ts.course_type_name,
         lower(btrim(coalesce(nullif(btrim(ts.course_type_name), ''), ts.name))) as course_key
    into v_host
    from public.training_series_sessions s
    join public.training_series ts on ts.id = s.series_id
   where s.id = p_host_session_id;

  if not found or v_host.facility_id <> v_missed.facility_id then
    raise exception 'That session is not at this facility.' using errcode = '22023';
  end if;
  if v_host.series_id = v_missed.series_id then
    raise exception 'A make-up is a session of another series.' using errcode = '22023';
  end if;
  if v_host.course_key <> v_missed.course_key then
    raise exception 'A make-up is a session of the same course.' using errcode = '22023';
  end if;
  if v_host.start_at <= now() or v_host.session_status <> 'scheduled'
     or v_host.series_status <> 'active' then
    raise exception 'That session has started, or is not running.' using errcode = '22023';
  end if;

  select count(*) into v_taken
    from public.bookings b
   where b.training_series_session_id = p_host_session_id
     and b.status::text not in ('cancelled', 'declined');
  if v_taken >= v_host.capacity then
    raise exception 'That session is full.' using errcode = '22023';
  end if;

  if exists (
    select 1
      from public.bookings b
      join public.booking_pets bp on bp.booking_id = b.id
     where b.training_series_session_id = p_host_session_id
       and bp.pet_id = v_missed.pet_id
       and b.status::text not in ('cancelled', 'declined')
  ) then
    raise exception 'That dog is already booked into that session.' using errcode = '22023';
  end if;

  select * into v_created from public.create_booking(
    jsonb_build_object(
      'facility_id', v_host.facility_id,
      'location_id', v_host.location_id,
      'client_id', v_missed.client_id,
      'service', 'training',
      'service_type', v_host.course_type_name,
      'status', 'confirmed',
      'start_at', v_host.start_at,
      'end_at', v_host.end_at,
      'assigned_staff_id', v_host.staff_id,
      'base_price', 0,
      'total_cost', 0,
      'training_series_session_id', p_host_session_id
    ),
    array[v_missed.pet_id],
    null,
    null
  );

  insert into public.training_makeups
    (facility_id, missed_booking_id, missed_session_id, pet_id, client_id, status,
     host_session_id, host_booking_id, offered_at, offered_by_name)
  values
    (v_missed.facility_id, p_missed_booking_id, v_missed.session_id, v_missed.pet_id,
     v_missed.client_id, 'offered', p_host_session_id, v_created.booking_id, now(),
     nullif(btrim(coalesce(p_by_name, '')), ''))
  on conflict (missed_booking_id) do update
     set status = 'offered',
         host_session_id = excluded.host_session_id,
         host_booking_id = excluded.host_booking_id,
         offered_at = excluded.offered_at,
         offered_by_name = excluded.offered_by_name,
         answered_at = null,
         updated_at = now()
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."offer_training_makeup"("p_missed_booking_id" "uuid", "p_host_session_id" "uuid", "p_by_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."offered_boarding_services"("p_facility_id" "uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_pet_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with allowed as (
    select private.is_platform_admin()
        or p_facility_id in (select private.client_facility_ids())
        or p_facility_id in (select private.member_facility_ids_all()) as ok
  ),
  -- Every pet tag carried by the pets the customer named, as text, so the
  -- service's own `text[]` columns compare against it directly.
  pet_tags as (
    select coalesce(array_agg(distinct ta.tag_id::text), '{}'::text[]) as tags
      from public.facility_tag_assignments ta
     where ta.entity_type = 'pet'
       and ta.entity_id = any (p_pet_ids)
       and ta.facility_id = p_facility_id
       and (ta.expires_at is null or ta.expires_at > now())
  ),
  offered as (
    select s.display_order,
           s.name,
           jsonb_build_object(
             'id',                  s.id,
             'categoryId',          s.category_id,
             'name',                s.name,
             'description',         s.description,
             'imageUrl',            s.image_url,
             -- What it costs HERE: the branch's own row where it set one, the
             -- facility-wide row next, the service's own column last. The same
             -- order `effectiveBoardingPrice()` resolves in TypeScript,
             -- because a customer quoted a different number from the till is
             -- the whole class of bug this phase exists to close.
             'price',               coalesce(branch.price, facility_wide.price, s.price),
             'facilityPrice',       coalesce(facility_wide.price, s.price),
             -- PER NIGHT OR PER DAY. Not withholdable: it is half of the price.
             'unit',                s.unit::text,
             'taxable',             s.taxable,
             -- Which lodging types this may be booked into. The wizard filters
             -- the kennel list by it AFTER the service is picked, so a customer
             -- is never offered a kennel the service cannot be sold into.
             'lodgingTypeIds',      to_jsonb(s.lodging_type_ids),
             -- These describe the SERVICE ("for dogs under 20 lb"), which is
             -- exactly what a customer needs to understand the menu. The pet
             -- TAG rules describe the PET, and are applied above instead.
             'eligibleSpecies',     to_jsonb(s.eligible_species),
             'eligibleBreeds',      to_jsonb(s.eligible_breeds),
             'eligibleWeightTiers', to_jsonb(s.eligible_weight_tiers),
             'locationIds',         to_jsonb(s.location_ids),
             -- Kept, because the flow has to be able to SAY why a service is
             -- not bookable yet rather than silently omitting it.
             'requiresEvaluationOnline', s.requires_evaluation_online,
             'displayOrder',        s.display_order,
             -- What a stay of it gets by its length. Part of the price.
             'defaultAddOns',       coalesce((
               select jsonb_agg(jsonb_build_object(
                        'addon_id',         d.addon_id,
                        'applies_on',       d.applies_on,
                        'quantity_per_day', d.quantity_per_day,
                        'min_nights',       d.min_nights)
                      order by d.created_at, d.id)
                 from public.boarding_service_default_addons d
                where d.service_id = s.id), '[]'::jsonb)
           ) as service
      from public.boarding_services s
      cross join allowed
      cross join pet_tags
      left join public.boarding_service_location_prices branch
        on branch.service_id = s.id and branch.location_id = p_location_id
      left join public.boarding_service_location_prices facility_wide
        on facility_wide.service_id = s.id and facility_wide.location_id is null
     where allowed.ok
       and s.facility_id = p_facility_id
       -- A draft is not on offer.
       and s.is_active
       -- Empty `location_ids` means every branch, which is why this is not a
       -- plain `@>`: an unrestricted service must survive a null branch too.
       and (cardinality(s.location_ids) = 0
            or p_location_id is null
            or p_location_id = any (s.location_ids))
       -- Blocked beats eligible, the rule the editor states and
       -- `isPetEligibleForBoarding` implements. Both are no-ops on an empty
       -- array.
       and not (cardinality(s.blocked_pet_tags) > 0
                and s.blocked_pet_tags && pet_tags.tags)
       and (cardinality(s.eligible_pet_tags) = 0
            or s.eligible_pet_tags && pet_tags.tags)
  )
  select coalesce(
           jsonb_agg(offered.service order by offered.display_order, offered.name),
           '[]'::jsonb)
    from offered;
$$;


ALTER FUNCTION "public"."offered_boarding_services"("p_facility_id" "uuid", "p_location_id" "uuid", "p_pet_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."offered_boarding_services"("p_facility_id" "uuid", "p_location_id" "uuid", "p_pet_ids" "uuid"[]) IS 'The boarding services a facility offers online, as a customer may see them: active, offered at that branch, pet-tag rules already applied, projected to an allowlist of keys. Colour, pet tags and the STAFF evaluation flag are the facility own and are not returned. The unit and the lodging types ARE, because the unit is half of the price and the types decide which kennels the wizard may then offer. Default add-ons are part of the price.';



CREATE OR REPLACE FUNCTION "public"."offered_custom_services"("p_facility_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(offered.module order by offered.ord), '[]'::jsonb)
    from (
      select t.ord,
             (select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb)
                from jsonb_each(jsonb_build_object(
                  'id',                    t.m->'id',
                  'slug',                  t.m->'slug',
                  'name',                  t.m->'name',
                  'sidebarLabel',          t.m->'sidebarLabel',
                  'icon',                  t.m->'icon',
                  'iconColor',             t.m->'iconColor',
                  'iconColorTo',           t.m->'iconColorTo',
                  'category',              t.m->'category',
                  'description',           t.m->'description',
                  'calendar',              t.m->'calendar',
                  'checkInOut',            t.m->'checkInOut',
                  'stayBased',             t.m->'stayBased',
                  'onlineBooking',         t.m->'onlineBooking',
                  'pricing',               t.m->'pricing',
                  'yipyyGoRequired',       t.m->'yipyyGoRequired',
                  'yipyyGo',               t.m->'yipyyGo',
                  'requiresEvaluation',    t.m->'requiresEvaluation',
                  'evaluationType',        t.m->'evaluationType',
                  'customEvaluationLabel', t.m->'customEvaluationLabel',
                  'geographicRestriction', t.m->'geographicRestriction',
                  'staffAssignment',
                    jsonb_build_object('autoAssign', t.m->'staffAssignment'->'autoAssign'),
                  'status',                t.m->'status'
                )) as e
               where e.value is not null and e.value <> 'null'::jsonb
             ) as module
        from public.facility_settings fs
       cross join lateral jsonb_array_elements(fs.value->'modules')
             with ordinality as t(m, ord)
       where fs.facility_id = p_facility_id
         and fs.domain = 'custom_services'
         and (
           private.is_platform_admin()
           or p_facility_id in (select private.client_facility_ids())
           or p_facility_id in (select private.member_facility_ids_all())
         )
         and t.m->>'status' = 'active'
         and coalesce((t.m->'onlineBooking'->>'enabled')::boolean, false)
    ) as offered;
$$;


ALTER FUNCTION "public"."offered_custom_services"("p_facility_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."offered_custom_services"("p_facility_id" "uuid") IS 'The custom services a facility offers online, as a customer may see them: active, online-bookable modules, projected to an allowlist of keys. The custom_services setting itself is not customer-readable.';



CREATE OR REPLACE FUNCTION "public"."offered_daycare_services"("p_facility_id" "uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_pet_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with allowed as (
    select private.is_platform_admin()
        or p_facility_id in (select private.client_facility_ids())
        or p_facility_id in (select private.member_facility_ids_all()) as ok
  ),
  -- Every pet tag carried by the pets the customer named, as text, so the
  -- service's own `text[]` columns compare against it directly.
  pet_tags as (
    select coalesce(array_agg(distinct ta.tag_id::text), '{}'::text[]) as tags
      from public.facility_tag_assignments ta
     where ta.entity_type = 'pet'
       and ta.entity_id = any (p_pet_ids)
       and ta.facility_id = p_facility_id
       and (ta.expires_at is null or ta.expires_at > now())
  ),
  offered as (
    select s.display_order,
           s.name,
           jsonb_build_object(
             'id',                  s.id,
             'categoryId',          s.category_id,
             'name',                s.name,
             'description',         s.description,
             'imageUrl',            s.image_url,
             -- What it costs HERE: the branch's own row where it set one, the
             -- facility-wide row next, the service's own column last. The same
             -- order `effectivePrice()` resolves in TypeScript, because a
             -- customer quoted a different number from the till is the whole
             -- class of bug this phase exists to close.
             'price',               coalesce(branch.price, facility_wide.price, s.price),
             'facilityPrice',       coalesce(facility_wide.price, s.price),
             'taxable',             s.taxable,
             'maxDurationHours',    s.max_duration_hours,
             -- These describe the SERVICE ("for dogs under 20 lb"), which is
             -- exactly what a customer needs to understand the menu. The pet
             -- TAG rules describe the PET, and are applied above instead.
             'eligibleSpecies',     to_jsonb(s.eligible_species),
             'eligibleBreeds',      to_jsonb(s.eligible_breeds),
             'eligibleWeightTiers', to_jsonb(s.eligible_weight_tiers),
             'includedAddOnIds',    to_jsonb(s.included_addon_ids),
             'locationIds',         to_jsonb(s.location_ids),
             -- Kept, because the flow has to be able to SAY why a service is
             -- not bookable yet rather than silently omitting it.
             'requiresEvaluationOnline', s.requires_evaluation_online,
             'displayOrder',        s.display_order
           ) as service
      from public.daycare_services s
      cross join allowed
      cross join pet_tags
      left join public.daycare_service_location_prices branch
        on branch.service_id = s.id and branch.location_id = p_location_id
      left join public.daycare_service_location_prices facility_wide
        on facility_wide.service_id = s.id and facility_wide.location_id is null
     where allowed.ok
       and s.facility_id = p_facility_id
       -- A draft is not on offer.
       and s.is_active
       -- Empty `location_ids` means every branch, which is why this is not a
       -- plain `@>`: an unrestricted service must survive a null branch too.
       and (cardinality(s.location_ids) = 0
            or p_location_id is null
            or p_location_id = any (s.location_ids))
       -- Blocked beats eligible, the rule the editor states and Phase 4's
       -- `isPetEligible` implements. Both are no-ops on an empty array.
       and not (cardinality(s.blocked_pet_tags) > 0
                and s.blocked_pet_tags && pet_tags.tags)
       and (cardinality(s.eligible_pet_tags) = 0
            or s.eligible_pet_tags && pet_tags.tags)
  )
  select coalesce(
           jsonb_agg(offered.service order by offered.display_order, offered.name),
           '[]'::jsonb)
    from offered;
$$;


ALTER FUNCTION "public"."offered_daycare_services"("p_facility_id" "uuid", "p_location_id" "uuid", "p_pet_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."offered_daycare_services"("p_facility_id" "uuid", "p_location_id" "uuid", "p_pet_ids" "uuid"[]) IS 'The daycare services a facility offers online, as a customer may see them: active, offered at that branch, pet-tag rules already applied, projected to an allowlist of keys. Colour, pet tags, sections and rollover are the facility own and are not returned.';



CREATE OR REPLACE FUNCTION "public"."offered_grooming_services"("p_facility_id" "uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with allowed as (
    select private.is_platform_admin()
        or p_facility_id in (select private.client_facility_ids())
        or p_facility_id in (select private.member_facility_ids_all()) as ok
  ),
  offered as (
    select s.display_order,
           s.name,
           jsonb_build_object(
             'id',                    coalesce(s.legacy_id, s.id::text),
             'name',                  s.name,
             'description',           s.description,
             'basePrice',             s.base_price,
             'duration',              s.duration_min,
             -- These three decide what the customer is actually charged, so
             -- withholding them would leave a quote nobody could check.
             'coatAdjustments',       s.coat_adjustments,
             'coatAdjustmentMode',    s.coat_adjustment_mode,
             'mattedSurchargeDefault', s.matted_surcharge_default,
             'includes',              to_jsonb(coalesce(s.includes, '{}'::text[])),
             'taxable',               s.taxable,
             'isPopular',             s.is_popular,
             'imageUrl',              s.image_url,
             'minBookingNoticeHours', s.min_booking_notice_hours,
             -- Descriptions of the SERVICE, which is why they are here: a
             -- customer needs to know a package is for short coats.
             'eligiblePetSizes',      to_jsonb(coalesce(s.eligible_pet_sizes, '{}'::text[])),
             'eligibleCoatTypes',     to_jsonb(coalesce(s.eligible_coat_types, '{}'::text[])),
             'eligibleBreeds',        to_jsonb(coalesce(s.eligible_breeds, '{}'::text[])),
             'displayOrder',          s.display_order,
             -- ONE price set: the branch's own row per size where it set one,
             -- the facility-wide row otherwise. The same resolution order
             -- `effectiveSizePricing()` applies in TypeScript, because a
             -- customer quoted a different number from the till is the whole
             -- class of bug this closes.
             'sizePricing', coalesce((
               select jsonb_object_agg(size_label, price)
                 from (
                   select distinct on (sp.size_label)
                          sp.size_label, sp.price
                     from public.grooming_service_size_prices sp
                    where sp.service_id = s.id
                      and (sp.location_id is null
                           or sp.location_id = p_location_id)
                      and sp.size_label in ('small','medium','large','giant')
                    -- The branch's own row sorts first, so `distinct on` keeps
                    -- it and falls back to the facility-wide one.
                    order by sp.size_label,
                             (sp.location_id is not null) desc
                 ) resolved
             ), '{}'::jsonb)
           ) as service
      from public.grooming_services s
      cross join allowed
     where allowed.ok
       and s.facility_id = p_facility_id
       -- A draft is not on offer. RLS says the same for a client; this says it
       -- for everybody, because the function is SECURITY DEFINER and a member
       -- calling it is asking what a CUSTOMER would see.
       and s.is_active
  )
  select coalesce(
           jsonb_agg(offered.service order by offered.display_order, offered.name),
           '[]'::jsonb)
    from offered;
$$;


ALTER FUNCTION "public"."offered_grooming_services"("p_facility_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."offered_grooming_services"("p_facility_id" "uuid", "p_location_id" "uuid") IS 'The grooming services a facility offers, as a customer may see them: active, size prices resolved for one branch, projected to an allowlist of keys. Colour, required skill level, per-day capacity and the cross-branch price breakdown are the facility own and are not returned.';



CREATE OR REPLACE FUNCTION "public"."offered_mobile_grooming"("p_facility_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with allowed as (
    select (
      private.is_platform_admin()
      or p_facility_id in (select private.client_facility_ids())
      or p_facility_id in (select private.member_facility_ids_all())
    ) as ok
  ),
  setting as (
    select fs.value as v
      from public.facility_settings fs
      cross join allowed
     where allowed.ok
       and fs.facility_id = p_facility_id
       and fs.domain = 'mobile_grooming'
  ),
  base as (
    select nullif(btrim(f.address->>'zipCode'), '') as postal
      from public.facilities f
      cross join allowed
     where allowed.ok
       and f.id = p_facility_id
  )
  select jsonb_build_object(
    'enabled', coalesce((s.v->>'enabled')::boolean, false),
    'hasActiveVans', coalesce((
      select bool_or(
               coalesce((van->>'active')::boolean, false)
               and jsonb_array_length(coalesce(van->'assignedStaffIds', '[]'::jsonb)) > 0
             )
        from jsonb_array_elements(coalesce(s.v->'vans', '[]'::jsonb)) as van
    ), false),
    'arrivalWindowMinutes', coalesce((s.v->>'arrivalWindowMinutes')::int, 60),
    'certainAreaEnabled', coalesce((s.v->>'certainAreaEnabled')::boolean, false),
    'serviceAreas', coalesce((
      select jsonb_agg(p.obj order by t.ord)
        from jsonb_array_elements(coalesce(s.v->'serviceAreas', '[]'::jsonb))
             with ordinality as t(a, ord)
        cross join lateral (
          select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb) as obj
            from jsonb_each(jsonb_build_object(
              'id',            t.a->'id',
              'name',          t.a->'name',
              'type',          t.a->'type',
              'polygon',       t.a->'polygon',
              'postalCodes',   t.a->'postalCodes',
              'centerAddress', t.a->'centerAddress',
              'centerLat',     t.a->'centerLat',
              'centerLng',     t.a->'centerLng',
              'radiusKm',      t.a->'radiusKm',
              'daysOfWeek',    t.a->'daysOfWeek',
              'active',        t.a->'active',
              'color',         t.a->'color'
            )) as e
           where e.value is not null and e.value <> 'null'::jsonb
        ) as p
       where coalesce((t.a->>'active')::boolean, false)
    ), '[]'::jsonb),
    'travelZones', coalesce((
      select jsonb_agg(p.obj order by t.ord)
        from jsonb_array_elements(coalesce(s.v->'travelZones', '[]'::jsonb))
             with ordinality as t(z, ord)
        cross join lateral (
          select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb) as obj
            from jsonb_each(jsonb_build_object(
              'id',              t.z->'id',
              'label',           t.z->'label',
              'maxMiles',        t.z->'maxMiles',
              'surchargeMode',   t.z->'surchargeMode',
              'surchargeAmount', t.z->'surchargeAmount',
              'active',          t.z->'active'
            )) as e
           where e.value is not null and e.value <> 'null'::jsonb
        ) as p
       where coalesce((t.z->>'active')::boolean, false)
    ), '[]'::jsonb),
    'basePostalCode', (select postal from base)
  )
  from (select 1) as one
  left join setting s on true;
$$;


ALTER FUNCTION "public"."offered_mobile_grooming"("p_facility_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."offered_mobile_grooming"("p_facility_id" "uuid") IS 'Mobile grooming as a customer may see it: whether van visits are offered, the arrival window, active service areas and travel zones, and the base postal code. Vans and staff area schedules are never returned; the mobile_grooming setting itself is not customer-readable.';



CREATE OR REPLACE FUNCTION "public"."onboarding_by_token"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v jsonb;
begin
  if p_token is null or length(p_token) < 8 then
    return null;
  end if;

  select jsonb_build_object(
           'instanceId',      i.id,
           'staffId',         s.legacy_id,
           'staffFirstName',  s.first_name,
           'staffLastName',   s.last_name,
           'staffEmail',      s.email,
           'facilityName',    f.name,
           'facilityLogo',    f.logo_url,
           'templateId',      t.legacy_id,
           'welcomeMessage',  t.welcome_message,
           'tokenExpiresAt',  i.token_expires_at,
           'invitedAt',       i.invited_at,
           'accountPasswordSetAt', i.account_password_set_at,
           'tasks', coalesce((
             select jsonb_agg(jsonb_build_object(
                      'id',           coalesce(et.legacy_id, et.id::text),
                      'type',         et.task_type,
                      'name',         et.name,
                      'description',  et.description,
                      'required',     et.required,
                      'documentName', et.document_name,
                      'documentRef',  et.document_ref,
                      'fields',       coalesce(et.config -> 'fields', '[]'::jsonb),
                      'question',     et.config -> 'question')
                    order by et.position)
               from public.onboarding_employee_tasks et
              where et.template_id = i.template_id), '[]'::jsonb),
           'sections', coalesce((
             select jsonb_agg(jsonb_build_object(
                      'taskId', sec.task_key, 'type', sec.section_type,
                      'status', sec.status, 'data', sec.data,
                      'completedAt', sec.completed_at) order by sec.created_at)
               from public.onboarding_sections sec where sec.instance_id = i.id), '[]'::jsonb),
           'changeRequests', coalesce((
             select jsonb_agg(jsonb_build_object(
                      'taskId', cr.task_key, 'sectionType', cr.section_type,
                      'note', cr.note, 'resolvedAt', cr.resolved_at) order by cr.created_at)
               from public.onboarding_change_requests cr
              where cr.instance_id = i.id and cr.resolved_at is null), '[]'::jsonb))
    into v
    from public.onboarding_instances i
    join public.staff s on s.id = i.staff_id
    left join public.facilities f on f.id = s.facility_id
    left join public.onboarding_templates t on t.id = i.template_id
   where i.token_hash = private.hash_onboarding_token(p_token)
     and i.token_expires_at > now()
     and i.submitted_at is null
     and s.status = 'invited';

  return v;
end;
$$;


ALTER FUNCTION "public"."onboarding_by_token"("p_token" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."onboarding_by_token"("p_token" "text") IS 'The ONLY way an unauthenticated caller reaches an onboarding instance. Token is hashed and matched against a unique index, never a policy predicate.';



CREATE OR REPLACE FUNCTION "public"."open_payment_intent"("p_facility_id" "uuid", "p_amount_cents" integer, "p_currency" "text", "p_kind" "text", "p_idempotency_key" "text", "p_booking_id" "uuid" DEFAULT NULL::"uuid", "p_client_id" "uuid" DEFAULT NULL::"uuid", "p_created_by" "text" DEFAULT NULL::"text", "p_device_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_env text;
  v_id  uuid;
begin
  select pc.environment into v_env
    from public.payment_connections pc
   where pc.facility_id = p_facility_id
     and pc.processor = 'clover'
     and pc.status = 'connected';

  if v_env is null then
    raise exception 'That facility has no connected payment account.'
      using errcode = '42501';
  end if;

  insert into public.payment_intents
    (facility_id, booking_id, client_id, environment, kind, amount_cents,
     currency, idempotency_key, created_by, device_id)
  values
    (p_facility_id, p_booking_id, p_client_id, v_env, p_kind, p_amount_cents,
     p_currency, p_idempotency_key, p_created_by, p_device_id)
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."open_payment_intent"("p_facility_id" "uuid", "p_amount_cents" integer, "p_currency" "text", "p_kind" "text", "p_idempotency_key" "text", "p_booking_id" "uuid", "p_client_id" "uuid", "p_created_by" "text", "p_device_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pay_booking_with_gift_card"("p_code" "text", "p_booking_ref" bigint, "p_amount" numeric, "p_note" "text" DEFAULT NULL::"text", "p_tax" numeric DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_booking record;
  v_owed numeric;
  v_tax numeric := round(coalesce(p_tax, 0), 2);
  v_card public.gift_cards;
  v_payment jsonb;
begin
  if p_amount is null or p_amount <= 0 then
    raise exception 'A gift card payment has to take something off the card.'
      using errcode = '22023';
  end if;
  if v_tax < 0 then
    raise exception 'Tax on a gift card payment cannot be negative.'
      using errcode = '22023';
  end if;

  select b.id, b.facility_id, b.client_id,
         coalesce(b.amount_due, b.total_cost) as amount_due,
         coalesce(b.amount_paid, 0) as amount_paid
    into v_booking
    from public.bookings b
   where b.ref = p_booking_ref;
  if not found then
    raise exception 'No such booking.' using errcode = '42501';
  end if;

  v_owed := v_booking.amount_due - v_booking.amount_paid;
  if p_amount > v_owed then
    raise exception 'Only % is still owed on this booking.',
      to_char(greatest(v_owed, 0), 'FM999999990.00')
      using errcode = '22023';
  end if;

  v_card := public.redeem_gift_card(
    p_code, p_amount + v_tax, v_booking.id,
    coalesce(nullif(btrim(p_note), ''), 'Booking payment')
  );

  if v_card.facility_id <> v_booking.facility_id then
    raise exception 'That gift card belongs to another business.'
      using errcode = '42501';
  end if;

  v_payment := public.record_payment(
    p_facility_id => v_booking.facility_id,
    p_method => 'gift-card',
    p_subtotal => p_amount,
    p_tax => v_tax,
    p_tip => 0,
    p_amount_charged => p_amount + v_tax,
    p_grand_total => p_amount + v_tax,
    p_booking_id => v_booking.id,
    p_client_id => v_booking.client_id,
    p_note => 'Gift card ending ' || right(btrim(p_code), 4)
  );

  return jsonb_build_object(
    'payment_id', v_payment->>'payment_id',
    'card_balance', v_card.balance
  );
end;
$$;


ALTER FUNCTION "public"."pay_booking_with_gift_card"("p_code" "text", "p_booking_ref" bigint, "p_amount" numeric, "p_note" "text", "p_tax" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pay_booking_with_gift_card"("p_code" "text", "p_booking_ref" bigint, "p_amount" numeric, "p_note" "text", "p_tax" numeric) IS 'Redeem a gift card against a booking and record the payment, atomically: p_amount of supply plus p_tax, recorded separately. Refuses more supply than the booking owes and a card from another facility.';



CREATE OR REPLACE FUNCTION "public"."payment_access_token"("p_facility_id" "uuid", "p_processor" "text" DEFAULT 'clover'::"text") RETURNS TABLE("access_token" "text", "refresh_token" "text", "access_token_expires_at" timestamp with time zone, "refresh_token_expires_at" timestamp with time zone, "merchant_id" "text", "environment" "text", "connection_status" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select (select s.decrypted_secret from vault.decrypted_secrets s
           where s.id = c.access_token_secret_id),
         (select s.decrypted_secret from vault.decrypted_secrets s
           where s.id = c.refresh_token_secret_id),
         c.access_token_expires_at,
         c.refresh_token_expires_at,
         pc.merchant_id,
         pc.environment,
         pc.status
    from private.payment_credentials c
    join public.payment_connections pc
      on pc.facility_id = c.facility_id and pc.processor = c.processor
   where c.facility_id = p_facility_id
     and c.processor = p_processor
     and pc.status not in ('revoked', 'pending');
$$;


ALTER FUNCTION "public"."payment_access_token"("p_facility_id" "uuid", "p_processor" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."payment_access_token"("p_facility_id" "uuid", "p_processor" "text") IS 'Live merchant tokens, for a server about to call Clover. Readable while a connection is connected OR in error — the second is what a refresh repairs. service_role only.';



CREATE OR REPLACE FUNCTION "public"."payroll_summary"("p_facility_id" "uuid", "p_from" "date", "p_to" "date") RETURNS TABLE("staff_id" "uuid", "first_name" "text", "last_name" "text", "sessions" integer, "hourly_minutes" integer, "salaried_minutes" integer, "unpriced_minutes" integer, "regular_minutes" integer, "overtime_minutes" integer, "holiday_minutes" integer, "gross" numeric, "overtime_pay" numeric, "holiday_premium" numeric, "open_sessions" integer, "overtime_configured" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  v_timezone     text;
  v_from         timestamptz;
  v_to           timestamptz;
  v_config       jsonb;
  v_ot_enabled   boolean;
  v_ot_threshold numeric;
  v_ot_multiple  numeric;
  v_week_starts  integer;
begin
  if not private.has_permission(p_facility_id, 'view_payroll') then
    raise exception 'You do not have permission to see payroll.'
      using errcode = '42501';
  end if;

  if p_to < p_from then
    raise exception 'The period ends before it starts.' using errcode = '22023';
  end if;

  select coalesce(f.timezone, 'UTC') into v_timezone
    from public.facilities f
   where f.id = p_facility_id;

  v_from := (p_from::timestamp at time zone v_timezone);
  v_to   := ((p_to + 1)::timestamp at time zone v_timezone);

  select s.value into v_config
    from public.facility_settings s
   where s.facility_id = p_facility_id
     and s.domain = 'payroll_config';

  v_ot_enabled   := coalesce((v_config -> 'overtime' ->> 'enabled')::boolean, false);
  v_ot_threshold := coalesce((v_config -> 'overtime' ->> 'weeklyThresholdHours')::numeric, 0);
  v_ot_multiple  := coalesce((v_config -> 'overtime' ->> 'multiplier')::numeric, 1);
  v_week_starts  := coalesce((v_config ->> 'weekStartsOn')::integer, 0);

  if v_ot_threshold <= 0 then
    v_ot_enabled := false;
  end if;

  return query
  with entries as (
    select
      e.id,
      e.staff_id                                    as sid,
      e.minutes_worked                              as minutes,
      e.clocked_in_at,
      e.clocked_out_at is null                      as still_open,
      pay.pay_type,
      pay.hourly_rate,
      (e.clocked_in_at at time zone v_timezone)::date as local_date
    from public.staff_time_clock_entries e
    left join public.staff_shifts s        on s.id = e.shift_id
    left join public.facility_position_pay pay on pay.position_id = s.position_id
    where e.facility_id = p_facility_id
      and e.clocked_in_at >= v_from
      and e.clocked_in_at <  v_to
  ),
  priced as (
    select
      en.*,
      (not en.still_open
        and en.pay_type = 'hourly'
        and en.hourly_rate is not null)              as billable,
      coalesce((
        select (h ->> 'multiplier')::numeric
          from jsonb_array_elements(coalesce(v_config -> 'holidays', '[]'::jsonb)) h
         where (h ->> 'date') = en.local_date::text
         limit 1
      ), 1)                                          as holiday_multiple,
      en.local_date
        - (((extract(dow from en.local_date)::integer - v_week_starts) + 7) % 7)
                                                     as week_start
    from entries en
  ),
  running as (
    select
      p.*,
      coalesce(sum(case when p.billable then p.minutes else 0 end)
               over (partition by p.sid, p.week_start
                     order by p.clocked_in_at, p.id
                     rows between unbounded preceding and 1 preceding), 0)
                                                     as minutes_before
    from priced p
  ),
  split as (
    select
      r.*,
      case when r.billable then r.minutes else 0 end  as billable_minutes,
      case
        when not r.billable or not v_ot_enabled or r.holiday_multiple > 1 then 0
        else greatest(
               0,
               least(
                 r.minutes,
                 (r.minutes_before + r.minutes) - (v_ot_threshold * 60)
               )
             )
      end                                            as ot_minutes
    from running r
  ),
  lines as (
    select
      s.sid,
      s.still_open,
      s.pay_type,
      s.hourly_rate,
      s.minutes,
      s.billable,
      s.billable_minutes,
      s.holiday_multiple,
      s.ot_minutes,
      case when s.holiday_multiple > 1 then s.billable_minutes else 0 end
                                                     as holiday_minutes,
      case
        when s.holiday_multiple > 1 then 0
        else s.billable_minutes - s.ot_minutes
      end                                            as regular_minutes
    from split s
  )
  select
    st.id,
    st.first_name,
    st.last_name,
    count(*) filter (where not l.still_open)::integer,
    coalesce(sum(l.minutes) filter (where l.billable), 0)::integer,
    coalesce(sum(l.minutes) filter (
      where not l.still_open and l.pay_type = 'salary'
    ), 0)::integer,
    coalesce(sum(l.minutes) filter (
      where not l.still_open
        and (l.pay_type is null or (l.pay_type = 'hourly' and l.hourly_rate is null))
    ), 0)::integer,
    coalesce(sum(l.regular_minutes), 0)::integer,
    coalesce(sum(l.ot_minutes), 0)::integer,
    coalesce(sum(l.holiday_minutes), 0)::integer,
    coalesce(round(sum(
      (l.regular_minutes::numeric / 60) * coalesce(l.hourly_rate, 0)
      + (l.ot_minutes::numeric / 60) * coalesce(l.hourly_rate, 0) * v_ot_multiple
      + (l.holiday_minutes::numeric / 60) * coalesce(l.hourly_rate, 0) * l.holiday_multiple
    ), 2), 0),
    coalesce(round(sum(
      (l.ot_minutes::numeric / 60) * coalesce(l.hourly_rate, 0) * (v_ot_multiple - 1)
    ), 2), 0),
    coalesce(round(sum(
      (l.holiday_minutes::numeric / 60) * coalesce(l.hourly_rate, 0)
        * (l.holiday_multiple - 1)
    ), 2), 0),
    count(*) filter (where l.still_open)::integer,
    v_ot_enabled
  from lines l
  join public.staff st on st.id = l.sid
  group by st.id, st.first_name, st.last_name
  order by st.last_name, st.first_name;
end;
$$;


ALTER FUNCTION "public"."payroll_summary"("p_facility_id" "uuid", "p_from" "date", "p_to" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."payroll_summary"("p_facility_id" "uuid", "p_from" "date", "p_to" "date") IS 'What we owe people for a period. Overtime is weekly, bucketed in the facility timezone on its own first-day-of-week; holiday hours pay their declared multiplier and are not also given the overtime premium. Rules come from facility_settings.payroll_config and may be absent - see overtime_configured.';



CREATE OR REPLACE FUNCTION "public"."platform_booking_volume"("p_weeks" integer DEFAULT 52) RETURNS TABLE("week_start" "date", "bookings" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_weeks integer := least(greatest(coalesce(p_weeks, 52), 1), 104);
begin
  if not private.is_platform_admin() then
    raise exception 'Only Yipyy''s team may read the platform''s booking volume.'
      using errcode = '42501';
  end if;

  return query
    select w.week::date as week_start,
           count(b.id) as bookings
      from generate_series(
             date_trunc('week', now()) - make_interval(weeks => v_weeks - 1),
             date_trunc('week', now()),
             interval '1 week') as w(week)
      left join public.bookings b
        on b.created_at >= w.week
       and b.created_at < w.week + interval '1 week'
     group by w.week
     order by w.week;
end;
$$;


ALTER FUNCTION "public"."platform_booking_volume"("p_weeks" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."platform_facility_volume"("p_days" integer DEFAULT 28) RETURNS TABLE("facility_id" "uuid", "made_this_period" bigint, "made_last_period" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_days integer := least(greatest(coalesce(p_days, 28), 1), 365);
begin
  if not private.is_platform_admin() then
    raise exception 'Only Yipyy''s team may read a facility''s booking volume.'
      using errcode = '42501';
  end if;

  return query
    select f.id,
           count(b.id) filter (
             where b.created_at >= now() - make_interval(days => v_days)) as made_this_period,
           count(b.id) filter (
             where b.created_at >= now() - make_interval(days => v_days * 2)
               and b.created_at <  now() - make_interval(days => v_days)) as made_last_period
      from public.facilities f
      left join public.bookings b
        on b.facility_id = f.id
       and b.created_at >= now() - make_interval(days => v_days * 2)
     group by f.id;
end;
$$;


ALTER FUNCTION "public"."platform_facility_volume"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_audit_log_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  raise exception
    'audit_log is append-only: % is not permitted on an audit entry', tg_op
    using errcode = 'insufficient_privilege',
          hint    = 'Audit entries are immutable; insert a new corrective entry instead.';
  return null;
end;
$$;


