CREATE OR REPLACE FUNCTION "public"."provision_facility"("p_request_id" "uuid", "p_name" "text", "p_slug" "text", "p_timezone" "text", "p_owner_name" "text", "p_owner_email" "text", "p_owner_phone" "text" DEFAULT NULL::"text", "p_contact_email" "text" DEFAULT NULL::"text", "p_contact_phone" "text" DEFAULT NULL::"text", "p_website" "text" DEFAULT NULL::"text", "p_locations" "jsonb" DEFAULT '[]'::"jsonb", "p_business_types" "text"[] DEFAULT '{}'::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_existing    jsonb;
  v_org_id      uuid;
  v_facility_id uuid;
  v_location_id uuid;
  v_staff       public.staff;
  v_first       text;
  v_last        text;
  v_loc         jsonb;
  v_primary     boolean := true;
  v_grant       jsonb;
begin
  if not private.is_platform_admin() then
    raise exception 'Only a platform administrator may create a facility.'
      using errcode = '42501';
  end if;

  if p_request_id is null then
    raise exception 'A request id is required so a retry cannot create a second facility.'
      using errcode = '22023';
  end if;

  select r.response into v_existing
    from public.provisioning_requests r where r.id = p_request_id;
  if v_existing is not null then
    return v_existing || jsonb_build_object('replayed', true);
  end if;

  if coalesce(trim(p_name), '') = '' then
    raise exception 'A facility needs a name.' using errcode = '22023';
  end if;
  if coalesce(trim(p_owner_email), '') = '' then
    raise exception 'A facility needs an owner email address to invite.'
      using errcode = '22023';
  end if;

  insert into public.orgs (name, slug)
  values (trim(p_name), lower(trim(p_slug)))
  returning id into v_org_id;

  insert into public.facilities (org_id, name, slug, timezone, business_types)
  values (v_org_id, trim(p_name), lower(trim(p_slug)),
          coalesce(nullif(trim(p_timezone), ''), 'America/Toronto'),
          coalesce(p_business_types, '{}'))
  returning id into v_facility_id;

  -- Trialing, not active: nobody has paid yet, and recording that they had
  -- would be exactly the convenient fiction this spec exists to remove.
  insert into public.facility_subscriptions
    (facility_id, trial_ends_at, period_end)
  values (v_facility_id, now() + interval '30 days', now() + interval '30 days');

  if jsonb_array_length(coalesce(p_locations, '[]'::jsonb)) = 0 then
    insert into public.locations (facility_id, name, is_primary, timezone)
    values (v_facility_id, 'Main', true,
            coalesce(nullif(trim(p_timezone), ''), 'America/Toronto'))
    returning id into v_location_id;
  else
    for v_loc in select * from jsonb_array_elements(p_locations)
    loop
      insert into public.locations (facility_id, name, is_primary, timezone)
      values (v_facility_id,
              coalesce(nullif(trim(v_loc->>'name'), ''), 'Main'),
              v_primary,
              coalesce(nullif(trim(p_timezone), ''), 'America/Toronto'))
      returning id into v_location_id;
      v_primary := false;
    end loop;
  end if;

  v_first := split_part(trim(coalesce(p_owner_name, '')), ' ', 1);
  v_last  := nullif(trim(substr(trim(coalesce(p_owner_name, '')),
                                length(v_first) + 1)), '');

  insert into public.staff (
    facility_id, first_name, last_name, email, phone,
    job_title, primary_role, status
  )
  values (
    v_facility_id,
    coalesce(nullif(v_first, ''), 'Owner'),
    coalesce(v_last, ''),
    lower(trim(p_owner_email)),
    nullif(trim(coalesce(p_owner_phone, '')), ''),
    'Owner',
    'owner'::public.facility_staff_role,
    'active'
  )
  returning * into v_staff;

  v_grant := private.record_grant_for_staff(v_staff, null);

  v_existing := jsonb_build_object(
    'facilityId', v_facility_id,
    'orgId',      v_org_id,
    'locationId', v_location_id,
    'slug',       lower(trim(p_slug)),
    'staffId',    v_staff.id,
    'ownerEmail', lower(trim(p_owner_email)),
    'grant',      v_grant,
    'contact',    jsonb_build_object(
                    'email',   nullif(trim(coalesce(p_contact_email, '')), ''),
                    'phone',   nullif(trim(coalesce(p_contact_phone, '')), ''),
                    'website', nullif(trim(coalesce(p_website, '')), '')),
    'replayed',   false);

  insert into public.provisioning_requests (id, requested_by, facility_id, response)
  values (p_request_id, (select auth.jwt()->>'sub'), v_facility_id, v_existing);

  return v_existing;
end;
$$;


ALTER FUNCTION "public"."provision_facility"("p_request_id" "uuid", "p_name" "text", "p_slug" "text", "p_timezone" "text", "p_owner_name" "text", "p_owner_email" "text", "p_owner_phone" "text", "p_contact_email" "text", "p_contact_phone" "text", "p_website" "text", "p_locations" "jsonb", "p_business_types" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."published_review_summary"("p_slug" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'count', count(*),
    'average', case when count(*) > 0
                    then round(avg(rating)::numeric, 1) end)
    from public.published_reviews_for(p_slug, 50);
$$;


ALTER FUNCTION "public"."published_review_summary"("p_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."published_review_summary"("p_slug" "text") IS 'Count and average over exactly the rows published_reviews_for returns, so the header cannot disagree with the list.';



CREATE OR REPLACE FUNCTION "public"."published_reviews_for"("p_slug" "text", "p_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "rating" smallint, "comment" "text", "author" "text", "service_type" "text", "submitted_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    resp.id,
    resp.rating,
    resp.comment,
    -- First name plus an initial. See the header.
    split_part(c.name, ' ', 1) ||
      case
        when split_part(c.name, ' ', 2) <> ''
          then ' ' || left(split_part(c.name, ' ', 2), 1) || '.'
        else ''
      end,
    coalesce(r.service_types[1], 'visit'),
    resp.submitted_at
  from public.review_responses resp
  join public.review_requests r on r.id = resp.request_id
  join public.clients c on c.id = r.client_id
  join public.facilities f on f.id = resp.facility_id
 where f.slug = p_slug
   -- LIVE only. `approved` means a person said yes; `live` means they put it
   -- up. Publishing on `approved` would take the decision away from them.
   and resp.moderation_state = 'live'
   -- Belt and braces: the same three conditions the moderation screen enforces,
   -- restated here so a row that reached `live` by some other route still
   -- cannot be published without a comment or without consent.
   and resp.display_consent
   and nullif(btrim(resp.comment), '') is not null
   and resp.rating >= r.showcase_min
 order by coalesce(resp.showcase_sort_order, 999), resp.submitted_at desc
 limit least(greatest(coalesce(p_limit, 20), 1), 50);
$$;


ALTER FUNCTION "public"."published_reviews_for"("p_slug" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."published_reviews_for"("p_slug" "text", "p_limit" integer) IS 'The reviews a facility has put on its own booking page. Returns only the fields that page renders; the tables stay unreachable by anon.';



CREATE OR REPLACE FUNCTION "public"."purchase_package"("p_client_id" "uuid", "p_package_id" "uuid", "p_price_override" numeric DEFAULT NULL::numeric) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_pkg    record;
  v_client uuid;
  v_cp     uuid;
begin
  select p.id, p.facility_id, p.name, p.package_price, p.validity_days, p.status
    into v_pkg
    from public.prepaid_packages p
   where p.id = p_package_id;

  if v_pkg.id is null then
    raise exception 'That package does not exist, or is not yours.'
      using errcode = 'no_data_found';
  end if;

  if v_pkg.status <> 'active' and v_pkg.status <> 'seasonal' then
    raise exception 'That package is not on sale.' using errcode = '23514';
  end if;

  select c.id into v_client
    from public.clients c
   where c.id = p_client_id and c.facility_id = v_pkg.facility_id;

  if v_client is null then
    raise exception 'That client is not at this facility.'
      using errcode = 'no_data_found';
  end if;

  if not exists (select 1 from public.prepaid_package_lines l
                  where l.package_id = v_pkg.id) then
    raise exception 'That package has nothing in it.' using errcode = '23514';
  end if;

  if p_price_override is not null and p_price_override < 0 then
    raise exception 'A package cannot be sold for less than nothing.'
      using errcode = '23514';
  end if;

  insert into public.customer_packages
    (facility_id, client_id, package_id, package_name, price_paid,
     purchased_at, expires_at)
  values
    (v_pkg.facility_id, v_client, v_pkg.id, v_pkg.name,
     coalesce(p_price_override, v_pkg.package_price),
     now(), now() + make_interval(days => v_pkg.validity_days))
  returning id into v_cp;

  insert into public.customer_package_lines
    (customer_package_id, service_id, service_name, passes_total, module)
  select v_cp, l.service_id, l.service_name, l.quantity, l.module
    from public.prepaid_package_lines l
   where l.package_id = v_pkg.id;

  return v_cp;
end;
$$;


ALTER FUNCTION "public"."purchase_package"("p_client_id" "uuid", "p_package_id" "uuid", "p_price_override" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."purchase_package"("p_client_id" "uuid", "p_package_id" "uuid", "p_price_override" numeric) IS 'Sells a prepaid package to a client. Name, price, validity and pools are copied from the catalogue row inside the transaction, never taken from the caller. p_price_override exists for a negotiated price and is still a snapshot. Both writes or neither.';



CREATE OR REPLACE FUNCTION "public"."purge_e2e_bookings"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_deleted integer;
begin
  with removable as (
    select b.id
      from public.bookings b
     where b.special_requests like '%[e2e %'
       and b.status = 'cancelled'
       and not exists (
         select 1 from public.payments p where p.booking_id = b.id
       )
       and not exists (
         select 1 from public.store_credit_entries s where s.booking_id = b.id
       )
       and not exists (
         select 1 from public.package_pass_entries k where k.booking_id = b.id
       )
  )
  delete from public.bookings b
   using removable r
   where b.id = r.id;

  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;


ALTER FUNCTION "public"."purge_e2e_bookings"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."purge_e2e_bookings"() IS 'Delete cancelled e2e bookings that hold no money. Takes no argument on purpose — it can only ever match ''%[e2e %''. Run by scripts/purge-e2e-bookings.ts after a suite run.';



CREATE OR REPLACE FUNCTION "public"."purge_e2e_forms"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_deleted integer;
begin
  -- The answers first: RESTRICT would otherwise refuse the form.
  delete from public.form_submissions s
   using public.form_versions v, public.forms f
   where s.form_version_id = v.id
     and v.form_id = f.id
     and f.name like '[e2e]%';

  -- Versions and requirement overrides cascade from here.
  delete from public.forms f
   where f.name like '[e2e]%';

  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;


ALTER FUNCTION "public"."purge_e2e_forms"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."purge_e2e_forms"() IS 'Deletes forms named [e2e]% and their submissions. Service role only; called by bun run e2e:purge.';



CREATE OR REPLACE FUNCTION "public"."purge_e2e_report_cards"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_deleted integer;
begin
  with removable as (
    select c.id
      from public.report_cards c
     where c.generated->>'todaysVibe' like 'E2E: %'
       -- Untouched by the person it was addressed to.
       and c.viewed_at is null
       and c.reply_message is null
       and c.rating_submitted_at is null
       and c.favourite = false
  )
  delete from public.report_cards t
   using removable r
   where t.id = r.id;

  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;


ALTER FUNCTION "public"."purge_e2e_report_cards"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."purge_e2e_report_cards"() IS 'YES, THIS DELETES SENT REPORT CARDS — that is the point, and it is why it is service_role only. A sent card has no DELETE policy for anyone, deliberately, because the owner received it; the suite therefore cannot clean up the one card it sends per run. Takes no argument on purpose, so there is no pattern for a caller to widen: it can only ever match generated->>''todaysVibe'' like ''E2E: %'', which the report-card form cannot produce, and never a card a customer has opened, replied to, rated or favourited. Run by scripts/purge-e2e-bookings.ts after a suite run.';



CREATE OR REPLACE FUNCTION "public"."purge_e2e_store_credit"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row     record;
  v_written integer := 0;
begin
  for v_row in
    select e.facility_id,
           e.client_id,
           sum(e.amount) as outstanding
      from public.store_credit_entries e
     where (e.note like 'Gift card E2E-GC-%'
            or e.note like '%[e2e store-credit]%')
       -- Never a row that some payment or booking depends on.
       and e.payment_id is null
       and e.booking_id is null
     group by e.facility_id, e.client_id
    having abs(sum(e.amount)) > 0.005
  loop
    insert into public.store_credit_entries
      (facility_id, client_id, amount, reason, note, author_name)
    values
      (v_row.facility_id, v_row.client_id, -v_row.outstanding, 'adjustment',
       '[e2e store-credit] purge correction', 'e2e:purge');
    v_written := v_written + 1;
  end loop;

  return v_written;
end;
$$;


ALTER FUNCTION "public"."purge_e2e_store_credit"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."purge_e2e_store_credit"() IS 'Appends one balancing adjustment per client for store credit the suite invented. Never deletes: the ledger is append-only by design. Service role only; called by bun run e2e:purge.';



CREATE OR REPLACE FUNCTION "public"."purge_e2e_task_groups"() RETURNS TABLE("tasks" integer, "groups" integer, "definitions" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- No foreign key binds these to anything, so they are neither a blocker nor
  -- a cascade. Deleted first only so the count reads in dependency order.
  delete from public.facility_tasks t where t.title like '[e2e]%';
  get diagnostics tasks = row_count;

  -- Their items cascade from here.
  delete from public.facility_task_groups g where g.name like '[e2e]%';
  get diagnostics groups = row_count;

  -- Only the chores nothing names any more. A chore a surviving group still
  -- uses stays, and the count is how you find out.
  delete from public.facility_task_definitions d
   where d.title like '[e2e]%'
     and not exists (
       select 1 from public.facility_task_group_items i
        where i.definition_id = d.id
     );
  get diagnostics definitions = row_count;

  return next;
end;
$$;


ALTER FUNCTION "public"."purge_e2e_task_groups"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."purge_e2e_task_groups"() IS 'Deletes facility tasks, task groups and unreferenced task definitions named [e2e]%. Service role only; called by bun run e2e:purge.';



CREATE OR REPLACE FUNCTION "public"."quote_promo_code"("p_facility_id" "uuid", "p_code" "text", "p_client_id" "uuid", "p_service" "text", "p_amount" numeric, "p_lock" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_promo public.promo_codes;
  v_tz text;
  v_today date;
  v_uses integer;
  v_days jsonb;
  v_amount numeric(10, 2);
begin
  if not private.has_permission(p_facility_id, 'retail_process_sale') then
    raise exception 'Not allowed to take a sale at this facility.'
      using errcode = '42501', hint = 'promo_not_allowed';
  end if;

  if p_lock then
    select * into v_promo from public.promo_codes
     where facility_id = p_facility_id and code = upper(btrim(coalesce(p_code, '')))
     for update;
  else
    select * into v_promo from public.promo_codes
     where facility_id = p_facility_id and code = upper(btrim(coalesce(p_code, '')));
  end if;
  if not found or not v_promo.is_active then
    raise exception 'No active promo code by that name.' using hint = 'promo_unknown';
  end if;

  select timezone into v_tz from public.facilities where id = p_facility_id;
  v_today := (now() at time zone coalesce(v_tz, 'America/Toronto'))::date;
  if (v_promo.valid_from is not null and v_today < v_promo.valid_from)
     or (v_promo.valid_until is not null and v_today > v_promo.valid_until) then
    raise exception 'That code is outside its dates.' using hint = 'promo_expired';
  end if;
  if cardinality(v_promo.applies_to) > 0
     and not (lower(coalesce(p_service, '')) = any (v_promo.applies_to)) then
    raise exception 'That code does not cover this service.' using hint = 'promo_wrong_service';
  end if;
  v_days := v_promo.detail->'specificDays';
  if jsonb_typeof(v_days) = 'array' and jsonb_array_length(v_days) > 0
     and not (v_days ? trim(to_char(now() at time zone coalesce(v_tz, 'America/Toronto'), 'fmday'))) then
    raise exception 'That code is not valid on this day.' using hint = 'promo_wrong_day';
  end if;
  if v_promo.usage_limit is not null then
    select count(*) into v_uses from public.promo_code_redemptions where promo_code_id = v_promo.id;
    if v_uses >= v_promo.usage_limit then
      raise exception 'That code has been used up.' using hint = 'promo_used_up';
    end if;
  end if;
  if v_promo.per_customer_limit is not null and p_client_id is not null then
    select count(*) into v_uses from public.promo_code_redemptions
     where promo_code_id = v_promo.id and client_id = p_client_id;
    if v_uses >= v_promo.per_customer_limit then
      raise exception 'This client has already used that code.' using hint = 'promo_client_limit';
    end if;
  end if;
  if v_promo.first_time_only and (
       p_client_id is null
       or exists (select 1 from public.bookings o
                   where o.client_id = p_client_id and o.status = 'completed')
       or exists (select 1 from public.retail_sales s
                   where s.client_id = p_client_id and s.status = 'completed')) then
    raise exception 'That code is for a first visit.' using hint = 'promo_first_time';
  end if;
  if v_promo.min_purchase is not null and coalesce(p_amount, 0) < v_promo.min_purchase then
    raise exception 'The sale is under the code''s minimum.' using hint = 'promo_minimum';
  end if;

  v_amount := case v_promo.discount_type
    when 'percentage' then round(coalesce(p_amount, 0) * v_promo.discount_value / 100, 2)
    when 'fixed' then v_promo.discount_value
    else coalesce(p_amount, 0)
  end;
  if v_promo.max_discount is not null then
    v_amount := least(v_amount, v_promo.max_discount);
  end if;
  v_amount := greatest(0, least(v_amount, coalesce(p_amount, 0)));
  if v_amount <= 0 then
    raise exception 'Nothing is left to discount.' using hint = 'promo_nothing_due';
  end if;
  return jsonb_build_object('promoCodeId', v_promo.id, 'code', v_promo.code, 'amount', v_amount);
end;
$$;


ALTER FUNCTION "public"."quote_promo_code"("p_facility_id" "uuid", "p_code" "text", "p_client_id" "uuid", "p_service" "text", "p_amount" numeric, "p_lock" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rate_report_card"("p_card_id" "uuid", "p_stars" integer, "p_comment" "text" DEFAULT NULL::"text") RETURNS "public"."report_cards"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_card public.report_cards;
begin
  if p_stars is null or p_stars < 1 or p_stars > 5 then
    raise exception 'A rating is between 1 and 5 stars.' using errcode = '22023';
  end if;

  -- Rated once. A card whose rating can be revised is a card whose reported
  -- satisfaction depends on when it was read, and the facility's reputation
  -- screens average these.
  update public.report_cards
     set rating_stars        = p_stars,
         rating_comment      = p_comment,
         rating_submitted_at = now(),
         updated_at          = now()
   where id = p_card_id
     and client_id in (select private.own_client_ids())
     and delivery_status = 'sent'
     and rating_submitted_at is null
  returning * into v_card;

  if v_card.id is null then
    raise exception 'That report card is not yours to rate, or you have already rated it.'
      using errcode = '42501';
  end if;

  return v_card;
end;
$$;


ALTER FUNCTION "public"."rate_report_card"("p_card_id" "uuid", "p_stars" integer, "p_comment" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rate_report_card"("p_card_id" "uuid", "p_stars" integer, "p_comment" "text") IS 'Record the owner''s star rating once. Raises 42501 on a second attempt. anon holds no EXECUTE grant.';



CREATE OR REPLACE FUNCTION "public"."read_boarding_secret"("p_application_id" "uuid", "p_kind" "text", "p_principal_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_name text;
begin
  v_name := format('boarding:%s:%s:%s', p_application_id, p_kind,
                   coalesce(p_principal_id::text, 'business'));
  return (select s.decrypted_secret from vault.decrypted_secrets s
           where s.name = v_name);
end;
$$;


ALTER FUNCTION "public"."read_boarding_secret"("p_application_id" "uuid", "p_kind" "text", "p_principal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rebook_history"("p_facility_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS TABLE("send_id" "uuid", "client_id" "uuid", "client_name" "text", "service" "text", "channel" "text", "status" "text", "skip_reason" "text", "to_address" "text", "created_at" timestamp with time zone, "sent_at" timestamp with time zone, "rebooked_at" timestamp with time zone, "rebooked_total" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select
    ms.id,
    ms.client_id,
    c.name,
    split_part(ms.idempotency_key, ':', 2),
    ms.channel,
    ms.status,
    ms.skip_reason,
    ms.to_address,
    ms.created_at,
    ms.sent_at,
    rb.created_at,
    rb.total_cost
  from public.message_sends ms
  left join public.clients c on c.id = ms.client_id
  left join lateral (
    select b.created_at, b.total_cost
      from public.bookings b
     where b.facility_id = ms.facility_id
       and b.client_id   = ms.client_id
       and b.service     = split_part(ms.idempotency_key, ':', 2)
       and b.status not in ('cancelled', 'declined', 'no_show')
       and b.created_at > coalesce(ms.sent_at, ms.created_at)
     order by b.created_at
     limit 1
  ) rb on true
 where ms.facility_id = p_facility_id
   and ms.source_kind = 'rebook'
 order by ms.created_at desc
 limit greatest(coalesce(p_limit, 100), 0);
$$;


ALTER FUNCTION "public"."rebook_history"("p_facility_id" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rebook_history"("p_facility_id" "uuid", "p_limit" integer) IS 'Rebook reminders that were attempted, read straight off the outbox. rebooked_at is derived by lateral join, never stored.';



CREATE OR REPLACE FUNCTION "public"."rebook_pipeline"("p_facility_id" "uuid", "p_rules" "jsonb", "p_today" "date" DEFAULT CURRENT_DATE, "p_min_overdue" integer DEFAULT NULL::integer, "p_max_overdue" integer DEFAULT NULL::integer, "p_limit" integer DEFAULT 200) RETURNS TABLE("client_id" "uuid", "client_name" "text", "client_email" "text", "client_phone" "text", "service" "text", "last_visit_at" timestamp with time zone, "last_booking_id" "uuid", "days_since" integer, "expected_days" integer, "days_overdue" integer, "due_on" "date", "lead_days" integer, "scheduled_send_on" "date", "is_lapsed" boolean, "reminders_sent" integer, "pet_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with allowed as (
    -- THE CHECK THIS FUNCTION NOW OWES. Running as definer means RLS no longer
    -- stands between the caller and 2,300 bookings, so the permission is asked
    -- ONCE, here, instead of per row. `view_clients` because that is what
    -- `clients_read` requires and what this returns: name, email and phone.
    select private.is_platform_admin()
        or private.has_permission(p_facility_id, 'view_clients') as ok
  ),
  rules as (
    select key as service,
           (value ->> 'frequencyDays')::int              as expected_days,
           (value ->> 'lapsedAfterDays')::int            as grace_days,
           coalesce((value ->> 'leadDays')::int, 0)      as lead_days
      from jsonb_each(coalesce(p_rules, '{}'::jsonb))
     where (value ->> 'frequencyDays') is not null
       and (value ->> 'lapsedAfterDays') is not null
  ),
  last_visit as (
    select distinct on (b.client_id, b.service)
           b.client_id,
           b.service,
           b.start_at as last_visit_at,
           b.id       as booking_id
      from public.bookings b
     where b.facility_id = p_facility_id
       and b.status = 'completed'
       and b.service is not null
       and b.client_id is not null
     order by b.client_id, b.service, b.start_at desc
  ),
  resolved as (
    select
      c.id   as client_id,
      c.name as client_name,
      c.email as client_email,
      c.phone as client_phone,
      lv.service,
      lv.last_visit_at,
      lv.booking_id,
      r.grace_days,
      r.lead_days,
      coalesce(pref.frequency_days::int, r.expected_days) as expected_days
    from last_visit lv
    join rules r          on r.service = lv.service
    join public.clients c on c.id = lv.client_id
    left join public.client_rebook_preferences pref
      on pref.facility_id = p_facility_id
     and pref.client_id   = c.id
     and pref.service     = lv.service
    left join public.client_rebook_preferences whole
      on whole.facility_id = p_facility_id
     and whole.client_id   = c.id
     and whole.service is null
   where c.facility_id = p_facility_id
     and c.status = 'active'
     and not coalesce(c.is_blocked, false)
     -- The facility's own note: do not chase this client. For this service, or
     -- for all of them.
     and coalesce(pref.reminders_enabled, true)
     and coalesce(whole.reminders_enabled, true)
     and not exists (
       select 1 from public.bookings b2
        where b2.facility_id = p_facility_id
          and b2.client_id = c.id
          and b2.service = lv.service
          and b2.status not in ('completed', 'cancelled', 'no_show', 'declined')
     )
     and not exists (
       select 1 from public.rebook_dismissals d
        where d.facility_id = p_facility_id
          and d.client_id = c.id
          and d.service = lv.service
          and d.dismissed_at > lv.last_visit_at
     )
  )
  select
    x.client_id,
    x.client_name,
    x.client_email,
    x.client_phone,
    x.service,
    x.last_visit_at,
    x.booking_id,
    (p_today - x.last_visit_at::date)::int,
    x.expected_days,
    ((p_today - x.last_visit_at::date) - x.expected_days)::int,
    (x.last_visit_at::date + x.expected_days),
    x.lead_days,
    (x.last_visit_at::date + x.expected_days - x.lead_days),
    ((p_today - x.last_visit_at::date) >= x.expected_days + x.grace_days),
    (select count(*)::int
       from public.message_sends ms
      where ms.facility_id = p_facility_id
        and ms.status in ('queued', 'sending', 'sent')
        and ms.idempotency_key like
            'rebook:' || x.service || ':-:' || x.client_id::text || ':%'),
    (select p.name
       from public.booking_pets bp
       join public.pets p on p.id = bp.pet_id
      where bp.booking_id = x.booking_id
      order by p.name
      limit 1)
  from resolved x
 cross join allowed
 where allowed.ok
   and ((p_today - x.last_visit_at::date) - x.expected_days)
         >= coalesce(p_min_overdue, -100000)
   and ((p_today - x.last_visit_at::date) - x.expected_days)
         <= coalesce(p_max_overdue,  100000)
 order by ((p_today - x.last_visit_at::date) - x.expected_days) desc, x.client_name
 limit greatest(coalesce(p_limit, 200), 0);
$$;


ALTER FUNCTION "public"."rebook_pipeline"("p_facility_id" "uuid", "p_rules" "jsonb", "p_today" "date", "p_min_overdue" integer, "p_max_overdue" integer, "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rebook_pipeline"("p_facility_id" "uuid", "p_rules" "jsonb", "p_today" "date", "p_min_overdue" integer, "p_max_overdue" integer, "p_limit" integer) IS 'Every client+service pairing with a completed visit, over a window on days_overdue, using the CLIENT''s interval where they have one. is_lapsed is returned, not filtered: the Queue reads the false half and the Lapsed tab the true half, from one definition of who is excluded.';



CREATE OR REPLACE FUNCTION "public"."receive_purchase_order"("p_po_id" "uuid", "p_lines" "jsonb", "p_author_name" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_po public.retail_purchase_orders;
  v_line jsonb;
  v_items jsonb;
  v_idx integer;
  v_qty integer;
  v_item jsonb;
  v_all boolean := true;
  v_any boolean := false;
  v_status text;
begin
  select * into v_po from public.retail_purchase_orders where id = p_po_id for update;
  if not found then
    raise exception 'No such purchase order.' using errcode = '42501';
  end if;
  if not private.has_permission(v_po.facility_id, 'retail_manage_inventory') then
    raise exception 'Not allowed to receive stock at this facility.' using errcode = '42501';
  end if;
  if v_po.status in ('received', 'cancelled') then
    raise exception 'That order is already closed.' using errcode = '22023';
  end if;

  v_items := v_po.items;
  for v_line in select * from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) loop
    v_idx := (v_line->>'index')::integer;
    v_qty := coalesce((v_line->>'quantity')::integer, 0);
    if v_idx is null or v_idx < 0 or v_idx >= jsonb_array_length(v_items) then
      raise exception 'No such line on the order.' using errcode = '22023';
    end if;
    if v_qty <= 0 then continue; end if;
    v_item := v_items->v_idx;
    if nullif(v_item->>'productId', '') is not null then
      insert into public.retail_stock_movements
        (facility_id, product_id, variant_id, delta, reason, note, purchase_order_id, author_name)
      values
        (v_po.facility_id, (v_item->>'productId')::uuid, nullif(v_item->>'variantId', ''),
         v_qty, 'received', 'PO #' || v_po.number, v_po.id,
         coalesce(nullif(btrim(p_author_name), ''), 'Staff'));
    end if;
    v_item := jsonb_set(v_item, '{received}',
      to_jsonb(coalesce((v_item->>'received')::integer, 0) + v_qty));
    if v_line ? 'unitCost' then
      v_item := jsonb_set(v_item, '{unitCost}', v_line->'unitCost');
    end if;
    v_items := jsonb_set(v_items, array[v_idx::text], v_item);
    v_any := true;
  end loop;
  if not v_any then
    raise exception 'Nothing was received.' using errcode = '22023';
  end if;

  select bool_and(coalesce((x->>'received')::integer, 0) >= coalesce((x->>'quantity')::integer, 0))
    into v_all from jsonb_array_elements(v_items) x;
  v_status := case when v_all then 'received' else 'partial' end;

  update public.retail_purchase_orders
     set items = v_items, status = v_status,
         received_at = case when v_all then now() else received_at end,
         updated_at = now()
   where id = v_po.id;

  return jsonb_build_object('status', v_status, 'items', v_items);
end;
$$;


ALTER FUNCTION "public"."receive_purchase_order"("p_po_id" "uuid", "p_lines" "jsonb", "p_author_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_boarding_arrival"("p_booking_ref" bigint, "p_action" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking      public.bookings%rowtype;
  v_stay         public.boarding_stays%rowtype;
  v_checked_in   timestamptz;
  v_checked_out  timestamptz;
  v_status       text;
begin
  if p_action not in ('check_in', 'check_out', 'reopen', 'revert') then
    raise exception 'Unknown action "%".', p_action using errcode = '22023';
  end if;

  select * into v_booking from public.bookings where ref = p_booking_ref;
  if not found then
    raise exception 'That booking does not exist.' using errcode = 'P0002';
  end if;

  if not private.has_permission(v_booking.facility_id, 'check_in_out') then
    raise exception 'Not allowed to check guests in or out at this facility.'
      using errcode = '42501';
  end if;

  if v_booking.service <> 'boarding' then
    raise exception 'That booking is not a boarding booking.'
      using errcode = '22023';
  end if;

  select * into v_stay from public.boarding_stays
   where booking_id = v_booking.id and segment_order = 1;
  if not found then
    raise exception
      'This guest has no kennel yet. Assign one on Boarding Ops, then check in.'
      using errcode = '55000';
  end if;

  v_checked_in  := v_stay.checked_in_at;
  v_checked_out := v_stay.checked_out_at;

  if p_action = 'check_in' then
    if v_booking.status in ('cancelled', 'declined') then
      raise exception
        'That booking is cancelled. Reinstate it before checking in.'
        using errcode = '22023';
    end if;
    if v_checked_in is null or v_checked_out is not null then
      v_checked_in  := now();
      v_checked_out := null;
    end if;

  elsif p_action = 'check_out' then
    if v_checked_in is null then
      raise exception 'This guest has not been checked in yet.'
        using errcode = '22023';
    end if;
    v_checked_out := now();

  elsif p_action = 'reopen' then
    v_checked_out := null;

  else
    if v_checked_out is not null then
      raise exception
        'This stay has been checked out. Reopen it first, then revert the arrival.'
        using errcode = '22023';
    end if;
    if v_checked_in is null then
      raise exception 'This guest was never checked in.' using errcode = '22023';
    end if;
    v_checked_in := null;
  end if;

  update public.boarding_stays
     set checked_in_at  = v_checked_in,
         checked_out_at = v_checked_out,
         updated_at     = now()
   where id = v_stay.id
  returning status into v_status;

  -- A split booking's LAST stay holds the night by the departure, so it is
  -- touched to let the cut-off read the one just recorded.
  update public.boarding_stays
     set updated_at = now()
   where booking_id = v_booking.id
     and segment_order > 1
     and segment_order = (select max(s.segment_order) from public.boarding_stays s
                           where s.booking_id = v_booking.id);

  return v_status;
end $$;


ALTER FUNCTION "public"."record_boarding_arrival"("p_booking_ref" bigint, "p_action" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_boarding_arrival"("p_booking_ref" bigint, "p_action" "text") IS 'Check-in/out for a boarding stay. Requires check_in_out on the booking''s own facility. anon holds no EXECUTE grant — see 20260804200000_rpc_require_session.sql for why that must be revoked explicitly.';



CREATE OR REPLACE FUNCTION "public"."record_care_gate_override"("p_booking_id" "uuid", "p_reason" "text", "p_items" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking  public.bookings;
  v_reason   text := nullif(btrim(coalesce(p_reason, '')), '');
  v_items    jsonb;
  v_critical boolean;
  v_id       uuid;
begin
  select * into v_booking from public.bookings b where b.id = p_booking_id;

  if not found
     or not (
       private.has_permission(v_booking.facility_id, 'edit_bookings')
       or private.has_permission(v_booking.facility_id, 'check_in_out')
       or private.has_permission(v_booking.facility_id, 'daycare_check_in_out')
     )
  then
    raise exception 'Not allowed to check this booking out.'
      using errcode = '42501';
  end if;

  if v_reason is null then
    raise exception 'A reason is required to check out with care not logged.'
      using errcode = '22023';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'kind', left(coalesce(e->>'kind', ''), 40),
           'label', left(coalesce(e->>'label', ''), 200),
           'critical', coalesce((e->>'critical')::boolean, false))), '[]'::jsonb)
    into v_items
    from (select e from jsonb_array_elements(
            case when jsonb_typeof(p_items) = 'array' then p_items else '[]'::jsonb end) e
          limit 50) x;

  v_critical := exists (select 1 from jsonb_array_elements(v_items) e
                         where (e->>'critical')::boolean);

  insert into public.care_gate_overrides
    (facility_id, booking_id, reason, items, has_critical, created_by)
  values
    (v_booking.facility_id, v_booking.id, left(v_reason, 500), v_items,
     v_critical, auth.jwt()->>'sub')
  returning id into v_id;

  perform private.record_audit(
    'Checked out with care not logged', 'Data',
    case when v_critical then 'Medium' else 'Low' end,
    'booking', v_booking.id::text, v_booking.ref::text,
    v_booking.facility_id, null, left(v_reason, 500),
    jsonb_build_array(jsonb_build_object(
      'field', 'careGate', 'from', v_items, 'to', left(v_reason, 500))));

  return v_id;
end;
$$;


ALTER FUNCTION "public"."record_care_gate_override"("p_booking_id" "uuid", "p_reason" "text", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_clover_payment"("p_intent_id" "uuid", "p_processor_payment_id" "text", "p_subtotal_cents" integer, "p_tax_cents" integer DEFAULT 0, "p_tip_cents" integer DEFAULT 0, "p_card_brand" "text" DEFAULT NULL::"text", "p_card_last4" "text" DEFAULT NULL::"text", "p_auth_code" "text" DEFAULT NULL::"text", "p_entry_method" "text" DEFAULT 'ecom'::"text", "p_author_name" "text" DEFAULT 'Online payment'::"text", "p_saved_card_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_intent  public.payment_intents%rowtype;
  v_payment uuid;
  v_total   integer;
begin
  select * into v_intent from public.payment_intents where id = p_intent_id;
  if not found then
    raise exception 'No payment intent %', p_intent_id using errcode = '23503';
  end if;

  if v_intent.payment_id is not null then
    return v_intent.payment_id;
  end if;

  v_total := coalesce(p_subtotal_cents, 0) + coalesce(p_tax_cents, 0)
             + coalesce(p_tip_cents, 0);

  if v_total <> v_intent.amount_cents then
    raise exception
      'The ledger split (% cents) does not match what was charged (% cents).',
      v_total, v_intent.amount_cents
      using errcode = '22023';
  end if;

  insert into public.payments (
    facility_id, booking_id, client_id, method,
    subtotal, tax, tip,
    store_credit_applied, package_pass_applied, loyalty_discount_applied,
    amount_charged, grand_total,
    processor, processor_payment_id, card_brand, card_last4, auth_code,
    entry_method, author_name, created_by, saved_card_id)
  values (
    v_intent.facility_id, v_intent.booking_id, v_intent.client_id,
    case
      when p_saved_card_id is not null then 'card-on-file'
      when p_entry_method = 'ecom' then 'new-card'
      else 'terminal'
    end,
    p_subtotal_cents / 100.0, coalesce(p_tax_cents, 0) / 100.0,
    coalesce(p_tip_cents, 0) / 100.0,
    0, 0, 0,
    v_intent.amount_cents / 100.0, v_intent.amount_cents / 100.0,
    v_intent.processor, p_processor_payment_id, p_card_brand, p_card_last4,
    p_auth_code, p_entry_method, coalesce(p_author_name, 'Online payment'),
    v_intent.created_by, p_saved_card_id)
  returning id into v_payment;

  update public.payment_intents
     set status               = 'approved',
         processor_payment_id = p_processor_payment_id,
         payment_id           = v_payment,
         completed_at         = coalesce(completed_at, now())
   where id = p_intent_id;

  return v_payment;
end;
$$;


ALTER FUNCTION "public"."record_clover_payment"("p_intent_id" "uuid", "p_processor_payment_id" "text", "p_subtotal_cents" integer, "p_tax_cents" integer, "p_tip_cents" integer, "p_card_brand" "text", "p_card_last4" "text", "p_auth_code" "text", "p_entry_method" "text", "p_author_name" "text", "p_saved_card_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_clover_payment"("p_intent_id" "uuid", "p_processor_payment_id" "text", "p_subtotal_cents" integer, "p_tax_cents" integer, "p_tip_cents" integer, "p_card_brand" "text", "p_card_last4" "text", "p_auth_code" "text", "p_entry_method" "text", "p_author_name" "text", "p_saved_card_id" "uuid") IS 'Writes the ledger row and links its intent in ONE transaction, so the reconciliation gap cannot open. Idempotent. service_role only. p_saved_card_id names the stored card, and makes the row card-on-file.';



