CREATE OR REPLACE FUNCTION "public"."record_facility_export"("p_facility_id" "uuid", "p_datasets" "text"[], "p_row_count" integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_facility text;
begin
  if not private.is_platform_admin() then
    raise exception 'Only a platform administrator may export a facility''s data.'
      using errcode = '42501';
  end if;

  select f.name into v_facility from public.facilities f where f.id = p_facility_id;
  if v_facility is null then
    raise exception 'No facility %', p_facility_id using errcode = '23503';
  end if;

  return private.record_audit(
    'Facility data exported',
    'Data',
    'High',
    'facility', p_facility_id::text, v_facility,
    p_facility_id, v_facility,
    format('%s rows exported from %s (%s)',
           greatest(coalesce(p_row_count, 0), 0),
           v_facility,
           coalesce(array_to_string(p_datasets, ', '), 'no datasets')),
    jsonb_build_array(
      jsonb_build_object(
        'field', 'datasets',
        'from', null,
        'to', coalesce(array_to_string(p_datasets, ', '), 'none')),
      jsonb_build_object(
        'field', 'rows',
        'from', null,
        'to', greatest(coalesce(p_row_count, 0), 0)))
  );
end;
$$;


ALTER FUNCTION "public"."record_facility_export"("p_facility_id" "uuid", "p_datasets" "text"[], "p_row_count" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_facility_export"("p_facility_id" "uuid", "p_datasets" "text"[], "p_row_count" integer) IS 'Records that a facility''s data was exported. The one audited act with no row to hang a trigger on — see the header of 20260807640000.';



CREATE OR REPLACE FUNCTION "public"."record_form_requirement_override"("p_booking_id" "uuid", "p_stage" "text", "p_reason" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_facility uuid;
begin
  if p_stage not in ('before_approval', 'before_checkin') then
    raise exception 'Only approval and check-in overrides are recorded here.'
      using errcode = '22023';
  end if;

  select b.facility_id into v_facility from public.bookings b where b.id = p_booking_id;

  if v_facility is null
     or not (
       private.has_permission(v_facility, 'edit_bookings')
       or (p_stage = 'before_checkin'
           and (private.has_permission(v_facility, 'check_in_out')
                or private.has_permission(v_facility, 'daycare_check_in_out')))
     )
  then
    raise exception 'Not allowed to go ahead without the required forms.'
      using errcode = '42501';
  end if;

  return private.record_form_overrides(p_booking_id, p_stage, p_reason);
end;
$$;


