CREATE OR REPLACE FUNCTION "public"."record_payment"("p_facility_id" "uuid", "p_method" "text", "p_subtotal" numeric, "p_tax" numeric, "p_tip" numeric, "p_amount_charged" numeric, "p_grand_total" numeric, "p_booking_id" "uuid" DEFAULT NULL::"uuid", "p_client_id" "uuid" DEFAULT NULL::"uuid", "p_store_credit_applied" numeric DEFAULT 0, "p_package_pass_applied" numeric DEFAULT 0, "p_loyalty_discount_applied" numeric DEFAULT 0, "p_cash_received" numeric DEFAULT NULL::numeric, "p_saved_card_id" "text" DEFAULT NULL::"text", "p_package_pass_id" "text" DEFAULT NULL::"text", "p_receipt_channels" "text"[] DEFAULT '{}'::"text"[], "p_credit_note" "text" DEFAULT ''::"text", "p_customer_package_id" "uuid" DEFAULT NULL::"uuid", "p_package_service_id" "text" DEFAULT NULL::"text", "p_pet_id" "uuid" DEFAULT NULL::"uuid", "p_pet_name" "text" DEFAULT NULL::"text", "p_service_label" "text" DEFAULT ''::"text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_payment_id uuid;
  v_passes_remaining integer;
begin
  insert into public.payments
    (facility_id, booking_id, client_id, method,
     subtotal, tax, tip,
     store_credit_applied, package_pass_applied, loyalty_discount_applied,
     amount_charged, grand_total,
     cash_received, saved_card_id, package_pass_id, receipt_channels, note)
  values
    (p_facility_id, p_booking_id, p_client_id, p_method,
     p_subtotal, p_tax, p_tip,
     p_store_credit_applied, p_package_pass_applied, p_loyalty_discount_applied,
     p_amount_charged, p_grand_total,
     p_cash_received,
     nullif(btrim(coalesce(p_saved_card_id, '')), '')::uuid,
     p_package_pass_id, p_receipt_channels,
     nullif(btrim(coalesce(p_note, '')), ''))
  returning id into v_payment_id;

  if p_store_credit_applied > 0 then
    if p_client_id is null then
      raise exception 'Store credit cannot be applied without a client.'
        using errcode = '23502';
    end if;
    insert into public.store_credit_entries
      (facility_id, client_id, amount, reason, note, booking_id, payment_id)
    values
      (p_facility_id, p_client_id, -p_store_credit_applied, 'redeemed',
       p_credit_note, p_booking_id, v_payment_id);
  end if;

  if p_grand_total < 0 and p_method = 'store-credit' then
    if p_client_id is null then
      raise exception 'A refund to store credit needs a client to credit.'
        using errcode = '23502';
    end if;
    insert into public.store_credit_entries
      (facility_id, client_id, amount, reason, note, booking_id, payment_id)
    values
      (p_facility_id, p_client_id, -p_grand_total, 'refund',
       p_credit_note, p_booking_id, v_payment_id);
  end if;

  if p_customer_package_id is not null then
    if p_package_service_id is null then
      raise exception 'A pass redemption must name which service it is for.'
        using errcode = '23502';
    end if;
    v_passes_remaining := public.redeem_package_pass(
      p_customer_package_id, p_package_service_id, p_service_label,
      p_booking_id, p_pet_id, p_pet_name
    );
  end if;

  return jsonb_build_object(
    'payment_id', v_payment_id,
    'passes_remaining', v_passes_remaining
  );
end;
$$;


ALTER FUNCTION "public"."record_payment"("p_facility_id" "uuid", "p_method" "text", "p_subtotal" numeric, "p_tax" numeric, "p_tip" numeric, "p_amount_charged" numeric, "p_grand_total" numeric, "p_booking_id" "uuid", "p_client_id" "uuid", "p_store_credit_applied" numeric, "p_package_pass_applied" numeric, "p_loyalty_discount_applied" numeric, "p_cash_received" numeric, "p_saved_card_id" "text", "p_package_pass_id" "text", "p_receipt_channels" "text"[], "p_credit_note" "text", "p_customer_package_id" "uuid", "p_package_service_id" "text", "p_pet_id" "uuid", "p_pet_name" "text", "p_service_label" "text", "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_payment"("p_facility_id" "uuid", "p_method" "text", "p_subtotal" numeric, "p_tax" numeric, "p_tip" numeric, "p_amount_charged" numeric, "p_grand_total" numeric, "p_booking_id" "uuid", "p_client_id" "uuid", "p_store_credit_applied" numeric, "p_package_pass_applied" numeric, "p_loyalty_discount_applied" numeric, "p_cash_received" numeric, "p_saved_card_id" "text", "p_package_pass_id" "text", "p_receipt_channels" "text"[], "p_credit_note" "text", "p_customer_package_id" "uuid", "p_package_service_id" "text", "p_pet_id" "uuid", "p_pet_name" "text", "p_service_label" "text", "p_note" "text") IS 'Records a payment and, in the SAME transaction, the store-credit entry it implies — negative when credit is spent, positive when a refund is issued as credit. p_note is why it happened, in the operator''s words. SECURITY INVOKER: every insert still faces its own table''s RLS.';



