    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  update public.payment_connections
     set status     = 'error',
         last_error = left(coalesce(p_error, 'Unknown error'), 500)
   where facility_id = p_facility_id
     and processor = p_processor;
$$;


ALTER FUNCTION "public"."record_payment_connection_error"("p_facility_id" "uuid", "p_error" "text", "p_processor" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_payment_webhook"("p_processor" "text", "p_environment" "text", "p_app_id" "text", "p_merchant_id" "text", "p_object_kind" "text", "p_object_id" "text", "p_change" "text", "p_occurred_at" timestamp with time zone, "p_payload" "jsonb") RETURNS TABLE("event_id" "uuid", "is_new" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_facility uuid;
  v_id       uuid;
begin
  select pc.facility_id into v_facility
    from public.payment_connections pc
   where pc.processor = p_processor
     and pc.merchant_id = p_merchant_id;

  insert into public.payment_webhook_events (
    processor, environment, app_id, merchant_id, facility_id,
    object_kind, object_id, change, occurred_at, payload
  )
  values (
    p_processor, p_environment, p_app_id, p_merchant_id, v_facility,
    p_object_kind, p_object_id, p_change, p_occurred_at, p_payload
  )
  on conflict do nothing
  returning id into v_id;

  if v_id is not null then
    return query select v_id, true;
    return;
  end if;

  select e.id into v_id
    from public.payment_webhook_events e
   where e.processor = p_processor
     and e.merchant_id = p_merchant_id
     and e.object_id = p_object_id
     and e.change is not distinct from p_change
     and e.occurred_at is not distinct from p_occurred_at;

  return query select v_id, false;
end;
$$;


ALTER FUNCTION "public"."record_payment_webhook"("p_processor" "text", "p_environment" "text", "p_app_id" "text", "p_merchant_id" "text", "p_object_kind" "text", "p_object_id" "text", "p_change" "text", "p_occurred_at" timestamp with time zone, "p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_payment_webhook"("p_processor" "text", "p_environment" "text", "p_app_id" "text", "p_merchant_id" "text", "p_object_kind" "text", "p_object_id" "text", "p_change" "text", "p_occurred_at" timestamp with time zone, "p_payload" "jsonb") IS 'Idempotent. Returns the event and whether this delivery was the first one; a retry returns the original row untouched.';



CREATE OR REPLACE FUNCTION "public"."record_retail_sale"("p_facility_id" "uuid", "p_items" "jsonb", "p_subtotal" numeric, "p_discount" numeric, "p_tax" numeric, "p_tip" numeric, "p_total" numeric, "p_tender" "text", "p_client_id" "uuid" DEFAULT NULL::"uuid", "p_payment_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_payments" "jsonb" DEFAULT '[]'::"jsonb", "p_promo_code" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text", "p_cashier_name" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_sale public.retail_sales;
  v_number bigint;
  v_label text;
  v_cashier text := coalesce(nullif(btrim(coalesce(p_cashier_name, '')), ''), 'Staff');
  v_item jsonb;
  v_pay jsonb;
  v_method text;
  v_amount numeric;
  v_paid numeric := 0;
  v_ids uuid[] := '{}';
  v_payment jsonb;
  v_card public.gift_cards;
  v_linked numeric;
  v_count integer;
  v_promo jsonb;
  v_product uuid;
  v_qty integer;
begin
  if not private.has_permission(p_facility_id, 'retail_process_sale') then
    raise exception 'Not allowed to take a sale at this facility.' using errcode = '42501';
  end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'A sale needs at least one line.' using errcode = '22023';
  end if;
  if p_client_id is not null and not exists (
    select 1 from public.clients where id = p_client_id and facility_id = p_facility_id
  ) then
    raise exception 'That client is not this facility''s.' using errcode = '42501';
  end if;

  -- The promo code, checked and locked before anything is written.
  if nullif(btrim(coalesce(p_promo_code, '')), '') is not null then
    v_promo := public.quote_promo_code(p_facility_id, p_promo_code, p_client_id,
                                       'retail', p_subtotal, true);
  end if;

  v_number := nextval('public.retail_sales_number_seq');
  v_label := 'Retail sale #' || v_number;

  -- Money taken by card before this call: this facility's, with no booking.
  if cardinality(p_payment_ids) > 0 then
    select coalesce(sum(grand_total), 0), count(*) into v_linked, v_count
      from public.payments
     where id = any (p_payment_ids) and facility_id = p_facility_id
       and booking_id is null and refund_of_payment_id is null;
    if v_count <> cardinality(p_payment_ids) then
      raise exception 'A linked payment is not a counter payment of this facility.'
        using errcode = '42501';
    end if;
    v_paid := v_paid + v_linked;
    v_ids := v_ids || p_payment_ids;
  end if;

  -- Money recorded now, through the checkout's own record_payment.
  for v_pay in select * from jsonb_array_elements(coalesce(p_payments, '[]'::jsonb)) loop
    v_method := v_pay->>'method';
    v_amount := round(coalesce((v_pay->>'amount')::numeric, 0), 2);
    if v_amount <= 0 then
      raise exception 'A payment needs an amount.' using errcode = '22023';
    end if;
    if v_method = 'gift-card' then
      v_card := public.redeem_gift_card(v_pay->>'giftCardCode', v_amount, null, v_label);
      if v_card.facility_id <> p_facility_id then
        raise exception 'That gift card belongs to another business.' using errcode = '42501';
      end if;
      v_payment := public.record_payment(
        p_facility_id => p_facility_id, p_method => 'gift-card',
        p_subtotal => v_amount, p_tax => 0, p_tip => 0,
        p_amount_charged => v_amount, p_grand_total => v_amount,
        p_client_id => p_client_id, p_service_label => v_label,
        p_note => 'Gift card ending ' || right(btrim(v_pay->>'giftCardCode'), 4));
    elsif v_method = 'store-credit' then
      v_payment := public.record_payment(
        p_facility_id => p_facility_id, p_method => 'store-credit',
        p_subtotal => v_amount, p_tax => 0, p_tip => 0,
        p_amount_charged => 0, p_grand_total => v_amount,
        p_client_id => p_client_id, p_store_credit_applied => v_amount,
        p_credit_note => v_label, p_service_label => v_label);
    elsif v_method in ('cash', 'e-transfer') then
      v_payment := public.record_payment(
        p_facility_id => p_facility_id, p_method => v_method,
        p_subtotal => v_amount, p_tax => 0, p_tip => 0,
        p_amount_charged => v_amount, p_grand_total => v_amount,
        p_client_id => p_client_id,
        p_cash_received => case when v_method = 'cash'
                                then coalesce((v_pay->>'cashReceived')::numeric, v_amount) end,
        p_service_label => v_label,
        p_note => nullif(btrim(coalesce(v_pay->>'note', '')), ''));
    else
      raise exception 'The till cannot record a % payment.', v_method using errcode = '22023';
    end if;
    v_ids := v_ids || (v_payment->>'payment_id')::uuid;
    v_paid := v_paid + v_amount;
  end loop;

  -- Paid in full, to the cent: a sale is never recorded as paid when it was not.
  if abs(v_paid - p_total) > 0.01 then
    raise exception 'The payments (%) do not meet the total (%).',
      to_char(v_paid, 'FM999999990.00'), to_char(p_total, 'FM999999990.00')
      using errcode = '22023', hint = 'sale_unpaid';
  end if;

  insert into public.retail_sales
    (facility_id, number, client_id, items, subtotal, discount_total, promo_code,
     tax_total, tip, total, tender, payment_ids, cashier_name, note)
  values
    (p_facility_id, v_number, p_client_id, p_items, p_subtotal, coalesce(p_discount, 0),
     v_promo->>'code', coalesce(p_tax, 0), coalesce(p_tip, 0), p_total, p_tender,
     v_ids, v_cashier, coalesce(p_note, ''))
  returning * into v_sale;

  -- Off the shelf, line by line.
  for v_item in select * from jsonb_array_elements(p_items) loop
    v_qty := coalesce((v_item->>'quantity')::integer, 0);
    if v_qty <= 0 then
      raise exception 'Every line needs a quantity.' using errcode = '22023';
    end if;
    v_product := nullif(v_item->>'productId', '')::uuid;
    if v_product is not null then
      insert into public.retail_stock_movements
        (facility_id, product_id, variant_id, delta, reason, note, sale_id, author_name)
      values
        (p_facility_id, v_product, nullif(v_item->>'variantId', ''), -v_qty, 'sale',
         v_label, v_sale.id, v_cashier);
    end if;
  end loop;

  if v_promo is not null then
    insert into public.promo_code_redemptions
      (facility_id, promo_code_id, code, client_id, retail_sale_id, amount)
    values
      (p_facility_id, (v_promo->>'promoCodeId')::uuid, v_promo->>'code', p_client_id,
       v_sale.id, (v_promo->>'amount')::numeric);
  end if;

  return jsonb_build_object(
    'saleId', v_sale.id,
    'number', v_sale.number,
    'paymentIds', to_jsonb(v_ids),
    'promoAmount', coalesce((v_promo->>'amount')::numeric, 0)
  );
end;
$$;


ALTER FUNCTION "public"."record_retail_sale"("p_facility_id" "uuid", "p_items" "jsonb", "p_subtotal" numeric, "p_discount" numeric, "p_tax" numeric, "p_tip" numeric, "p_total" numeric, "p_tender" "text", "p_client_id" "uuid", "p_payment_ids" "uuid"[], "p_payments" "jsonb", "p_promo_code" "text", "p_note" "text", "p_cashier_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_review_click"("p_token" "text", "p_channel_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_req  public.review_requests%rowtype;
  v_ch   public.review_channels%rowtype;
begin
  if p_token is null or length(p_token) < 16 then
    return null;
  end if;

  select * into v_req
    from public.review_requests
   where token_hash = private.hash_review_token(p_token)
     and token_expires_at > now()
     and state not in ('suppressed', 'cancelled', 'expired');
  if not found then
    return null;
  end if;

  select * into v_ch
    from public.review_channels
   where id = p_channel_id
     and facility_id = v_req.facility_id
     and (location_id is null or location_id = v_req.location_id)
     and enabled
     and solicitable;
  if not found then
    return null;
  end if;

  -- Only where a response exists, and only the FIRST click: "did they follow
  -- the link" is a yes/no per request, and re-stamping it would make the
  -- interval between rating and click meaningless.
  update public.review_responses
     set public_channel_id = v_ch.id,
         public_clicked_at = now()
   where request_id = v_req.id
     and public_clicked_at is null;

  -- The place id wins. A pasted profile URL is the fallback precisely because
  -- it rots when the business profile changes.
  return case
    when v_ch.place_id is not null
      then 'https://search.google.com/local/writereview?placeid=' || v_ch.place_id
    else v_ch.profile_url
  end;
end;
$$;


ALTER FUNCTION "public"."record_review_click"("p_token" "text", "p_channel_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_review_click"("p_token" "text", "p_channel_id" "uuid") IS 'Stamps the first public click and returns the destination. Null for anything the caller was not offered.';



CREATE OR REPLACE FUNCTION "public"."record_unattached_payment"("p_facility_id" "uuid", "p_processor_payment_id" "text", "p_amount_cents" integer, "p_tip_cents" integer DEFAULT 0, "p_tax_cents" integer DEFAULT 0, "p_currency" "text" DEFAULT NULL::"text", "p_processor_order_id" "text" DEFAULT NULL::"text", "p_processor_merchant_id" "text" DEFAULT NULL::"text", "p_processor_device_serial" "text" DEFAULT NULL::"text", "p_card_brand" "text" DEFAULT NULL::"text", "p_card_last4" "text" DEFAULT NULL::"text", "p_entry_method" "text" DEFAULT NULL::"text", "p_taken_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_payload" "jsonb" DEFAULT NULL::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid;
begin
  insert into public.unattached_payments (
    facility_id, processor, processor_payment_id,
    processor_order_id, processor_merchant_id, processor_device_serial,
    amount_cents, tip_cents, tax_cents, currency,
    card_brand, card_last4, entry_method, taken_at, payload
  )
  values (
    p_facility_id, 'clover', p_processor_payment_id,
    p_processor_order_id, p_processor_merchant_id, p_processor_device_serial,
    p_amount_cents, coalesce(p_tip_cents, 0), coalesce(p_tax_cents, 0), p_currency,
    p_card_brand, p_card_last4, p_entry_method, p_taken_at, p_payload
  )
  on conflict (processor, processor_payment_id) do nothing
  returning id into v_id;

  if v_id is not null then
    return v_id;
  end if;

  -- Already known. Hand back the original rather than deciding again — the same
  -- contract record_payment_webhook keeps, and for the same reason.
  select u.id into v_id
    from public.unattached_payments u
   where u.processor = 'clover'
     and u.processor_payment_id = p_processor_payment_id;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."record_unattached_payment"("p_facility_id" "uuid", "p_processor_payment_id" "text", "p_amount_cents" integer, "p_tip_cents" integer, "p_tax_cents" integer, "p_currency" "text", "p_processor_order_id" "text", "p_processor_merchant_id" "text", "p_processor_device_serial" "text", "p_card_brand" "text", "p_card_last4" "text", "p_entry_method" "text", "p_taken_at" timestamp with time zone, "p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_unattached_payment"("p_facility_id" "uuid", "p_processor_payment_id" "text", "p_amount_cents" integer, "p_tip_cents" integer, "p_tax_cents" integer, "p_currency" "text", "p_processor_order_id" "text", "p_processor_merchant_id" "text", "p_processor_device_serial" "text", "p_card_brand" "text", "p_card_last4" "text", "p_entry_method" "text", "p_taken_at" timestamp with time zone, "p_payload" "jsonb") IS 'Idempotent. Records a Clover payment Yipyy cannot place, or returns the row that already holds it.';



CREATE TABLE IF NOT EXISTS "public"."yipyy_go_desk_checks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "booking_id" "uuid" NOT NULL,
    "pet_id" "uuid" NOT NULL,
    "source" "text" NOT NULL,
    "medications_confirmed" boolean DEFAULT false NOT NULL,
    "belongings_confirmed" boolean DEFAULT false NOT NULL,
    "requirement" "text",
    "form_status" "text" NOT NULL,
    "form_missing" boolean NOT NULL,
    "override_reason" "text",
    "recorded_by" "text" DEFAULT ("auth"."jwt"() ->> 'sub'::"text"),
    "recorded_by_name" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "yipyy_go_desk_checks_missing_form_says_why" CHECK (((NOT "form_missing") OR ("override_reason" IS NOT NULL))),
    CONSTRAINT "yipyy_go_desk_checks_override_reason_check" CHECK ((("override_reason" IS NULL) OR (("length"("btrim"("override_reason")) >= 1) AND ("length"("btrim"("override_reason")) <= 1000)))),
    CONSTRAINT "yipyy_go_desk_checks_recorded_by_name_check" CHECK ((("recorded_by_name" IS NULL) OR (("length"("recorded_by_name") >= 1) AND ("length"("recorded_by_name") <= 200)))),
    CONSTRAINT "yipyy_go_desk_checks_requirement_check" CHECK ((("requirement" IS NULL) OR ("requirement" = ANY (ARRAY['mandatory'::"text", 'optional'::"text"])))),
    CONSTRAINT "yipyy_go_desk_checks_source_check" CHECK (("source" = ANY (ARRAY['code'::"text", 'search'::"text"])))
);


ALTER TABLE "public"."yipyy_go_desk_checks" OWNER TO "postgres";


COMMENT ON TABLE "public"."yipyy_go_desk_checks" IS 'What the desk confirmed when a dog was checked in from the kiosk: how it was found (code or search), that medications and belongings were gone through, where its pre-arrival form stood — and, when a mandatory form was missing, why it came in anyway. Replaces an in-memory audit array (2026-09-13). The arrival itself is the service''s own check-in.';



CREATE OR REPLACE FUNCTION "public"."record_yipyy_go_desk_check"("p_booking_id" "uuid", "p_pets" "jsonb", "p_source" "text", "p_by_name" "text" DEFAULT NULL::"text") RETURNS SETOF "public"."yipyy_go_desk_checks"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking     public.bookings;
  v_requirement text;
  v_pet         record;
  v_entry       jsonb;
  v_status      text;
  v_missing     boolean;
  v_reason      text;
  v_row         public.yipyy_go_desk_checks;
begin
  select * into v_booking from public.bookings where id = p_booking_id;
  if not found or not private.yipyy_go_may_check_in(v_booking.facility_id, v_booking.service) then
    raise exception 'That booking is not yours to check in.' using errcode = '42501';
  end if;
  if v_booking.status::text in ('cancelled', 'declined', 'no_show', 'completed') then
    raise exception 'This booking is not arriving.' using errcode = '22023';
  end if;
  if p_source is null or p_source not in ('code', 'search') then
    raise exception 'Say how the booking was found.' using errcode = '22023';
  end if;
  if p_pets is null or jsonb_typeof(p_pets) <> 'array'
     or (select count(*) from jsonb_array_elements(p_pets)) <> (
       select count(*) from public.booking_pets bp where bp.booking_id = p_booking_id
     )
     or exists (
       select 1 from public.booking_pets bp
        where bp.booking_id = p_booking_id
          and not exists (
            select 1 from jsonb_array_elements(p_pets) e(value)
             where e.value ->> 'petId' = bp.pet_id::text
          )
     )
  then
    raise exception 'Check in every dog on the booking.' using errcode = '22023';
  end if;

  v_requirement := private.yipyy_go_requirement(v_booking.facility_id, v_booking.service);

  for v_pet in
    select p.id, p.name
      from public.booking_pets bp
      join public.pets p on p.id = bp.pet_id
     where bp.booking_id = p_booking_id
     order by p.name
  loop
    select e.value into v_entry from jsonb_array_elements(p_pets) e(value)
     where e.value ->> 'petId' = v_pet.id::text
     limit 1;

    select coalesce(
      (select y.status from public.yipyy_go_submissions y
        where y.booking_id = p_booking_id and y.pet_id = v_pet.id),
      'not_started') into v_status;
    -- No requirement is not a mandatory one: NULL must not reach form_missing.
    v_missing := coalesce(v_requirement = 'mandatory', false)
                 and v_status not in ('submitted', 'approved', 'completed_by_staff');
    v_reason := nullif(btrim(coalesce(v_entry ->> 'overrideReason', '')), '');

    if v_missing and v_reason is null then
      raise exception 'Say why % is checking in without the form.', v_pet.name
        using errcode = '22023', hint = 'override_reason_required';
    end if;
    if v_reason is not null and length(v_reason) > 1000 then
      raise exception 'Keep the reason under 1,000 characters.' using errcode = '22023';
    end if;

    insert into public.yipyy_go_desk_checks
      (facility_id, booking_id, pet_id, source, medications_confirmed, belongings_confirmed,
       requirement, form_status, form_missing, override_reason, recorded_by_name)
    values
      (v_booking.facility_id, p_booking_id, v_pet.id, p_source,
       coalesce((v_entry ->> 'medicationsConfirmed')::boolean, false),
       coalesce((v_entry ->> 'belongingsConfirmed')::boolean, false),
       v_requirement, v_status, v_missing, case when v_missing then v_reason else null end,
       nullif(left(btrim(coalesce(p_by_name, '')), 200), ''))
    returning * into v_row;

    return next v_row;
  end loop;
end;
$$;


ALTER FUNCTION "public"."record_yipyy_go_desk_check"("p_booking_id" "uuid", "p_pets" "jsonb", "p_source" "text", "p_by_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."redeem_gift_card"("p_code" "text", "p_amount" numeric, "p_booking_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "public"."gift_cards"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_card public.gift_cards%rowtype;
  v_sub  text := (select auth.jwt() ->> 'sub');
begin
  if p_amount is null or p_amount <= 0 then
    raise exception 'A redemption has to take something off the card.'
      using errcode = '22023';
  end if;

  -- ONE query: the permission is part of finding the row. A caller who may not
  -- redeem at that facility gets the same answer as a caller who invented the
  -- code, which is the point — see the header.
  select * into v_card
    from public.gift_cards
   where code = btrim(p_code)
     and private.has_permission(facility_id, 'financial_manage_gift_cards')
   for update;

  if not found then
    raise exception 'No gift card with that code that you can redeem.'
      using errcode = '42501';
  end if;

  -- Status before money. A cancelled card is a decision somebody made and must
  -- not be spendable just because it still has a balance on it.
  if v_card.status = 'cancelled' then
    raise exception 'That gift card was cancelled.' using errcode = '42501';
  end if;

  -- Checked against the DATABASE's clock, not the caller's. Nothing sweeps
  -- expired cards, so `status` still reads `active` on a card that is not - the
  -- same trap `effectiveStatus` exists for on loyalty vouchers.
  if v_card.expires_at is not null and v_card.expires_at <= now() then
    raise exception 'That gift card expired on %.',
      to_char(v_card.expires_at, 'YYYY-MM-DD')
      using errcode = '42501';
  end if;

  -- The negative entry. The trigger holds the row lock, recomputes the balance
  -- and refuses an overdraft with a sentence naming both numbers.
  insert into public.gift_card_transactions (
    gift_card_id, facility_id, kind, amount, balance_after,
    booking_id, note, created_by
  )
  values (
    v_card.id, v_card.facility_id, 'redeemed', -p_amount, 0,
    p_booking_id, p_note, v_sub
  );

  select * into v_card from public.gift_cards where id = v_card.id;
  return v_card;
end;
$$;


ALTER FUNCTION "public"."redeem_gift_card"("p_code" "text", "p_amount" numeric, "p_booking_id" "uuid", "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."redeem_gift_card"("p_code" "text", "p_amount" numeric, "p_booking_id" "uuid", "p_note" "text") IS 'Take an amount off a gift card, as one append-only ledger entry. Finds the card and checks permission in a single query, so a code that does not exist and one at another facility are indistinguishable - a gift card code is a bearer instrument. Refuses cancelled and expired cards against the database clock. anon holds no EXECUTE grant.';



CREATE OR REPLACE FUNCTION "public"."redeem_gift_card_to_credit"("p_code" "text", "p_amount" numeric, "p_client_ref" bigint, "p_note" "text" DEFAULT NULL::"text") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_card    public.gift_cards%rowtype;
  v_client  public.clients%rowtype;
  v_sub     text := (select auth.jwt() ->> 'sub');
  v_author  text;
  v_balance numeric(10, 2);
begin
  if p_amount is null or p_amount <= 0 then
    raise exception 'A redemption has to take something off the card.'
      using errcode = '22023';
  end if;

  select * into v_card
    from public.gift_cards
   where code = btrim(p_code)
     and private.has_permission(facility_id, 'financial_manage_gift_cards')
   for update;

  if not found then
    raise exception 'No gift card with that code that you can redeem.'
      using errcode = '42501';
  end if;

  if v_card.status = 'cancelled' then
    raise exception 'That gift card was cancelled.' using errcode = '42501';
  end if;

  if v_card.expires_at is not null and v_card.expires_at <= now() then
    raise exception 'That gift card expired on %.',
      to_char(v_card.expires_at, 'YYYY-MM-DD')
      using errcode = '42501';
  end if;

  select * into v_client
    from public.clients
   where facility_id = v_card.facility_id
     and ref = p_client_ref;

  if not found then
    raise exception 'No client with that number at this facility.'
      using errcode = '42501';
  end if;

  select full_name into v_author from public.profiles where id = v_sub;

  insert into public.gift_card_transactions (
    gift_card_id, facility_id, kind, amount, balance_after, note, created_by
  )
  values (
    v_card.id, v_card.facility_id, 'redeemed', -p_amount, 0,
    coalesce(nullif(btrim(p_note), ''),
             'Moved to ' || v_client.name || '''s account credit'),
    v_sub
  );

  insert into public.store_credit_entries (
    facility_id, client_id, amount, reason, note, author_name, created_by
  )
  values (
    v_card.facility_id, v_client.id, p_amount, 'gift_card',
    coalesce(nullif(btrim(p_note), ''), 'Gift card ' || v_card.code),
    coalesce(v_author, 'Staff'), v_sub
  );

  select coalesce(balance, 0) into v_balance
    from public.client_store_credit
   where client_id = v_client.id and facility_id = v_card.facility_id;

  return coalesce(v_balance, 0);
end;
$$;


ALTER FUNCTION "public"."redeem_gift_card_to_credit"("p_code" "text", "p_amount" numeric, "p_client_ref" bigint, "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."redeem_gift_card_to_credit"("p_code" "text", "p_amount" numeric, "p_client_ref" bigint, "p_note" "text") IS 'Move value off a gift card onto a customer''s store credit, as two ledger entries in one transaction. Requires financial_manage_gift_cards, checked in the same query that finds the card - and checked EXPLICITLY because a SECURITY DEFINER function bypasses the store-credit insert policy. Returns the account balance afterwards. anon holds no EXECUTE grant.';



CREATE OR REPLACE FUNCTION "public"."redeem_loyalty_points"("p_account_id" "uuid", "p_reward_type" "text", "p_reward_value" numeric, "p_points" integer, "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_applies_to" "text"[] DEFAULT NULL::"text"[], "p_description" "text" DEFAULT NULL::"text") RETURNS "public"."loyalty_vouchers"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_facility uuid;
  v_voucher  public.loyalty_vouchers;
begin
  select a.facility_id into v_facility
    from public.loyalty_accounts a
   where a.id = p_account_id;

  if v_facility is null then
    raise exception 'That loyalty account does not exist.' using errcode = 'P0002';
  end if;

  if not private.has_permission(v_facility, 'marketing_manage_loyalty') then
    raise exception 'You do not have permission to redeem loyalty points.'
      using errcode = '42501';
  end if;

  if p_points < 0 then
    raise exception 'A redemption cannot cost negative points.'
      using errcode = '22023';
  end if;

  if p_points > 0 then
    insert into public.loyalty_transactions
      (facility_id, account_id, kind, points, description, source)
    values
      (v_facility, p_account_id, 'redeemed', -p_points,
       coalesce(p_description, 'Reward redeemed'), 'manual');
  end if;

  insert into public.loyalty_vouchers
    (facility_id, account_id, reward_type, reward_value,
     applies_to_services, points_spent, expires_at)
  values
    (v_facility, p_account_id, p_reward_type, p_reward_value,
     p_applies_to, p_points, p_expires_at)
  returning * into v_voucher;

  if p_reward_type = 'credit_balance' then
    perform set_config('app.loyalty_ledger_write', 'on', true);
    update public.loyalty_accounts
       set credit_balance = credit_balance + p_reward_value,
           updated_at     = now()
     where id = p_account_id;
    perform set_config('app.loyalty_ledger_write', 'off', true);
  end if;

  return v_voucher;
end;
$$;


ALTER FUNCTION "public"."redeem_loyalty_points"("p_account_id" "uuid", "p_reward_type" "text", "p_reward_value" numeric, "p_points" integer, "p_expires_at" timestamp with time zone, "p_applies_to" "text"[], "p_description" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."redeem_loyalty_points"("p_account_id" "uuid", "p_reward_type" "text", "p_reward_value" numeric, "p_points" integer, "p_expires_at" timestamp with time zone, "p_applies_to" "text"[], "p_description" "text") IS 'Spend points on a reward. The ledger entry and the voucher move together; an account that cannot afford it is refused by the balance trigger before any voucher exists.';



CREATE OR REPLACE FUNCTION "public"."redeem_package_pass"("p_customer_package_id" "uuid", "p_service_id" "text", "p_service_label" "text" DEFAULT ''::"text", "p_booking_id" "uuid" DEFAULT NULL::"uuid", "p_pet_id" "uuid" DEFAULT NULL::"uuid", "p_pet_name" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_facility uuid;
  v_expires timestamptz;
  v_remaining integer;
begin
  perform pg_advisory_xact_lock(hashtext(p_customer_package_id::text));

  select cp.facility_id, cp.expires_at into v_facility, v_expires
    from public.customer_packages cp
   where cp.id = p_customer_package_id;

  if v_facility is null then
    raise exception 'That package does not exist, or is not yours.'
      using errcode = 'no_data_found';
  end if;
  if v_expires is not null and v_expires < now() then
    raise exception 'That package has expired.' using errcode = '23514';
  end if;

  select s.passes_remaining into v_remaining
    from public.customer_package_pool_status s
   where s.customer_package_id = p_customer_package_id
     and s.service_id = p_service_id;

  if v_remaining is null then
    raise exception 'That package does not include that service.'
      using errcode = '23514';
  end if;
  if v_remaining <= 0 then
    raise exception 'No passes left for that service.' using errcode = '23514';
  end if;

  insert into public.package_pass_entries
    (facility_id, customer_package_id, service_id, passes, reason,
     booking_id, pet_id, pet_name, service_label)
  values
    (v_facility, p_customer_package_id, p_service_id, -1, 'redeemed',
     p_booking_id, p_pet_id, p_pet_name, coalesce(p_service_label, ''));

  return v_remaining - 1;
end;
$$;


ALTER FUNCTION "public"."redeem_package_pass"("p_customer_package_id" "uuid", "p_service_id" "text", "p_service_label" "text", "p_booking_id" "uuid", "p_pet_id" "uuid", "p_pet_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."redeem_promo_code"("p_booking_id" "uuid", "p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking record;
  v_promo public.promo_codes;
  v_today date;
  v_balance numeric(10, 2);
  v_amount numeric(10, 2);
  v_uses integer;
  v_line uuid;
  v_days jsonb;
begin
  select b.id, b.facility_id, b.client_id, b.service, b.start_at,
         b.amount_due, b.amount_paid, b.status, f.timezone
    into v_booking
    from public.bookings b
    join public.facilities f on f.id = b.facility_id
   where b.id = p_booking_id;
  if not found then
    raise exception 'No such booking.' using hint = 'promo_no_booking';
  end if;
  -- What RLS would have asked of each write, asked here.
  if not private.has_permission(v_booking.facility_id, 'retail_process_sale') then
    raise exception 'Not allowed to take a sale at this facility.'
      using errcode = '42501', hint = 'promo_not_allowed';
  end if;
  if v_booking.status in ('cancelled', 'declined', 'no_show') then
    raise exception 'That booking is closed.' using hint = 'promo_booking_closed';
  end if;

  -- Locked: the usage limit is read and spent in one step.
  select * into v_promo
    from public.promo_codes
   where facility_id = v_booking.facility_id
     and code = upper(btrim(coalesce(p_code, '')))
   for update;
  if not found or not v_promo.is_active then
    raise exception 'No active promo code by that name.' using hint = 'promo_unknown';
  end if;

  v_today := (now() at time zone coalesce(v_booking.timezone, 'America/Toronto'))::date;
  if (v_promo.valid_from is not null and v_today < v_promo.valid_from)
     or (v_promo.valid_until is not null and v_today > v_promo.valid_until) then
    raise exception 'That code is outside its dates.' using hint = 'promo_expired';
  end if;

  if cardinality(v_promo.applies_to) > 0
     and not (lower(v_booking.service) = any (v_promo.applies_to)) then
    raise exception 'That code does not cover this service.' using hint = 'promo_wrong_service';
  end if;

  v_days := v_promo.detail->'specificDays';
  if jsonb_typeof(v_days) = 'array' and jsonb_array_length(v_days) > 0
     and not (v_days ? trim(to_char(
       v_booking.start_at at time zone coalesce(v_booking.timezone, 'America/Toronto'),
       'fmday'))) then
    raise exception 'That code is not valid on this day.' using hint = 'promo_wrong_day';
  end if;

  if v_promo.usage_limit is not null then
    select count(*) into v_uses from public.promo_code_redemptions
     where promo_code_id = v_promo.id;
    if v_uses >= v_promo.usage_limit then
      raise exception 'That code has been used up.' using hint = 'promo_used_up';
    end if;
  end if;

  if v_promo.per_customer_limit is not null then
    select count(*) into v_uses from public.promo_code_redemptions
     where promo_code_id = v_promo.id and client_id = v_booking.client_id;
    if v_uses >= v_promo.per_customer_limit then
      raise exception 'This client has already used that code.' using hint = 'promo_client_limit';
    end if;
  end if;

  if v_promo.first_time_only and exists (
    select 1 from public.bookings o
     where o.client_id = v_booking.client_id
       and o.id <> v_booking.id
       and o.status = 'completed'
  ) then
    raise exception 'That code is for a first visit.' using hint = 'promo_first_time';
  end if;

  if exists (
    select 1 from public.promo_code_redemptions
     where promo_code_id = v_promo.id and booking_id = v_booking.id
  ) then
    raise exception 'That code is already on this bill.' using hint = 'promo_already_applied';
  end if;

  v_balance := greatest(0, coalesce(v_booking.amount_due, 0) - coalesce(v_booking.amount_paid, 0));
  if v_promo.min_purchase is not null and coalesce(v_booking.amount_due, 0) < v_promo.min_purchase then
    raise exception 'The bill is under the code''s minimum.' using hint = 'promo_minimum';
  end if;

  v_amount := case v_promo.discount_type
    when 'percentage' then round(coalesce(v_booking.amount_due, 0) * v_promo.discount_value / 100, 2)
    when 'fixed' then v_promo.discount_value
    else v_balance
  end;
  if v_promo.max_discount is not null then
    v_amount := least(v_amount, v_promo.max_discount);
  end if;
  v_amount := least(v_amount, v_balance);
  if v_amount <= 0 then
    raise exception 'Nothing is left to discount.' using hint = 'promo_nothing_due';
  end if;

  insert into public.booking_line_items
    (booking_id, facility_id, kind, name, unit_price, quantity, source_id)
  values
    (v_booking.id, v_booking.facility_id, 'item', 'Promo code ' || v_promo.code,
     -v_amount, 1, 'promo:' || v_promo.id::text)
  returning id into v_line;

  insert into public.promo_code_redemptions
    (facility_id, promo_code_id, code, client_id, booking_id, line_item_id, amount)
  values
    (v_booking.facility_id, v_promo.id, v_promo.code, v_booking.client_id,
     v_booking.id, v_line, v_amount);

  return jsonb_build_object(
    'code', v_promo.code,
    'amount', v_amount,
    'lineItemId', v_line
  );
end;
$$;


ALTER FUNCTION "public"."redeem_promo_code"("p_booking_id" "uuid", "p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_client"("p_facility_slug" "text", "p_name" "text", "p_phone" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id  text := (select auth.jwt()->>'sub');
  v_email    text;
  v_facility uuid;
  v_open     boolean;
  v_client   uuid;
begin
  if v_user_id is null then
    raise exception 'You must be signed in to register.' using errcode = '42501';
  end if;

  select p.email into v_email from public.profiles p where p.id = v_user_id;
  if v_email is null then
    raise exception 'Your account has no verified email address yet.'
      using errcode = '22023';
  end if;

  select f.id, f.allow_customer_signup into v_facility, v_open
    from public.facilities f where f.slug = lower(trim(p_facility_slug));
  if v_facility is null then
    raise exception 'No such facility.' using errcode = 'no_data_found';
  end if;

  v_client := private.link_client_at(v_facility);
  if v_client is not null then
    return v_client;
  end if;

  if not v_open then
    raise exception 'This facility does not accept online registration.'
      using errcode = '42501';
  end if;

  insert into public.clients (facility_id, profile_id, name, email, phone, status, details)
  values (
    v_facility,
    v_user_id,
    coalesce(nullif(trim(p_name), ''), split_part(v_email, '@', 1)),
    lower(trim(v_email)),
    nullif(trim(coalesce(p_phone, '')), ''),
    'active',
    '{}'::jsonb
  )
  returning id into v_client;

  return v_client;
end;
$$;


ALTER FUNCTION "public"."register_client"("p_facility_slug" "text", "p_name" "text", "p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_loyalty_voucher"("p_voucher_id" "uuid") RETURNS "public"."loyalty_vouchers"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_facility uuid;
  v_voucher  public.loyalty_vouchers;
begin
  select v.facility_id into v_facility
    from public.loyalty_vouchers v
   where v.id = p_voucher_id;

  if v_facility is null then
    raise exception 'That reward does not exist.' using errcode = 'P0002';
  end if;

  -- The same pair that may spend one. Whoever can take the payment can undo
  -- the reward the failed payment consumed.
  if not (private.has_permission(v_facility, 'take_payment')
          or private.has_permission(v_facility, 'marketing_manage_loyalty')) then
    raise exception 'You do not have permission to return a reward.'
      using errcode = '42501';
  end if;

  update public.loyalty_vouchers v
     set status             = 'active',
         used_at            = null,
         used_on_booking_id = null
   where v.id = p_voucher_id
     and v.status = 'used'
  returning * into v_voucher;

  -- Nothing matched: it was already active, or expired, or cancelled. None of
  -- those is a failure to report — the caller wanted the customer to be holding
  -- their reward, and in every one of those cases the caller is not the reason
  -- they are not.
  if v_voucher.id is null then
    select * into v_voucher from public.loyalty_vouchers where id = p_voucher_id;
  end if;

  return v_voucher;
end;
$$;


ALTER FUNCTION "public"."release_loyalty_voucher"("p_voucher_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."release_loyalty_voucher"("p_voucher_id" "uuid") IS 'Return a voucher consumed for a payment that then failed. Only undoes `used` — never an expiry or a cancellation — and is safe to call twice.';



CREATE OR REPLACE FUNCTION "public"."reply_to_report_card"("p_card_id" "uuid", "p_message" "text") RETURNS "public"."report_cards"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_card public.report_cards;
begin
  if coalesce(btrim(p_message), '') = '' then
    raise exception 'A reply cannot be empty.' using errcode = '22023';
  end if;

  update public.report_cards
     set reply_message = p_message,
         replied_at    = now(),
         updated_at    = now()
   where id = p_card_id
     and client_id in (select private.own_client_ids())
     and delivery_status = 'sent'
  returning * into v_card;

  if v_card.id is null then
    raise exception 'That report card is not yours to reply to.' using errcode = '42501';
  end if;

  return v_card;
end;
$$;


ALTER FUNCTION "public"."reply_to_report_card"("p_card_id" "uuid", "p_message" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reply_to_report_card"("p_card_id" "uuid", "p_message" "text") IS 'Record the owner''s reply to a sent card they own. anon holds no EXECUTE grant.';



CREATE OR REPLACE FUNCTION "public"."reputation_metrics"("p_facility_id" "uuid", "p_from" "date", "p_to" "date", "p_location_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
with scoped as (
  select r.*
    from public.review_requests r
   where r.facility_id = p_facility_id
     and r.created_at >= p_from::timestamptz
     and r.created_at < (p_to + 1)::timestamptz
     -- NULL means every location, never "no locations". An empty array meaning
     -- none would silently blank every card the day somebody cleared the last
     -- chip on the scope selector.
     and (p_location_ids is null or r.location_id = any (p_location_ids))
),
asked as (
  -- The initial ask only. Nudges and backups are excluded so the number is not
  -- inflated by retries -- "requests sent" must mean people asked, not
  -- messages emitted.
  select s.source_id, min(s.sent_at) as sent_at
    from public.message_sends s
    join scoped r on r.id = s.source_id
   where s.source_kind = 'review_request'
     and s.step_index = 0
     and s.status = 'sent'
   group by s.source_id
),
nudged as (
  select s.source_id, min(s.sent_at) as sent_at
    from public.message_sends s
    join scoped r on r.id = s.source_id
   where s.source_kind = 'review_request'
     and s.step_index = 1
     and s.status = 'sent'
   group by s.source_id
),
answers as (
  select resp.*, r.escalation_threshold, r.id as request_id_key
    from public.review_responses resp
    join scoped r on r.id = resp.request_id
),
counts as (
  select
    (select count(*) from scoped)                                   as visits,
    (select count(*) from asked)                                    as sent,
    (select count(*) from nudged)                                   as nudges,
    (select count(*) from scoped where state = 'suppressed')        as suppressed,
    (select count(*) from answers)                                  as responses,
    (select count(*) from answers where rating = 5)                 as five_star,
    (select count(*) from answers where rating >= 4)                as positive,
    (select count(*) from answers where rating = 3)                 as neutral,
    (select count(*) from answers where rating <= 2)                as negative,
    (select count(*) from answers
      where rating <= escalation_threshold)                         as detractors,
    (select count(*) from answers where public_clicked_at is not null) as clicked,
    (select count(*) from answers a
       join nudged n on n.source_id = a.request_id_key
      where a.submitted_at > n.sent_at)                             as after_nudge,
    (select coalesce(sum(rating), 0) from answers)                  as rating_sum
)
select jsonb_build_object(
  'scope', jsonb_build_object(
    'facilityId', p_facility_id,
    'locationIds', p_location_ids,
    'from', p_from,
    'to', p_to),

  -- Each metric is {value, numerator, denominator}. `value` is null rather
  -- than 0 when the denominator is 0: "0% of nobody responded" is a false
  -- statement, and a card showing 0% reads as a failure rather than as no data.
  'requestsSent', jsonb_build_object(
    'value', sent, 'numerator', sent, 'denominator', null,
    'definition', 'initial sends that the provider accepted; excludes nudges'),

  'responseRate', jsonb_build_object(
    'value', case when sent > 0 then round(responses::numeric / sent, 4) end,
    'numerator', responses, 'denominator', sent,
    'definition', 'responses per initial send; not per DELIVERED - see the header'),

  'averageRating', jsonb_build_object(
    'value', case when responses > 0
                  then round(rating_sum::numeric / responses, 2) end,
    'numerator', rating_sum, 'denominator', responses,
    'definition', 'count-weighted, rounded once; never an average of averages'),

  'fiveStarShare', jsonb_build_object(
    'value', case when responses > 0
                  then round(five_star::numeric / responses, 4) end,
    'numerator', five_star, 'denominator', responses,
    'definition', 'responses rating exactly 5'),

  'detractorRate', jsonb_build_object(
    'value', case when responses > 0
                  then round(detractors::numeric / responses, 4) end,
    'numerator', detractors, 'denominator', responses,
    'definition', 'rating <= the escalation threshold in force when asked'),

  'publicClickRate', jsonb_build_object(
    'value', case when responses > 0
                  then round(clicked::numeric / responses, 4) end,
    'numerator', clicked, 'denominator', responses,
    'definition', 'responses that followed a public link; was "public conversions"'),

  'nudgeRecovery', jsonb_build_object(
    'value', case when nudges > 0
                  then round(after_nudge::numeric / nudges, 4) end,
    'numerator', after_nudge, 'denominator', nudges,
    'definition', 'responses arriving after a nudge, per nudge sent'),

  'suppressionRate', jsonb_build_object(
    'value', case when visits > 0
                  then round(suppressed::numeric / visits, 4) end,
    'numerator', suppressed, 'denominator', visits,
    'definition', 'visits considered but not asked; the answer to "why only 312 of 480"'),

  -- THE THREE BUCKETS SUM TO THE RESPONSE COUNT, BY CONSTRUCTION. They are
  -- three ranges over one column with no gap and no overlap, which is what the
  -- shipped screens could not manage: Emma had 84 + 1 = 85 against 87 reviews.
  'sentiment', jsonb_build_object(
    'positive', positive, 'neutral', neutral, 'negative', negative,
    'total', responses,
    'definition', 'positive >= 4, neutral = 3, negative <= 2; sums to total')
)
from counts;
$$;


ALTER FUNCTION "public"."reputation_metrics"("p_facility_id" "uuid", "p_from" "date", "p_to" "date", "p_location_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reputation_metrics"("p_facility_id" "uuid", "p_from" "date", "p_to" "date", "p_location_ids" "uuid"[]) IS 'The metric dictionary, as one query. Every metric carries its numerator and denominator; see the header of 20260829140000 for why delivery rate is absent.';



CREATE OR REPLACE FUNCTION "public"."reputation_service_stats"("p_facility_id" "uuid", "p_from" "date", "p_to" "date", "p_location_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("service_type" "text", "requests" bigint, "responses" bigint, "average_rating" numeric, "detractors" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
with scoped as (
  select r.*
    from public.review_requests r
   where r.facility_id = p_facility_id
     and r.created_at >= p_from::timestamptz
     and r.created_at < (p_to + 1)::timestamptz
     and (p_location_ids is null or r.location_id = any (p_location_ids))
),
exploded as (
  select unnest(
           case when cardinality(r.service_types) = 0
                then array['unknown']::text[]
                else r.service_types end) as service_type,
         r.id, r.escalation_threshold
    from scoped r
)
select
  e.service_type,
  count(distinct e.id),
  count(resp.id),
  case when count(resp.id) > 0
       then round(sum(resp.rating)::numeric / count(resp.id), 2) end,
  count(*) filter (where resp.rating <= e.escalation_threshold)
from exploded e
left join public.review_responses resp on resp.request_id = e.id
group by e.service_type
order by count(distinct e.id) desc;
$$;


ALTER FUNCTION "public"."reputation_service_stats"("p_facility_id" "uuid", "p_from" "date", "p_to" "date", "p_location_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reputation_service_stats"("p_facility_id" "uuid", "p_from" "date", "p_to" "date", "p_location_ids" "uuid"[]) IS 'Per service. A multi-service visit is counted under each of its services, so these do NOT sum to the visit count.';



CREATE OR REPLACE FUNCTION "public"."reputation_staff_stats"("p_facility_id" "uuid", "p_from" "date", "p_to" "date", "p_location_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("staff_id" "uuid", "staff_name" "text", "reviews" bigint, "mentions" bigint, "rating_sum" bigint, "average_rating" numeric, "detractors" bigint, "praise" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
with scoped as (
  select r.*
    from public.review_requests r
   where r.facility_id = p_facility_id
     and r.created_at >= p_from::timestamptz
     and r.created_at < (p_to + 1)::timestamptz
     and (p_location_ids is null or r.location_id = any (p_location_ids))
),
answers as (
  select resp.*, r.escalation_threshold, r.staff_on_visit
    from public.review_responses resp
    join scoped r on r.id = resp.request_id
)
select
  s.id,
  s.first_name || ' ' || s.last_name,
  count(*) filter (where a.attributed_staff_id = s.id),
  (select count(*) from answers m where s.id = any (m.staff_on_visit)),
  coalesce(sum(a.rating) filter (where a.attributed_staff_id = s.id), 0)::bigint,
  case
    when count(*) filter (where a.attributed_staff_id = s.id) > 0
    then round(
      sum(a.rating) filter (where a.attributed_staff_id = s.id)::numeric
      / count(*) filter (where a.attributed_staff_id = s.id), 2)
  end,
  count(*) filter (
    where a.attributed_staff_id = s.id
      and a.rating <= a.escalation_threshold),
  -- X-12: the "Praise" column existed on the shipped screen with no tag
  -- catalogue anywhere behind it. This is the number it was pretending to be.
  (select count(*)
     from public.review_response_tags rt
     join public.review_tags t on t.id = rt.tag_id
     join answers pa on pa.id = rt.response_id
    where t.polarity = 'positive'
      and pa.attributed_staff_id = s.id)
from public.staff s
left join answers a on a.attributed_staff_id = s.id
where s.facility_id = p_facility_id
group by s.id, s.first_name, s.last_name
having count(*) filter (where a.attributed_staff_id = s.id) > 0
    or (select count(*) from answers m where s.id = any (m.staff_on_visit)) > 0
order by count(*) filter (where a.attributed_staff_id = s.id) desc;
$$;


ALTER FUNCTION "public"."reputation_staff_stats"("p_facility_id" "uuid", "p_from" "date", "p_to" "date", "p_location_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reputation_staff_stats"("p_facility_id" "uuid", "p_from" "date", "p_to" "date", "p_location_ids" "uuid"[]) IS 'Per staff. `reviews` is single-valued and SUMS to the response total; `mentions` may exceed it and must be labelled separately (D-03).';



CREATE OR REPLACE FUNCTION "public"."request_training_makeup"("p_missed_booking_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "public"."training_makeups"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_missed record;
  v_row    public.training_makeups;
begin
  select * into v_missed from private.training_missed_booking(p_missed_booking_id);
  -- One refusal for "no such missed session" and "not yours".
  if not found or private.training_makeup_actor(v_missed.facility_id, v_missed.client_id) is null then
    raise exception 'That missed session is not yours to make up.' using errcode = '42501';
  end if;

  select * into v_row from public.training_makeups
   where missed_booking_id = p_missed_booking_id
   for update;
  if found then
    if v_row.status = 'requested' then
      return v_row;
    elsif v_row.status = 'offered' then
      raise exception 'A seat is already booked for this make-up.' using errcode = '22023';
    elsif v_row.status = 'ineligible' then
      raise exception 'The facility has decided there is no make-up for this session.' using errcode = '22023';
    end if;
  end if;

  insert into public.training_makeups
    (facility_id, missed_booking_id, missed_session_id, pet_id, client_id,
     status, owner_note, requested_at)
  values
    (v_missed.facility_id, p_missed_booking_id, v_missed.session_id, v_missed.pet_id,
     v_missed.client_id, 'requested', nullif(btrim(coalesce(p_note, '')), ''), now())
  on conflict (missed_booking_id) do update
     set status = 'requested',
         owner_note = excluded.owner_note,
         requested_at = excluded.requested_at,
         answered_at = null,
         updated_at = now()
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."request_training_makeup"("p_missed_booking_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_facility_modules"("p_facility_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_count integer;
begin
  if not private.is_platform_admin() then
    raise exception 'Only the platform team can change what a facility is sold.'
      using errcode = '42501';
  end if;

  delete from public.facility_modules fm where fm.facility_id = p_facility_id;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


