CREATE OR REPLACE FUNCTION "public"."resolve_yipyy_go_check_in_pass"("p_token" "text") RETURNS TABLE("booking_id" "uuid", "booking_ref" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_token is null or length(p_token) < 16 or length(p_token) > 128 then
    return;
  end if;

  return query
    select b.id, b.ref
      from public.yipyy_go_check_in_passes cp
      join public.bookings b on b.id = cp.booking_id
     where cp.token_hash = private.hash_check_in_token(p_token)
       and cp.token_expires_at > now()
       and b.status::text not in ('cancelled', 'declined', 'no_show', 'completed')
       and private.yipyy_go_may_check_in(b.facility_id, b.service);
end;
$$;


ALTER FUNCTION "public"."resolve_yipyy_go_check_in_pass"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_to_estimate"("p_estimate_id" "uuid", "p_action" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_est public.estimates;
  v_allow boolean;
  v_actor text;
begin
  if p_action not in ('view', 'accept', 'decline') then
    raise exception 'An estimate is viewed, accepted or declined.' using errcode = '22023';
  end if;

  select * into v_est from public.estimates
   where id = p_estimate_id
     and client_id in (select private.own_client_ids())
   for update;
  if not found then
    raise exception 'No such estimate.' using errcode = '42501';
  end if;

  select coalesce(p.full_name, p.email) into v_actor
    from public.profiles p where p.id = (select auth.jwt()->>'sub');

  if p_action = 'view' then
    if v_est.viewed_at is null and v_est.status = 'sent' then
      update public.estimates
         set viewed_at = now(),
             activity_log = activity_log || jsonb_build_array(jsonb_build_object(
               'at', now(), 'type', 'viewed', 'actor', coalesce(v_actor, 'Customer')))
       where id = v_est.id;
    end if;
    return jsonb_build_object('status', v_est.status);
  end if;

  if v_est.status <> 'sent' then
    raise exception 'This estimate is no longer open.' using errcode = '22023';
  end if;
  if v_est.expires_at is not null and v_est.expires_at <= now() then
    raise exception 'This estimate has expired.' using errcode = '22023';
  end if;

  if p_action = 'accept' then
    select coalesce((value->>'allowCustomerAcceptance')::boolean, true) into v_allow
      from public.facility_settings
     where facility_id = v_est.facility_id and domain = 'estimate_settings';
    if coalesce(v_allow, true) is false then
      raise exception 'This business accepts estimates by phone or at the desk.'
        using errcode = '42501';
    end if;
    update public.estimates
       set status = 'accepted', accepted_at = now(), accepted_by = v_actor,
           accepted_on_behalf = false,
           activity_log = activity_log || jsonb_build_array(jsonb_build_object(
             'at', now(), 'type', 'accepted', 'actor', coalesce(v_actor, 'Customer')))
     where id = v_est.id;
    return jsonb_build_object('status', 'accepted');
  end if;

  update public.estimates
     set status = 'declined', declined_at = now(),
         decline_reason = nullif(btrim(coalesce(p_reason, '')), ''),
         activity_log = activity_log || jsonb_build_array(jsonb_build_object(
           'at', now(), 'type', 'declined', 'actor', coalesce(v_actor, 'Customer'),
           'detail', nullif(btrim(coalesce(p_reason, '')), '')))
   where id = v_est.id;
  return jsonb_build_object('status', 'declined');
end;
$$;


ALTER FUNCTION "public"."respond_to_estimate"("p_estimate_id" "uuid", "p_action" "text", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."respond_to_estimate"("p_estimate_id" "uuid", "p_action" "text", "p_reason" "text") IS 'A signed-in customer views, accepts or declines their own sent estimate. Changes status and the log only.';



CREATE OR REPLACE FUNCTION "public"."reverse_package_pass"("p_ref" bigint, "p_note" "text" DEFAULT ''::"text") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_booking   uuid;
  v_entry     public.package_pass_entries;
  v_redeemed  integer;
  v_reversed  integer;
  v_remaining integer;
begin
  select b.id into v_booking from public.bookings b where b.ref = p_ref;
  if v_booking is null then
    raise exception 'No such booking.' using errcode = 'P0002';
  end if;

  -- The pass this booking spent. Newest first, because a booking that somehow
  -- spent two gives back the most recent one first.
  select e.* into v_entry
    from public.package_pass_entries e
   where e.booking_id = v_booking
     and e.reason = 'redeemed'
   order by e.created_at desc
   limit 1;

  -- Nothing was spent on this booking, so there is nothing to return. Null
  -- rather than an exception: "this booking used no pass" is an ordinary
  -- answer at a cancellation, not a failure.
  if not found then
    return null;
  end if;

  perform pg_advisory_xact_lock(hashtext(v_entry.customer_package_id::text));

  select
    count(*) filter (where e.reason = 'redeemed'),
    count(*) filter (where e.reason = 'reversed')
    into v_redeemed, v_reversed
    from public.package_pass_entries e
   where e.booking_id = v_booking
     and e.service_id = v_entry.service_id
     and e.customer_package_id = v_entry.customer_package_id;

  -- Already given back. Idempotent by counting, so a repeated cancel, a
  -- retried request and a double click all do the same nothing.
  if v_reversed >= v_redeemed then
    return null;
  end if;

  insert into public.package_pass_entries
    (facility_id, customer_package_id, service_id, passes, reason,
     booking_id, pet_id, pet_name, service_label, note)
  values
    (v_entry.facility_id, v_entry.customer_package_id, v_entry.service_id,
     1, 'reversed', v_booking, v_entry.pet_id, v_entry.pet_name,
     v_entry.service_label, left(coalesce(p_note, ''), 500));

  select s.passes_remaining into v_remaining
    from public.customer_package_pool_status s
   where s.customer_package_id = v_entry.customer_package_id
     and s.service_id = v_entry.service_id;

  return v_remaining;
end;
$$;


ALTER FUNCTION "public"."reverse_package_pass"("p_ref" bigint, "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reverse_package_pass"("p_ref" bigint, "p_note" "text") IS 'Give back the pass a booking spent. Null when it spent none, or when one was already returned.';



CREATE OR REPLACE FUNCTION "public"."review_request_by_token"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v jsonb;
begin
  -- Cheap guard before touching the index: a short or absent token is not a
  -- token, and answering instantly costs a guesser nothing to discover.
  if p_token is null or length(p_token) < 16 then
    return null;
  end if;

  select jsonb_build_object(
      'requestId',    r.id,
      'facilityName', f.name,
      'facilitySlug', f.slug,
      'locale',       coalesce(c.preferred_language, 'en'),
      'clientFirstName', split_part(c.name, ' ', 1),
      'serviceTypes', r.service_types,
      'petNames',     coalesce(
        (select array_agg(p.name order by p.name)
           from public.pets p
          where p.id = any (
            select distinct (b.details->>'petId')::uuid
              from public.bookings b
             where b.id = any (r.booking_ids)
               and b.details->>'petId' is not null)),
        '{}'::text[]),
      -- Whether it has been answered. The survey shows a read-only state
      -- rather than a second rating box.
      'answered',     (resp.id is not null),
      'rating',       resp.rating,
      -- The public destinations, in the facility's own priority order and
      -- WITHOUT anything monitor-only. Yelp cannot appear here even if a
      -- facility enabled it: the constraint on the table forbids it.
      'channels',     coalesce(
        (select jsonb_agg(jsonb_build_object(
                  'id', ch.id, 'platform', ch.platform, 'weight', ch.weight)
                  order by ch.priority, ch.platform)
           from public.review_channels ch
          where ch.facility_id = r.facility_id
            and (ch.location_id is null or ch.location_id = r.location_id)
            and ch.enabled
            and ch.solicitable
            and (ch.place_id is not null or ch.profile_url is not null)),
        '[]'::jsonb),
      -- The tags offered depend on the rating the client picks, so both halves
      -- are sent and the page chooses. One round trip, no second call that
      -- could leak which rating somebody was about to give.
      'tags',         coalesce(
        (select jsonb_agg(jsonb_build_object(
                  'id', t.id, 'polarity', t.polarity,
                  'serviceType', t.service_type, 'labels', t.labels)
                  order by t.polarity, t.sort_order)
           from public.review_tags t
          where t.facility_id = r.facility_id
            and t.is_active
            and (r.service_types = '{}' or t.service_type = any (r.service_types))),
        '[]'::jsonb)
    )
    into v
    from public.review_requests r
    join public.facilities f on f.id = r.facility_id
    join public.clients    c on c.id = r.client_id
    left join public.review_responses resp on resp.request_id = r.id
   where r.token_hash = private.hash_review_token(p_token)
     and r.token_expires_at > now()
     and r.state not in ('suppressed', 'cancelled', 'expired');

  return v;
end;
$$;


ALTER FUNCTION "public"."review_request_by_token"("p_token" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."review_request_by_token"("p_token" "text") IS 'The survey page, by link token. Returns null for every kind of failure so a guesser cannot tell them apart.';



CREATE OR REPLACE FUNCTION "public"."review_yipyy_go_submission"("p_submission_id" "uuid", "p_action" "text", "p_message" "text" DEFAULT NULL::"text", "p_by_name" "text" DEFAULT NULL::"text") RETURNS "public"."yipyy_go_submissions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.yipyy_go_submissions;
begin
  select * into v_row from public.yipyy_go_submissions where id = p_submission_id for update;
  if not found or not private.has_permission(v_row.facility_id, 'edit_bookings') then
    raise exception 'That form is not yours to review.' using errcode = '42501';
  end if;

  if p_action = 'approve' then
    if v_row.status <> 'submitted' then
      raise exception 'Only a sent form can be approved.' using errcode = '22023';
    end if;
    update public.yipyy_go_submissions
       set status = 'approved',
           reviewed_at = now(),
           reviewed_by_name = nullif(left(btrim(coalesce(p_by_name, '')), 200), '')
     where id = p_submission_id
    returning * into v_row;
  elsif p_action = 'request_changes' then
    if v_row.status not in ('submitted', 'approved') then
      raise exception 'Only a sent form can be sent back.' using errcode = '22023';
    end if;
    if p_message is null or length(btrim(p_message)) not between 1 and 1000 then
      raise exception 'Say what needs changing.' using errcode = '22023';
    end if;
    update public.yipyy_go_submissions
       set status = 'changes_requested',
           changes_message = btrim(p_message),
           reviewed_at = now(),
           reviewed_by_name = nullif(left(btrim(coalesce(p_by_name, '')), 200), '')
     where id = p_submission_id
    returning * into v_row;
  else
    raise exception 'That is not a review action.' using errcode = '22023';
  end if;

  -- Approval puts a staff-approved form's charges on the bill; sending a form
  -- back takes them off until it is sent again.
  perform private.yipyy_go_write_charges(v_row.booking_id);

  return v_row;
end;
$$;


ALTER FUNCTION "public"."review_yipyy_go_submission"("p_submission_id" "uuid", "p_action" "text", "p_message" "text", "p_by_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_facility_owner_invite"("p_facility_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_grant    public.facility_membership_grants;
  v_staff_id uuid;
begin
  if not private.is_platform_admin() then
    raise exception 'Only a platform administrator may withdraw an invitation.'
      using errcode = '42501';
  end if;

  select g.* into v_grant
    from public.facility_membership_grants g
    join public.staff s on s.id = g.staff_id
   where g.facility_id = p_facility_id
     and s.primary_role = 'owner'
   order by g.created_at
   limit 1;

  if v_grant.id is null then
    raise exception 'There is no owner invitation to withdraw.'
      using errcode = 'no_data_found';
  end if;

  if v_grant.claimed_at is not null then
    raise exception 'That invitation has already been accepted. Remove the membership instead.'
      using errcode = '42501';
  end if;

  v_staff_id := v_grant.staff_id;
  delete from public.facility_membership_grants where id = v_grant.id;

  update public.staff
     set status            = 'inactive',
         status_changed_at = now()
   where id = v_staff_id;

  return jsonb_build_object(
    'revoked',    true,
    'staffId',    v_staff_id,
    'email',      v_grant.email,
    'facilityId', p_facility_id);
end;
$$;


ALTER FUNCTION "public"."revoke_facility_owner_invite"("p_facility_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_payment_connection"("p_facility_id" "uuid", "p_reason" "text", "p_processor" "text" DEFAULT 'clover'::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_changed integer;
begin
  update public.payment_connections
     set status     = 'revoked',
         revoked_at = coalesce(revoked_at, now()),
         last_error = p_reason,
         updated_at = now()
   where facility_id = p_facility_id
     and processor = p_processor
     and status is distinct from 'revoked';

  get diagnostics v_changed = row_count;
  return v_changed > 0;
end;
$$;


ALTER FUNCTION "public"."revoke_payment_connection"("p_facility_id" "uuid", "p_reason" "text", "p_processor" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_platform_invitation"("p_invitation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.has_platform_role('superadmin') then
    raise exception 'Only a superadmin may revoke a platform invitation.'
      using errcode = '42501';
  end if;

  delete from public.platform_invitations
   where id = p_invitation_id and accepted_at is null;

  if not found then
    raise exception 'No pending invitation with that id.'
      using errcode = 'no_data_found';
  end if;

  return jsonb_build_object('invitationId', p_invitation_id, 'revoked', true);
end;
$$;


ALTER FUNCTION "public"."revoke_platform_invitation"("p_invitation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_platform_role"("p_profile_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_role public.platform_role;
begin
  if not private.has_platform_role('superadmin') then
    raise exception 'Only a superadmin may change platform roles.' using errcode = '42501';
  end if;

  select role into v_role from public.platform_memberships where profile_id = p_profile_id;
  if v_role is null then
    raise exception 'That person is not on the platform team.' using errcode = 'no_data_found';
  end if;

  -- Guards the person being REMOVED, not the caller. The self-revoke version
  -- happened to hold the same invariant — only a superadmin can call this, so
  -- they are always one of the remaining ones — but it stated a smaller rule
  -- than it meant, and the smaller rule is the one somebody edits later.
  --
  -- A platform with nobody who can grant roles is unrecoverable without direct
  -- database access, and the moment somebody reaches for this is the moment
  -- they are tidying up.
  if v_role = 'superadmin'
     and (select count(*) from public.platform_memberships where role = 'superadmin') <= 1 then
    raise exception 'That is the last superadmin. Promote somebody else first.'
      using errcode = '42501';
  end if;

  delete from public.platform_memberships where profile_id = p_profile_id;
  return jsonb_build_object('profileId', p_profile_id, 'revoked', true);
end;
$$;


ALTER FUNCTION "public"."revoke_platform_role"("p_profile_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_checkout_cut_off"("p_facility_id" "uuid", "p_enabled" boolean, "p_time" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_cut      jsonb;
  r          record;
  v_after    timestamptz;
  v_held     integer := 0;
  v_released integer := 0;
  v_conflicts jsonb := '[]'::jsonb;
begin
  if not (private.is_facility_admin(p_facility_id)
          and private.has_permission(p_facility_id, 'settings_general')) then
    raise exception 'You do not have permission to change lodging settings.'
      using errcode = '42501';
  end if;

  if p_time is not null
     and p_time !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
    raise exception 'The cut-off time must be HH:MM on a 24-hour clock.'
      using errcode = '22023';
  end if;
  if coalesce(p_enabled, false) and p_time is null then
    raise exception 'A cut-off that is on needs a time.'
      using errcode = '22023';
  end if;

  v_cut := jsonb_build_object('enabled', coalesce(p_enabled, false))
        || case when p_time is null then '{}'::jsonb
                else jsonb_build_object('time', p_time) end;

  insert into public.facility_settings (facility_id, domain, value)
  values (p_facility_id, 'lodging_config', jsonb_build_object('checkoutCutOff', v_cut))
  on conflict (facility_id, domain) do update
     set value = jsonb_set(
           coalesce(public.facility_settings.value, '{}'::jsonb),
           '{checkoutCutOff}',
           v_cut);

  set constraints public.boarding_stays_area_within_capacity immediate;

  -- The LAST stay of every booking still to leave: the only one the cut-off
  -- decides. Its lower bound is a transfer or the arrival, and stays put.
  for r in
    select s.id,
           lower(s.occupies) as lower_now,
           upper(s.occupies) as upper_before,
           b.end_at,
           b.ref
      from public.boarding_stays s
      join public.bookings b on b.id = s.booking_id
      left join public.boarding_stays first
        on first.booking_id = s.booking_id and first.segment_order = 1
     where s.facility_id = p_facility_id
       and s.released_at is null
       and first.checked_out_at is null
       and b.start_at is not null
       and b.end_at is not null
       and b.end_at > now()
       and s.segment_order = (select max(x.segment_order) from public.boarding_stays x
                               where x.booking_id = s.booking_id)
     order by b.start_at, b.ref
  loop
    begin
      update public.boarding_stays
         set occupies = tstzrange(r.lower_now, r.end_at, '[)'),
             updated_at = now()
       where id = r.id
      returning upper(occupies) into v_after;

      if v_after > r.upper_before then
        v_held := v_held + 1;
      elsif v_after < r.upper_before then
        v_released := v_released + 1;
      end if;
    exception
      when exclusion_violation or check_violation then
        v_conflicts := v_conflicts || to_jsonb(r.ref);
    end;
  end loop;

  return jsonb_build_object(
    'held', v_held,
    'released', v_released,
    'conflicts', v_conflicts);
end;
$_$;


ALTER FUNCTION "public"."save_checkout_cut_off"("p_facility_id" "uuid", "p_enabled" boolean, "p_time" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_checkout_cut_off"("p_facility_id" "uuid", "p_enabled" boolean, "p_time" "text") IS 'Saves lodging_config.checkoutCutOff and re-derives every upcoming stay from its booking so the cut-off applies to stays already booked. Returns {held, released, conflicts[booking refs]}; a stay that would collide is left as it was. Facility admins with settings_general only. See 20260925120000.';



CREATE OR REPLACE FUNCTION "public"."save_my_notification_preferences"("p_facility_id" "uuid", "p_in_app" "jsonb", "p_email" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_membership public.facility_memberships;
begin
  select * into v_membership
    from public.facility_memberships m
   where m.facility_id = p_facility_id
     and m.is_active
     and m.profile_id = (select auth.jwt()->>'sub')
   limit 1;
  if not found then
    raise exception 'You are not a member of this facility.' using errcode = '42501';
  end if;

  insert into public.staff_notification_preferences
    (membership_id, facility_id, profile_id, in_app, email, updated_at)
  values (
    v_membership.id, v_membership.facility_id, v_membership.profile_id,
    private.clean_notification_switches(p_in_app),
    private.clean_notification_switches(p_email),
    now()
  )
  on conflict (membership_id) do update
     set in_app = excluded.in_app,
         email = excluded.email,
         updated_at = now();
end;
$$;


ALTER FUNCTION "public"."save_my_notification_preferences"("p_facility_id" "uuid", "p_in_app" "jsonb", "p_email" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_onboarding_section"("p_token" "text", "p_task_key" "text", "p_section_type" "text", "p_data" "jsonb", "p_status" "text" DEFAULT 'in_progress'::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_instance uuid;
begin
  if p_status not in ('not_started', 'in_progress', 'complete') then
    return false;
  end if;
  select i.id into v_instance
    from public.onboarding_instances i
    join public.staff s on s.id = i.staff_id
   where i.token_hash = private.hash_onboarding_token(p_token)
     and i.token_expires_at > now() and i.submitted_at is null and s.status = 'invited';
  if v_instance is null then return false; end if;
  insert into public.onboarding_sections
    (instance_id, task_key, section_type, status, data, completed_at)
  values (v_instance, p_task_key, p_section_type, p_status,
          coalesce(p_data, '{}'::jsonb),
          case when p_status = 'complete' then now() else null end)
  on conflict (instance_id, task_key) do update
    set data = public.onboarding_sections.data || excluded.data,
        status = excluded.status,
        section_type = excluded.section_type,
        completed_at = case when excluded.status = 'complete'
                         then coalesce(public.onboarding_sections.completed_at, now())
                         else public.onboarding_sections.completed_at end;
  return true;
end;
$$;


ALTER FUNCTION "public"."save_onboarding_section"("p_token" "text", "p_task_key" "text", "p_section_type" "text", "p_data" "jsonb", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_yipyy_go_draft"("p_booking_id" "uuid", "p_pet_id" "uuid", "p_answers" "jsonb", "p_add_on_requests" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "public"."yipyy_go_submissions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings;
  v_status  text;
  v_row     public.yipyy_go_submissions;
begin
  select * into v_booking from public.bookings where id = p_booking_id;
  if not found
     or not private.yipyy_go_is_owner(v_booking.client_id)
     or not exists (
       select 1 from public.booking_pets bp where bp.booking_id = p_booking_id and bp.pet_id = p_pet_id
     )
  then
    raise exception 'That booking is not yours.' using errcode = '42501';
  end if;

  if private.yipyy_go_requirement(v_booking.facility_id, v_booking.service) is null then
    raise exception 'This booking does not ask for a pre-arrival form.' using errcode = '22023';
  end if;

  select status into v_status from public.yipyy_go_submissions
   where booking_id = p_booking_id and pet_id = p_pet_id;
  if v_status = 'submitted' then
    raise exception 'This form has been sent. Send it again to change it.' using errcode = '22023';
  end if;
  if not coalesce(private.yipyy_go_editable(p_booking_id, v_status), false) then
    raise exception 'This form can no longer be changed.' using errcode = '22023';
  end if;

  insert into public.yipyy_go_submissions as y (booking_id, pet_id, answers, add_on_requests)
  values (p_booking_id, p_pet_id, coalesce(p_answers, '{}'::jsonb), coalesce(p_add_on_requests, '[]'::jsonb))
  on conflict (booking_id, pet_id) do update
     set answers = excluded.answers,
         add_on_requests = excluded.add_on_requests
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."save_yipyy_go_draft"("p_booking_id" "uuid", "p_pet_id" "uuid", "p_answers" "jsonb", "p_add_on_requests" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_booking_tip_split"("p_booking_ref" bigint, "p_method" "text", "p_allocations" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking   public.bookings%rowtype;
  v_collected numeric(10,2);
  v_total     numeric(10,2) := 0;
  v_count     integer := 0;
  v_row       jsonb;
  v_staff     uuid;
begin
  if p_method not in ('by_service', 'equal', 'custom_percent', 'custom_amount') then
    raise exception 'Unknown split method "%".', p_method using errcode = '22023';
  end if;

  select * into v_booking from public.bookings where ref = p_booking_ref;
  if not found then
    raise exception 'That booking does not exist.' using errcode = 'P0002';
  end if;

  if not private.has_permission(v_booking.facility_id, 'take_payment') then
    raise exception 'Not allowed to split tips at this facility.'
      using errcode = '42501';
  end if;

  select coalesce(sum(p.tip), 0) into v_collected
    from public.payments p
   where p.booking_id = v_booking.id;

  delete from public.booking_tip_allocations where booking_id = v_booking.id;

  for v_row in select * from jsonb_array_elements(coalesce(p_allocations, '[]'::jsonb))
  loop
    select s.id into v_staff
      from public.staff s
     where s.id = (v_row->>'staffId')::uuid
       and s.facility_id = v_booking.facility_id;

    if v_staff is null then
      raise exception 'No such staff member at this facility: %.',
        coalesce(v_row->>'staffId', 'null') using errcode = '23503';
    end if;

    if (v_row->>'amount')::numeric <= 0 then
      continue;
    end if;

    insert into public.booking_tip_allocations
      (booking_id, facility_id, staff_id, amount, method, created_by, author_name)
    values
      (v_booking.id, v_booking.facility_id, v_staff,
       round((v_row->>'amount')::numeric, 2), p_method,
       (select auth.jwt()->>'sub'),
       (select p.full_name from public.profiles p
         where p.id = (select auth.jwt()->>'sub')));

    v_total := v_total + round((v_row->>'amount')::numeric, 2);
    v_count := v_count + 1;
  end loop;

  if v_total > v_collected + 0.005 then
    raise exception
      'Tips allocated (%) exceed the tips collected on this booking (%).',
      to_char(v_total, 'FM999999990.00'),
      to_char(v_collected, 'FM999999990.00')
      using errcode = '23514';
  end if;

  return v_count;
end $$;


ALTER FUNCTION "public"."set_booking_tip_split"("p_booking_ref" bigint, "p_method" "text", "p_allocations" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_booking_tip_split"("p_booking_ref" bigint, "p_method" "text", "p_allocations" "jsonb") IS 'Rewrites a booking''s tip allocations. Requires take_payment on the booking''s own facility. anon holds no EXECUTE grant.';



CREATE OR REPLACE FUNCTION "public"."set_customer_signup"("p_facility_id" "uuid", "p_enabled" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.is_platform_admin()
     and not private.has_permission(p_facility_id, 'settings_general') then
    raise exception 'You may not change this facility''s registration setting.'
      using errcode = '42501';
  end if;

  update public.facilities
     set allow_customer_signup = coalesce(p_enabled, false)
   where id = p_facility_id;

  if not found then
    raise exception 'No such facility.' using errcode = 'no_data_found';
  end if;

  return coalesce(p_enabled, false);
end;
$$;


ALTER FUNCTION "public"."set_customer_signup"("p_facility_id" "uuid", "p_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_default_terminal"("p_terminal_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_facility uuid;
begin
  select facility_id into v_facility
    from public.facility_terminals
   where id = p_terminal_id;

  if v_facility is null then
    raise exception 'No such terminal.' using errcode = '42704';
  end if;

  update public.facility_terminals
     set is_default = false
   where facility_id = v_facility
     and is_default
     and id <> p_terminal_id;

  update public.facility_terminals
     set is_default = true
   where id = p_terminal_id;
end;
$$;


ALTER FUNCTION "public"."set_default_terminal"("p_terminal_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_default_terminal"("p_terminal_id" "uuid") IS 'SECURITY INVOKER: the RLS policy decides, so this is not a way around manage_settings.';



CREATE OR REPLACE FUNCTION "public"."set_facility_module"("p_facility_id" "uuid", "p_module_id" "text", "p_enabled" boolean, "p_price_override_cents" integer DEFAULT NULL::integer, "p_note" "text" DEFAULT ''::"text", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor text := (select auth.jwt() ->> 'sub');
begin
  if not private.is_platform_admin() then
    raise exception 'Only the platform team can change what a facility is sold.'
      using errcode = '42501';
  end if;

  if not exists (select 1 from public.modules m where m.id = p_module_id and m.is_active) then
    raise exception 'No active module called %', p_module_id using errcode = '23503';
  end if;

  insert into public.facility_modules as fm
    (facility_id, module_id, enabled, price_override_cents, note, granted_by, expires_at)
  values
    (p_facility_id, p_module_id, p_enabled, p_price_override_cents,
     coalesce(p_note, ''), v_actor, p_expires_at)
  on conflict (facility_id, module_id) do update
     set enabled              = excluded.enabled,
         price_override_cents = excluded.price_override_cents,
         note                 = excluded.note,
         granted_by           = excluded.granted_by,
         expires_at           = excluded.expires_at;
end;
$$;


ALTER FUNCTION "public"."set_facility_module"("p_facility_id" "uuid", "p_module_id" "text", "p_enabled" boolean, "p_price_override_cents" integer, "p_note" "text", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_facility_owner_email"("p_facility_id" "uuid", "p_email" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_staff   public.staff;
  v_grant   public.facility_membership_grants;
  v_email   text := lower(trim(coalesce(p_email, '')));
  v_before  text;
begin
  if not private.is_platform_admin() then
    raise exception 'Only a platform administrator may change an owner''s address.'
      using errcode = '42501';
  end if;

  if v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'That is not a valid email address.' using errcode = '22023';
  end if;

  select * into v_staff
    from public.staff
   where facility_id = p_facility_id
     and primary_role = 'owner'
   order by created_at
   limit 1;

  if v_staff.id is null then
    raise exception 'That facility has no owner.' using errcode = 'no_data_found';
  end if;

  select * into v_grant
    from public.facility_membership_grants
   where staff_id = v_staff.id;

  if v_grant.claimed_at is not null then
    raise exception
      'That invitation has already been accepted. Changing the address would not move their access — remove the membership instead.'
      using errcode = '42501';
  end if;

  v_before := v_staff.email;
  if lower(trim(v_before)) = v_email then
    return jsonb_build_object('changed', false, 'email', v_email);
  end if;

  update public.staff
     set email = v_email
   where id = v_staff.id;

  if v_grant.id is not null then
    update public.facility_membership_grants
       set email = v_email
     where id = v_grant.id;
  end if;

  return jsonb_build_object(
    'changed', true,
    'from',    v_before,
    'email',   v_email,
    'staffId', v_staff.id);
end;
$_$;


ALTER FUNCTION "public"."set_facility_owner_email"("p_facility_id" "uuid", "p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_my_notification_state"("p_id" "uuid", "p_read" boolean DEFAULT NULL::boolean, "p_archived" boolean DEFAULT NULL::boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_found boolean;
begin
  update public.staff_notifications n
     set read_at = case
                     when p_read is null then n.read_at
                     when p_read then coalesce(n.read_at, now())
                     else null
                   end,
         archived_at = case
                         when p_archived is null then n.archived_at
                         when p_archived then coalesce(n.archived_at, now())
                         else null
                       end
   where n.id = p_id
     and n.recipient_profile_id = (select auth.jwt()->>'sub');
  v_found := found;
  if not v_found then
    raise exception 'No such notification.' using errcode = '42501';
  end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."set_my_notification_state"("p_id" "uuid", "p_read" boolean, "p_archived" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_onboarding_account_complete"("p_token" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_instance uuid;
begin
  select i.id into v_instance
    from public.onboarding_instances i
    join public.staff s on s.id = i.staff_id
   where i.token_hash = private.hash_onboarding_token(p_token)
     and i.token_expires_at > now() and i.submitted_at is null and s.status = 'invited';
  if v_instance is null then return false; end if;
  update public.onboarding_instances
     set account_password_set_at = coalesce(account_password_set_at, now())
   where id = v_instance;
  return true;
end;
$$;


