CREATE OR REPLACE FUNCTION "public"."set_report_card_favourite"("p_card_id" "uuid", "p_favourite" boolean) RETURNS "public"."report_cards"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_card public.report_cards;
begin
  update public.report_cards
     set favourite  = p_favourite,
         updated_at = now()
   where id = p_card_id
     and client_id in (select private.own_client_ids())
     and delivery_status = 'sent'
  returning * into v_card;

  if v_card.id is null then
    raise exception 'That report card is not yours to keep.' using errcode = '42501';
  end if;

  return v_card;
end;
