CREATE OR REPLACE FUNCTION "public"."set_subscription_status"("p_facility_id" "uuid", "p_status" "public"."subscription_status") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_previous public.subscription_status;
begin
  if not private.has_platform_role('superadmin') then
    raise exception 'Only a superadmin may change a subscription''s status.'
      using errcode = '42501';
  end if;

  select status into v_previous from public.facility_subscriptions
   where facility_id = p_facility_id;
  if v_previous is null then
    raise exception 'That facility has no subscription.' using errcode = 'no_data_found';
  end if;

  update public.facility_subscriptions
     set status       = p_status,
         cancelled_at = case when p_status = 'cancelled' then now() else null end
   where facility_id = p_facility_id;

  return jsonb_build_object('facilityId', p_facility_id, 'from', v_previous, 'to', p_status);
end;
$$;


ALTER FUNCTION "public"."set_subscription_status"("p_facility_id" "uuid", "p_status" "public"."subscription_status") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."settle_bookings"("p_facility_id" "uuid", "p_method" "text", "p_booking_ids" "uuid"[], "p_receipt_channels" "text"[] DEFAULT '{}'::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_booking record;
  v_balance numeric(10,2);
  v_settled jsonb := '[]'::jsonb;
begin
  if p_booking_ids is null or array_length(p_booking_ids, 1) is null then
    raise exception 'No bookings were named.' using errcode = '22023';
  end if;

  for v_booking in
    select b.id, b.ref, b.client_id, b.facility_id,
           (b.amount_due - b.amount_paid)::numeric(10,2) as balance
      from public.bookings b
     where b.id = any(p_booking_ids)
     order by b.ref
  loop
    if v_booking.facility_id is distinct from p_facility_id then
      raise exception 'Booking % belongs to a different facility.', v_booking.ref
        using errcode = '42501';
    end if;

    v_balance := v_booking.balance;

    if v_balance is null or v_balance <= 0 then
      continue;
    end if;

    perform public.record_payment(
      p_facility_id      => p_facility_id,
      p_method           => p_method,
      p_subtotal         => v_balance,
      p_tax              => 0,
      p_tip              => 0,
      p_amount_charged   => v_balance,
      p_grand_total      => v_balance,
      p_booking_id       => v_booking.id,
      p_client_id        => v_booking.client_id,
      p_cash_received    => case when p_method = 'cash' then v_balance end,
      p_receipt_channels => p_receipt_channels
    );

    v_settled := v_settled || jsonb_build_object(
      'bookingRef', v_booking.ref,
      'amount',     v_balance
    );
  end loop;

  return v_settled;
end;
$$;


ALTER FUNCTION "public"."settle_bookings"("p_facility_id" "uuid", "p_method" "text", "p_booking_ids" "uuid"[], "p_receipt_channels" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."settle_bookings"("p_facility_id" "uuid", "p_method" "text", "p_booking_ids" "uuid"[], "p_receipt_channels" "text"[]) IS 'Settles the outstanding balance on several bookings in ONE transaction, measured against amount_due.';



CREATE OR REPLACE FUNCTION "public"."skip_training_makeup"("p_missed_booking_id" "uuid") RETURNS "public"."training_makeups"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_missed record;
  v_row    public.training_makeups;
begin
  select * into v_missed from private.training_missed_booking(p_missed_booking_id);
  if not found or private.training_makeup_actor(v_missed.facility_id, v_missed.client_id) is null then
    raise exception 'That missed session is not yours to skip.' using errcode = '42501';
  end if;

  select * into v_row from public.training_makeups
   where missed_booking_id = p_missed_booking_id
   for update;
  if found then
    if v_row.status = 'skipped' then
      return v_row;
    elsif v_row.status = 'offered' then
      raise exception 'A seat is booked for this make-up; decline it instead.' using errcode = '22023';
    elsif v_row.status = 'ineligible' then
      raise exception 'The facility has decided there is no make-up for this session.' using errcode = '22023';
    end if;
  end if;

  insert into public.training_makeups
    (facility_id, missed_booking_id, missed_session_id, pet_id, client_id, status, answered_at)
  values
    (v_missed.facility_id, p_missed_booking_id, v_missed.session_id, v_missed.pet_id,
     v_missed.client_id, 'skipped', now())
  on conflict (missed_booking_id) do update
     set status = 'skipped',
         answered_at = excluded.answered_at,
         updated_at = now()
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."skip_training_makeup"("p_missed_booking_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."split_boarding_stay"("p_booking_ref" bigint, "p_from" "date", "p_room_id" "text", "p_override_reason" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_booking_id  uuid;
  v_facility_id uuid;
  v_start       timestamptz;
  v_end         timestamptz;
  v_tz          text;
  v_at          timestamptz;
  v_room_id     uuid;
  v_override    text;
  v_seg         public.boarding_stays%rowtype;
  v_touched     integer;
  v_status      public.booking_status;
begin
  select b.id, b.facility_id, b.start_at, b.end_at, b.status
    into v_booking_id, v_facility_id, v_start, v_end, v_status
    from public.bookings b
   where b.ref = p_booking_ref and b.service = 'boarding';

  if v_booking_id is null then
    raise exception 'That boarding booking does not exist, or is not yours.'
      using errcode = '42501';
  end if;

  -- A stay that is over, or will not happen, has no night left to move.
  if v_status in ('cancelled', 'declined', 'no_show', 'completed') then
    raise exception 'This booking is % and cannot move kennels.',
      replace(v_status::text, '_', ' ')
      using errcode = '22023', hint = 'split_closed_booking';
  end if;

  select r.id into v_room_id
    from public.facility_rooms r
   where r.facility_id = v_facility_id
     and r.legacy_id = p_room_id
     and r.active;
  if v_room_id is null then
    raise exception 'This facility has no room %.', p_room_id
      using errcode = '23503';
  end if;

  v_override := nullif(trim(coalesce(p_override_reason, '')), '');
  if v_override is not null
     and not private.has_permission(v_facility_id, 'override_booking_capacity')
  then
    raise exception 'Not allowed to override capacity limits.'
      using errcode = '42501';
  end if;

  select coalesce(f.timezone, 'America/Toronto') into v_tz
    from public.facilities f where f.id = v_facility_id;
  v_tz := coalesce(v_tz, 'America/Toronto');

  -- The booking's own check-in time, on the first night in the new kennel.
  v_at := (p_from + (v_start at time zone v_tz)::time) at time zone v_tz;

  -- From the first night is allowed — it moves the first stay whole, below —
  -- but a move must leave the guest at least one night in the new kennel.
  if v_at < v_start or v_at >= v_end then
    raise exception 'A move has to fall on a night of the stay.'
      using errcode = '22023', hint = 'split_outside_stay';
  end if;

  select * into v_seg from public.boarding_stays
   where booking_id = v_booking_id and occupies @> v_at
   order by segment_order limit 1;
  if not found then
    raise exception 'This guest has no kennel yet. Assign one first.'
      using errcode = '55000';
  end if;

  if v_seg.room_id = v_room_id then
    raise exception 'The guest is already in that kennel then.'
      using errcode = '22023', hint = 'split_same_room';
  end if;

  if lower(v_seg.occupies) = v_at then
    -- A stay already starts that night: it changes kennel, nothing splits.
    update public.boarding_stays
       set room_id = v_room_id, override_reason = v_override, updated_at = now()
     where id = v_seg.id;
    get diagnostics v_touched = row_count;
    if v_touched = 0 then
      raise exception 'Not allowed to change this booking''s room.' using errcode = '42501';
    end if;
    return v_seg.segment_order;
  end if;

  set constraints public.boarding_stays_segment_order_unique deferred;

  update public.boarding_stays
     set segment_order = segment_order + 1, updated_at = now()
   where booking_id = v_booking_id and segment_order > v_seg.segment_order;

  update public.boarding_stays
     set occupies = tstzrange(lower(occupies), v_at, '[)'), updated_at = now()
   where id = v_seg.id;
  get diagnostics v_touched = row_count;
  if v_touched = 0 then
    raise exception 'Not allowed to change this booking''s room.' using errcode = '42501';
  end if;

  insert into public.boarding_stays
    (booking_id, facility_id, room_id, occupies, override_reason, segment_order,
     released_at)
  values
    (v_booking_id, v_facility_id, v_room_id,
     tstzrange(v_at, upper(v_seg.occupies), '[)'), v_override,
     v_seg.segment_order + 1, v_seg.released_at);

  set constraints public.boarding_stays_segment_order_unique immediate;

  return v_seg.segment_order + 1;
end;
$$;


ALTER FUNCTION "public"."split_boarding_stay"("p_booking_ref" bigint, "p_from" "date", "p_room_id" "text", "p_override_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."status_page_maintenance"() RETURNS TABLE("id" "uuid", "title" "text", "body" "text", "published_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select a.id, a.title, a.body, coalesce(a.starts_at, a.published_at)
    from public.platform_announcements a
   where a.target = 'all'
     and private.platform_announcement_is_live(a.status, a.starts_at, a.published_at, a.auto_archive_days)
     and (a.title || ' ' || a.body) ~* 'maintenance|downtime|service window|scheduled\s+upgrade'
   order by coalesce(a.starts_at, a.published_at) desc
   limit 10;
$$;


ALTER FUNCTION "public"."status_page_maintenance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."stop_workflow_enrollment"("p_enrollment_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("enrollment_id" "uuid", "cancelled_messages" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_facility uuid;
  v_status   text;
  v_cancelled integer := 0;
begin
  select w.facility_id, e.status
    into v_facility, v_status
    from public.workflow_enrollments e
    join public.workflows w on w.id = e.workflow_id
   where e.id = p_enrollment_id;

  if v_facility is null
     or not private.has_permission(v_facility, 'marketing_manage_automations')
  then
    raise exception 'no such enrolment, or not yours to stop'
      using errcode = '42501';
  end if;

  if v_status is distinct from 'active' then
    raise exception 'that sequence has already ended (%)', v_status
      using errcode = '22023';
  end if;

  update public.workflow_enrollments
     set status         = 'stopped',
         stopped_reason = 'manual:' ||
           coalesce(nullif(btrim(p_reason), ''), 'stopped by staff'),
         next_run_at    = null,
         completed_at   = now(),
         updated_at     = now()
   where public.workflow_enrollments.id = p_enrollment_id
     and public.workflow_enrollments.status = 'active';

  update public.message_sends
     set status      = 'cancelled',
         skip_reason = 'enrolment_stopped'
   where public.message_sends.enrollment_id = p_enrollment_id
     and public.message_sends.status = 'queued';
  get diagnostics v_cancelled = row_count;

  return query select p_enrollment_id, v_cancelled;
end;
$$;


ALTER FUNCTION "public"."stop_workflow_enrollment"("p_enrollment_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."stop_workflow_enrollment"("p_enrollment_id" "uuid", "p_reason" "text") IS 'Take one client out of one workflow by hand. The only write a session may make to workflow_enrollments; also cancels that enrolment''s queued messages.';



CREATE OR REPLACE FUNCTION "public"."store_boarding_secret"("p_application_id" "uuid", "p_kind" "text", "p_principal_id" "uuid", "p_value" "text", "p_last4" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_facility uuid;
  v_status   text;
  v_name     text;
  v_id       uuid;
begin
  select facility_id, status into v_facility, v_status
    from public.merchant_applications where id = p_application_id;

  if v_facility is null then
    raise exception 'No such application.' using errcode = '42704';
  end if;

  if not (private.is_platform_admin()
          or private.has_permission(v_facility, 'settings_billing')
          or current_setting('role', true) = 'service_role') then
    raise exception 'You may not edit this facility''s merchant application.'
      using errcode = '42501';
  end if;

  if v_status not in ('draft', 'more_info_needed') then
    raise exception 'This application has been submitted and can no longer be edited.'
      using errcode = '42501';
  end if;

  if p_value is null or length(trim(p_value)) = 0 then
    raise exception 'A value is required.' using errcode = '22023';
  end if;

  v_name := format('boarding:%s:%s:%s', p_application_id, p_kind,
                   coalesce(p_principal_id::text, 'business'));

  select id into v_id from vault.secrets where name = v_name;
  if v_id is null then
    v_id := vault.create_secret(p_value, v_name, 'Merchant boarding evidence');
  else
    perform vault.update_secret(v_id, p_value, v_name);
  end if;

  if p_kind = 'bank' then
    update public.merchant_applications
       set bank_secret_id = v_id, bank_last4 = p_last4
     where id = p_application_id;
  elsif p_kind = 'principal' then
    update public.merchant_application_principals
       set national_id_secret_id = v_id, national_id_last4 = p_last4
     where id = p_principal_id and application_id = p_application_id;
  else
    raise exception 'Unknown secret kind: %', p_kind using errcode = '22023';
  end if;
end;
$$;


ALTER FUNCTION "public"."store_boarding_secret"("p_application_id" "uuid", "p_kind" "text", "p_principal_id" "uuid", "p_value" "text", "p_last4" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."store_boarding_secret"("p_application_id" "uuid", "p_kind" "text", "p_principal_id" "uuid", "p_value" "text", "p_last4" "text") IS 'SECURITY DEFINER: vault is unreachable otherwise. Re-checks settings_billing itself, because a definer function bypasses RLS here.';



CREATE OR REPLACE FUNCTION "public"."store_communication_credentials"("p_facility_id" "uuid", "p_subaccount_sid" "text", "p_auth_token" "text", "p_friendly_name" "text" DEFAULT NULL::"text", "p_connected_by" "text" DEFAULT NULL::"text", "p_provider" "text" DEFAULT 'twilio'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_secret_name text := format('%s:%s:auth', p_provider, p_facility_id);
  v_secret_id   uuid;
begin
  if p_auth_token is null or length(trim(p_auth_token)) = 0 then
    raise exception 'An auth token is required to record a connection.'
      using errcode = '22023';
  end if;

  insert into public.communication_connections as cc
    (facility_id, provider, subaccount_sid, friendly_name, status,
     connected_by, connected_at, suspended_at, last_error, last_verified_at)
  values
    (p_facility_id, p_provider, p_subaccount_sid, p_friendly_name, 'connected',
     p_connected_by, now(), null, null, now())
  on conflict (facility_id, provider) do update
     set subaccount_sid   = excluded.subaccount_sid,
         friendly_name    = coalesce(excluded.friendly_name, cc.friendly_name),
         status           = 'connected',
         connected_by     = coalesce(excluded.connected_by, cc.connected_by),
         connected_at     = coalesce(cc.connected_at, excluded.connected_at),
         suspended_at     = null,
         last_error       = null,
         last_verified_at = now();

  select c.auth_token_secret_id into v_secret_id
    from private.communication_credentials c
   where c.facility_id = p_facility_id and c.provider = p_provider;

  if v_secret_id is null then
    v_secret_id := vault.create_secret(
      p_auth_token, v_secret_name, 'Twilio subaccount auth token');
  else
    perform vault.update_secret(v_secret_id, p_auth_token, v_secret_name);
  end if;

  insert into private.communication_credentials as ccred
    (facility_id, provider, auth_token_secret_id, rotated_at)
  values
    (p_facility_id, p_provider, v_secret_id, now())
  on conflict (facility_id, provider) do update
     set auth_token_secret_id = excluded.auth_token_secret_id,
         rotated_at           = now();
end;
$$;


ALTER FUNCTION "public"."store_communication_credentials"("p_facility_id" "uuid", "p_subaccount_sid" "text", "p_auth_token" "text", "p_friendly_name" "text", "p_connected_by" "text", "p_provider" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."store_communication_credentials"("p_facility_id" "uuid", "p_subaccount_sid" "text", "p_auth_token" "text", "p_friendly_name" "text", "p_connected_by" "text", "p_provider" "text") IS 'Records a facility''s Twilio subaccount and puts its auth token in Vault. service_role only — see the header of 20260809200000.';



CREATE OR REPLACE FUNCTION "public"."store_payment_credentials"("p_facility_id" "uuid", "p_merchant_id" "text", "p_environment" "text", "p_access_token" "text", "p_refresh_token" "text" DEFAULT NULL::"text", "p_access_expires" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_refresh_expires" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_public_api_key" "text" DEFAULT NULL::"text", "p_scopes" "text"[] DEFAULT '{}'::"text"[], "p_connected_by" "text" DEFAULT NULL::"text", "p_processor" "text" DEFAULT 'clover'::"text", "p_currency" "text" DEFAULT NULL::"text", "p_country" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_access_name  text := format('%s:%s:access',  p_processor, p_facility_id);
  v_refresh_name text := format('%s:%s:refresh', p_processor, p_facility_id);
  v_access_id    uuid;
  v_refresh_id   uuid;
begin
  if p_access_token is null or length(trim(p_access_token)) = 0 then
    raise exception 'An access token is required to record a connection.'
      using errcode = '22023';
  end if;

  insert into public.payment_connections as pc
    (facility_id, processor, environment, merchant_id, public_api_key,
     status, scopes, connected_by, connected_at, revoked_at, last_error,
     last_verified_at, currency, country)
  values
    (p_facility_id, p_processor, p_environment, p_merchant_id, p_public_api_key,
     'connected', coalesce(p_scopes, '{}'), p_connected_by, now(), null, null,
     now(), p_currency, p_country)
  on conflict (facility_id, processor) do update
     set environment      = excluded.environment,
         merchant_id      = excluded.merchant_id,
         public_api_key   = coalesce(excluded.public_api_key, pc.public_api_key),
         currency         = coalesce(excluded.currency, pc.currency),
         country          = coalesce(excluded.country, pc.country),
         status           = 'connected',
         scopes           = excluded.scopes,
         connected_by     = coalesce(excluded.connected_by, pc.connected_by),
         connected_at     = coalesce(pc.connected_at, excluded.connected_at),
         revoked_at       = null,
         last_error       = null,
         last_verified_at = now();

  select c.access_token_secret_id, c.refresh_token_secret_id
    into v_access_id, v_refresh_id
    from private.payment_credentials c
   where c.facility_id = p_facility_id and c.processor = p_processor;

  if v_access_id is null then
    v_access_id := vault.create_secret(
      p_access_token, v_access_name, 'Clover OAuth access token');
  else
    perform vault.update_secret(v_access_id, p_access_token, v_access_name);
  end if;

  if p_refresh_token is not null then
    if v_refresh_id is null then
      v_refresh_id := vault.create_secret(
        p_refresh_token, v_refresh_name, 'Clover OAuth refresh token');
    else
      perform vault.update_secret(v_refresh_id, p_refresh_token, v_refresh_name);
    end if;
  end if;

  insert into private.payment_credentials as pcred
    (facility_id, processor, access_token_secret_id, refresh_token_secret_id,
     access_token_expires_at, refresh_token_expires_at, rotated_at)
  values
    (p_facility_id, p_processor, v_access_id, v_refresh_id,
     p_access_expires, p_refresh_expires, now())
  on conflict (facility_id, processor) do update
     set access_token_secret_id   = excluded.access_token_secret_id,
         refresh_token_secret_id  = coalesce(excluded.refresh_token_secret_id,
                                             pcred.refresh_token_secret_id),
         access_token_expires_at  = excluded.access_token_expires_at,
         refresh_token_expires_at = coalesce(excluded.refresh_token_expires_at,
                                             pcred.refresh_token_expires_at),
         rotated_at               = now();
end;
$$;


ALTER FUNCTION "public"."store_payment_credentials"("p_facility_id" "uuid", "p_merchant_id" "text", "p_environment" "text", "p_access_token" "text", "p_refresh_token" "text", "p_access_expires" timestamp with time zone, "p_refresh_expires" timestamp with time zone, "p_public_api_key" "text", "p_scopes" "text"[], "p_connected_by" "text", "p_processor" "text", "p_currency" "text", "p_country" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_onboarding"("p_token" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_instance uuid;
begin
  select i.id into v_instance
    from public.onboarding_instances i
    join public.staff s on s.id = i.staff_id
   where i.token_hash = private.hash_onboarding_token(p_token)
     and i.token_expires_at > now() and i.submitted_at is null and s.status = 'invited';
  if v_instance is null then return false; end if;
  update public.onboarding_instances set submitted_at = now() where id = v_instance;
  return true;
end;
$$;


ALTER FUNCTION "public"."submit_onboarding"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_review_response"("p_token" "text", "p_rating" integer, "p_comment" "text" DEFAULT NULL::"text", "p_tag_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_staff_id" "uuid" DEFAULT NULL::"uuid", "p_display_consent" boolean DEFAULT false, "p_locale" "text" DEFAULT NULL::"text", "p_source" "text" DEFAULT 'sms_link'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_req      public.review_requests%rowtype;
  v_response uuid;
  v_staff    uuid;
  v_escalation uuid;
begin
  if p_token is null or length(p_token) < 16 then
    raise exception 'That review link is not valid.' using errcode = '42501';
  end if;
  if p_rating is null or p_rating < 1 or p_rating > 5 then
    raise exception 'A rating is 1 to 5.' using errcode = '22023';
  end if;

  select * into v_req
    from public.review_requests
   where token_hash = private.hash_review_token(p_token)
     and token_expires_at > now()
     and state not in ('suppressed', 'cancelled', 'expired')
   for update;

  if not found then
    raise exception 'That review link is not valid.' using errcode = '42501';
  end if;

  if p_staff_id is not null then
    select s.id into v_staff
      from public.staff s
     where s.id = p_staff_id
       and s.facility_id = v_req.facility_id
       and (v_req.staff_on_visit = '{}' or s.id = any (v_req.staff_on_visit));
  end if;
  v_staff := coalesce(v_staff, v_req.primary_staff_id);

  insert into public.review_responses (
    facility_id, request_id, rating, comment, locale, source,
    attributed_staff_id, display_consent)
  values (
    v_req.facility_id, v_req.id, p_rating, nullif(btrim(coalesce(p_comment, '')), ''),
    coalesce(p_locale, v_req.channel, 'en'),
    case when p_source in ('sms_link','email_link','report_card','portal','kiosk','staff')
         then p_source else 'sms_link' end,
    v_staff, coalesce(p_display_consent, false))
  returning id into v_response;

  insert into public.review_response_tags (response_id, tag_id)
  select v_response, t.id
    from public.review_tags t
   where t.id = any (coalesce(p_tag_ids, '{}'))
     and t.facility_id = v_req.facility_id
     and t.is_active
  on conflict do nothing;

  update public.review_requests
     set state = 'rated', state_changed_at = now()
   where id = v_req.id;

  -- THE TICKET, IN THIS TRANSACTION. A poor rating recorded without one is the
  -- failure the whole recovery half of this feature exists to prevent, and
  -- doing it in a second call would leave a window where exactly that is true.
  v_escalation := private.open_review_escalation(v_response);

  -- The rating decides what happens INTERNALLY. It does NOT decide whether the
  -- public links come back in this payload - they always do, at every rating.
  return jsonb_build_object(
    'responseId', v_response,
    'rating', p_rating,
    'escalated', v_escalation is not null,
    'showcaseEligible',
      p_rating >= v_req.showcase_min
      and coalesce(p_display_consent, false)
      and nullif(btrim(coalesce(p_comment, '')), '') is not null);

exception
  when unique_violation then
    raise exception 'That review has already been submitted.' using errcode = '42501';
end;
$$;


ALTER FUNCTION "public"."submit_review_response"("p_token" "text", "p_rating" integer, "p_comment" "text", "p_tag_ids" "uuid"[], "p_staff_id" "uuid", "p_display_consent" boolean, "p_locale" "text", "p_source" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."submit_review_response"("p_token" "text", "p_rating" integer, "p_comment" "text", "p_tag_ids" "uuid"[], "p_staff_id" "uuid", "p_display_consent" boolean, "p_locale" "text", "p_source" "text") IS 'Records one response, once. Rate-once comes from the unique on request_id, not from a check the caller could race.';



CREATE OR REPLACE FUNCTION "public"."submit_yipyy_go_form"("p_booking_id" "uuid", "p_pet_id" "uuid", "p_answers" "jsonb", "p_add_on_requests" "jsonb" DEFAULT '[]'::"jsonb", "p_tip" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking  public.bookings;
  v_settings jsonb;
  v_status   text;
  v_name     text;
  v_row      public.yipyy_go_submissions;
  v_entering boolean;
  v_req      jsonb;
begin
  select * into v_booking from public.bookings where id = p_booking_id for update;
  if not found
     or not private.yipyy_go_is_owner(v_booking.client_id)
     or not exists (
       select 1 from public.booking_pets bp where bp.booking_id = p_booking_id and bp.pet_id = p_pet_id
     )
  then
    raise exception 'That booking is not yours.' using errcode = '42501';
  end if;

  if private.yipyy_go_requirement(v_booking.facility_id, v_booking.service) is null then
    raise exception 'This booking does not ask for a pre-arrival form.' using errcode = '22023';
  end if;

  select status into v_status from public.yipyy_go_submissions
   where booking_id = p_booking_id and pet_id = p_pet_id;
  if not coalesce(private.yipyy_go_editable(p_booking_id, v_status), false) then
    raise exception 'This form can no longer be changed.' using errcode = '22023';
  end if;

  if p_tip is not null and jsonb_typeof(p_tip) <> 'object' then
    raise exception 'That is not a tip.' using errcode = '22023';
  end if;
  if p_add_on_requests is not null and jsonb_typeof(p_add_on_requests) <> 'array' then
    raise exception 'That is not a list of add-ons.' using errcode = '22023';
  end if;
  for v_req in select e.value from jsonb_array_elements(coalesce(p_add_on_requests, '[]'::jsonb)) e(value) loop
    if jsonb_typeof(v_req) <> 'object'
       or (v_req ? 'quantity' and jsonb_typeof(v_req -> 'quantity') <> 'number')
       or private.yipyy_go_offered_add_on(v_booking, v_req ->> 'addOnId') is null
    then
      raise exception 'That add-on is not offered on this booking.' using errcode = '22023';
    end if;
  end loop;

  select c.name into v_name from public.clients c where c.id = v_booking.client_id;

  insert into public.yipyy_go_submissions as y
    (booking_id, pet_id, status, answers, add_on_requests, tip_choice, submitted_at, submitted_by_name)
  values
    (p_booking_id, p_pet_id, 'submitted', coalesce(p_answers, '{}'::jsonb),
     coalesce(p_add_on_requests, '[]'::jsonb), p_tip, now(), nullif(left(btrim(coalesce(v_name, '')), 200), ''))
  on conflict (booking_id, pet_id) do update
     set status = 'submitted',
         answers = excluded.answers,
         add_on_requests = excluded.add_on_requests,
         tip_choice = excluded.tip_choice,
         submitted_at = excluded.submitted_at,
         submitted_by_name = excluded.submitted_by_name
  returning * into v_row;

  perform private.yipyy_go_write_charges(p_booking_id);
  perform private.yipyy_go_pledge_tip(p_booking_id, p_tip);

  select s.value into v_settings from public.facility_settings s
   where s.facility_id = v_booking.facility_id and s.domain = 'yipyy_go_config';
  v_entering := v_status is distinct from 'submitted';

  return jsonb_build_object(
    'submission', to_jsonb(v_row),
    'notifyStaff', v_entering and coalesce((v_settings ->> 'notifyStaffEmailOnSubmit')::boolean, false),
    'sendConfirmation', v_entering and coalesce((v_settings -> 'confirmationEmail' ->> 'enabled')::boolean, false),
    'charges', coalesce((
      select jsonb_agg(jsonb_build_object(
               'key', c.charge_key, 'kind', c.kind, 'name', c.name,
               'unitPrice', c.unit_price, 'quantity', c.quantity,
               'onBill', c.line_item_id is not null
             ) order by c.created_at)
        from public.yipyy_go_charges c
       where c.booking_id = p_booking_id
    ), '[]'::jsonb),
    'tipAmount', (select b.tip_amount from public.bookings b where b.id = p_booking_id)
  );
end;
$$;


ALTER FUNCTION "public"."submit_yipyy_go_form"("p_booking_id" "uuid", "p_pet_id" "uuid", "p_answers" "jsonb", "p_add_on_requests" "jsonb", "p_tip" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."time_off_shift_conflicts"("p_request_id" "uuid") RETURNS TABLE("shift_id" "uuid", "starts_at" timestamp with time zone, "ends_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_request  record;
  v_timezone text;
begin
  select * into v_request
    from public.staff_time_off_requests
   where id = p_request_id;

  if v_request.id is null then
    raise exception 'No such time-off request.' using errcode = 'P0002';
  end if;

  if not private.has_permission(v_request.facility_id, 'scheduling_approve_time_off')
     and v_request.staff_id not in (select private.own_staff_ids()) then
    raise exception 'You do not have permission to read that request.'
      using errcode = '42501';
  end if;

  select coalesce(f.timezone, 'UTC') into v_timezone
    from public.facilities f
   where f.id = v_request.facility_id;

  return query
    select s.id, s.starts_at, s.ends_at
      from public.staff_shifts s
     where s.staff_id = v_request.staff_id
       and s.status <> 'cancelled'
       and s.starts_at < ((v_request.ends_on + 1)::timestamp at time zone v_timezone)
       and s.ends_at   > (v_request.starts_on::timestamp at time zone v_timezone)
     order by s.starts_at;
end;
$$;


ALTER FUNCTION "public"."time_off_shift_conflicts"("p_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."time_off_shift_conflicts"("p_request_id" "uuid") IS 'Shifts the requester is still rostered for during the leave. Approving over a rostered shift is allowed — it is the manager''s call — but it is never silent.';



CREATE OR REPLACE FUNCTION "public"."training_attendance_history"("p_facility_id" "uuid" DEFAULT NULL::"uuid", "p_pet_ref" bigint DEFAULT NULL::bigint) RETURNS TABLE("booking_id" "uuid", "booking_ref" bigint, "facility_id" "uuid", "timezone" "text", "session_id" "uuid", "session_number" integer, "session_start_at" timestamp with time zone, "session_end_at" timestamp with time zone, "series_id" "uuid", "enrollment_id" "uuid", "pet_ref" bigint, "pet_name" "text", "checked_in_at" timestamp with time zone, "checked_out_at" timestamp with time zone, "mark" "text", "session_notes" "text", "exercises" "jsonb", "conditions" "jsonb", "makeup" boolean, "recorded_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select b.id, b.ref, b.facility_id, f.timezone,
         s.id, s.session_number, s.start_at, s.end_at, s.series_id,
         e.id, p.ref, p.name,
         a.checked_in_at, a.checked_out_at, a.mark, a.session_notes,
         coalesce(a.exercises, '[]'::jsonb),
         a.conditions,
         e.series_id <> s.series_id,
         a.created_at, a.updated_at
    from public.bookings b
    join public.training_series_sessions s on s.id = b.training_series_session_id
    join lateral (
      select x.pet_id from public.booking_pets x
       where x.booking_id = b.id
       order by x.pet_id
       limit 1
    ) bp on true
    join public.pets p on p.id = bp.pet_id
    left join lateral (
      select ms.series_id from public.training_makeups m
        join public.training_series_sessions ms on ms.id = m.missed_session_id
       where m.host_booking_id = b.id
         and m.status = 'offered'
       limit 1
    ) mk on true
    join lateral (
      select y.id, y.series_id from public.training_series_enrollments y
       where y.pet_id = bp.pet_id
         and y.client_id = b.client_id
         and (y.series_id = s.series_id or y.series_id = mk.series_id)
       order by (y.series_id = s.series_id) desc, y.enrolled_at desc
       limit 1
    ) e on true
    left join public.facilities f on f.id = b.facility_id
    left join public.training_attendance a on a.booking_id = b.id
   where b.service = 'training'
     and (p_facility_id is null or b.facility_id = p_facility_id)
     and (p_pet_ref is null or p.ref = p_pet_ref)
     and b.status::text not in ('cancelled', 'declined')
     and (s.end_at < now() or a.booking_id is not null)
   order by s.start_at desc
   limit 5000;
$$;


ALTER FUNCTION "public"."training_attendance_history"("p_facility_id" "uuid", "p_pet_ref" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."training_attendance_history"("p_facility_id" "uuid", "p_pet_ref" bigint) IS 'Every ended or recorded session booking of an enrolled dog, with its times, mark, exercises and conditions. A make-up seat (training_makeups, offered) is read under the enrollment of the series the dog missed, with makeup = true.';



CREATE OR REPLACE FUNCTION "public"."training_makeup_host_sessions"("p_missed_booking_id" "uuid") RETURNS TABLE("session_id" "uuid", "series_id" "uuid", "series_name" "text", "session_number" integer, "start_at" timestamp with time zone, "end_at" timestamp with time zone, "location_name" "text", "trainer_name" "text", "seats_left" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_missed record;
begin
  select * into v_missed from private.training_missed_booking(p_missed_booking_id);
  if not found or not private.has_permission(v_missed.facility_id, 'create_bookings') then
    raise exception 'Not allowed to offer a make-up for that session.' using errcode = '42501';
  end if;

  return query
    select q.sid, q.tsid, q.tsname, q.snum, q.sstart, q.send,
           q.lname, q.tname, (q.cap - q.taken)::integer
      from (
        select s.id as sid, ts.id as tsid, ts.name as tsname,
               s.session_number as snum, s.start_at as sstart, s.end_at as send,
               l.name as lname,
               nullif(btrim(concat_ws(' ', st.first_name, st.last_name)), '') as tname,
               ts.capacity as cap,
               (select count(*) from public.bookings b
                 where b.training_series_session_id = s.id
                   and b.status::text not in ('cancelled', 'declined')) as taken
          from public.training_series_sessions s
          join public.training_series ts on ts.id = s.series_id
          left join public.locations l on l.id = ts.location_id
          left join public.staff st on st.id = ts.staff_id
         where ts.facility_id = v_missed.facility_id
           and ts.id <> v_missed.series_id
           and ts.status = 'active'
           and s.status = 'scheduled'
           and s.start_at > now()
           and lower(btrim(coalesce(nullif(btrim(ts.course_type_name), ''), ts.name))) = v_missed.course_key
           and not exists (
             select 1
               from public.bookings b
               join public.booking_pets bp on bp.booking_id = b.id
              where b.training_series_session_id = s.id
                and bp.pet_id = v_missed.pet_id
                and b.status::text not in ('cancelled', 'declined')
           )
      ) q
     where q.taken < q.cap
     order by q.sstart
     limit 100;
end;
$$;


ALTER FUNCTION "public"."training_makeup_host_sessions"("p_missed_booking_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."training_missed_sessions"("p_facility_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("booking_id" "uuid", "booking_ref" bigint, "facility_id" "uuid", "booking_status" "text", "pet_ref" bigint, "pet_name" "text", "client_ref" bigint, "client_name" "text", "client_phone" "text", "client_email" "text", "series_id" "uuid", "series_name" "text", "course_name" "text", "session_id" "uuid", "session_number" integer, "session_start_at" timestamp with time zone, "enrollment_id" "uuid", "enrollment_status" "text", "makeup_id" "uuid", "makeup_status" "text", "owner_note" "text", "ineligible_reason" "text", "requested_at" timestamp with time zone, "offered_at" timestamp with time zone, "offered_by_name" "text", "answered_at" timestamp with time zone, "decided_at" timestamp with time zone, "decided_by_name" "text", "host_session_id" "uuid", "host_session_number" integer, "host_start_at" timestamp with time zone, "host_series_id" "uuid", "host_series_name" "text", "host_booking_ref" bigint, "host_booking_status" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select b.id, b.ref, b.facility_id, b.status::text,
         p.ref, p.name, c.ref, c.name, c.phone, c.email,
         ts.id, ts.name, coalesce(nullif(btrim(ts.course_type_name), ''), ts.name),
         s.id, s.session_number, s.start_at,
         e.id, e.status,
         m.id, m.status, m.owner_note, m.ineligible_reason,
         m.requested_at, m.offered_at, m.offered_by_name,
         m.answered_at, m.decided_at, m.decided_by_name,
         hs.id, hs.session_number, hs.start_at, hts.id, hts.name,
         hb.ref, hb.status::text
    from public.bookings b
    join public.training_series_sessions s on s.id = b.training_series_session_id
    join public.training_series ts on ts.id = s.series_id
    join lateral (
      select x.pet_id from public.booking_pets x
       where x.booking_id = b.id
       order by x.pet_id
       limit 1
    ) bp on true
    join public.pets p on p.id = bp.pet_id
    join public.clients c on c.id = b.client_id
    left join lateral (
      select y.id, y.status from public.training_series_enrollments y
       where y.series_id = s.series_id and y.pet_id = bp.pet_id and y.client_id = b.client_id
       order by y.enrolled_at desc
       limit 1
    ) e on true
    left join public.training_makeups m on m.missed_booking_id = b.id
    left join public.bookings hb on hb.id = m.host_booking_id
    left join public.training_series_sessions hs on hs.id = m.host_session_id
    left join public.training_series hts on hts.id = hs.series_id
   where b.service = 'training'
     and (p_facility_id is null or b.facility_id = p_facility_id)
     and s.end_at < now()
     and b.status::text not in ('cancelled', 'declined')
     and (
       b.status::text = 'no_show'
       or not exists (
         select 1 from public.training_attendance a
          where a.booking_id = b.id and a.checked_in_at is not null
       )
     )
     and not exists (
       select 1 from public.training_makeups hm where hm.host_booking_id = b.id
     )
   order by s.start_at desc
   limit 1000;
$$;


ALTER FUNCTION "public"."training_missed_sessions"("p_facility_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."withdraw_from_training_series"("p_enrollment_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_enrollment public.training_series_enrollments;
begin
  select * into v_enrollment
    from public.training_series_enrollments
   where id = p_enrollment_id
   for update;

  if not found then
    raise exception 'No such enrollment.' using errcode = '23503';
  end if;

  update public.training_series_enrollments
     set status = 'cancelled'
   where id = p_enrollment_id;

  update public.bookings b
     set status = 'cancelled'
   where b.training_series_session_id in (
           select tss.id from public.training_series_sessions tss
            where tss.series_id = v_enrollment.series_id
         )
     and b.client_id = v_enrollment.client_id
     and b.start_at >= now()
     and b.status not in ('completed', 'cancelled', 'no_show')
     and exists (
           select 1 from public.booking_pets bp
            where bp.booking_id = b.id and bp.pet_id = v_enrollment.pet_id
         );
end;
$$;


ALTER FUNCTION "public"."withdraw_from_training_series"("p_enrollment_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."withdraw_from_training_series"("p_enrollment_id" "uuid") IS 'Cancels an enrollment and its still-upcoming bookings. Past/completed sessions are left alone -- withdrawing does not rewrite history. SECURITY INVOKER.';



CREATE OR REPLACE FUNCTION "public"."yipyy_go_arrivals"("p_facility_id" "uuid", "p_query" "text" DEFAULT NULL::"text") RETURNS TABLE("booking_id" "uuid", "booking_ref" bigint, "service" "text", "status" "text", "start_at" timestamp with time zone, "end_at" timestamp with time zone, "client_name" "text", "pets" "jsonb", "requirement" "text", "form_status" "text", "satisfied" boolean, "presence" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with z as (
    select coalesce(
      (select nullif(f.timezone, '') from public.facilities f where f.id = p_facility_id),
      'America/Toronto'
    ) as tz
  ), q as (
    select nullif(btrim(coalesce(p_query, '')), '') as needle
  )
  select b.id, b.ref, b.service, b.status::text, b.start_at, b.end_at, c.name,
         coalesce((
           select jsonb_agg(jsonb_build_object('id', p.id, 'ref', p.ref, 'name', p.name) order by p.name)
             from public.booking_pets bp
             join public.pets p on p.id = bp.pet_id
            where bp.booking_id = b.id
         ), '[]'::jsonb),
         yg.requirement, yg.status, yg.satisfied, pr.presence
    from public.bookings b
    cross join z
    cross join q
    join public.clients c on c.id = b.client_id
    left join public.booking_yipyy_go yg on yg.booking_id = b.id
    left join public.booking_presence pr on pr.booking_id = b.id
   where p_facility_id is not null
     and b.facility_id = p_facility_id
     and b.status::text in ('pending', 'request_submitted', 'confirmed', 'checked_in')
     and (
       (timezone(z.tz, b.start_at))::date = (timezone(z.tz, now()))::date
       or (
         b.service = 'boarding'
         and (timezone(z.tz, b.start_at))::date < (timezone(z.tz, now()))::date
         and (timezone(z.tz, b.end_at))::date >= (timezone(z.tz, now()))::date
         and coalesce(pr.presence, 'expected') = 'expected'
       )
     )
     and (
       q.needle is null
       or strpos(lower(coalesce(c.name, '')), lower(q.needle)) > 0
       or b.ref::text = q.needle
       or exists (
         select 1 from public.booking_pets bp2
           join public.pets p2 on p2.id = bp2.pet_id
          where bp2.booking_id = b.id
            and strpos(lower(p2.name), lower(q.needle)) > 0
       )
     )
   order by b.start_at
   limit 200;
$$;


ALTER FUNCTION "public"."yipyy_go_arrivals"("p_facility_id" "uuid", "p_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."yipyy_go_form_state"("p_booking_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings;
begin
  select * into v_booking from public.bookings where id = p_booking_id;
  if not found
     or not (
       private.yipyy_go_is_owner(v_booking.client_id)
       or private.has_permission(v_booking.facility_id, 'view_bookings')
     )
  then
    raise exception 'That booking is not yours.' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'requirement', private.yipyy_go_requirement(v_booking.facility_id, v_booking.service),
    'deadline', private.yipyy_go_deadline(p_booking_id),
    'pets', coalesce((
      select jsonb_agg(jsonb_build_object(
               'petId', p.id,
               'petRef', p.ref,
               'petName', p.name,
               'status', coalesce(y.status, 'not_started'),
               'editable', coalesce(private.yipyy_go_editable(p_booking_id, y.status), false)
             ) order by p.name)
        from public.booking_pets bp
        join public.pets p on p.id = bp.pet_id
        left join public.yipyy_go_submissions y
          on y.booking_id = bp.booking_id and y.pet_id = bp.pet_id
       where bp.booking_id = p_booking_id
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."yipyy_go_form_state"("p_booking_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."yipyy_go_offered_add_ons"("p_booking_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking public.bookings;
begin
  select * into v_booking from public.bookings where id = p_booking_id;
  if not found
     or not (
       private.yipyy_go_is_owner(v_booking.client_id)
       or private.has_permission(v_booking.facility_id, 'view_bookings')
     )
  then
    raise exception 'That booking is not yours.' using errcode = '42501';
  end if;

  if private.yipyy_go_requirement(v_booking.facility_id, v_booking.service) is null then
    return '[]'::jsonb;
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', o.offer ->> 'id',
             'name', o.offer ->> 'name',
             'description', o.offer ->> 'description',
             'pricingType', o.offer ->> 'pricingType',
             'unitPrice', pr.unit_price,
             'unitLabel', o.offer ->> 'unitLabel',
             'maxQuantity', (o.offer ->> 'maxQuantity')::int,
             'petScope', o.offer ->> 'petScope'
           ) order by o.ord)
      from (
        select private.yipyy_go_offered_add_on(v_booking, ids.id) as offer, ids.ord
          from (
            select g.id::text as id, g.display_order::bigint as ord
              from public.grooming_add_ons g
             where v_booking.service = 'grooming'
               and g.facility_id = v_booking.facility_id
               and g.is_active
            union all
            select a.value ->> 'id', a.ordinality
              from public.facility_settings s
              cross join lateral jsonb_array_elements(
                case when jsonb_typeof(s.value -> 'addOns') = 'array' then s.value -> 'addOns' else '[]'::jsonb end
              ) with ordinality a(value, ordinality)
             where v_booking.service <> 'grooming'
               and s.facility_id = v_booking.facility_id
               and s.domain = 'service_addons'
          ) ids
      ) o
      cross join lateral private.yipyy_go_price_add_on(v_booking, o.offer, 1) pr
     where o.offer is not null
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."yipyy_go_offered_add_ons"("p_booking_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."yipyy_go_staff_recipients"("p_submission_id" "uuid") RETURNS TABLE("email" "text", "full_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select distinct p.email::text, p.full_name::text
    from public.yipyy_go_submissions y
    join public.facility_memberships m
      on m.facility_id = y.facility_id
     and m.is_active
     and m.role::text in ('owner', 'admin')
    join public.profiles p on p.id::text = m.profile_id::text
   where y.id = p_submission_id
     and y.status = 'submitted'
     and p.email is not null
     and btrim(p.email::text) <> '';
$$;


