);

ALTER TABLE ONLY "public"."audit_log" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."audit_log" OWNER TO "postgres";


COMMENT ON TABLE "public"."audit_log" IS 'Immutable, append-only audit trail. UPDATE/DELETE/TRUNCATE are blocked for EVERY role by trigger. Entries are written only by private.record_audit().';



COMMENT ON COLUMN "public"."audit_log"."occurred_at" IS 'clock_timestamp(), not now(): several entries can be written in one transaction (provisioning writes three) and the order between them is load-bearing.';



COMMENT ON COLUMN "public"."audit_log"."facility_id" IS 'Which facility the event happened at. DESCRIPTIVE, not referential: no foreign key, deliberately, so an entry outlives the facility it describes — see facility_name beside it. An audit trail that could be nulled by a cascade would lose the fact it exists to keep.';



CREATE TABLE IF NOT EXISTS "public"."automation_events" (
    "id" bigint NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "kind" "text" NOT NULL,
    "occurred_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "client_id" "uuid",
    "pet_id" "uuid",
    "booking_id" "uuid",
    "location_id" "uuid",
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "dedupe_key" "text" NOT NULL,
    "processed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "automation_events_kind_check" CHECK (("kind" = ANY (ARRAY['booking_created'::"text", 'booking_cancelled'::"text", 'booking_request_submitted'::"text", 'booking_request_approved'::"text", 'booking_request_declined'::"text", '24h_before'::"text", 'check_in'::"text", 'check_out'::"text", 'payment_received'::"text", 'payment_overdue'::"text", 'vaccination_expiry'::"text", 'appointment_reminder'::"text", 'form_link_sent'::"text", 'form_started'::"text", 'form_submitted'::"text", 'form_incomplete_by_deadline'::"text", 'form_red_flag_answer'::"text", 'booking_abandoned'::"text", 'package_expiry'::"text"])))
);


ALTER TABLE "public"."automation_events" OWNER TO "postgres";


COMMENT ON TABLE "public"."automation_events" IS 'Domain events that automations react to. Claimed via processed_at + FOR UPDATE SKIP LOCKED. Not an audit trail.';



ALTER TABLE "public"."automation_events" ALTER COLUMN "id" ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME "public"."automation_events_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);



CREATE TABLE IF NOT EXISTS "public"."automation_rules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "trigger" "text" NOT NULL,
    "enabled" boolean DEFAULT false NOT NULL,
    "email_template_id" "uuid",
    "sms_template_id" "uuid",
    "service_types" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "location_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "min_amount" numeric(12,2),
    "offset_minutes" integer,
    "cooldown_days" smallint DEFAULT 0 NOT NULL,
    "is_transactional" boolean DEFAULT false NOT NULL,
    "created_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "seed_key" "text",
    CONSTRAINT "automation_rules_cooldown_days_check" CHECK (("cooldown_days" >= 0)),
    CONSTRAINT "automation_rules_name_check" CHECK (("btrim"("name") <> ''::"text")),
    CONSTRAINT "automation_rules_needs_a_template" CHECK ((("email_template_id" IS NOT NULL) OR ("sms_template_id" IS NOT NULL))),
    CONSTRAINT "automation_rules_trigger_check" CHECK (("trigger" = ANY (ARRAY['booking_created'::"text", 'booking_cancelled'::"text", 'booking_request_submitted'::"text", 'booking_request_approved'::"text", 'booking_request_declined'::"text", '24h_before'::"text", 'check_in'::"text", 'check_out'::"text", 'payment_received'::"text", 'payment_overdue'::"text", 'vaccination_expiry'::"text", 'appointment_reminder'::"text", 'form_link_sent'::"text", 'form_started'::"text", 'form_submitted'::"text", 'form_incomplete_by_deadline'::"text", 'form_red_flag_answer'::"text", 'booking_abandoned'::"text", 'package_expiry'::"text"])))
);


ALTER TABLE "public"."automation_rules" OWNER TO "postgres";


COMMENT ON TABLE "public"."automation_rules" IS 'Event-driven customer messaging. NOT the tag-reaction rule in src/types/tags.ts, which was also called AutomationRule until 2026-08-27 and is now TagAutomationRule.';



COMMENT ON COLUMN "public"."automation_rules"."seed_key" IS 'Stable handle for a rule Yipyy ships. NULL for a facility''s own. Idempotency for ensure_automation_rules - never the name, which the user may change.';



