ALTER TABLE "public"."boarding_services" OWNER TO "postgres";


COMMENT ON TABLE "public"."boarding_services" IS 'The boarding menu: what a client books and what it costs. Separate from room_categories, which is the ROOM. A service names the lodging types it may be booked into; empty means all of them.';



COMMENT ON COLUMN "public"."boarding_services"."unit" IS 'MoeGo "Unit" — per night (the gap between dates) or per day (the dates themselves). Monday to Wednesday is 2 nights or 3 days.';



COMMENT ON COLUMN "public"."boarding_services"."lodging_type_ids" IS 'room_categories this service may be booked into. Empty = every type. Not an FK: Postgres cannot reference array elements, so a deleted type leaves a dead id the app must filter rather than trust.';



CREATE TABLE IF NOT EXISTS "public"."boarding_stays" (
    "booking_id" "uuid" NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "room_id" "uuid" NOT NULL,
    "occupies" "tstzrange" NOT NULL,
    "released_at" timestamp with time zone,
    "override_reason" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "checked_in_at" timestamp with time zone,
    "checked_out_at" timestamp with time zone,
    "status" "text" GENERATED ALWAYS AS (
CASE
    WHEN ("checked_out_at" IS NOT NULL) THEN 'checked-out'::"text"
    WHEN ("checked_in_at" IS NOT NULL) THEN 'checked-in'::"text"
    WHEN ("released_at" IS NOT NULL) THEN 'released'::"text"
    ELSE 'scheduled'::"text"
END) STORED,
    "space_type" "public"."lodging_space_type" DEFAULT 'room'::"public"."lodging_space_type" NOT NULL,
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "segment_order" integer DEFAULT 1 NOT NULL,
    CONSTRAINT "boarding_stay_leaves_after_arriving" CHECK ((("checked_out_at" IS NULL) OR (("checked_in_at" IS NOT NULL) AND ("checked_out_at" >= "checked_in_at")))),
    CONSTRAINT "boarding_stay_occupies_forward" CHECK (((NOT "isempty"("occupies")) AND ("lower"("occupies") < "upper"("occupies")))),
    CONSTRAINT "boarding_stay_segment_order_positive" CHECK (("segment_order" >= 1)),
    CONSTRAINT "boarding_stays_override_reason_check" CHECK ((("override_reason" IS NULL) OR ("length"(TRIM(BOTH FROM "override_reason")) >= 3)))
);


ALTER TABLE "public"."boarding_stays" OWNER TO "postgres";


COMMENT ON COLUMN "public"."boarding_stays"."checked_in_at" IS 'When the guest actually arrived, as against occupies, which is when the kennel was booked from. A late arrival does not move the reservation.';



COMMENT ON COLUMN "public"."boarding_stays"."status" IS 'Derived, never written. A stay that has been checked in reads checked-in even once released_at is set: a cancelled booking whose dog is on site is still a dog on site, and it must stay on the board.';



COMMENT ON COLUMN "public"."boarding_stays"."space_type" IS 'Copied from the room category by private.boarding_stay_space_type(). Here so boarding_stay_no_double_booking can be predicated on it — an exclusion constraint cannot join.';



COMMENT ON COLUMN "public"."boarding_stays"."id" IS 'The stay''s own key. A booking holds one stay today and, once a stay can be split, several in sequence.';



COMMENT ON COLUMN "public"."boarding_stays"."segment_order" IS 'This stay''s place in its booking, from 1. Arrival and departure are stamped on segment 1 only.';



CREATE TABLE IF NOT EXISTS "public"."booking_commission_allocations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "booking_id" "uuid" NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "staff_id" "uuid" NOT NULL,
    "basis" numeric(10,2) NOT NULL,
    "rate" numeric(6,3) NOT NULL,
    "paid_share" numeric(6,4) NOT NULL,
    "amount" numeric(10,2) NOT NULL,
    "source" "text" DEFAULT 'auto'::"text" NOT NULL,
    "paid_at" timestamp with time zone,
    "paid_by" "uuid",
    "payout_note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "booking_commission_allocations_amount_check" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "booking_commission_allocations_basis_check" CHECK (("basis" >= (0)::numeric)),
    CONSTRAINT "booking_commission_allocations_paid_share_check" CHECK ((("paid_share" >= (0)::numeric) AND ("paid_share" <= (1)::numeric))),
    CONSTRAINT "booking_commission_allocations_rate_check" CHECK ((("rate" >= (0)::numeric) AND ("rate" <= (100)::numeric))),
    CONSTRAINT "booking_commission_allocations_source_check" CHECK (("source" = ANY (ARRAY['auto'::"text", 'manual'::"text"])))
);


ALTER TABLE "public"."booking_commission_allocations" OWNER TO "postgres";


COMMENT ON TABLE "public"."booking_commission_allocations" IS 'What each member of staff earned on a booking. Service only, net of discounts, before tax, in proportion to what was paid — service charges and every other extra are excluded by construction. Derived by private.derive_booking_commission() unless source = manual.';



COMMENT ON COLUMN "public"."booking_commission_allocations"."basis" IS 'The SERVICE this commission was worked out on: total_cost less the service''s OWN share of the discount, weighed by total_cost / (total_cost + extras_total). Service charges are never commissionable revenue — they appear in that weight and nowhere else. Proportional since 20260924110000, to agree with how the same discount lowers the taxable base.';



COMMENT ON COLUMN "public"."booking_commission_allocations"."paid_share" IS 'How much of the bill had been paid. 1.0000 is settled in full.';



