CREATE TABLE IF NOT EXISTS "public"."training_attendance" (
    "booking_id" "uuid" NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "checked_in_at" timestamp with time zone,
    "checked_out_at" timestamp with time zone,
    "status" "text" GENERATED ALWAYS AS (
CASE
    WHEN ("checked_out_at" IS NOT NULL) THEN 'checked-out'::"text"
    WHEN ("checked_in_at" IS NOT NULL) THEN 'checked-in'::"text"
    ELSE 'scheduled'::"text"
END) STORED,
    "session_notes" "text" DEFAULT ''::"text" NOT NULL,
    "author_name" "text",
    "created_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "mark" "text",
    "exercises" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "conditions" "jsonb",
    CONSTRAINT "training_attendance_conditions_are_known" CHECK ("private"."training_session_conditions_are_valid"("conditions")),
    CONSTRAINT "training_attendance_exercises_are_ratings" CHECK ("private"."training_exercise_ratings_are_valid"("exercises")),
    CONSTRAINT "training_attendance_mark_agrees_with_the_times" CHECK ((("mark" IS NULL) OR (("mark" = 'late'::"text") AND ("checked_in_at" IS NOT NULL)) OR (("mark" = ANY (ARRAY['absent'::"text", 'excused'::"text"])) AND ("checked_in_at" IS NULL) AND ("checked_out_at" IS NULL)))),
    CONSTRAINT "training_attendance_mark_is_known" CHECK ((("mark" IS NULL) OR ("mark" = ANY (ARRAY['late'::"text", 'absent'::"text", 'excused'::"text"])))),
    CONSTRAINT "training_attendance_no_conditions_without_the_dog" CHECK ((("mark" IS NULL) OR ("mark" = 'late'::"text") OR ("conditions" IS NULL))),
    CONSTRAINT "training_attendance_no_exercises_without_the_dog" CHECK ((("mark" IS NULL) OR ("mark" = 'late'::"text") OR ("exercises" = '[]'::"jsonb"))),
    CONSTRAINT "training_leaves_after_arriving" CHECK ((("checked_out_at" IS NULL) OR (("checked_in_at" IS NOT NULL) AND ("checked_out_at" >= "checked_in_at"))))
);


ALTER TABLE "public"."training_attendance" OWNER TO "postgres";


COMMENT ON TABLE "public"."training_attendance" IS 'Who turned up to a training session. One row per BOOKING, like daycare and boarding — a booking is already per-pet, and attendance is a fact about a dog arriving rather than about a class happening.';



COMMENT ON COLUMN "public"."training_attendance"."mark" IS 'What the times cannot say: late (checked in after the start), absent (did not come) or excused (did not come, and the owner said). Null for a dog that simply came.';



COMMENT ON COLUMN "public"."training_attendance"."exercises" IS 'The exercises this dog did in this session and how it did: [{"exerciseName": text, "rating": 1-5}]. Empty for an absence.';



COMMENT ON COLUMN "public"."training_attendance"."conditions" IS 'What the dog worked through in this session: {"weather": [sunny|cloudy|rain|hot|cold|windy], "distractionLevel": low|medium|high}. Null when nobody said, and for an absence.';



CREATE OR REPLACE VIEW "public"."booking_presence" WITH ("security_invoker"='true') AS
 SELECT "b"."id" AS "booking_id",
    "b"."service" AS "source",
    COALESCE("g"."check_in_at", "d"."checked_in_at", "s"."checked_in_at", "t"."checked_in_at") AS "arrived_at",
    COALESCE("g"."check_out_at", "d"."checked_out_at", "s"."checked_out_at", "t"."checked_out_at") AS "departed_at",
        CASE
            WHEN ("b"."service" <> ALL (ARRAY['grooming'::"text", 'daycare'::"text", 'boarding'::"text", 'training'::"text"])) THEN 'unknown'::"text"
            WHEN (COALESCE("g"."check_out_at", "d"."checked_out_at", "s"."checked_out_at", "t"."checked_out_at") IS NOT NULL) THEN 'departed'::"text"
            WHEN (COALESCE("g"."check_in_at", "d"."checked_in_at", "s"."checked_in_at", "t"."checked_in_at") IS NOT NULL) THEN 'on-site'::"text"
            ELSE 'expected'::"text"
        END AS "presence"
   FROM (((("public"."bookings" "b"
     LEFT JOIN "public"."grooming_appointments" "g" ON (("g"."booking_id" = "b"."id")))
     LEFT JOIN "public"."daycare_attendance" "d" ON (("d"."booking_id" = "b"."id")))
     LEFT JOIN "public"."boarding_stays" "s" ON ((("s"."booking_id" = "b"."id") AND ("s"."segment_order" = 1))))
     LEFT JOIN "public"."training_attendance" "t" ON (("t"."booking_id" = "b"."id")));


ALTER VIEW "public"."booking_presence" OWNER TO "postgres";


COMMENT ON VIEW "public"."booking_presence" IS 'Is this pet here, and since when — derived from whichever table owns the answer for the service. security_invoker, so a row is visible only to somebody who could already read the booking. presence = unknown means the service has no attendance table (custom modules); expected means it has one and nobody has arrived yet.';



CREATE TABLE IF NOT EXISTS "public"."booking_tip_allocations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "booking_id" "uuid" NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "staff_id" "uuid" NOT NULL,
    "amount" numeric(10,2) NOT NULL,
    "method" "text" NOT NULL,
    "author_name" "text",
    "created_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "source" "text" DEFAULT 'manual'::"text" NOT NULL,
    "paid_at" timestamp with time zone,
