    CONSTRAINT "booking_tip_allocations_method_check" CHECK (("method" = ANY (ARRAY['by_service'::"text", 'equal'::"text", 'custom_percent'::"text", 'custom_amount'::"text", 'auto_assigned'::"text", 'auto_split'::"text"]))),
    CONSTRAINT "booking_tip_allocations_source_check" CHECK (("source" = ANY (ARRAY['auto'::"text", 'manual'::"text"])))
);


