CREATE OR REPLACE VIEW "public"."booking_yipyy_go" WITH ("security_invoker"='true') AS
 SELECT "b"."id" AS "booking_id",
    "r"."requirement",
    "pets"."total" AS "pets_total",
    COALESCE("sub"."satisfied", 0) AS "pets_satisfied",
    (("r"."requirement" IS NULL) OR (("pets"."total" > 0) AND (COALESCE("sub"."satisfied", 0) >= "pets"."total"))) AS "satisfied",
        CASE
            WHEN ("r"."requirement" IS NULL) THEN 'not_required'::"text"
            WHEN (COALESCE("sub"."total", 0) = 0) THEN 'not_started'::"text"
            WHEN (COALESCE("sub"."changes", 0) > 0) THEN 'changes_requested'::"text"
            WHEN (("pets"."total" > 0) AND (COALESCE("sub"."approved", 0) >= "pets"."total")) THEN 'approved'::"text"
            WHEN (("pets"."total" > 0) AND (COALESCE("sub"."satisfied", 0) >= "pets"."total")) THEN 'submitted'::"text"
            ELSE 'in_progress'::"text"
        END AS "status"
   FROM (((("public"."bookings" "b"
     LEFT JOIN "public"."facility_settings" "s" ON ((("s"."facility_id" = "b"."facility_id") AND ("s"."domain" = 'yipyy_go_config'::"text"))))
     CROSS JOIN LATERAL ( SELECT
                CASE
                    WHEN COALESCE((("s"."value" ->> 'enabled'::"text"))::boolean, false) THEN ( SELECT ("sc"."value" ->> 'requirement'::"text")
                       FROM "jsonb_array_elements"(COALESCE(("s"."value" -> 'serviceConfigs'::"text"), '[]'::"jsonb")) "sc"("value")
                      WHERE ((("sc"."value" ->> 'serviceType'::"text") = "b"."service") AND COALESCE((("sc"."value" ->> 'enabled'::"text"))::boolean, false) AND (("sc"."value" ->> 'requirement'::"text") = ANY (ARRAY['mandatory'::"text", 'optional'::"text"])))
                     LIMIT 1)
                    ELSE NULL::"text"
                END AS "requirement") "r")
     CROSS JOIN LATERAL ( SELECT ("count"(*))::integer AS "total"
           FROM "public"."booking_pets" "bp"
          WHERE ("bp"."booking_id" = "b"."id")) "pets")
     LEFT JOIN LATERAL ( SELECT ("count"(*))::integer AS "total",
            ("count"(*) FILTER (WHERE ("y"."status" = ANY (ARRAY['submitted'::"text", 'approved'::"text", 'completed_by_staff'::"text"]))))::integer AS "satisfied",
            ("count"(*) FILTER (WHERE ("y"."status" = ANY (ARRAY['approved'::"text", 'completed_by_staff'::"text"]))))::integer AS "approved",
            ("count"(*) FILTER (WHERE ("y"."status" = 'changes_requested'::"text")))::integer AS "changes"
           FROM "public"."yipyy_go_submissions" "y"
          WHERE ("y"."booking_id" = "b"."id")) "sub" ON (true));


ALTER VIEW "public"."booking_yipyy_go" OWNER TO "postgres";


COMMENT ON VIEW "public"."booking_yipyy_go" IS 'Where each booking stands on its pre-arrival form: whether the facility asks for one (requirement), how many of its pets have one that counts (submitted, approved or completed by staff), and one status for the booking. SECURITY INVOKER — the bookings, settings and submissions policies decide what comes back.';



