    CONSTRAINT "estimates_service_check" CHECK (("btrim"("service") <> ''::"text")),
    CONSTRAINT "estimates_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'sent'::"text", 'accepted'::"text", 'declined'::"text", 'expired'::"text", 'converted'::"text"]))),
    CONSTRAINT "estimates_subtotal_check" CHECK (("subtotal" >= (0)::numeric)),
    CONSTRAINT "estimates_tax_amount_check" CHECK (("tax_amount" >= (0)::numeric)),
