    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "org_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "slug" "text" NOT NULL,
    "timezone" "text" DEFAULT 'America/New_York'::"text" NOT NULL,
    "legacy_id" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "allow_customer_signup" boolean DEFAULT false NOT NULL,
    "business_types" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "email" "text",
    "phone" "text",
    "website" "text",
    "description" "text",
    "logo_url" "text",
    "address" "jsonb",
    "social_media" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "preferences" "jsonb" DEFAULT '{"weightUnit": "lbs", "clockFormat": "12h", "temperatureUnit": "celsius"}'::"jsonb" NOT NULL,
    "archived_at" timestamp with time zone,
    CONSTRAINT "facilities_slug_is_a_dns_label" CHECK (("slug" ~ '^[a-z0-9]([a-z0-9-]{1,48}[a-z0-9])?$'::"text")),
    CONSTRAINT "facilities_slug_not_reserved" CHECK (("slug" <> ALL (ARRAY['www'::"text", 'app'::"text", 'api'::"text", 'admin'::"text", 'dashboard'::"text", 'clerk'::"text", 'status'::"text", 'accounts'::"text", 'hq'::"text", 'sign-in'::"text", 'sign-up'::"text", 'sso-callback'::"text", 'book'::"text", 'review'::"text", 'forms'::"text", 'onboard'::"text", 'setup'::"text", 'profile'::"text", 'customer'::"text", 'facility'::"text", 'employee'::"text", 'groomer'::"text", 'staff'::"text", 'mail'::"text", 'smtp'::"text", 'ftp'::"text", 'cdn'::"text", 'static'::"text", 'assets'::"text", 'support'::"text", 'help'::"text", 'billing'::"text", 'docs'::"text", 'blog'::"text", 'test'::"text", 'staging'::"text", 'dev'::"text", 'internal'::"text"])))
);


ALTER TABLE "public"."facilities" OWNER TO "postgres";


COMMENT ON COLUMN "public"."facilities"."address" IS 'street, city, state, zipCode, country - one object because it is always read and written together.';



COMMENT ON COLUMN "public"."facilities"."preferences" IS 'clockFormat 12h|24h, weightUnit lbs|kg, temperatureUnit celsius|fahrenheit.';



COMMENT ON COLUMN "public"."facilities"."archived_at" IS 'When set, this facility is kept out of the platform facility list and the
staff facility switcher. It is NOT a delete and not a permission: every row the
facility owns is untouched, RLS is unchanged, its own subdomain keeps answering,
and clearing the column brings it straight back.

WHY IT EXISTS (2026-09-20). The ask was to remove three of four facilities and
keep only Doggieville Mtl for client testing. The database refuses that by
design: payments, loyalty_transactions, gift_card_transactions,
store_credit_entries and retail_sales are all append-only by trigger, AND
payments holds a foreign key to facilities. So a facility that has ever taken
money can neither be deleted (the FK holds it) nor merged into another (the
ledger refuses the UPDATE) without switching off the financial-integrity
triggers. Hiding it is the honest version of the request, and it keeps the
e2e suite''s own facility alive while the client sees one business.';



