CREATE TABLE IF NOT EXISTS "public"."form_versions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "form_id" "uuid" NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "version_number" integer NOT NULL,
    "schema" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "published_at" timestamp with time zone,
    "created_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "form_versions_version_number_check" CHECK (("version_number" > 0))
);


ALTER TABLE "public"."form_versions" OWNER TO "postgres";


COMMENT ON TABLE "public"."form_versions" IS 'An immutable snapshot of a form''s questions. Once `published_at` is set nothing on the row may change - a submission names the version it was filled against, and the questions must still be readable years later.';



COMMENT ON COLUMN "public"."form_versions"."schema" IS 'The WHOLE definition: sections, fields, options, logic. One document because it is authored and rendered as one, and because a normalised field table would give answers a foreign key into a mutable definition.';



CREATE OR REPLACE VIEW "public"."form_versions_current" WITH ("security_invoker"='true') AS
 SELECT DISTINCT ON ("form_id", ("published_at" IS NOT NULL)) "id",
    "form_id",
    "facility_id",
    "version_number",
    "schema",
    "published_at",
    "created_by",
    "created_at"
   FROM "public"."form_versions" "v"
  ORDER BY "form_id", ("published_at" IS NOT NULL), "version_number" DESC;


ALTER VIEW "public"."form_versions_current" OWNER TO "postgres";


COMMENT ON VIEW "public"."form_versions_current" IS 'At most two rows per form: the highest-numbered published version and the highest-numbered draft. security_invoker, so form_versions RLS still applies.';



