CREATE TABLE IF NOT EXISTS "public"."grooming_appointment_history" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "booking_id" "uuid" NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "kind" "text" NOT NULL,
    "description" "text",
    "field" "text",
    "before_value" "text",
    "after_value" "text",
    "author_name" "text" DEFAULT 'Staff'::"text" NOT NULL,
    "created_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "grooming_appointment_history_kind_check" CHECK (("kind" = ANY (ARRAY['event'::"text", 'field_change'::"text"]))),
    CONSTRAINT "grooming_history_shape" CHECK (
CASE "kind"
    WHEN 'event'::"text" THEN (("description" IS NOT NULL) AND ("length"("btrim"("description")) > 0) AND ("field" IS NULL) AND ("before_value" IS NULL) AND ("after_value" IS NULL))
    WHEN 'field_change'::"text" THEN (("field" IS NOT NULL) AND ("length"("btrim"("field")) > 0) AND ("description" IS NULL))
    ELSE NULL::boolean
END)
);

ALTER TABLE ONLY "public"."grooming_appointment_history" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."grooming_appointment_history" OWNER TO "postgres";


COMMENT ON TABLE "public"."grooming_appointment_history" IS 'Immutable, append-only history of a grooming appointment. UPDATE/DELETE/TRUNCATE are blocked for EVERY role by trigger. Holds identifiers rather than foreign keys — see Decision 2 in 20260806160000.';



COMMENT ON COLUMN "public"."grooming_appointment_history"."booking_id" IS 'The appointment this entry describes. No foreign key, deliberately: the trail outlives the booking, which is what makes it an audit trail rather than a detail-page field. RESTRICT was added at some point and made a groomed booking undeletable.';



COMMENT ON COLUMN "public"."grooming_appointment_history"."facility_id" IS 'Whose salon it was. No foreign key, for the same reason as booking_id — and it is still what grooming_history_read gates on, which is a value comparison and needs no referenced row.';



