CREATE TABLE IF NOT EXISTS "public"."grooming_waitlist_entries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "legacy_id" "text",
    "client_id" "uuid",
    "pet_id" "uuid",
    "pet_name" "text" NOT NULL,
    "pet_breed" "text" DEFAULT ''::"text" NOT NULL,
    "owner_name" "text" NOT NULL,
    "owner_phone" "text" DEFAULT ''::"text" NOT NULL,
    "owner_email" "text",
    "service_id" "uuid",
    "service_name" "text" NOT NULL,
    "anchor_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "expected_date_kind" "text" NOT NULL,
    "expected_date" "date",
    "expected_days_of_week" smallint[],
    "expected_start_date" "date",
    "expected_end_date" "date",
    "excluded_dates" "date"[] DEFAULT '{}'::"date"[] NOT NULL,
    "expected_time_kind" "text" DEFAULT 'anytime'::"text" NOT NULL,
    "expected_period" "text",
    "expected_time" time without time zone,
    "preferred_staff_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "valid_until" "date",
    "postal_code" "text",
    "source" "text" DEFAULT 'manual'::"text" NOT NULL,
    "comment" "text",
    "status" "text" DEFAULT 'waiting'::"text" NOT NULL,
    "offer_window_minutes" integer DEFAULT 240 NOT NULL,
    "offered_at" timestamp with time zone,
    "offered_until" timestamp with time zone,
    "offered_slot" "text",
    "added_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "grooming_waitlist_date_shape" CHECK (
CASE "expected_date_kind"
    WHEN 'asap'::"text" THEN (("expected_date" IS NULL) AND ("expected_days_of_week" IS NULL) AND ("expected_start_date" IS NULL) AND ("expected_end_date" IS NULL))
    WHEN 'specific-date'::"text" THEN (("expected_date" IS NOT NULL) AND ("expected_days_of_week" IS NULL) AND ("expected_start_date" IS NULL) AND ("expected_end_date" IS NULL))
    WHEN 'day-of-week'::"text" THEN (("expected_date" IS NULL) AND ("expected_days_of_week" IS NOT NULL) AND ("array_length"("expected_days_of_week", 1) > 0) AND ("expected_start_date" IS NULL) AND ("expected_end_date" IS NULL))
    WHEN 'range'::"text" THEN (("expected_date" IS NULL) AND ("expected_days_of_week" IS NULL) AND ("expected_start_date" IS NOT NULL) AND ("expected_end_date" IS NOT NULL) AND ("expected_end_date" >= "expected_start_date"))
    ELSE NULL::boolean
END),
    CONSTRAINT "grooming_waitlist_dow_domain" CHECK ((("expected_days_of_week" IS NULL) OR ("expected_days_of_week" <@ ARRAY[(0)::smallint, (1)::smallint, (2)::smallint, (3)::smallint, (4)::smallint, (5)::smallint, (6)::smallint]))),
    CONSTRAINT "grooming_waitlist_entries_expected_date_kind_check" CHECK (("expected_date_kind" = ANY (ARRAY['asap'::"text", 'specific-date'::"text", 'day-of-week'::"text", 'range'::"text"]))),
    CONSTRAINT "grooming_waitlist_entries_expected_period_check" CHECK (("expected_period" = ANY (ARRAY['morning'::"text", 'afternoon'::"text", 'evening'::"text"]))),
    CONSTRAINT "grooming_waitlist_entries_expected_time_kind_check" CHECK (("expected_time_kind" = ANY (ARRAY['anytime'::"text", 'period'::"text", 'exact-time'::"text"]))),
    CONSTRAINT "grooming_waitlist_entries_offer_window_minutes_check" CHECK (("offer_window_minutes" > 0)),
    CONSTRAINT "grooming_waitlist_entries_owner_name_check" CHECK (("length"(TRIM(BOTH FROM "owner_name")) > 0)),
    CONSTRAINT "grooming_waitlist_entries_pet_name_check" CHECK (("length"(TRIM(BOTH FROM "pet_name")) > 0)),
    CONSTRAINT "grooming_waitlist_entries_service_name_check" CHECK (("length"(TRIM(BOTH FROM "service_name")) > 0)),
    CONSTRAINT "grooming_waitlist_entries_source_check" CHECK (("source" = ANY (ARRAY['manual'::"text", 'calendar-plus'::"text", 'moved-from-appointment'::"text", 'online-booking'::"text", 'intake-form'::"text"]))),
    CONSTRAINT "grooming_waitlist_entries_status_check" CHECK (("status" = ANY (ARRAY['waiting'::"text", 'offered'::"text", 'confirmed'::"text", 'expired'::"text", 'removed'::"text"]))),
    CONSTRAINT "grooming_waitlist_offer_shape" CHECK ((("status" <> 'offered'::"text") OR (("offered_at" IS NOT NULL) AND ("offered_until" IS NOT NULL)))),
    CONSTRAINT "grooming_waitlist_time_shape" CHECK (
CASE "expected_time_kind"
    WHEN 'anytime'::"text" THEN (("expected_period" IS NULL) AND ("expected_time" IS NULL))
    WHEN 'period'::"text" THEN (("expected_period" IS NOT NULL) AND ("expected_time" IS NULL))
    WHEN 'exact-time'::"text" THEN (("expected_period" IS NULL) AND ("expected_time" IS NOT NULL))
    ELSE NULL::boolean
END)
);


