CREATE TABLE IF NOT EXISTS "public"."loyalty_transactions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "account_id" "uuid" NOT NULL,
    "kind" "text" NOT NULL,
    "points" integer NOT NULL,
    "description" "text" NOT NULL,
    "source" "text" NOT NULL,
    "source_id" "text",
    "booking_id" "uuid",
    "staff_id" "uuid",
    "reason" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "loyalty_transactions_kind_check" CHECK (("kind" = ANY (ARRAY['earned'::"text", 'redeemed'::"text", 'expired'::"text", 'adjusted'::"text", 'referral'::"text"]))),
    CONSTRAINT "loyalty_transactions_points_not_zero" CHECK (("points" <> 0)),
    CONSTRAINT "loyalty_transactions_source_check" CHECK (("source" = ANY (ARRAY['booking'::"text", 'pos'::"text", 'online_payment'::"text", 'membership'::"text", 'package'::"text", 'referral'::"text", 'manual'::"text", 'expiry'::"text"])))
);


ALTER TABLE "public"."loyalty_transactions" OWNER TO "postgres";


COMMENT ON TABLE "public"."loyalty_transactions" IS 'Append-only points ledger. points is signed. UPDATE is refused by trigger and no DELETE policy exists, so an application can only add - correct a mistake by posting the opposite entry. A cascade from the account deletes it, deliberately.';



CREATE OR REPLACE VIEW "public"."loyalty_account_overview" WITH ("security_invoker"='true') AS
 SELECT "a"."id",
    "a"."facility_id",
    "a"."client_id",
    "a"."points_balance",
    "a"."lifetime_points_earned",
    "a"."lifetime_points_redeemed",
    "a"."credit_balance",
    "a"."current_tier_id",
    "a"."tier_joined_at",
    "a"."referral_code",
    "a"."created_at",
    "a"."updated_at",
    "c"."ref" AS "client_ref",
    "c"."name" AS "client_name",
    "c"."email" AS "client_email",
    (COALESCE("spend"."total_spend", (0)::numeric))::numeric(12,2) AS "total_spend",
    (COALESCE("spend"."total_visits", (0)::bigint))::integer AS "total_visits",
    GREATEST("a"."updated_at", COALESCE("activity"."last_at", "a"."created_at")) AS "last_activity_at"
   FROM ((("public"."loyalty_accounts" "a"
     JOIN "public"."clients" "c" ON (("c"."id" = "a"."client_id")))
     LEFT JOIN LATERAL ( SELECT "sum"("b"."amount_paid") AS "total_spend",
            "count"(*) FILTER (WHERE ("b"."amount_paid" > (0)::numeric)) AS "total_visits"
           FROM "public"."bookings" "b"
          WHERE (("b"."client_id" = "a"."client_id") AND ("b"."facility_id" = "a"."facility_id") AND ("b"."amount_paid" > (0)::numeric))) "spend" ON (true))
     LEFT JOIN LATERAL ( SELECT "max"("t"."created_at") AS "last_at"
           FROM "public"."loyalty_transactions" "t"
          WHERE ("t"."account_id" = "a"."id")) "activity" ON (true));


ALTER VIEW "public"."loyalty_account_overview" OWNER TO "postgres";


COMMENT ON VIEW "public"."loyalty_account_overview" IS 'A loyalty account with the facts the members screen asks for. total_spend and total_visits are DERIVED from bookings rather than stored — see the migration. security_invoker, so the caller''s own RLS applies.';



