    "connected_by" "text",
    "connected_at" timestamp with time zone,
    "revoked_at" timestamp with time zone,
    "last_error" "text",
    "last_verified_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "currency" "text",
    "country" "text",
    "last_swept_at" timestamp with time zone,
    CONSTRAINT "payment_connection_connected_is_dated" CHECK ((("status" <> 'connected'::"text") OR ("connected_at" IS NOT NULL))),
    CONSTRAINT "payment_connections_country_check" CHECK ((("country" IS NULL) OR ("country" ~ '^[A-Z]{2}$'::"text"))),
    CONSTRAINT "payment_connections_currency_check" CHECK ((("currency" IS NULL) OR ("currency" ~ '^[A-Z]{3}$'::"text"))),
    CONSTRAINT "payment_connections_environment_check" CHECK (("environment" = ANY (ARRAY['sandbox'::"text", 'production'::"text"]))),
    CONSTRAINT "payment_connections_merchant_id_check" CHECK (("length"(TRIM(BOTH FROM "merchant_id")) > 0)),
    CONSTRAINT "payment_connections_processor_check" CHECK (("processor" = 'clover'::"text")),
    CONSTRAINT "payment_connections_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'connected'::"text", 'revoked'::"text", 'error'::"text"])))
);


ALTER TABLE "public"."payment_connections" OWNER TO "postgres";


COMMENT ON TABLE "public"."payment_connections" IS 'A facility''s own payment-processor account. The non-secret half — tokens live in private.payment_credentials, in Vault. See the header of 20260807660000.';



COMMENT ON COLUMN "public"."payment_connections"."merchant_id" IS 'Clover merchant id. Not a secret — it is in every API path.';



COMMENT ON COLUMN "public"."payment_connections"."public_api_key" IS 'The PUBLIC apiAccessKey (PAKMS). Required in the browser by Clover''s hosted iframe. The private key is never stored here.';



COMMENT ON COLUMN "public"."payment_connections"."currency" IS 'ISO-4217, read from the merchant''s own Clover properties. NULL means not yet asked — never assume USD.';



COMMENT ON COLUMN "public"."payment_connections"."country" IS 'ISO-3166-1 alpha-2, from the merchant record. Decides which Clover estate a production merchant belongs to.';



COMMENT ON COLUMN "public"."payment_connections"."last_swept_at" IS 'High-water mark for the reconciliation sweep. Null means never swept.';



