    "kind" "text" NOT NULL,
    "amount_cents" integer NOT NULL,
    "currency" "text" DEFAULT 'USD'::"text" NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "status" "text" DEFAULT 'created'::"text" NOT NULL,
    "processor_payment_id" "text",
    "device_id" "text",
    "failure_code" "text",
    "failure_message" "text",
    "payment_id" "uuid",
    "created_by" "text",
