    "processor_order_id" "text",
    CONSTRAINT "payment_intent_approved_has_an_id" CHECK ((("status" <> 'approved'::"text") OR ("processor_payment_id" IS NOT NULL))),
    CONSTRAINT "payment_intent_failure_is_explained" CHECK ((("status" <> ALL (ARRAY['declined'::"text", 'failed'::"text"])) OR ("failure_code" IS NOT NULL))),
    CONSTRAINT "payment_intents_amount_cents_check" CHECK (("amount_cents" <> 0)),
    CONSTRAINT "payment_intents_environment_check" CHECK (("environment" = ANY (ARRAY['sandbox'::"text", 'production'::"text"]))),
    CONSTRAINT "payment_intents_kind_check" CHECK (("kind" = ANY (ARRAY['terminal'::"text", 'ecom'::"text", 'refund'::"text"]))),
    CONSTRAINT "payment_intents_processor_check" CHECK (("processor" = 'clover'::"text")),
    CONSTRAINT "payment_intents_status_check" CHECK (("status" = ANY (ARRAY['created'::"text", 'sent'::"text", 'approved'::"text", 'declined'::"text", 'failed'::"text", 'cancelled'::"text", 'expired'::"text"])))
);


ALTER TABLE "public"."payment_intents" OWNER TO "postgres";


COMMENT ON TABLE "public"."payment_intents" IS 'Written BEFORE the processor is called, so a crash mid-charge is recoverable rather than an invisible double charge. See the header of 20260807680000.';



COMMENT ON COLUMN "public"."payment_intents"."amount_cents" IS 'Cents, unlike the dollars in payments: this is the number sent to Clover, and it exists to be compared with what Clover reports.';



COMMENT ON COLUMN "public"."payment_intents"."payment_id" IS 'NULL on an approved intent means money moved and no ledger row was written. That is the condition unreconciled_payments surfaces.';



