    CONSTRAINT "payment_webhook_events_processor_check" CHECK (("processor" = 'clover'::"text")),
    CONSTRAINT "payment_webhook_events_status_check" CHECK (("status" = ANY (ARRAY['received'::"text", 'processed'::"text", 'ignored'::"text", 'failed'::"text"]))),
    CONSTRAINT "payment_webhook_terminal_has_reason" CHECK ((("status" = ANY (ARRAY['received'::"text", 'processed'::"text"])) OR ("outcome" IS NOT NULL)))
);


ALTER TABLE "public"."payment_webhook_events" OWNER TO "postgres";


COMMENT ON TABLE "public"."payment_webhook_events" IS 'Every delivery Clover made, recorded before it is acted on. Evidence of what arrived — never a statement that it was true.';



COMMENT ON COLUMN "public"."payment_webhook_events"."payload" IS 'The delivery verbatim. Keeps a parsing mistake recoverable without asking Clover to resend.';



CREATE TABLE IF NOT EXISTS "public"."payments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "booking_id" "uuid",
    "client_id" "uuid",
    "method" "text" NOT NULL,
    "subtotal" numeric(10,2) NOT NULL,
    "tax" numeric(10,2) DEFAULT 0 NOT NULL,
    "tip" numeric(10,2) DEFAULT 0 NOT NULL,
    "store_credit_applied" numeric(10,2) DEFAULT 0 NOT NULL,
    "package_pass_applied" numeric(10,2) DEFAULT 0 NOT NULL,
    "amount_charged" numeric(10,2) NOT NULL,
    "grand_total" numeric(10,2) NOT NULL,
    "cash_received" numeric(10,2),
    "saved_card_id" "uuid",
    "package_pass_id" "text",
    "receipt_channels" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "author_name" "text" DEFAULT 'Staff'::"text" NOT NULL,
    "created_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "loyalty_discount_applied" numeric(10,2) DEFAULT 0 NOT NULL,
    "processor" "text",
    "processor_payment_id" "text",
    "card_brand" "text",
    "card_last4" "text",
    "auth_code" "text",
    "entry_method" "text",
    "refund_of_payment_id" "uuid",
    "processor_order_id" "text",
    "processor_merchant_id" "text",
    "processor_device_serial" "text",
    "note" "text",
    CONSTRAINT "payments_card_last4_shape" CHECK ((("card_last4" IS NULL) OR ("card_last4" ~ '^[0-9]{4}$'::"text"))),
    CONSTRAINT "payments_cash_shape" CHECK (((("method" = 'cash'::"text") AND ("cash_received" IS NOT NULL) AND ("cash_received" >= "amount_charged")) OR (("method" <> 'cash'::"text") AND ("cash_received" IS NULL)))),
    CONSTRAINT "payments_charge_matches_direction" CHECK (((("grand_total" >= (0)::numeric) AND ("amount_charged" >= (0)::numeric)) OR (("grand_total" < (0)::numeric) AND ("amount_charged" <= (0)::numeric)))),
    CONSTRAINT "payments_charged_is_the_remainder" CHECK (("amount_charged" = ((("grand_total" - "store_credit_applied") - "package_pass_applied") - "loyalty_discount_applied"))),
    CONSTRAINT "payments_credits_are_not_negative" CHECK ((("store_credit_applied" >= (0)::numeric) AND ("package_pass_applied" >= (0)::numeric) AND ("loyalty_discount_applied" >= (0)::numeric))),
    CONSTRAINT "payments_entry_method_check" CHECK ((("entry_method" IS NULL) OR ("entry_method" = ANY (ARRAY['swipe'::"text", 'chip'::"text", 'contactless'::"text", 'keyed'::"text", 'ecom'::"text", 'manual'::"text"])))),
    CONSTRAINT "payments_method_check" CHECK (("method" = ANY (ARRAY['card-on-file'::"text", 'new-card'::"text", 'cash'::"text", 'package-pass'::"text", 'store-credit'::"text", 'terminal'::"text", 'e-transfer'::"text", 'ach'::"text", 'gift-card'::"text"]))),
    CONSTRAINT "payments_processor_check" CHECK ((("processor" IS NULL) OR ("processor" = 'clover'::"text"))),
    CONSTRAINT "payments_processor_pairing" CHECK ((("processor" IS NULL) = ("processor_payment_id" IS NULL))),
    CONSTRAINT "payments_refund_is_negative" CHECK ((("refund_of_payment_id" IS NULL) OR ("grand_total" < (0)::numeric))),
    CONSTRAINT "payments_saved_card_shape" CHECK ((("saved_card_id" IS NULL) OR ("method" = 'card-on-file'::"text"))),
    CONSTRAINT "payments_total_is_its_parts" CHECK (("grand_total" = (("subtotal" + "tax") + "tip")))
);

ALTER TABLE ONLY "public"."payments" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."payments" OWNER TO "postgres";


COMMENT ON TABLE "public"."payments" IS 'Immutable record of money taken. A refund is a NEW row with negative amounts — see Decisions 1 and 2 in 20260806220000. Holds identifiers rather than foreign keys because an immutable table cannot participate in cascades.';



COMMENT ON COLUMN "public"."payments"."loyalty_discount_applied" IS 'Loyalty voucher value consumed by this payment. APPLIED, not nominal — capped at what was owed; see 20260806240000.';



COMMENT ON COLUMN "public"."payments"."processor_payment_id" IS 'Clover''s id for this payment. Unique per processor — a retried webhook cannot create a second row.';



COMMENT ON COLUMN "public"."payments"."card_last4" IS 'Exactly four digits or NULL. Never a masked PAN.';



COMMENT ON COLUMN "public"."payments"."processor_order_id" IS 'Clover''s order id, when one exists. Card-present sales have none: the REST Pay Display API is documented as payment-only and will not accept an order id.';



COMMENT ON COLUMN "public"."payments"."processor_merchant_id" IS 'The merchant that took this money, as it was AT THE TIME. Not read from payment_connections, which describes the merchant a facility uses now.';



COMMENT ON COLUMN "public"."payments"."processor_device_serial" IS 'Which terminal took it. The SERIAL — what X-Clover-Device-Id actually wants — not Clover''s device id.';



COMMENT ON COLUMN "public"."payments"."note" IS 'Why this payment or refund happened, in the operator''s own words. Written at insert and never updated, like every other column here. Null on an ordinary sale, where the line items already say it.';



