ALTER TABLE "public"."review_escalation_events" ALTER COLUMN "id" ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME "public"."review_escalation_events_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);



CREATE TABLE IF NOT EXISTS "public"."review_escalations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "location_id" "uuid",
    "response_id" "uuid" NOT NULL,
    "service_type" "text",
    "state" "text" DEFAULT 'open'::"text" NOT NULL,
    "assignee_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "opened_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "first_response_due_at" timestamp with time zone NOT NULL,
    "acknowledged_at" timestamp with time zone,
    "acknowledged_by" "text",
    "resolve_due_at" timestamp with time zone NOT NULL,
    "resolved_at" timestamp with time zone,
    "resolved_by" "text",
    "resolution_code" "text",
    "resolution_note" "text",
    "breach_notified_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "incident_id" "uuid",
    CONSTRAINT "review_escalations_acknowledged_says_who" CHECK ((("acknowledged_at" IS NULL) = ("acknowledged_by" IS NULL))),
    CONSTRAINT "review_escalations_closed_is_resolved" CHECK ((("state" <> 'closed'::"text") OR ("resolved_at" IS NOT NULL))),
    CONSTRAINT "review_escalations_resolution_code_check" CHECK (("resolution_code" = ANY (ARRAY['contacted_apologised'::"text", 'credit_issued'::"text", 'refunded'::"text", 'policy_change'::"text", 'staff_coached'::"text", 'no_contact_possible'::"text", 'client_satisfied'::"text"]))),
    CONSTRAINT "review_escalations_resolved_says_how" CHECK ((("resolved_at" IS NULL) = ("resolution_code" IS NULL))),
    CONSTRAINT "review_escalations_state_check" CHECK (("state" = ANY (ARRAY['open'::"text", 'acknowledged'::"text", 'in_recovery'::"text", 'resolved'::"text", 'closed'::"text"])))
);


ALTER TABLE "public"."review_escalations" OWNER TO "postgres";


COMMENT ON TABLE "public"."review_escalations" IS 'One recovery ticket per poor rating. The case file; the assignee''s to-do is a linked facility_tasks row.';



COMMENT ON COLUMN "public"."review_escalations"."incident_id" IS 'The incident this complaint turned out to be about, if any. Nullable and set by a person: an escalation is not evidence that something happened, it is evidence somebody is unhappy.';



CREATE TABLE IF NOT EXISTS "public"."review_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "location_id" "uuid",
    "client_id" "uuid" NOT NULL,
    "business_day" "date" NOT NULL,
    "primary_staff_id" "uuid",
    "staff_on_visit" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "service_types" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "booking_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "state" "text" DEFAULT 'scheduled'::"text" NOT NULL,
    "state_changed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "escalation_threshold" smallint DEFAULT 3 NOT NULL,
    "showcase_min" smallint DEFAULT 4 NOT NULL,
    "first_send_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "nudge_due_at" timestamp with time zone,
    "nudge_resolved_at" timestamp with time zone,
    "nudge_outcome" "text",
    "channel" "text",
    "token_hash" "bytea",
    "token_expires_at" timestamp with time zone,
    "source" "text" DEFAULT 'automated'::"text" NOT NULL,
    "requested_by" "text",
    "override_reason" "text",
    "suppress_reason" "text",
    "suppress_stage" "text",
    "suppressed_at" timestamp with time zone,
    "next_eligible_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "review_requests_channel_check" CHECK (("channel" = ANY (ARRAY['email'::"text", 'sms'::"text"]))),
    CONSTRAINT "review_requests_escalation_threshold_check" CHECK ((("escalation_threshold" >= 1) AND ("escalation_threshold" <= 5))),
    CONSTRAINT "review_requests_manual_says_who" CHECK ((("source" <> 'manual'::"text") OR ("requested_by" IS NOT NULL))),
    CONSTRAINT "review_requests_nudge_outcome_check" CHECK (("nudge_outcome" = ANY (ARRAY['backup'::"text", 'share'::"text", 'none'::"text", 'expired'::"text"]))),
    CONSTRAINT "review_requests_nudge_outcome_needs_resolution" CHECK ((("nudge_resolved_at" IS NULL) = ("nudge_outcome" IS NULL))),
    CONSTRAINT "review_requests_showcase_min_check" CHECK ((("showcase_min" >= 1) AND ("showcase_min" <= 5))),
    CONSTRAINT "review_requests_source_check" CHECK (("source" = ANY (ARRAY['automated'::"text", 'manual'::"text", 'report_card'::"text", 'portal'::"text", 'kiosk'::"text"]))),
    CONSTRAINT "review_requests_state_check" CHECK (("state" = ANY (ARRAY['scheduled'::"text", 'sent'::"text", 'delivered'::"text", 'failed'::"text", 'rated'::"text", 'expired'::"text", 'suppressed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "review_requests_suppress_reason_check" CHECK (("suppress_reason" = ANY (ARRAY['opted_out'::"text", 'no_consent'::"text", 'campaign_unregistered'::"text", 'no_channel'::"text", 'invalid_address'::"text", 'hard_bounced'::"text", 'cancelled'::"text", 'refund_open'::"text", 'dispute'::"text", 'cooldown'::"text", 'negative_pause'::"text", 'manual_hold'::"text", 'daily_cap'::"text", 'velocity_cap'::"text"]))),
    CONSTRAINT "review_requests_suppress_stage_check" CHECK (("suppress_stage" = ANY (ARRAY['trigger'::"text", 'send'::"text"]))),
    CONSTRAINT "review_requests_suppressed_says_why" CHECK ((("state" = 'suppressed'::"text") = ("suppress_reason" IS NOT NULL)))
);


ALTER TABLE "public"."review_requests" OWNER TO "postgres";


COMMENT ON TABLE "public"."review_requests" IS 'One ask per visit. The visit is the unique index on (facility, client, location, business_day), not a table - see the header of 20260829090000.';



COMMENT ON COLUMN "public"."review_requests"."primary_staff_id" IS 'Snapshot of who the visit was assigned to, as staff(id). NOT facility_memberships - bookings.assigned_staff_id was repointed in 20260801150000.';



COMMENT ON COLUMN "public"."review_requests"."token_hash" IS 'sha256 of the survey link token. The plaintext exists only in the message that was sent.';



