);


ALTER TABLE "public"."review_response_tags" OWNER TO "postgres";


COMMENT ON TABLE "public"."review_response_tags" IS 'What the client picked. on delete restrict - retiring a tag must not rewrite history.';



CREATE TABLE IF NOT EXISTS "public"."review_responses" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "request_id" "uuid" NOT NULL,
    "rating" smallint NOT NULL,
    "comment" "text",
    "locale" "text",
    "source" "text" NOT NULL,
    "attributed_staff_id" "uuid",
    "pet_id" "uuid",
    "display_consent" boolean DEFAULT false NOT NULL,
    "moderation_state" "text" DEFAULT 'pending'::"text" NOT NULL,
    "showcase_sort_order" integer,
    "showcase_pet_photo_id" "uuid",
    "approved_by" "text",
    "approved_at" timestamp with time zone,
    "public_channel_id" "uuid",
    "public_clicked_at" timestamp with time zone,
    "submitted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "review_responses_approved_says_who" CHECK ((("approved_at" IS NULL) = ("approved_by" IS NULL))),
    CONSTRAINT "review_responses_click_names_a_channel" CHECK ((("public_clicked_at" IS NULL) = ("public_channel_id" IS NULL))),
    CONSTRAINT "review_responses_moderation_state_check" CHECK (("moderation_state" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'live'::"text", 'hidden'::"text", 'rejected'::"text"]))),
    CONSTRAINT "review_responses_rating_check" CHECK ((("rating" >= 1) AND ("rating" <= 5))),
    CONSTRAINT "review_responses_source_check" CHECK (("source" = ANY (ARRAY['sms_link'::"text", 'email_link'::"text", 'report_card'::"text", 'portal'::"text", 'kiosk'::"text", 'staff'::"text"])))
);


ALTER TABLE "public"."review_responses" OWNER TO "postgres";


COMMENT ON TABLE "public"."review_responses" IS 'One response per request, enforced by the unique on request_id. Internal survey ratings ONLY - never averaged with public platform ratings (R-04).';



CREATE TABLE IF NOT EXISTS "public"."review_tags" (
