CREATE TABLE IF NOT EXISTS "public"."room_categories" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "legacy_id" "text" NOT NULL,
    "service" "public"."service_module" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "color" "text" DEFAULT 'slate'::"text" NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "default_capacity" integer DEFAULT 1 NOT NULL,
    "default_base_price" numeric,
    "visible_to_clients" boolean DEFAULT true NOT NULL,
    "image_url" "text",
    "rules" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "taxable" boolean DEFAULT true NOT NULL,
    "space_type" "public"."lodging_space_type" DEFAULT 'room'::"public"."lodging_space_type" NOT NULL,
    "max_pets_per_area" integer,
    CONSTRAINT "room_categories_area_max_pets" CHECK ((("space_type" = 'area'::"public"."lodging_space_type") = ("max_pets_per_area" IS NOT NULL))),
    CONSTRAINT "room_categories_area_max_pets_positive" CHECK ((("max_pets_per_area" IS NULL) OR ("max_pets_per_area" > 0))),
    CONSTRAINT "room_categories_default_base_price_check" CHECK ((("default_base_price" IS NULL) OR ("default_base_price" >= (0)::numeric))),
    CONSTRAINT "room_categories_default_capacity_check" CHECK (("default_capacity" > 0)),
    CONSTRAINT "room_category_rules_are_read" CHECK ((NOT ("rules" @? '$[*]?(!(exists (@."type")) || !((@."type" == "min_weight" || @."type" == "max_weight") || @."type" == "pet_type"))'::"jsonpath"))),
    CONSTRAINT "room_category_rules_is_array" CHECK (("jsonb_typeof"("rules") = 'array'::"text"))
);


ALTER TABLE "public"."room_categories" OWNER TO "postgres";


COMMENT ON COLUMN "public"."room_categories"."default_capacity" IS 'MoeGo "Max # of Pets (same family) per room" — the pets one FAMILY may put in one unit. Not a limit on unrelated bookings: the exclusion constraint already allows only one live stay per room.';



COMMENT ON COLUMN "public"."room_categories"."active" IS 'Whether this category is currently offered. Added for daycare play areas, which close seasonally; boarding categories default to true and nothing turns them off today.';



COMMENT ON COLUMN "public"."room_categories"."taxable" IS 'Whether a boarding stay in this class is charged the facility''s tax. Default true: a class that has never been edited keeps charging tax. See 20260921171524.';



COMMENT ON COLUMN "public"."room_categories"."space_type" IS 'MoeGo Space type. Every row existing before 20260924180000 is a room, which is what boarding_stay_no_double_booking has always assumed.';



COMMENT ON COLUMN "public"."room_categories"."max_pets_per_area" IS 'MoeGo "Max # of pets per area" — pets in the area at once, regardless of family. Null for a room type, and required for an area.';



COMMENT ON CONSTRAINT "room_category_rules_are_read" ON "public"."room_categories" IS 'Only the rule types petMatchesRules reads: min_weight, max_weight, pet_type. single_pet_only and max_pets were default_capacity spelled twice more, and size_restriction was read by nothing (20260925164457).';



CREATE TABLE IF NOT EXISTS "public"."room_category_location_prices" (
