    CONSTRAINT "room_category_location_prices_price_check" CHECK (("price" >= (0)::numeric))
);


ALTER TABLE "public"."room_category_location_prices" OWNER TO "postgres";


COMMENT ON TABLE "public"."room_category_location_prices" IS 'A branch''s own nightly rate for a boarding kennel class, replacing room_categories.default_base_price for that branch only. Overrides only -- there is no facility-wide row in this table.';



CREATE TABLE IF NOT EXISTS "public"."saved_cards" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "client_id" "uuid" NOT NULL,
    "processor" "text" DEFAULT 'clover'::"text" NOT NULL,
    "processor_customer_id" "text" NOT NULL,
    "processor_card_id" "text",
    "card_brand" "text",
    "card_last4" "text",
    "exp_month" smallint,
    "exp_year" smallint,
    "consent_at" timestamp with time zone,
    "consent_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "text",
    "revoked_at" timestamp with time zone,
    CONSTRAINT "saved_cards_consent_complete" CHECK ((("consent_at" IS NULL) = ("consent_by" IS NULL))),
    CONSTRAINT "saved_cards_last4_shape" CHECK ((("card_last4" IS NULL) OR ("card_last4" ~ '^[0-9]{4}$'::"text")))
);

ALTER TABLE ONLY "public"."saved_cards" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."saved_cards" OWNER TO "postgres";


COMMENT ON TABLE "public"."saved_cards" IS 'Cards a customer has consented to Yipyy storing at the processor. Holds only processor identifiers and display metadata - never a card number, which is what keeps this deployment out of PCI scope.';



COMMENT ON COLUMN "public"."saved_cards"."consent_at" IS 'When the cardholder agreed we may charge this card again. Null means the card is NOT chargeable; the charge path checks this rather than trusting the UI.';



COMMENT ON COLUMN "public"."saved_cards"."revoked_at" IS 'A removed card. Never deleted: payments.saved_card_id references these rows and payments is append-only.';



