);


ALTER TABLE "public"."schedule_template_shifts" OWNER TO "postgres";


COMMENT ON COLUMN "public"."schedule_template_shifts"."end_time" IS 'At or before start_time means the shift ends the following day. Night shifts are ordinary.';



