ALTER TABLE "public"."shift_swap_requests" OWNER TO "postgres";


COMMENT ON TABLE "public"."shift_swap_requests" IS 'One offer to trade or hand off a shift. target_shift_id NULL is a hand-off. Approving goes through approve_shift_swap, which moves the shifts in the same transaction.';



CREATE TABLE IF NOT EXISTS "public"."staff_availability" (
    "staff_id" "uuid" NOT NULL,
