);


ALTER TABLE "public"."staff_availability" OWNER TO "postgres";


COMMENT ON TABLE "public"."staff_availability" IS 'When somebody can work, as a weekly pattern. One row per weekday, 0 = Sunday to match Date.getDay(). NULL window while available means all day; available_to <= available_from wraps past midnight.';



