CREATE TABLE IF NOT EXISTS "public"."staff_time_clock_entries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "staff_id" "uuid" NOT NULL,
    "shift_id" "uuid",
    "clocked_in_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "clocked_out_at" timestamp with time zone,
    "source" "public"."time_clock_source" DEFAULT 'self'::"public"."time_clock_source" NOT NULL,
    "notes" "text",
    "minutes_worked" integer GENERATED ALWAYS AS (
CASE
    WHEN ("clocked_out_at" IS NULL) THEN NULL::integer
    ELSE ((EXTRACT(epoch FROM ("clocked_out_at" - "clocked_in_at")) / (60)::numeric))::integer
END) STORED,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "staff_time_clock_out_after_in" CHECK ((("clocked_out_at" IS NULL) OR ("clocked_out_at" > "clocked_in_at")))
);


ALTER TABLE "public"."staff_time_clock_entries" OWNER TO "postgres";


COMMENT ON TABLE "public"."staff_time_clock_entries" IS 'One clock-in, and the clock-out that ended it. clocked_out_at NULL means ON THE CLOCK — the only representation of that state. shift_id is optional because people cover. An exclusion constraint forbids two overlapping sessions for one person, which is also what stops a double clock-in.';



COMMENT ON COLUMN "public"."staff_time_clock_entries"."source" IS 'Who stamped it. Separating "they clocked out" from "a manager closed it for them" is what a pay dispute turns on.';



