    CONSTRAINT "unfinished_bookings_recovery_detail_check" CHECK ((("recovery_detail" IS NULL) OR ("length"("recovery_detail") <= 500))),
    CONSTRAINT "unfinished_bookings_recovery_outcome_check" CHECK ((("recovery_outcome" IS NULL) OR ("recovery_outcome" = ANY (ARRAY['queued'::"text", 'none'::"text", 'skipped'::"text"])))),
    CONSTRAINT "unfinished_bookings_recovery_resolved_together" CHECK ((("recovery_resolved_at" IS NULL) = ("recovery_outcome" IS NULL))),
    CONSTRAINT "unfinished_bookings_service_check" CHECK ((("service" IS NULL) OR ("length"("service") <= 60))),
    CONSTRAINT "unfinished_bookings_status_check" CHECK (("status" = ANY (ARRAY['abandoned'::"text", 'contacted'::"text", 'recovered'::"text"]))),
    CONSTRAINT "unfinished_bookings_step_check" CHECK (("step" = ANY (ARRAY['service_selection'::"text", 'pet_selection'::"text", 'date_and_details'::"text", 'add_ons'::"text", 'forms'::"text", 'review'::"text", 'payment'::"text"])))
);


ALTER TABLE "public"."unfinished_bookings" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."unreconciled_payments" WITH ("security_invoker"='true') AS
 SELECT "i"."id" AS "intent_id",
    "i"."facility_id",
    "f"."name" AS "facility_name",
    "i"."booking_id",
    "i"."client_id",
    "i"."kind",
    "i"."amount_cents",
    "i"."currency",
    "i"."processor",
    "i"."processor_payment_id",
    "i"."environment",
    "i"."created_at",
    "i"."completed_at",
    ("now"() - "i"."completed_at") AS "unreconciled_for"
   FROM ("public"."payment_intents" "i"
     JOIN "public"."facilities" "f" ON (("f"."id" = "i"."facility_id")))
  WHERE (("i"."status" = 'approved'::"text") AND ("i"."payment_id" IS NULL));


ALTER VIEW "public"."unreconciled_payments" OWNER TO "postgres";


COMMENT ON VIEW "public"."unreconciled_payments" IS 'Approved charges with no ledger row: the customer paid and the books do not show it. Should always be empty. security_invoker, so it shows the caller only their own facilities.';



