CREATE TABLE IF NOT EXISTS "public"."waiver_signatures" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "waiver_id" "uuid",
    "client_id" "uuid" NOT NULL,
    "pet_id" "uuid",
    "waiver_name" "text" NOT NULL,
    "waiver_version" "text" NOT NULL,
    "waiver_text" "text" NOT NULL,
    "waiver_hash" "text" NOT NULL,
    "signature_name" "text" NOT NULL,
    "signature_data" "text",
    "witness_name" "text",
    "witness_signature_data" "text",
    "ip_address" "text",
    "user_agent" "text",
    "signed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "signed_by" "text",
    "expires_at" timestamp with time zone,
    "revoked_at" timestamp with time zone,
    "revoked_reason" "text",
    "revoked_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "waiver_signatures_revocation_has_a_reason" CHECK ((("revoked_at" IS NULL) OR ("btrim"(COALESCE("revoked_reason", ''::"text")) <> ''::"text"))),
    CONSTRAINT "waiver_signatures_text_not_empty" CHECK (("btrim"("waiver_text") <> ''::"text"))
);


ALTER TABLE "public"."waiver_signatures" OWNER TO "postgres";


COMMENT ON TABLE "public"."waiver_signatures" IS 'Append-only record of a person agreeing to a waiver. Carries a COPY of the text and its sha256, not a reference to a document that can be edited afterwards. Only `revoked_at`/`revoked_reason`/`revoked_by` may ever change, once.';



COMMENT ON COLUMN "public"."waiver_signatures"."waiver_id" IS 'Which waiver this was. DESCRIPTIVE, not referential: no foreign key, so the signature outlives the document. An append-only table cannot hold `on delete set null` (SET NULL is an UPDATE the guard refuses - see audit_log, 20260822500000) and a cascade would delete the evidence.';



CREATE TABLE IF NOT EXISTS "public"."waivers" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
