CREATE TABLE IF NOT EXISTS "public"."workflows" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "kind" "text" NOT NULL,
    "trigger" "text",
    "audience" "jsonb",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "location_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "frequency" "text",
    "day_of_week" smallint,
    "day_of_month" smallint,
    "send_at_local" time without time zone,
    "min_days_between_sends" smallint DEFAULT 30 NOT NULL,
    "stop_on" "jsonb" DEFAULT '["booked", "unsubscribed"]'::"jsonb" NOT NULL,
    "last_estimate" integer,
    "last_estimated_at" timestamp with time zone,
    "last_run_at" timestamp with time zone,
    "activated_at" timestamp with time zone,
    "activated_by" "text",
    "created_by" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "trigger_filters" "jsonb",
    "service_types" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    CONSTRAINT "workflows_day_of_month_check" CHECK ((("day_of_month" >= 1) AND ("day_of_month" <= 31))),
    CONSTRAINT "workflows_day_of_week_check" CHECK ((("day_of_week" >= 0) AND ("day_of_week" <= 6))),
    CONSTRAINT "workflows_filters_are_for_events" CHECK ((("kind" = 'event'::"text") OR (("trigger_filters" IS NULL) AND ("service_types" = '{}'::"text"[])))),
    CONSTRAINT "workflows_frequency_check" CHECK (("frequency" = ANY (ARRAY['daily'::"text", 'weekly'::"text", 'monthly'::"text"]))),
    CONSTRAINT "workflows_kind_check" CHECK (("kind" = ANY (ARRAY['event'::"text", 'audience'::"text"]))),
    CONSTRAINT "workflows_kind_target" CHECK (((("kind" = 'event'::"text") AND ("trigger" IS NOT NULL) AND ("audience" IS NULL)) OR (("kind" = 'audience'::"text") AND ("audience" IS NOT NULL) AND ("trigger" IS NULL)))),
    CONSTRAINT "workflows_min_days_between_sends_check" CHECK (("min_days_between_sends" >= 0)),
    CONSTRAINT "workflows_name_check" CHECK (("btrim"("name") <> ''::"text")),
    CONSTRAINT "workflows_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'active'::"text", 'paused'::"text", 'archived'::"text"])))
);


ALTER TABLE "public"."workflows" OWNER TO "postgres";


COMMENT ON TABLE "public"."workflows" IS 'Multi-step message sequences. kind=event reuses automation_events; kind=audience is a filter re-checked on a schedule.';



COMMENT ON COLUMN "public"."workflows"."trigger_filters" IS 'Optional audience filter applied to the CLIENT at enrolment, for kind=event. Same shape as `audience`; compiled by the same function.';



COMMENT ON COLUMN "public"."workflows"."service_types" IS 'Optional care-type narrowing matched against the booking behind the event. Empty means every service, never none.';



