);


ALTER TABLE "public"."yipyy_go_charges" OWNER TO "postgres";


COMMENT ON TABLE "public"."yipyy_go_charges" IS 'What a pre-arrival form put on the bill: an add-on priced from the facility''s catalogue, or the medication fee. One row per charge key; line_item_id is the booking_line_items row it wrote, and turns null when staff remove that line — which the form then never re-adds. Written only by private.yipyy_go_write_charges().';



CREATE TABLE IF NOT EXISTS "public"."yipyy_go_check_in_passes" (
    "booking_id" "uuid" NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "token_hash" "bytea" NOT NULL,
    "token_expires_at" timestamp with time zone NOT NULL,
    "issued_at" timestamp with time zone DEFAULT "now"() NOT NULL,
