    CONSTRAINT "yipyy_go_check_in_passes_token_hash_check" CHECK (("octet_length"("token_hash") = 32))
);


ALTER TABLE "public"."yipyy_go_check_in_passes" OWNER TO "postgres";


COMMENT ON TABLE "public"."yipyy_go_check_in_passes" IS 'The check-in code an owner shows at the desk: one per booking, stored as the sha256 of a random token (the token itself is never stored). Showing a new code replaces the old one. Read and written only through issue_ and resolve_yipyy_go_check_in_pass(). Replaces an in-memory Map that could not be read on any other device (2026-09-13).';



CREATE TABLE IF NOT EXISTS "public"."yipyy_go_photos" (
