    CONSTRAINT "yipyy_go_photos_storage_path_check" CHECK ((("length"("storage_path") >= 1) AND ("length"("storage_path") <= 500)))
);


ALTER TABLE "public"."yipyy_go_photos" OWNER TO "postgres";


COMMENT ON TABLE "public"."yipyy_go_photos" IS 'A photo an owner attached to a pre-arrival form: of the belongings, a medication label, or an answer to a question. The file lives in the private yipyy-go-photos bucket at {facility_id}/{submission_id}/…; this row is what the form points at, by id. Replaces blob: URLs that died with the tab (2026-09-13).';



