CREATE OR REPLACE VIEW "public"."customer_package_pool_status" WITH ("security_invoker"='true') AS
 SELECT "cp"."id" AS "customer_package_id",
    "cp"."facility_id",
    "cp"."client_id",
    "l"."service_id",
    "l"."service_name",
    "l"."passes_total",
    ("l"."passes_total" + COALESCE("sum"("e"."passes"), (0)::bigint)) AS "passes_remaining",
    "l"."module"
   FROM (("public"."customer_packages" "cp"
     JOIN "public"."customer_package_lines" "l" ON (("l"."customer_package_id" = "cp"."id")))
     LEFT JOIN "public"."package_pass_entries" "e" ON ((("e"."customer_package_id" = "cp"."id") AND ("e"."service_id" = "l"."service_id"))))
  GROUP BY "cp"."id", "l"."id";



CREATE OR REPLACE VIEW "public"."customer_package_status" WITH ("security_invoker"='true') AS
 SELECT "cp"."id",
    "cp"."facility_id",
    "cp"."client_id",
    "cp"."package_name",
    "cp"."price_paid",
    "cp"."purchased_at",
    "cp"."expires_at",
    COALESCE("sum"("s"."passes_total"), (0)::bigint) AS "passes_total",
    COALESCE("sum"("s"."passes_remaining"), (0)::numeric) AS "passes_remaining",
    ((COALESCE("sum"("s"."passes_total"), (0)::bigint))::numeric - COALESCE("sum"("s"."passes_remaining"), (0)::numeric)) AS "passes_used",
        CASE
            WHEN (("cp"."expires_at" IS NOT NULL) AND ("cp"."expires_at" < "now"())) THEN 'expired'::"text"
            WHEN (COALESCE("sum"("s"."passes_remaining"), (0)::numeric) <= (0)::numeric) THEN 'exhausted'::"text"
            ELSE 'active'::"text"
        END AS "status"
   FROM ("public"."customer_packages" "cp"
     LEFT JOIN "public"."customer_package_pool_status" "s" ON (("s"."customer_package_id" = "cp"."id")))
  GROUP BY "cp"."id";



CREATE OR REPLACE VIEW "public"."grooming_stylist_stats" WITH ("security_invoker"='true') AS
 SELECT "s"."id" AS "staff_id",
    "s"."facility_id",
    "count"("ga"."booking_id") AS "total_appointments"
   FROM (("public"."staff" "s"
     LEFT JOIN "public"."bookings" "b" ON (("b"."assigned_staff_id" = "s"."id")))
     LEFT JOIN "public"."grooming_appointments" "ga" ON (("ga"."booking_id" = "b"."id")))
  GROUP BY "s"."id";



CREATE OR REPLACE VIEW "public"."prepaid_package_pricing" WITH ("security_invoker"='true') AS
 SELECT "p"."id",
    "p"."facility_id",
    "p"."package_price",
    COALESCE("sum"((("l"."quantity")::numeric * "l"."price_per_session")), (0)::numeric) AS "regular_price",
    COALESCE("sum"("l"."quantity"), (0)::bigint) AS "total_passes",
    (COALESCE("sum"((("l"."quantity")::numeric * "l"."price_per_session")), (0)::numeric) - "p"."package_price") AS "savings",
        CASE
            WHEN (COALESCE("sum"((("l"."quantity")::numeric * "l"."price_per_session")), (0)::numeric) > (0)::numeric) THEN "round"((((COALESCE("sum"((("l"."quantity")::numeric * "l"."price_per_session")), (0)::numeric) - "p"."package_price") / "sum"((("l"."quantity")::numeric * "l"."price_per_session"))) * (100)::numeric), 1)
            ELSE (0)::numeric
        END AS "savings_percentage",
    ( SELECT "count"(*) AS "count"
           FROM "public"."customer_packages" "cp"
          WHERE ("cp"."package_id" = "p"."id")) AS "purchase_count"
   FROM ("public"."prepaid_packages" "p"
     LEFT JOIN "public"."prepaid_package_lines" "l" ON (("l"."package_id" = "p"."id")))
  GROUP BY "p"."id";



