ALTER TABLE "public"."audit_log" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "audit_log_booking_read" ON "public"."audit_log" FOR SELECT TO "authenticated" USING ((("entity_type" = 'booking'::"text") AND ("facility_id" IS NOT NULL) AND "private"."has_permission"("facility_id", 'view_bookings'::"text") AND (EXISTS ( SELECT 1
   FROM "public"."bookings" "b"
  WHERE (("b"."id")::"text" = "audit_log"."entity_id"))) AND (("category" <> 'Financial'::"text") OR "private"."has_permission"("facility_id", 'view_booking_financials'::"text"))));



CREATE POLICY "audit_log_facility_read" ON "public"."audit_log" FOR SELECT TO "authenticated" USING ((("facility_id" IS NOT NULL) AND "private"."is_facility_admin"("facility_id")));



COMMENT ON POLICY "audit_log_facility_read" ON "public"."audit_log" IS 'A facility admin reads their own facility entries. Rows with a null facility are platform-level (who was made a Yipyy superadmin) and stay out of every facility view.';



CREATE POLICY "audit_log_read" ON "public"."audit_log" FOR SELECT TO "authenticated" USING ("private"."is_platform_admin"());



